window.__D("text/zohar-hebrew-translation/c024",{"p":[[9522011925,"<p>רַבִּי אֶלְעָזָר פָּתַח, (ישעיה ז) שְׁאַל לְךְ אוֹת מֵעִם ה' אֱלֹהֶיךְ הַעֲמֵק שְׁאָלָה אוֹ הַגְבֵּהַּ לְמָעְלָה. הִסְתַּכַּלְתִּי בְּדוֹרוֹת רִאשׁוֹנִים וְדוֹרוֹת אַחֲרוֹנִים, מַה בֵּין דּוֹרוֹת רִאשׁוֹנִים לְדוֹרוֹת אַחֲרוֹנִים? הַדּוֹרוֹת הָרִאשׁוֹנִים הָיוּ יוֹדְעִים וּמִתְבּוֹנְנִים בַּחָכְמָה הָעֶלְיוֹנָה וְיוֹדְעִים לְצָרֵף הָאוֹתִיּוֹת שֶׁנִּתְּנוּ לְמֹשֶׁה בְּסִינַי, וַאֲפִלּוּ הָרְשָׁעִים שֶׁבְּיִשְׂרָאֵל הָיוּ יוֹדְעִים בְּתוֹךְ הָאוֹתִיּוֹת אֶת הַחָכְמָה הָעֶלְיוֹנָה, וְיוֹדְעִים בְּתוֹךְ הָאוֹתִיּוֹת הָעֶלְיוֹנוֹת וְתוֹךְ הָאוֹתִיּוֹת הַתַּחְתּוֹנוֹת חָכְמָה לְהַנְהִיג אֶת הַמַּעֲשִׂים בָּעוֹלָם הַזֶּה.</p>\n<p>מִשּׁוּם שֶׁכָּל אוֹת וְאוֹת שֶׁנִּמְסְרָה לְמֹשֶׁה, הָיוּ מִתְעַטְּרוֹת וְעוֹלוֹת עַל רָאשֵׁי הַחַיּוֹת הַקְּדוֹשׁוֹת הָעֶלְיוֹנוֹת, וְכָל הַחַיּוֹת הָיוּ מִתְעַטְּרוֹת בָּהֶן, וּפוֹרְחוֹת לְתוֹךְ הָאֲוִיר שֶׁיּוֹרֵד מִתּוֹךְ הָאֲוִיר הָעֶלְיוֹן, דַּקִּיק וְלֹא יָדוּעַ.</p>\n<p>וְעוֹלוֹת וְיוֹרְדוֹת אוֹתִיּוֹת גְּדוֹלוֹת וְאוֹתִיּוֹת דַּקּוֹת. הָאוֹתִיּוֹת הַגְּדוֹלוֹת יוֹרְדוֹת מִתּוֹךְ הַהֵיכָל הָעֶלְיוֹן הַטָּמִיר שֶׁל הַכֹּל, וְהָאוֹתִיּוֹת הַדַּקּוֹת הָיוּ יוֹרְדוֹת מִתּוֹךְ הֵיכָל אַחֵר תַּחְתּוֹן, וְאֵלֶּה וְאֵלֶּה נִמְסְרוּ לְמֹשֶׁה בְּסִינַי.</p>\n<p>וְחִבּוּר הָאוֹתִיּוֹת שֶׁמִּתְחַבְּרוֹת בַּסֵּתֶר בְּכָל אוֹת וָאוֹת, כְּמוֹ א', אוֹת יְחִידָה, מִתְחַבְּרוֹת עִמָּהּ בַּסֵּתֶר שְׁתֵּי אֲחֵרוֹת לף. וְכֵן כֻּלָּן נִמְסְרוּ לְמֹשֶׁה בְּסִינַי, וְכֻלָּן נִסְתָּרוֹת בְּתוֹךְ הַחֲבֵרִים. אַשְׁרֵיהֶ ם.</p>\n<p>שְׁאַל לְךְ אוֹת - אוֹת מַמָּשׁ. שֶׁכֻּלָּם הָיוּ נוֹסְעִים בְּסוֹד הָאוֹתִיּוֹת. וְכֵן בְּרָחָב מַה כָּתוּב, (יהושע ב) וּנְתַתֶּם לִי אוֹת אֱמֶת, זוֹ אוֹת ו', שֶׁזּוֹ נִקְרֵאת אוֹת אֱמֶת. וְאִם תֹּאמַר שֶׁשְּׁאָר הָאותִיּות אֵינָן אֱמֶת - כֵּן, אֶלָּא הָאוֹת הַזּוֹ נִקְרֵאת אוֹת אֱמֶת.</p>\n<p>הַעָמֵק שְׁאָלָה - זוֹ אוֹת ה' אַחֲרוֹנָה שֶׁבַּשֵׁם הַקָּדוֹשׁ. אוֹ הַגְבֵּהַּ לְמָעְלָה - זוֹ אוֹת יוֹ\"ד הָרֹאשׁ שֶׁבַּשֵּׁם הַקָּדוֹשׁ. וְזֶהוּ סוֹד הַכָּתוּב, שְׁאַל נָא אוֹת מֵעִם ה' אֱלֹהֶיךְ, אוֹת מִן הַשֵּׁם הַקָּדוֹשׁ, מַשְׁמָע שֶׁכָּתוּב מֵעִם ה', שֶׁזֶּהוּ שְׁמוֹ שֶׁל הַקָּדוֹשׁ- בָּרוּךְ-הוּא, אוֹת אַחַת שֶׁבּוֹ, וְהַמִּשְׁכָּן עוֹמֵד עַל זֶה.</p>\n<p>בֹּא רְאֵה, כְּשֶׁעָלָה הֶעָנָן עַל הַמִּשְׁכָּן וְשָׁרָה עָלָיו, כָּל אוֹתָן הַמֶּרְכָּבוֹת וְכָל אוֹתָם כְּלֵי הַמִּשְׁכָּן שֶׁלְּמַעְלָה, כֻּלָּם הָיוּ בְּתוֹךְ הֶעָנָן. מַה כָּתוּב? (שמות מ) וְלֹא יָכוֹל מֹשֶׁה לָבֹא אֶל אֹהֶל מוֹעֵד כִּי שָׁכַן עָלָיו הֶעָנָן. וְכָתוּב, וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן, (שם כד) וַיְהִי מֹשֶׁה בָּהָר אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה. אִם מֹשֶׁה לֹא הָיָה יָכוֹל לְהִכָּנֵס לַמִּשְׁכָּן, לָמָּה הָיָה יוֹשֵׁב בָּהָר כָּל אוֹתָם אַרְבָּעִים הַיָּמִים?</p>\n<p>אֶלָּא (כדי לקבל התורה בפעם אחרת, שהרי שני לוחות נשברו בראשונה, ועתה היה בהר כבראשונה. אמר רבי יוסי, אם כן, והרי כתוב (שמות מ) ויקם משה את המשכן וכו', וכתוב ולא יכל משה לבא אל אהל מועד, וכתוב ויהי משה בהר ארבעים יום וגו'. וכתוב ויקרא אל משה וגו'. משמע שמשה היה בהר באותו זמן שקרא לו, וכתוב מאהל מועד, ואהל מועד לא היה בהר סיני, שהרי ביניהם של ישראל היה, אמר לו, באותו זמן נשלמו ארבעים ימים, וארבעים ימים היה משה בהר, וענן אחר עליון היה מתקן המשכן ומתקן השלחנות מכל אותן רוחות קדושות להתקין מקום, שהרי) שְׁנֵי עֲנָנִים הָיוּ (ס\"א ענן המאיר וענן המחשיך), אֶחָד שֶׁנִּכְנַס בּוֹ מֹשֶׁה, וְאֶחָד שֶׁשָּׁרוּי הָיָה עַל הַמִּשְׁכָּן. בֹּא וּרְאֵה מַה כָּתוּב, (שמות מ) וּכְבוֹד ה' מָלֵא אֶת הַמִּשְׁכָּן. מִלֵּא לֹא כָתוּב, אֶלָּא מָלֵא, שֶׁהָיָה שָׁלֵם לְמַעְלָה וּלְמַטָּה, עִם הַמִּשְׁכָּן שֶׁלְּמַטָּה. תִּקּוּן טָמִיר שֶׁיָּרַד לְמַטָּה וְנִתְקְנָה הַשְּׁכִינָה.</p>\n<p>אַרְבָּעָה צְדָדִים שֶׁל מַחֲנוֹת נִגְנְזוּ. תִּקּוּן רִאשׁוֹן שֶׁל מִשְׁמָרָה אַחַת מֵאוֹתָן אַרְבַּע מַחֲנוֹת, הַכֹּל עַד שֶׁהִתְתַּקְּנוּ. הָרִאשׁוֹן לְצַד יָמִין צַדְקִיאֵ\"ל, הַמְמֻנֶּה הַגָּדוֹל, גְּדוֹל הַמַּחֲנוֹת, שֶׁהוּא תַּחַת שִׁלְטוֹנוֹ שֶׁל מִיכָאֵ\"ל, וְעִמּוֹ הָיוּ מִתְתַּקְּנִים כָּל אוֹתָם הַמַּחֲנוֹת תַּחַת יָדוֹ.</p>\n<p>וּמְמְנֶּה אֶחָד הוּקַם עַל אַרְבַּע שָׁלֹשׁ, אַרְבַּע לְמַטָּה, לְפִי שֶׁכָּל אוֹתָם הַמַּחֲנוֹת הָעֶלְיוֹנִים, כְּשֶׁיּוֹרְדִים לְמַטָּה, מְשַׁנִּים אֶת הַשֵּׁם שֶׁלָּהֶם בְּשֵׁמוֹת אֲחֵרִים. כְּשֶׁהֵם עֶלְיוֹנִים, לֹא מִשְׁתַּנִּים לְעוֹלָמִים. וְהַמְמֻנֶּה הָעֶלְיוֹן הַזֶּה צַדְקִיאֵ\"ל עוֹמֵד עֲלֵיהֶם לְפָנִים. אוֹת אַחַת נוֹצֶצֶת עַל רָאשֵׁיהֶם, וְהִיא א קְטַנָּה. כְּשֶׁהָאוֹת הַזּוֹ נוֹצֶצֶת, כֻּלָּם נוֹסְעִים לְאוֹתוֹ מָקוֹם שֶׁנּוֹצֶצֶת הַהִתְנוֹצְצוּת הַזּוֹ.</p>\n<p>לִפְנִים מֵהֶם - רָזִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל, גְּדוֹל הַמַּחֲנוֹת, שֶׁעוֹמֵד לִפְנִים תַּחַת שִׁלְטוֹנוֹ שֶׁל מִיכָאֵ\"ל, וְעִמּוֹ כָּל אוֹתָם מַחֲנוֹת שֶׁתַּחַת יָדוֹ, וּמְמֻנֶּה אֶחָד עוֹמֵד עֲלֵיהֶם בַּשַּׁעַר, שֶׁנִּקְרָא רוּמִיאֵ\"ל. וְסוֹבְבִים אוֹתוֹ י\"ב מְמֻנִּים, שָׁלֹשׁ שָׁלֹשׁ אַרְבַּע פְּעָמִים. וְרָזִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל עוֹמֵד עַל כֻּלָּם, שֶׁלֹּא הִשְׁתַּנָּה שְׁמוֹ. אוֹת אַחַת נוֹצֶצֶת עַל רֹאשָׁם שֶׁל כָּל אוֹתָם הַמַּחֲנוֹת, וְהִיא אוֹת ר'. כְּשֶׁזּוֹ נוֹצֶצֶת, כֻּלָּם נוֹסְעִים לְאוֹתוֹ הַצַּד שֶׁל אוֹתָהּ הִתְנוֹצְצוּת. הָאוֹת הַזּוֹ עוֹמֶדֶת עַל הָעֹנֶשׁ שֶׁל מְגַלֵּה הַסּוֹדוֹת, וְסִימָנְךְ - רֵישׁ וְקָלוֹן.</p>\n<p>לִפְנִים מֵהֶם יוֹפִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל, גְּדוֹל הַמַּחֲנוֹת, תַּחַת שִׁלְטוֹנוֹ שֶׁל מִיכָאֵ\"ל וְעִמּוֹ הָיוּ מְתֻקָּנִים כָּל אוֹתָם הַמַּחֲנוֹת שֶׁתַּחַת יָדוֹ, וְלֹא הִתְגַּלּוּ כָּאן בַּחֶשְׁבּוֹן, מִשּׁוּם שֶׁלֹּא נִשְׁלְמוּ כָּאן עַד שֶׁבָּאוּ לְבֵית עוֹלָמִים, שֶׁשָּׁם כֻּלָּם נִשְׁלְמוּ, וְהִתְרַבּוּ הַמַּחֲנוֹת בִּשְׁלֵמוּת. וּמַה שֶּׁאָמַרְנוּ כָאן, כָּל אוֹתָם הַמַּחֲנוֹת שֶׁתַּחַת יָדוֹ, שֶׁנִּמְסְרוּ בְּאוֹתָהּ שָׁעָה לְהִכָּנֵס עִמּוֹ וּמְמֻנֶּה אֶחָד עוֹמֵד עֲלֵיהֶם, וּשְׁמוֹ חָכָמִיאֵ\"ל, וְי\"ב מְמֻנִּים סוֹבְבִים אוֹתוֹ לְכָל עֵבֶר שָׁלֹשׁ שָׁלֹשׁ, כְּמוֹ שֶׁאָמַרְנוּ. וְיוֹפִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל עוֹמֵד עַל כֻּלָּם, שֶׁלֹּא מִשְׁתַּנֶּה שְׁמוֹ.</p>\n<p>אוֹת אַחַת נוֹצֶצֶת עַל רָאשֵׁיהֶם שֶׁל כָּל הַמַּחֲנוֹת הַלָּלוּ, וְהִיא הָאוֹת ק'. כְּשֶׁזּוֹ נוֹצֶצֶת, כֻּלָּם נוֹסְעִים לְאוֹתוֹ הַצַּד שֶׁל אוֹתָהּ הִתְנוֹצְצוּת. הָאוֹת הַזּוֹ ק' תְּלוּיָה בָּאֲוִיר, נִכְנַעַת שָׁלֹשׁ פְּעָמִים בְּיוֹם, וְעוֹלָה וְיוֹרֶדֶת. שְׁתֵּי הָאוֹתִיּוֹת הַלָּלוּ קר, הֵן אוֹתִיּוֹת שֶׁעוֹמְדוֹת בָּאֶמְצַע. אַחַת הַמְכַסָּה עַל אוֹת א', וְאַחַת שֶׁמְּכַסָּה עַל אוֹת י', שֶׁהִיא אַחַר כָּךְ.</p>\n<p>לִפְנִים מֵהֶם קְדוּמִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל, גְּדוֹל הַמַּחֲנוֹת, תַּחַת שִׁלְטוֹנוֹ שֶׁל מִיכָאֵ\"ל, עִמּוֹ הָיוּ מִתְתַּקְּנִים כָּל אוֹתָם הַמַּחֲנוֹת שֶׁתַּחַת יָדוֹ. וּמְמֻנֶּה אֶחָד עוֹמֵד עֲלֵיהֶם בַּשַּׁעַר, שֶׁנִּקְרָא אֲרִיאֵ\"ל. וְי\"ב מְמֻנִּים סוֹבְבִים אוֹתוֹ שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד, וְהַמְמֻנֶּה הַזֶּה קְדוּמִיאֵ\"ל עוֹמֵד עֲלֵיהֶם, שֶׁלֹּא מִשְׁתַּנֶּה שְׁמוֹ לְעוֹלָמִים. אוֹת אַחַת עוֹמֶדֶת וְנוֹצֶצֶת עַל רָאשֵׁיהֶם, וְהִיא הָאוֹת י'. כְּשֶׁזּוֹ נוֹצֶצֶת, כֻּלָּם נוֹסְעִים לְאוֹתָהּ הִתְנוֹצְצוּת שֶׁנּוֹצֶצֶת. הָאוֹת ק' כְּפִי שֶׁאָמַרְנוּ, מְכַסָּה עַל הָאוֹת הַזּוֹ י', ר' מְכַסָּה עַל א'.</p>\n<p>לִפְנַי וְלִפְנִים, בַּמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ, נוֹצֶצֶת אוֹת אַחַת בַּסֵּתֶר וּבִגְנִיזָה, וְהִיא הָאוֹת ו'. וְהָאוֹת ו' הַזּוֹ נוֹצֶצֶת בְּהִתְנוֹצְצוּת עַל כָּל הָאוֹתִיּוֹת, וְקוֹל יוֹצֵא מִבֵּינֵיהֶן שֶׁל הָאוֹתִיּוֹת הַלָּלוּ, וְאָז מַכָּה הַהִתְנוֹצְצוּת שֶׁל הָאוֹת ו' לַהִתְנוֹצְצוּת שֶׁל הָאוֹת י', וְיוֹצֵאת אוֹתָהּ הִתְנוֹצְצוּת מִתּוֹךְ מְקוֹם (שנקרא קדש) הַקֹּדֶשׁ, וּמַכָּה לְתוֹךְ הַהִתְנוֹצְצוּת שֶׁל הָאוֹת י'.</p>\n<p>וְאָז הִתְנוצְצוּת הָאות י' מַכָּה לִפְנִים הִתְנוצְצוּת הָאות ק', וְיוֹצֵאת הִתְנוֹצְצוּת הָאוֹת ק' וּמַכָּה לְתוֹךְ הִתְנוֹצְצוּת הָאוֹת ר', וְיוֹצְאִים כָּל הַנִּיצוֹצוֹת וּמִתְחַבְּרִים לְתוֹךְ הִתְנוֹצְצוּת הָאוֹת א' שֶׁעוֹמֶדֶת. וְהַקּוֹל הָיָה יוֹצֵא וּמַכֶּה בְּכָל אוֹתָם הַנִּיצוֹצוֹת שֶׁל הָאוֹתִיּוֹת כְּאֶחָד, הִתְנוֹצְצוּת הָאוֹת ו' בְּיוֹ\"ד, הִתְנוֹצְצוּת שֶׁל יוֹ\"ד בְּק', הִתְנוֹצְצוּת שֶׁל ק' בְּר', וְהַהִתְנוֹצְצוּת שֶׁל ר' בְּא'. וּמִתְחַבְּרִים חִקּוּקֵי הַנִּיצוֹצוֹת וְיוֹצְאִים אַחַר כָּךְ. וְאַחַר שֶׁמִּתְחַבְּרִים בְּנִיצוֹצוֹתֵיהֶם, יוֹצֵא קוֹל מִבֵּינֵיהֶם, וּמִתְחַבְּרִים בְּסוֹד זֶה וַיִּקְרָא אֶל מֹשֶׁה. וּמֹשֶׁה הָיָה מִסְתַּכֵּל כָּל אוֹתָם הַיָּמִים שֶׁלֹּא נִכְנַס.</p>\n<p>אַחַר כָּךְ חָזְרוּ הָאוֹתִיּוֹת וְהָיוּ מִתְגַּלְגְּלוֹת בְּמַקְלוֹ, בְּצֵרוּפֵי הָאוֹתִיּוֹת שֶׁנִּמְסְרוּ לְאָדָם בְּגַן עֵדֶן. הָאוֹת א' לְהִכָּנֵס לְתוֹךְ הַסֵּתֶר, לַמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ, וְיוֹצֵאת ו', וְנוֹתֶנֶת מָקוֹם לָאוֹת א', וּמִתְחַבֶּרֶת א' לְתוֹךְ ו' שֶׁאַחֲרֶיהָ קר, וְי' נִכְנֶסֶת בֵּין ק' וְר', וְנִמְצָא קִיר. וְנֶחְקָקוֹת וּמִתְנוֹצְצוֹת כְּמוֹ מִקֹּדֶם, וְקוֹל יוֹצֵא מִבֵּינֵיהֶן, וּמִתְחַבְּרִים הַנִּיצוֹצוֹת שֶׁל הָאוֹתִיּוֹת, וְיוֹצְאוֹת הַחוּצָה וּמִתְגַּלּוֹת לְכָל אוֹתָם הַמַּחֲנוֹת, שֶׁהָיוּ נוֹסְעִים עִם הָאוֹתִיּוֹת הַלָּלוּ. וּכְשֶׁמִּתְחַבְּרִים הַנִּיצוֹצוֹת שֶׁל הָאוֹתִיּוֹת, מַכֶּה קוֹל בֵּינֵיהֶם, הֵם נִרְאִים בַּחֲקִיקוֹתֵיהֶם לְכָל אוֹתָן הַמֶּרְכָּבוֹת אוֹקִיר. וְקוֹל חוֹזֵר מִבֵּינֵיהֶם וְקוֹרֵא בֵּין אוֹתָן הַמֶּרְכָּבוֹת: (ישעיה יג) אוֹקִיר אֱנוֹשׁ מִפָּז וְאָדָם מִכֶּתֶם אוֹפִיר.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁרָאָה אֶת כָּל זֶה, אֲבָל הַצֵּרוּף הַזֶּה לֹא נִרְאָה לְעֵינֵי מֹשֶׁה, אֶלָּא הַצֵּרוּף הָרִאשׁוֹן שֶׁהוּא וַיִּקְרָא, אֶת זֶה הָיָה רוֹאֶה מֹשֶׁה. זֶהוּ שֶׁכָּתוּב וַיִּקְרָא אֶל מֹשֶׁה. וְצֵרוּף זֶה אַחֵר לֹא מְגַלִּים לוֹ, מִשּׁוּם שֶׁשִּׁבְחוֹ שֶׁל אָדָם לֹא מוֹדִיעִים לְפָנָיו, וְסִימָנְךְ - (במדבר יב) צְאוּ שְׁלָשְׁתְּכֶם, וְכָתוּב וַיִּקְרָא אַהֲרֹן וּמִרְיָם, וְכָתוּב פֶּה אֶל פֶּה אֲדַבֵּר בּוֹ, וְכָתוּב לֹא כֵן עַבְדִּי מֹשֶׁה, מִשּׁוּם שֶׁלֹּא מוֹדִיעִים שִׁבְחוֹ שֶׁל אָדָם לְפָנָיו.</p>\n<p>עָלוּ הָאוֹתִיּוֹת, וְחָזְרוּ בְּכָל אוֹתָם הַמַּחֲנוֹת כְּמוֹ זֶה, בַּצֵּרוּף הַזֶּה: אוֹקִיר. וְקוֹל יָצָא וְהִכְרִיז וְאָמַר: אוֹקִיר אֱנוֹשׁ מִפָּז וְגוֹ'. אַחַר כָּךְ נִמְשְׁכוּ הָאוֹתִיּוֹת וְהָיוּ נוֹצְצוֹת עַל רָאשֵׁי כָּל אוֹתָן הַמֶּרְכָּבוֹת, וְשָׁכְכוּ עַד שֶׁהִתְתַּקְּנוּ לִמְקוֹמוֹתֵיהֶן.</p>\n<p>הָרֹאשׁ לְצַד שְׂמֹאל חִזְקִיאֵ\"ל, הַמְמֻנֶּה הַגָּדוֹל, גְּדוֹל הַמַּחֲנוֹת לְכָל אוֹתָם שֶׁעוֹמְדִים לְשַׁעַר הַמִּשְׁכָּן, תַּחַת שִׁלְטוֹנוֹ שֶׁל גַּבְרִיאֵ\"ל. וְעִמּוֹ מִתְתַּקְּנִים בְּאוֹתוֹ הַשַּׁעַר כָּל אוֹתָם הַמַּחֲנוֹת שֶׁתַּחַת יָדוֹ, וּמְמֻנֶּה אֶחָד הָעֳמַד עַל הַשַּׁעַר בַּחוּץ, וּשְׁמוֹ גַּזְרִיאֵ\"ל. וְעִמּוֹ י\"ב מְמֻנִּים שֶׁסּוֹבְבִים אוֹתוֹ שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד לְאַרְבָּעָה צְדָדִים.</p>\n<p>וְאֵלּוּ שְׁנִינוּת שֶׁל לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת בִּידֵיהֶם. וְהַמְמֻנֶּה הַזֶּה חִזְקִיאֵ\"ל עוֹמֵד עֲלֵיהֶם לְמַעְלָה לְמַעְלָה בִּפְנִים. אוֹת אַחַת נוֹצֶצֶת עַל רֹאשָׁם, וְהִיא הָאוֹת א'. שֶׁהֲרֵי אֵלֶּה לֹא עוֹמְדִים וְלֹא שׁוֹאֲלִים (נוסעים) אֶלָּא בַּסּוֹד שֶׁל א', שֶׁהִיא יָמִין, מִשּׁוּם שֶׁשְּׂמֹאל אֵין נוֹסַעַת אֶלָּא בְּיָמִין. הַיָּמִין תָּמִיד נוֹסַעַת לִשְׂמֹאל, שֶׁא' אוֹת נוֹצֶצֶת וְיוֹצֵאת מִיָּמִין. וְאָז נוֹסְעִים לְאוֹתוֹ מָקוֹם שֶׁנּוֹצֶצֶת אוֹתָהּ הִתְנוֹצְצוּת.</p>\n<p>לִפְנִים מִמֶּנּוּ רַהֲטִיאֵ\"ל, גְּדוֹל הַמַּחֲנוֹת, שֶׁעוֹמֵד בִּפְנִים תַּחַת שִׁלְטוֹנוֹ שֶׁל גַּבְרִיאֵ\"ל, וְעִמּוֹ כָּל אוֹתָם מַחֲנוֹת תַּחַת יָדוֹ, וּמְמֻנֶּה אֶחָד עוֹמֵד עֲלֵיהֶם בַּשַּׁעַר, שֶׁנִּקְרָא קַדְשִׁיאֵ\"ל, וְסוֹבְבִים אוֹתוֹ י\"ב מְמֻנִּים שָׁלֹשׁ שָׁלֹשׁ אַרְבַּע פְּעָמִים. וְאוֹתוֹ הַמְמֻנֶּה רַהֲטִיאֵ\"ל עוֹמֵד עַל כֻּלָּם, שֶׁלֹּא מִשְׁתַּנֶּה שְׁמוֹ. אוֹת אַחַת נוֹצֶצֶת עַל רָאשֵׁיהֶם שֶׁל כָּל הַמַּחֲנוֹת הַלָּלוּ, וְהָאוֹת הַזּוֹ הִיא ז', וְהִיא מִתְחַלֶּפֶת בְּתוֹךְ תִּקּוּן הַמִּשְׁכָּן בָּאוֹת ל'. זוֹ מִתְחַלֶּפֶת בְּסוֹד שֶׁל (במדבר כד) יִזַּל מַיִם מִדָּלְיָו. וּמִתְחַלֶּפֶת בַּחֲקִיקוֹת שֶׁל הָאוֹתִיּוֹת, וְנִקְרָא חִלּוּף ל'. כְּשֶׁזּוֹ נוֹצֶצֶת עַל רֹאשָׁם שֶׁל כָּל הַמַּחֲנוֹת הַלָּלוּ, אָז כֻּלָּם נוֹסְעִים לְאוֹתוֹ צַד שֶׁל אוֹתָהּ הִתְנוֹצְצוּת.</p>\n<p>לִפְנִים מִזֶּה קַפְצִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל, גְּדוֹל הַמַּחֲנוֹת, תַּחַת שִׁלְטוֹנוֹ שֶׁל גַּבְרִיאֵ\"ל, וְעִמּוֹ הָיוּ מְתֻקָּנִים כָּל אוֹתָם הַמַּחֲנוֹת שֶׁתַּחַת יָדוֹ, הֵם נִמְסְרוּ לוֹ בְּאוֹתָהּ שָׁעָה, וּמְמֻנֶּה אֶחָד עוֹמֵד עֲלֵיהֶם שֶׁשְּׁמוֹ עֲזָאֵ\"ל, וְי\"ב מְמֻנִּים סוֹבְבִים אוֹתוֹ בְּכָל עֵבֶר שָׁלֹשׁ שָׁלֹשׁ כְּפִי שֶׁהֵקַמְנוּ, וְקַפְצִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל עוֹמֵד עַל כֻּלָּם. אוֹת אַחַת נוֹצֶצֶת עַל רֹאשָׁם שֶׁל כָּל הַמַּחֲנוֹת הַלָּלוּ, וְהִיא הָאוֹת ד', וְכֻלָּם נוֹסְעִים לְאוֹתָהּ הִתְנוֹצְצוּת שֶׁל אוֹתָהּ הָאוֹת. הָאוֹת הַזּוֹ תְּלוּיָה בְּתוֹךְ הָאֲוִיר, עַל שְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת.</p>\n<p>לִפְנִים מִזּוֹ שַׁמְעִיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל, זֶה מִתְחַלֵּף לְאַרְבָּעָה שֵׁמוֹת, בִּגְלַל שֶׁלֹּא עוֹמֵד בַּחֲקִיקוֹתָיו. לִפְעָמִים לְצַד יָמִין וְלִפְעָמִים לְצַד שְׂמֹאל, וְעִמּוֹ י\"ב מְמֻנִּים שֶׁסּוֹבְבִים אוֹתוֹ לְכָל עֵבֶר שָׁלֹשׁ שָׁלֹשׁ, כְּמוֹ שֶׁבֵּאַרְנוּ, וְרַגְשִׁיאֵ\"ל הַמְמֻנֶּה הַגָּדוֹל עַל אֵלֶּה הַי\"ב, תַּחַת אוֹתוֹ הַמְמֻנֶּה הָאַחֵר. וְאוֹת אַחַת נוֹצֶצֶת עַל רָאשֵׁיהֶם לְמַעְלָה, וְהָאוֹת הַזּוֹ הִיא הָאוֹת ה', וְזוֹ תְּלוּיָה בָּאֲוִיר עַל כָּל שְׁאָר הָאוֹתִיּוֹת בְּאוֹתָהּ הָאוֹת ד' שֶׁאָמַרְנוּ. אַרְבַּע אֵלּוּ עוֹלוֹת מֵעַל כָּל שְׁאָר הָאֲחֵרוֹת, וְכֻלָּם נוֹסְעִים לְאוֹתָהּ הִתְנוֹצְצוּת שֶׁתְּלוּיָה מֵאוֹתָהּ הָאוֹת.</p>\n<p>לִפְנַי וְלִפְנִים, בַּמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ, נוֹצֶצֶת אוֹת אַחַת בְּתוֹךְ סֵתֶר הַקֹּדֶשׁ, וְהִיא הָאוֹת ם הַסְּתוּמָה. זוֹ נוֹצֶצֶת בְּהִתְנוֹצְצוּת עַל כָּל הָאוֹתִיּוֹת, וְיוֹצֵא קוֹל מִבֵּין הָאותִיּות הַלָּלוּ. אָז מַכָּה הִתְנוצְצוּת הָאות הַזּו, וְנוטֶלֶת שְׁתֵּי אוֹתִיּוֹת אֲחֵרוֹת נוֹצְצוֹת שֶׁתְּלוּיוֹת בָּאֲוִיר, וְהֵן ד' ה' וְנִשְׁאָר אֵל, וּמִתְחַבְּרוֹת בָּאֲחֵרוֹת הַלָּלוּ שֶׁל צַד יָמִין, וּמַכּוֹת אֵלּוּ בְּאֵלּוּ, וְכֻלָּן נוֹסְעוֹת וְחוֹזְרוֹת הָרִאשׁוֹנוֹת כְּבָרִאשׁוֹנָה וְיוֹצְאוֹת הַחוּצָה, וְאָז נִקְרָאוֹת וַיִּקְרָא אֶל מֹשֶׁה.</p>"],[9522011926,"<p>וַיִּקְרָא אֶל מֹשֶׁה וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. רַבִּי חִיָּיא פָּתַח וְאָמַר, (שיר ה) בָּאתִי לְגַנִּי אֲחֹתִי כַלָּה אָרִיתִי מוֹרִי עִם בְּשָׂמִי אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי שָׁתִיתִי יֵינִי עִם חֲלָבִי וְגוֹ'. הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ וְאֵין סוֹפוֹ רֹאשׁוֹ. כָּתוּב אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי שָׁתִיתִי יֵינִי עִם חֲלָבִי, אַחַר כָּךְ - אִכְלוּ רֵעִים. מִי שֶׁמַּזְמִין אֶת הָאַחֵר, כְּשֶׁמָּזוֹן מְתֻקָּן לְפָנָיו. אַחַר שֶׁאָכַל, אֵיךְ יַזְמִין אֶת הָאַחֵר?</p>\n<p>אֶלָּא אַשְׁרֵיהֶם יִשְׂרָאֵל, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לְטַהֵר אוֹתָם וְהִתְרַצָּה בָהֶם מִכָּל שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, וּמִשֶּׁהִתְרַצָּה בָהֶם, רָצָה לְהַעֲלוֹתָם מִכָּל הַמְקַטְרְגִים שֶׁל הָעוֹלָם. בֹּא רְאֵה, (אחר שנעשה המשכן) בַּיּוֹם שֶׁהוּקַם הַמִּשְׁכָּן לְמַטָּה, בְּאוֹתוֹ יוֹם הוּקַם מִשְׁכָּן אַחֵר לְמַעְלָה עִמּוֹ, שֶׁכָּתוּב (שמות מ) הוּקַם הַמִּשְׁכָּן, סְתָם. וְאוֹתוֹ יוֹם הָיָה שִׂמְחָתוֹ שֶׁל הַקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>כֵּיוָן שֶׁהוּקַם הַמִּשְׁכָּן, מַה כָּתוּב? (שם) וְלֹא יָכוֹל מֹשֶׁה לָבֹא אֶל אֹהֶל מוֹעֵד. כְּשֶׁרָאָה הַקָּדוֹשׁ- בָּרוּךְ-הוּא כָּךְ, אָמַר, וּמָה עַל יְדֵי מֹשֶׁה הוּקַם, וְהוּא בַּחוּץ?! מִיָּד - וַיִּקְרָא אֶל מֹשֶׁה. אָמַר לוֹ, מֹשֶׁה, חֲנֻכַּת הַבַּיִת בַּמָּה הִיא? בִּסְעוּדָה, אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. זֶהוּ שֶׁכָּתוּב בָּאתִי לְגַנִּי אֲחֹתִי כַלָּה וְגוֹ'. (והרי בארנו הפסוק הזה. אבל באתי)</p>\n<p>דָּבָר אַחֵר בָּאתִי לְגַנִּי - זֶה גַּן עֵדֶן שֶׁלְּמַעְלָה. אֲחֹתִי כַלָּה - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁבְּאוֹתוֹ יוֹם הִזְדַּוְּגוּ זִוּוּגִים בַּכֹּל, הִזְדַּוְּגוּ זִוּוּגִים בְּאוֹתוֹ גַּן עֵדֶן, מִשּׁוּם שֶׁכֻּלָּם הִתְבָּרְכוּ מֵהַשְׁקָאַת הַנַּחַל וְנִקְשְׁרוּ כָּל אֶחָד בַּחֲבֵרוֹ. זֶהוּ שֶׁכָּתוּב אָרִיתִי מוֹרִי עִם בְּשָׂמִי אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי שָׁתִיתִי יֵינִי עִם חֲלָבִי. כֻּלָּם הֻשְׁקוּ וְהִתְרַוּוּ מִמַּעְיַן הַנַּחַל.</p>\n<p>אִכְלוּ רֵעִים שְׁתוּ וְשִׁכְרוּ דּוֹדִים, כָּל אוֹתָם שֶׁלְּמַטָּה, וְכֻלָּם עֲנָפִים, (עולמות) כֻּלָּם הִתְבָּרְכוּ וְנִזּוֹנוּ כְּשֶׁאֵלֶּה הִתְבָּרְכוּ לְמַעְלָה. וּבַמֶּה מִתְבָּרְכִים וּמִתְבַּשְּׂמִים? כֻּלָּם בְּרֵיחַ הַקָּרְבָּן.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁיָּרְדָה כְּנֶסֶת יִשְׂרָאֵל לְהַשְׁרוֹת דִּיּוּרָהּ בָּאָרֶץ, הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לָהּ אֶת הַפָּסוּק הַזֶּה, מִשּׁוּם שֶׁנִּמְצְאוּ בְרָכוֹת וְשִׂמְחָה בְּכָל הָעוֹלָמוֹת, וְהִיא הִתְבַּשְּׂמָה, לָצֵאת מִמֶּנָּה בְּרָכוֹת לַכֹּל. כְּשֶׁאֵלּוּ הַשִּׁשָּׁה מִתְבָּרְכִים, אָז כָּל הָעוֹלָמוֹת מִתְבָּרְכִים כְּאֶחָד לְמַטָּה וּמִתְבָּרְכִים לְמַעְלָה. (וכנסת ישראל וישראל) וְיִשְׂרָאֵל מִתְבָּרְכִים מִכֻּלָּם. דָּבָר אַחֵר בָּאתִי לְגַנִּי אֲחֹתִי כַלָּה - רַבִּי יִצְחָק אָמַר, אֵין מִזְדַּוֵּג הַקָּדוֹשׁ בָּרוּךְ הוּא (ישראל) עִם כְּנֶסֶת יִשְׂרָאֵל אֶלָּא בִּזְמַן שֶׁאֵלּוּ הַשִּׁשָּׁה מִתְרַוִּים מֵהַשְׁקָאַת הַנַּחַל שֶׁלֹּא פוֹסֵק.</p>"],[9522011927,"<p>פָּתַח וְאָמַר, בָּאתִי לְגַנִּי אֲחֹתִי כַלָּה - הִיא מַלְכוּת, אֲדנָ\"י. אָרִיתִי מוֹרִי - זֶה חֶסֶד, הַדַּרְגָּה שֶׁל אַבְרָהָם, שֶׁנֶּאֱמַר עָלָיו אֵלֵךְ לִי אֶל הַר הַמּוֹר. עִם בְּשָׂמִי - זֶה נֵצַח, הַדַּרְגָּה שֶׁל אַהֲרֹן, שֶׁכָּתוּב בּוֹ וְאַתָּה קַח לְךְ בְּשָׂמִים רֹאשׁ. וְהֵם זְרוֹעַ יָמִין בְּיֶרֶךְ יָמִין, וְסוֹד הַדָּבָר - נְעִמוֹת בִּימִינְךְ נֶצַח. וְאוֹתָן שְׁתֵּי הַבְּרָכוֹת כְּנֶגְדּוֹ - אַחַת מָגֵן אַבְרָהָם, וְהַשְּׁנִיָּה עֲבוֹדָה, שֶׁהִיא רְצֵה.</p>\n<p>אָכַלְתִּי יַעְרִי - זוֹ גְּבוּרָה, פַּחַד יִצְחָק. עִם דִּבְשִׁי - הוֹד, הַדַּרְגָּה שֶׁל דָּוִד, וְהַיְנוּ זְרוֹעַ שְׂמֹאל עִם יֶרֶךְ שְׂמֹאל. שָׁתִיתִי יֵינִי עִם חֲלָבִי - גּוּף וּבְרִית, יַעֲקֹב עִם שְׁלֹמֹה. אַחַר כָּךְ, אִכְלוּ רֵעִים שְׁתוּ וְשִׁכְרוּ דּוֹדִים - י\"ב שְׁבָטִים בְּי\"ב בְּרָכוֹת. תּוֹסֶפֶת בִּרְכַּת הַמִּינִים מִי אוֹכֵל אוֹתָהּ? אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ, בָּאתִי לְגַנִּי אֲחֹתִי כַלָּה.</p>\n<p>וְיֵשׁ מִי שֶׁמְּחַלֵּק אוֹתָם בְּסוֹד אַחֵר. אָרִיתִי מוֹרִי עִם בְּשָׂמִי - גּוּף וּבְרִית. יַעְרִי עִם דִּבְשִׁי - שׁוֹק יָמִין עִם שְׂמֹאל. יֵינִי עִם חֲלָבִי - זְרוֹעַ שְׂמֹאל עִם יָמִין, שֶׁהֵם - יֵינִי גְּבוּרָה, חֲלָבִי חֶסֶד. (ע\"כ רעיא מהימנא)</p>\n<p>רַבִּי יְהוּדָה אָמַר, אִכְלוּ רֵעִים שְׁתוּ וְשִׁכְרוּ דּוֹדִים. אֵלּוּ כָּל בַּעֲלֵי הַיְבָבָה וְהַיְלָלָה, שֶׁכֻּלָּם הִתְבַּשְּׂמוּ וְהִתְבָּרְכוּ כְאֶחָד, שֶׁהֲרֵי מִסְּעוּדַת הַמֶּלֶךְ כֻּלָּם נֶהֱנִים. וּמָתַי כֻּלָּם אוֹכְלִים? בְּשָׁעָה שֶׁהַמֶּלֶךְ (השתמח) בָּא שָׂמֵחַ, וְלָכֵן הַמֶּלֶךְ הִשְׂתַּמַּח, וּמְשַׂמֵּחַ אֶת הַגְּבִירָה בָּרִאשׁוֹנָה, אַחַר כָּךְ כֻּלָּם אוֹכְלִים וּשְׂמֵחִים.</p>\n<p>רַבִּי אַבָּא אָמַר, אִכְלוּ רֵעִים שְׁתוּ וְשִׁכְרוּ דּוֹדִים, אֵלּוּ הֵם הַשִּׁשָּׁה שֶׁאָמַרְנוּ, וְאֵלּוּ הֵם שֶׁכָּתוּב בָּהֶם, (שיר א) הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו וְגוֹ'. שְׁתוּ וְשִׁכְרוּ, מֵאוֹתוֹ הַיַּיִן הַמַּרְוֶה אֶת הַכֹּל. רַבִּי אֶלְעָזָר אָמַר, כָּל אוֹתָם שֶׁלְּמַטָּה, שֶׁכֵּיוָן שֶׁאוֹתָם הַשִּׁשָּׁה הִתְבָּרְכוּ, אָז כָּל אֵלּוּ שֶׁלְּמַטָּה מִתְבָּרְכִים.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, הַכֹּל יָפֶה, אֲבָל סוֹד הַדָּבָר - אִכְלוּ רֵעִים לְמַעְלָה, שְׁתוּ וְשִׁכְרוּ דּוֹדִים לְמַטָּה. אָמַר לוֹ רַבִּי אֶלְעָזָר, מִי הֵם לְמַעְלָה וּמִי הֵם לְמַטָּה? אָמַר לוֹ, יָפֶה שָׁאַלְתָּ, זֶה הַמָּקוֹם הָעֶלְיוֹן שֶׁהֵם בְּאַחְדוּת וּבְשִׂמְחָה שֶׁאֵין נִפְרָדִים לְעוֹלָמִים, אֵלּוּ נִקְרָאִים רֵעִים. זֶהוּ שֶׁכָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן, וְעֵדֶן וְנָהָר אֵין נִפְרָדִים לְעוֹלָמִים, וְנִמְצָאִים לְעוֹלָמִים בְּרָצוֹן וּבְאַחְדוּת וּבְשִׂמְחָה. שְׁתוּ וְשִׁכְרוּ דּוֹדִים, אֵלֶּה הֵם לְמַטָּה שֶׁנִּקְרָאִים דּוֹדִים לִזְמַנִּים יְדוּעִים, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>בֹּא רְאֵה, בְּאוֹתָם עֶלְיוֹנִים כָּתוּב בָּהֶם אֲכִילָה בְּלֹא שְׁתִיָּה. מָה הַטַּעַם? מִי שֶׁיֵּשׁ לוֹ נֹאדוֹת יַיִן, צָרִיךְ אֲכִילָה. וּמִשּׁוּם שֶׁשָּׁם שָׁרוּי הַיַּיִן הַמְשֻׁמָּר, כָּתוּב בָּהֶם אֲכִילָה. וּבְאוֹתָם הַתַּחְתּוֹנִים שֶׁצְּרִיכִים הַשְׁקָיָה, בָּהֶם כָּתוּב שְׁתִיָּה, שֶׁהֲרֵי כָּל הַנְּטִיעוֹת צְרִיכוֹת הַשְׁקָיָה מֵהַנָּחָל הֶעָמֹק. וְלָכֵן, בְּאֵלּוּ אֲכִילָה וּבְאֵלּוּ שְׁתִיָּה. אֵלּוּ רֵעִים וְאֵלּוּ דוֹדִים.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, נִרְאֶה שֶׁהַדּוֹדִים הֵם חֲבִיבוּת, לָמָּה הֵם תַּחְתּוֹנִים? אָמַר לוֹ, אֵלּוּ שֶׁמִּשְׁתּוֹקְקִים זֶה לָזֶה וְלֹא תָמִיד נִמְצָאִים, נִקְרְאוּ דוֹדִים. וְאֵלּוּ שֶׁנִּמְצָאִים תָּמִיד וְלֹא מִתְכַּסִּים וְלֹא נִפְרָדִים זֶה מִזֶּה, נִקְרְאוּ רֵעִים. וְלָכֵן אֵלּוּ דּוֹדִים וְאֵלּוּ רֵעִים, אֵלּוּ בְּרָצוֹן וּבְאַחְדוּת תָּמִיד וְאֵלֶּה בִתְשׁוּקָה לִפְעָמִים. וְזוֹהִי שְׁלֵמוּת הַכֹּל, כְּדֵי שֶׁתִּתְבָּרֵךְ כְּנֶסֶת יִשְׂרָאֵל, וְאָז שִׂמְחָה בְּכָל הָעוֹלָמוֹת.</p>\n<p>רַבִּי חִזְקִיָּה בֵּאֵר אֶת הַפָּסוּק הַזֶּה בַּקָּרְבָּנוֹת, מִשּׁוּם שֶׁהֵם סְעוּדַת הַמֶּלֶךְ לְהַקְרִיב לְפָנָיו, וְנֶהֱנִים מִמֶּנָּה בַּעֲלֵי הַדִּינִים, וְכֻלָּם מִתְבַּשְּׂמִים, וְנִמְצֵאת שִׂמְחָה בַּכֹּל.</p>\n<p>רַבִּי אָחָא בֵּאֵר אֶת הַפָּסוּק הַזֶּה בְּשָׁעָה שֶׁנִּכְנְסָה שְׁכִינָה לַמִּשְׁכָּן, כְּשֶׁנִּמְצְאוּ בְרָכוֹת וּשְׂמָחוֹת בַּכֹּל, וְנִכְנְסָה הַשְּׁכִינָה כְּמוֹ כַּלָּה לַחֻפָּה, וְאָז נִשְׁלְמוּ נִמְצְאוּ יִשְׂרָאֵל לְמַטָּה וְנֶאֶחְזוּ בַּקָּדוֹשׁ- בָּרוּךְ- הוּא בָּאָרֶץ. זֶהוּ שֶׁכָּתוּב (שמות כה) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם, וְאָז הִתְבַּשְּׂמוּ עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>"],[9522011928,"<p>וַיִּקְרָא אֶל מֹשֶׁה. רַבִּי שִׁמְעוֹן פָּתַח, (שיר ב) הַנִּצָּנִים נִרְאוּ בָאָרֶץ עֵת הַזָּמִיר הִגִּיעַ וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. בְּפָסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן, כֵּיוָן שֶׁכָּתוּב נִרְאוּ בָאָרֶץ, מַה זֶּה שֶׁכָּתוּב נִשְׁמַע בְּאַרְצֵנוּ? שֶׁהֲרֵי בְּאֶרֶץ אַחַת מַסְפִּיק. אֶלָּא הַנִּצָּנִים - אֵלּוּ אוֹתָן הַנְּטִיעוֹת שֶׁעָקַר אוֹתָן הַקָּדוֹשׁ בָּרוּךְ הוּא וְשָׁתַל אוֹתָן בְּמָקוֹם אַחֵר, וְגָדְלוּ כִנְטִיעָה כְּשֶׁמּוֹצִיאָה פְרָחִים.</p>\n<p>נִרְאוּ בָאָרֶץ, שֶׁהָאָרֶץ הַזּוֹ מִתְבָּרֶכֶת מֵהֶם כָּרָאוּי. וּמִיהוּ? הָאָרֶץ הַקְּדוֹשָׁה, הָאָרֶץ הָעֶלְיוֹנָה, אֶרֶץ וַדַּאי. עֵת הַזָּמִיר הִגִּיעַ, הָעֵת לַעֲקֹר אֶת שִׁלְטוֹן גְּדוֹלֵי הָעַמִּים שֶׁלֹּא יִשְׁלְטוּ עַל יִשְׂרָאֵל בְּשָׁעָה שֶׁהוּקַם הַמִּשְׁכָּן.</p>\n<p>וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ - זוֹ הָאָרֶץ שֶׁלְּמַטָּה שֶׁיָּרְשׁוּ יִשְׂרָאֵל עַל יְדֵי יְהוֹשֻׁעַ. מִי הוּא קוֹל הַתּוֹר? זֶהוּ הַתַּיָּר הָעֶלְיוֹן שֶׁהִזְדַּוֵּג עִמָּהּ כְּשֶׁבָּנָה שְׁלֹמֹה אֶת בֵּית הַמִּקְדָּשׁ לְמַטָּה, וְאָז הִתְעַטֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַטְרוֹתָיו כְּמוֹ חָתָן עִם כַּלָּה, כְּמוֹ שֶׁנֶּאֱמַר (שם ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹ'.</p>\n<p>בְּסֵפֶר הָאַגָּדָה אָמַר, קוֹל הַתּוֹר - זוֹ תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁתּוֹרָה שֶׁבִּכְתָב נִקְרֵאת סְתָם תּוֹרָה, תּוֹרָה שֶׁבְּעַל פֶּה נִקְרֵאת תּוֹר, כְּמוֹ שֶׁנֶּאֱמַר וַיִּקֶּר, וַיִּקְרָא. זוֹ שְׁלֵמוּת. וְזוֹ לֹא כָּךְ, וַאֲנִי בֵּאַרְתִּי כְּמוֹ שֶׁנִּתְבָּאֵר, וְכָךְ זֶה.</p>\n<p>בֹּא רְאֵה, כְּשֶׁיָּרְדָה שְׁכִינָה לַמִּשְׁכָּן, כָּתוּב כַּלֹּת מֹשֶׁה, חָסֵר ו', כַּלַּת מֹשֶׁה וַדַּאי, וּפֵרְשׁוּהָ. אֲבָל סוֹד הַדָּבָר - כַּלַּת מֹשֶׁה זוֹ כְּנֶסֶת יִשְׂרָאֵל, וְהַכֹּל דָּבָר אֶחָד, וְלַמֶּלֶךְ הָעֶלְיוֹן זֶה נֶאֱמַר. כֵּיוָן שֶׁהוּקַם הַמִּשְׁכָּן, עָמַד מֹשֶׁה בַּחוּץ וְאָמַר, לֹא רָאוּי לְהִכָּנֵס אֶלָּא בִּרְשׁוּת. מִיָּד - וַיִּקְרָא אֶל מֹשֶׁה. מִי זֶה וַיִּקְרָא? זוֹ אוֹתָהּ שֶׁהַבַּיִת שֶׁלָּהּ הִיא, אוֹתָהּ כַּלָּה שֶׁכָּל הַבַּיִת בִּרְשׁוּתָהּ. וַיְדַבֵּר ה' אֵלָיו, אוֹתוֹ שֶׁנִּקְרָא קוֹל, אוֹתוֹ שֶׁאָחוּז בּוֹ מֹשֶׁה.</p>"],[9522011929,"<p>וַיִּקְרָא אֶל מֹשֶׁה. רַבִּי אֶלְעָזָר פָּתַח, (ישעיה נ) מַדּוּעַ בָּאתִי וְאֵין אִישׁ קָרָאתִי וְאֵין עוֹנֶה הֲקָצוֹר קָצְרָה יָדִי מִפְּדוּת. אַשְׁרֵיהֶם יִשְׂרָאֵל, שֶׁבְּכָל מָקוֹם שֶׁנִּמְצְאוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא עִמָּהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בֵינֵיהֶם וּמִתְפָּאֵר בָּהֶם בְּיִשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁיִּשְׂרָאֵל מַשְׁלִימִים אֶת הָאֱמוּנָה בָּאָרֶץ, וְיִשְׂרָאֵל הֵם שְׁלֵמוּת הַשֵּׁם הַקָּדוֹשׁ. וּכְשֶׁיִּשְׂרָאֵל נִשְׁלָמִים בְּמַעֲשֵׂיהֶם, כִּבְיָכוֹל הַשֵּׁם הַקָּדוֹשׁ נִשְׁלָם. וּכְשֶׁיִּשְׂרָאֵל לֹא נִשְׁלָמִים לְמַטָּה בְּמַעֲשֵׂיהֶם וּמִתְחַיְּבִים גָּלוּת, כִּבְיָכוֹל הַשֵּׁם הַקָּדוֹשׁ לֹא שָׁלֵם לְמַעְלָה. שֶׁשָּׁנִינוּ, זֶה עוֹלֶה וְזֶה יוֹרֵד. יִשְׂרָאֵל שֶׁלְּמַעְלָה עוֹלֶה לְמַעְלָה - כְּנֶסֶת יִשְׂרָאֵל יוֹרֶדֶת לְמַטָּה. הִתְרַחֲקוּ זֶה מִזּוֹ, כִּבְיָכוֹל נִשְׁאָר הַשֵּׁם הַקָּדוֹשׁ בְּלִי שְׁלֵמוּת, וְהַכֹּל מִשּׁוּם שֶׁכְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת.</p>\n<p>וְאַף עַל גַּב שֶׁיִּשְׂרָאֵל בַּגָּלוּת, הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בֵינֵיהֶם, וּבָא וּמַקְדִּים לְבֵית הַכְּנֶסֶת, וְקוֹרֵא וְאוֹמֵר, (ירמיה ג) שׁוּבוּ בָנִים שׁוֹבָבִים אֶרְפָּא מְשׁוּבוֹתֵיכֶם. וְאֵין מִי שֶׁיָּעִיר אֶת רוּחוֹ. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר, מַדּוּעַ בָּאתִי וְאֵין אִישׁ קָרָאתִי וְאֵין עוֹנֶה. הִקְדַּמְתִּי - וְאֵין אִישׁ, וְאֵין מִי שֶׁיָּעִיר אֶת רוּחוֹ.</p>\n<p>בֹּא רְאֵה, בְּאוֹתוֹ יוֹם שֶׁהִשְׁתַּכְלֵל בֵּית הַמִּשְׁכָּן, הַקָּדוֹשׁ בָּרוּךְ הוּא הִקְדִּים וְשָׁרָה בּוֹ. מִיָּד - וַיִּקְרָא אֶל מֹשֶׁה וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. וַיְדַבֵּר ה' אֵלָיו, וְהוֹדִיעַ לוֹ שֶׁעֲתִידִים יִשְׂרָאֵל לַחֲטֹא לְפָנָיו וְשֶׁיִּתְמַשְׁכֵּן אֹהֶל מוֹעֵד הַזֶּה בַּחֲטָאֵיהֶם וְלֹא יִתְקַיֵּם בִּידֵיהֶם. זֶהוּ שֶׁכָּתוּב וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. מָה אָמַר לוֹ? מֵאֹהֶל מוֹעֵד, מֵעִסְקֵי אֹהֶל מוֹעֵד שֶׁעָתִיד לְהִתְמַשְׁכֵּן בַּחֲטָאֵי יִשְׂרָאֵל וְלֹא יַעֲמֹד בְּקִיּוּמוֹ. אֲבָל הָרְפוּאָה לָזֶה - אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. הֲרֵי לְךְ הַקָּרְבָּנוֹת שֶׁמְּגִנִּים עַל הַכֹּל.</p>"],[9522011930,"<p>רַבִּי חִזְקִיָּה הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, זֶה שֶׁנִּקְרָא קָרְבָּן, קֵרוּב הָיָה צָרִיךְ לִהְיוֹת, אוֹ קְרִיבוּת. מַה זֶּה קָרְבָּן? אָמַר לוֹ, הֲרֵי זֶה יָדוּעַ לַחֲבֵרִים, קָרְבָּן הוּא מֵאוֹתָם הַכְּתָרִים הַקְּדוֹשִׁים שֶׁנִּקְרָבִים כֻּלָּם כְּאֶחָד וְנִקְשָׁרִים זֶה עִם זֶה עַד שֶׁכֻּלָּם נַעֲשִׂים אֶחָד, בְּיִחוּד שָׁלֵם, לְתַקֵּן אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי. זֶהוּ שֶׁכָּתוּב קָרְבָּן לַה'. קָרְבָּן שֶׁל אוֹתָם כְּתָרִים קְדוֹשִׁים לַה' הוּא, לְהִתְתַּקֵּן הַשֵּׁם הַקָּדוֹשׁ וּלְיַחֲדוֹ כָּרָאוּי כְּדֵי שֶׁיִּמָּצְאוּ רַחֲמִים בְּכָל הָעוֹלָמוֹת. וְהַשֵּׁם הַקָּדוֹשׁ שֶׁהִתְעַטֵּר בְּעַטְרוֹתָיו לְבַשֵּׂם אֶת הַכֹּל.</p>\n<p>וְכָל זֶה כְּדֵי לְעוֹרֵר רַחֲמִים וְלֹא לְעוֹרֵר דִּין. וּמִשּׁוּם כָּךְ לַה' הוּא, וְלֹא לֵאלֹהִים. לַה' - אָנוּ צְרִיכִים לְעוֹרֵר רַחֲמִים, וְלֹא לֵאלֹהִים. אָנוּ רוֹצִים רַחֲמִים וְלֹא דִין. אָמַר, אַשְׁרֵי חֶלְקִי שֶׁשָּׁאַלְתִּי וְהִרְוַחְתִּי אֶת הַדְּבָרִים הַלָּלוּ, וְזֶהוּ בֵּרוּר הַדָּבָר. אֲבָל הֲרֵי כָּתוּב, (תהלים נא) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה. זִבְחֵי אֱלֹהִים כָּתוּב, וְלֹא זִבְחֵי ה'.</p>\n<p>אָמַר לוֹ, וַדַּאי כָּךְ זֶה, קָרְבַּן אֱלֹהִים לֹא כָתוּב, אֶלָּא זִבְחֵי אֱלֹהִים. וְלָכֵן שְׁחִיטָתָן בַּצָּפוֹן, שֶׁהֲרֵי זְבִיחָה הִיא בִּשְׁבִיל אֱלֹהִים, אוֹתוֹ הַצַּד שֶׁל הַגְּבוּרָה שֶׁיִּתְבַּשֵּׂם וְיִשְׁבֹּר אֶת רוּחַ הַדִּין, וְיֶחֱלַשׁ הַדִּין, וְיִתְגַּבְּרוּ רַחֲמִים עַל דִּין. וְעַל כֵּן זִבְחֵי אֱלֹהִים, לִשְׁבֹּר אֶת הַכֹּחַ וְהַתֹּקֶף שֶׁל הַדִּין הַקָּשֶׁה, שֶׁכָּתוּב רוּחַ נִשְׁבָּרָה, שֶׁתִּהְיֶה אוֹתָהּ רוּחַ הַתַּקִּיפָה נִשְׁבָּרָה, וְלֹא יִתְגַּבֵּר רוּחָהּ וְכֹחָהּ וְתָקְפָּהּ. וְאָז אָדָם צָרִיךְ לַעֲמֹד עַל הַמִּזְבֵּחַ בְּרוּחַ נִשְׁבָּרָה, וְיִתְבַּיֵּשׁ בְּמַעֲשָׂיו, כְּדֵי שֶׁתִּהְיֶה אוֹתָהּ רוּחַ תַּקִּיפָה שְׁבוּרָה, וְהַכֹּל כְּדֵי שֶׁהַדִּין יִתְבַּשֵּׂם, וְיִתְגַּבְּרוּ הָרַחֲמִים עַל הַדִּין.</p>\n<p>אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. אָמַר רַבִּי אֶלְעָזָר, כָּךְ הָיָה לוֹ לִכְתֹּב הַפָּסוּק הַזֶּה: אָדָם כִּי יַקְרִיב קָרְבָּן לַה'. מַה זֶּה מִכֶּם? לְהוֹצִיא אֶת אָדָם הָרִאשׁוֹן שֶׁהִקְרִיב קָרְבָּן כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, וַהֲרֵי פֵּרְשׁוּהָ, וְכָאן כָּתוּב מִכֶּם, הָאָדָם הַזֶּה, לְהוֹצִיא אָדָם אַחֵר שֶׁלֹּא הָיָה מִכֶּם. אָמַר לוֹ רַבִּי שִׁמְעוֹן, יָפֶה אָמַרְתָּ, וְכָךְ זֶה.</p>"],[9522011931,"<p>רַבִּי אַבָּא פָּתַח, (שם מח) שִׁיר מִזְמוֹר לִבְנֵי קֹרַח. הַשִּׁיר הַזֶּה הִיא תִשְׁבַּחַת מְעֻלָּה עַל כָּל שְׁאָר הַתִּשְׁבָּחוֹת שֶׁזָּכוּ לְשַׁבֵּחַ אוֹתוֹ בְּנֵי קֹרַח. שִׁיר מִזְמוֹר - תִּשְׁבַּחַת עַל תִּשְׁבַּחַת, תִּשְׁבַּחַת שֶׁמִּתְחַלֶּקֶת לִשְׁתֵּי תִשְׁבָּחוֹת.</p>\n<p>וְזָכוּ בְּנֵי קֹרַח לְשַׁבֵּחַ אֶת כְּנֶסֶת יִשְׂרָאֵל. וְהַשֶּׁבַח שֶׁל כְּנֶסֶת יִשְׂרָאֵל הֵם אוֹמְרִים. וּמַה הוּא? שֶׁכָּתוּב (שם) גָּדוֹל ה' וּמְהֻלָּל מְאֹד בְּעִיר אֱלֹהֵינוּ הַר קָדְשׁוֹ. מָתַי נִקְרָא הַקָּדוֹשׁ בָּרוּךְ הוּא גָּדוֹל? בִּזְמַן שֶׁכְּנֶסֶת יִשְׂרָאֵל נִמְצֵאת עִמּוֹ. זֶהוּ שֶׁכָּתוּב בְּעִיר אֱלֹהֵינוּ, הוּא גָּדוֹל בְּעִיר אֱלֹהֵינוּ, עִם עִיר אֱ לֹהֵינוּ.</p>\n<p>אָמַר לוֹ רַבִּי יְהוּדָה, מָה עוֹשֶׂה כָּאן אֱלֹהֵינוּ? אָמַר לוֹ, כָּךְ זֶה וַדַּאי, הָעִיר הַזּוֹ הִיא יִרְאַת אֱלֹהֵינוּ, (כחה) וְתִשְׁבַּחְתָּהּ שֶׁל יִשְׂרָאֵל הִיא. מַה מַּשְׁמָע? נִשְׁמָע שֶׁמֶּלֶךְ בְּלִי גְבִירָה אֵינוֹ מֶלֶךְ, וְאֵינוֹ גָדוֹל וְאֵינוֹ מְהֻלָּל. וְלָכֵן כָּל מִי שֶׁלֹּא נִמְצָא זָכָר וּנְקֵבָה, אֶת כָּל הַשֶּׁבַח מְסִירִים מִמֶּנּוּ וְאֵינוֹ בִּכְלָל שֶׁל אָדָם. וְלֹא עוֹד, אֶלָּא שֶׁאֵינוֹ כְדַאי לְהִתְבָּרֵךְ.</p>\n<p>כָּתוּב (איוב א) וַיְהִי הָאִישׁ הַהוּא גָּדוֹל מִכָּל בְּנֵי קֶדֶם. שָׁנִינוּ בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, שֶׁבַּת זוּגוֹ הָיְתָה כָּמוֹהוּ בְּיִרְאַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמֵהַצַּד שֶׁל אִשְׁתּוֹ נִקְרָא גָדוֹל. אַף כָּאן, גָּדוֹל ה' וּמְהֻלָּל מְאֹד. וּבַמָּה הוּא גָּדוֹל? חָזַר וְאָמַר, בְּעִיר אֱלֹהֵינוּ הַר קָדְשׁוֹ.</p>\n<p>וּמִשּׁוּם כָּךְ הַתִּשְׁבַּחַת הַזּוֹ בַּשֵּׁנִי. וְאִם תֹּאמַר, לָמָּה לֹא כָתוּב כִּי טוֹב בַּשֵּׁנִי? מִשּׁוּם שֶׁעֲתִידִים לְהִפָּרֵד, וְסוֹד הַדָּבָר - (בראשיתב) לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ. בִּזְמַן שֶׁהוּא לְבַדּוֹ, כָּתוּב לֹא טוֹב. וְלָכֵן לֹא כָתוּב כִּי טוֹב בַּשֵּׁנִי.</p>\n<p>גָּדוֹל ה' וּמְהֻלָּל, כְּפִי שֶׁאָמַרְנוּ. יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ, הַתִּשְׁבַּחַת שֶׁל הַזִּוּוּג שֶׁלָּהֶם. יְפֵה נוֹף - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזֶה צַדִּיק, מְשׂוֹשׂ כָּל הָאָרֶץ, אָז הִיא שִׂמְחַת הַכֹּל, וּכְנֶסֶת יִשְׂרָאֵל מִתְבָּרֶכֶת.</p>\n<p>אֱלֹהִים בְּאַרְמְנוֹתֶיהָ נוֹדַע לְמִשְׂגָּב וְגוֹ' - אֵלּוּ הֵם נֵצַ\"ח וְהוֹ\"ד, שֶׁשָּׁם הִתְכַּנְּסוּת שֶׁל כָּל הַבְּרָכוֹת, הִתְכַּנְּסוּת שֶׁל שִׂמְחָה. מִשָּׁם יוֹצֵאת עַל יְדֵי הַדַּרְגָּה הַזּוֹ שֶׁנִּקְרֵאת צַדִּיק, וְשָׁם הִתְכַּנְּסוּ הַבְּרָכוֹת לְבַשֵּׂם אֶת הָעִיר הַקְּדוֹשָׁה וּלְהִתְבָּרֵךְ מִשָּׁם. כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ - אֵלּוּ כָּל כִּתְרֵי הַמֶּלֶךְ בִּכְלָל אֶחָד, וּלְמָקוֹם אַחֵר הַדְּבָרִים הַלָּלוּ עוֹלִים.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁאָדָם מְתַקֵּן אֶת מַעֲשָׂיו עַל יְדֵי קָרְבָּן, הַכֹּל מִתְבַּשֵּׂם וְנִקְרָב וְנִקְשָׁר זֶה בָּזֶה בְּיִחוּד שָׁלֵם. זֶהוּ שֶׁכָּתוּב אָדָם כִּי יַקְרִיב מִכֶּם. כִּי יַקְרִיב לִקְשֹׁר אֶת הַדְּבָרִים כָּרָאוּי.</p>"],[9522011932,"<p>בֹּא רְאֵה, אָדָם כִּי יַקְרִיב, לְהוֹצִיא אֶת מִי שֶׁלֹּא נִשָּׂא, שֶׁהֲרֵי קָרְבָּנוֹ אֵינוֹ קָרְבָּן, וּבְרָכוֹת לֹא נִמְצָאוֹת אֶצְלוֹ (על ידו), לֹא לְמַעְלָה וְלֹא לְמַטָּה. מִמַּשְׁמָע שֶׁכָּתוּב אָדָם כִּי יַקְרִיב, שׁוֹנֶה כָּאן, שֶׁאֵינוֹ אָדָם, וְאֵינוֹ בִּכְלָל שֶׁל אָדָם, וּשְׁכִינָה אֵינָהּ שׁוֹרָה עָלָיו מִשּׁוּם שֶׁהוּא פָּגוּם, וְנִקְרָא בַּעַל מוּם, וּבַעַל מוּם מְרֻחָק מִן הַכֹּל, כָּל שֶׁכֵּן לַמִּזְבֵּחַ לְהַקְרִיב קָרְבָּן.</p>\n<p>וְנָדָב וַאֲבִיהוּא מוֹכִיחִים, שֶׁכָּתוּב (ויקרא י) וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה'. וּמִשּׁוּם כָּךְ כָּתוּב, אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. אָדָם שֶׁנִּמְצְאוּ זָכָר וּנְקֵבָה, זֶה רָאוּי לְהַקְרִיב אֶת הַקָּרְבָּן הַזֶּה וְלֹא אַחֵר.</p>\n<p>וְאָמַר רַבִּי אַבָּא, אַף עַל גַּב שֶׁבֵּאֲרוּהָ אֶת נָדָב וַאֲבִיהוּא בְּדָבָר אַחֵר, כָּךְ הוּא וַדַּאי. אֲבָל קְטֹרֶת הִיא עֶלְיוֹנָה מִכָּל הַקָּרְבָּנוֹת שֶׁל הָעוֹלָם, שֶׁעָלֶיהָ מִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים, וְהַקָּרְבָּן הַזֶּה שֶׁהוּא מֵעַל לְכָל הַקָּרְבָּנוֹת לֹא רְאוּיִים הֵם לְקָרְבוֹ, שֶׁהֲרֵי לֹא נִשְׂאוּ, לַקָּרְבָּן לֹא הָיוּ רְאוּיִים, כָּל שֶׁכֵּן לִדְבָרִים עֶלְיוֹנִים שֶׁיִּתְבָּרְכוּ עַל יָדָם.</p>\n<p>וְאִם תֹּאמַר, וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אוֹתָם, לָמָּה? לְאָדָם שֶׁבָּא לִפְנֵי הַגְּבִירָה לְבַשֵּׂר לָהּ שֶׁהֲרֵי הַמֶּלֶךְ בָּא לְבֵיתָהּ, וְיִשְׁרֶה עִם הַגְּבִירָה לִשְׂמֹחַ עִמָּהּ. בָּא לִפְנֵי הַמֶּלֶךְ, רָאָה הַמֶּלֶךְ שֶׁאוֹתוֹ אָדָם הוּא בַּעַל מוּמִים. אָמַר הַמֶּלֶךְ: אֵין זֶה כְּבוֹדִי שֶׁעַל יְדֵי הַפָּגוּם הַזֶּה אֶכָּנֵס אֶל הַגְּבִירָה. בֵּין כָּךְ הִתְקִינָה הַגְּבִירָה אֶת הַבַּיִת לַמֶּלֶךְ. כֵּיוָן שֶׁרָאֲתָה שֶׁהַמֶּלֶךְ הָיָה מְזֻמָּן לָבֹא אֵלֶיהָ, וְאוֹתוֹ אָדָם גָּרַם שֶׁהַמֶּלֶךְ יִסְתַּלֵּק מִמֶּנָּה, אָז צִוְּתָה הַגְּבִירָה לַהֲרֹג אֶת אוֹתוֹ אָדָם.</p>\n<p>כָּךְ בִּזְמַן שֶׁנִּכְנְסוּ נָדָב וַאֲבִיהוּא וּקְטֹרֶת בִּידֵיהֶם, שָׂמְחָה הַגְּבִירָה, וְהִתְתַּקְּנָה לְקַבֵּל אֶת הַמֶּלֶךְ. כֵּיוָן שֶׁרָאָה הַמֶּלֶךְ אוֹתָם אֲנָשִׁים פְּגוּמִים, בַּעֲלֵי מוּמִים, לֹא רָצָה הַמֶּלֶךְ שֶׁעַל יָדָם יָבֹא לִשְׁרוֹת עִמָּהּ, וְהִסְתַּלֵּק מִמֶּנָּה הַמֶּלֶךְ. כְּשֶׁרָאֲתָה הַגְּבִירָה שֶׁבִּגְלָלָם הִסְתַּלֵּק הַמֶּלֶךְ מִמֶּנָּה, מִיָּד - וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אוֹתָם.</p>\n<p>וְכָל זֶה מִשּׁוּם שֶׁמִּי שֶׁלֹּא נִשָּׂא הוּא פָּגוּם. בַּעֲלֵי מוּמִים לִפְנֵי הַמֶּלֶךְ, קְדֻשַּׁת הַמֶּלֶךְ מִסְתַּלֶּקֶת מִמֶּנּוּ וְלֹא שׁוֹרָה בִפְגָם. וְלָכֵן כָּתוּב אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן. מִי שֶׁנִּקְרָא אָדָם - יַקְרִיב. וּמִי שֶׁלֹּא נִקְרָא אָדָם - לֹא יַקְרִיב.</p>\n<p>מִן הַבְּהֵמָה - כְּלָל. מִן הַבָּקָר וּמִן הַצֹּאן - פְּרָט. אַחַר כָּךְ אֵלּוּ שֶׁכְּשֵׁרִים לֶאֱכֹל, וְשֶׁלֹּא כְשֵׁרִים לַאֲכִילָה אָסוּר לְהַקְרִיב. וּלְמָקוֹם אַחֵר הִסְתַּלְּקוּ אוֹתָם שֶׁכְּשֵׁרִים וְאוֹתָם שֶׁלֹּא כְשֵׁרִים.</p>"],[9522011933,"<p>אִם עֹלָה קָרְבָּנוֹ. רַבִּי חִיָּיא פָּתַח, (ישעיה נה) כִּי לֹא מַחְשְׁבתַי מַחְשְׁבוֹתֵיכֶם וְלֹא דַרְכֵיכֶם דְּרָכָי. כִּי לֹא מַחְשְׁבֹתַי מַחְשְׁבוֹתֵיכֶם, מַחְשְׁבֹתַי כָּתוּב חָסֵר בְּלֹא ו'. בֹּא רְאֵה, מַחֲשֶׁבֶת הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא עֶלְיוֹנָה וְרֹאשׁ שֶׁל הַכֹּל, וּמֵאוֹתָהּ מַחֲשָׁבָה הִתְפַּשְּׁטוּ דְרָכִים וּשְׁבִילִים לְהִמָּצֵא הַשֵּׁם הַקָּדוֹשׁ וּלְתַקְּנוֹ בְתִקּוּנָיו כָּרָאוּי. וּמֵאוֹתָהּ מַחֲשָׁבָה נִשְׁפַּעַת וְיוֹצֵאת הַשְׁקָאַת גַּן הָעֵדֶן לְהַשְׁקוֹת אֶת הַכֹּל. וּמֵאוֹתָהּ מַחֲשָׁבָה קַיָּמִים עֶלְיוֹנִים וְתַחְתּוֹנִים. וּמֵאוֹתָהּ מַחֲשָׁבָה נִמְצֵאת תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>מַחֲשֶׁבֶת הָאָדָם הִיא הָרֹאשׁ שֶׁל הַכֹּל, וּמֵאוֹתָהּ מַחֲשָׁבָה מִתְפַּשְּׁטִים דְּרָכִים וּשְׁבִילִים לְהָסִיט אֶת דְּרָכָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וּמֵאוֹתָהּ מַחֲשָׁבָה שׁוֹפַעַת וְיוֹצֵאת זֻהֲמַת הַיֵּצֶר הָרָע לְהָרַע לוֹ וְלַכֹּל. וּמֵאוֹתָהּ מַחֲשָׁבָה נִמְצָאוֹת עֲבֵרוֹת, חֲטָאוֹת וּזְדוֹנוֹת, עֲבוֹדָה זָרָה, גִּלּוּי עֲרָיוֹת וּשְׁפִיכוּת דָמִים. וְעַל זֶה, כִּי לֹא מַחְשְׁבֹתַי מַחְשְׁבוֹתֵיכֶם.</p>\n<p>וּמִשּׁוּם כָּךְ בְּרֹאשׁ הַכֹּל כָּתוּב, אִם עֹלָה קָרְבָּנוֹ. מִן הַבָּקָר, וְלֹא בָקָר, וּמִי הוּא? הוּא פַּר בֶּן בָּקָר, שֶׁהוּא זָכָר. רַבִּי יִצְחָק אָמַר, מִן הַבָּקָר סְתָם, וְחָזַר וּפֵרַשׁ - זָכָר תָּמִים יַקְרִיבֶנּוּ, זָכָר וְלֹא נְקֵבָה, שֶׁהֲרֵי זָכָר נוֹדָע לְמַעְלָה וּנְקֵבָה נוֹדַעַת לְמַטָּה. וְכֵן מִן הַצֹּאן וּמִן הַכְּבָשִׂים וּמִן הָעִזִּים.</p>\n<p>מִי שֶׁבָּאִים לְעוֹלָה - כֻּלָּם זָכָר, וְלֹא נְקֵבָה, מִשּׁוּם שֶׁעוֹלָה עוֹלָה עַל הַלֵּב, עַל הַלֵּב וַדַּאי, וְנוֹדָע מִי שֶׁעוֹמֵד עַל הַלֵּב. וּמִשּׁוּם כָּךְ עוֹלָה לְמַעְלָה, וְכֻלָּם זְכָרִים. וְלָכֵן פָּתַח הַכָּתוּב בָּרֹאשׁ בְּעוֹלָה יוֹתֵר מִכָּל שְׁאָר הַקָּרְבָּנוֹת, שֶׁהֲרֵי הַמַּחֲשָׁבָה הִיא הָרֹאשׁ שֶׁל הַכֹּל.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, בְּמָקוֹם שֶׁל מַחֲשָׁבָה שֶׁל מַעְלָה צָרִיךְ לְהַקְרִיב. לָמָּה לְמַטָּה יוֹתֵר? לֹא הָיָה בְיָדוֹ. בָּא לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, הָרֹאשׁ שֶׁל הַכֹּל הוּא מַחֲשָׁבָה, וְסִיּוּם שֶׁל אוֹתָהּ מַחֲשָׁבָה מָקוֹם שֶׁנִּקְרָא בֹּקֶר, וּמִיהוּ? אוֹתוֹ סִיּוּם הַגּוּף שֶׁמְּבַשֵּׂם אֶת הַנְּקֵבָה. כָּךְ מַחֲשָׁבָה שֶׁל אָדָם רֹאשׁ שֶׁל הַכֹּל. הַסִּיּוּם שֶׁל אוֹתָהּ מַחֲשָׁבָה, כְּשֶׁנַּעֲשֶׂה מַעֲשֶׂה, מָתַי? בַּבֹּקֶר. זֶהוּ שֶׁכָּתוּב (מיכה ב) הוֹי חֹשְׁבֵי אָוֶן וּפֹעֲלֵי רָע. אֵימָתַי? עַל מִשְׁכְּבוֹתָם בְּאוֹר הַבֹּקֶר יַעֲשׂוּהָ. וְעַל כֵּן לְאוֹתוֹ מָקוֹם שֶׁל מַחֲשָׁבָה, הַמַּחֲשָׁבָה עוֹלָה, וְהַמַּעֲשֶׂה מִתְקָרֵב לְסִיּוּם הַמַּחֲשָׁבָה וַדַּאי.</p>"],[9522011934,"<p>רַבִּי אָחָא הָיָה הוֹלֵךְ בַּדֶּרֶךְ, וְהָיוּ עִמּוֹ רַבִּי יְהוּדָה. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי יְהוּדָה, זֶה שֶׁשָּׁנִינוּ בְּתוּלַת יִשְׂרָאֵל, בְּתוּלָה שֶׁהִתְבָּרְכָה מִן שֶׁבַע (מישראל), שֶׁנִּקְרֵאת בַּת שֶׁבַע, וּפֵרְשׁוּהָ בְּכַמָּה מְקוֹמוֹת. וּבְתוּלָה לְמַטָּה יָרְשָׁה שֶׁבַע בְּרָכוֹת בִּגְלָלָהּ. וַהֲרֵי כָּתוּב, וְאַתָּה בֶּן אָדָם שָׂא קִינָה עַל בְּתוּלַת יִשְׂרָאֵל, וַדַּאי עָלֶיהָ נֶאֱמַר, עַל כְּנֶסֶת יִשְׂרָאֵל. וְזֶה קָשֶׁה מֵהַכֹּל, שֶׁכָּתוּב (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל. וְזֶה שֶׁאָמְרוּ כָּל הַחֲבֵרִים בְּדָבָר זֶה הוּא יָפֶה. אֲבָל אִם הַפָּרָשָׁה נֶאֶמְרָה בְּדֶרֶךְ שֶׁל נֶחָמָה, הָיִינוּ אוֹמְרִים כָּךְ, אֲבָל בַּקִּינָה הַזּוֹ נֶאֱמַר, וַהֲרֵי הַכָּתוּב מוֹכִיחַ כָּךְ.</p>\n<p>אָמַר לוֹ, וַדַּאי כָּךְ זֶה, וַהֲרֵי הָיָה קָשֶׁה לִי אוֹתוֹ דָבָר יוֹתֵר מֵהַכֹּל, וּבָאנוּ אֶל רַבִּי שִׁמְעוֹן בְּחַשְׁכוּת פָּנִים. אָמַר לִי, מִמַּרְאֵה פָנֶיךְ נוֹדָע מַה שֶּׁבְּלִבְּךְ. אָמַרְתִּי לוֹ, וַדַּאי שֶׁפָּנַי וְלִבִּי שָׁוִים. אָמַר לִי, אֱמֹר לִי דְּבָרֶךְ. אָמַרְתִּי לוֹ, כָּתוּב נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל. מִי שֶׁיֵּשׁ לוֹ רֹגֶז בְּאִשְׁתּוֹ וְיָצְאָה מִמֶּנּוּ, לֹא תַחֲזֹּר לְעוֹלָמִים. אִם כָּךְ, אוֹי לַבָּנִים שֶׁגֹּרְשׁוּ עִמָּהּ. אָמַר לִי, וְלֹא מַסְפִּיק לְךְ מַה שֶּׁאָמְרוּ כָּל הַחֲבֵרִים? אָמַרְתִּי, הֲרֵי שָׁמַעְתִּי דִבְרֵיהֶם, שֶׁהָיוּ מֵאַהֲבָה, וְלֹא מִתְיַשְּׁבִים בְּלִבִּי.</p>\n<p>אָמַר, כָּל מַה שֶּׁאָמְרוּ הַחֲבֵרִים יָפֶה וְנָאֶה, אֲבָל אוֹי לְדוֹר כְּשֶׁהָרוֹעִים אֵין נִמְצָאִים, וְהַצֹּאן סוֹטִים וְהוֹלְכִים, וְלֹא יוֹדְעִים לְאֵיזֶה מָקוֹם הוֹלְכִים, לֹא יָמִינָה וְלֹא שְׂמֹאלָה. וַדַּאי שֶׁפָּסוּק זֶה צָרִיךְ לְהַכִּיר, וְכֻלָּם גְּלוּיִים לְאוֹתָם שֶׁרוֹאִים בְּדֶרֶךְ הַתּוֹרָה בְּדֶרֶךְ אֱמֶת.</p>\n<p>בֹּא רְאֵה, בְּכָל הַגָּלֻיּוֹת שֶׁגָּלוּ יִשְׂרָאֵל, לְכֻלָּן שָׂם זְמַן וְקֵץ, וּבְכֻלָּן הָיוּ יִשְׂרָאֵל שָׁבִים לַקָּדוֹשׁ-בָּרוּךְ- הוּא, וּבְתוּלַת יִשְׂרָאֵל הָיְתָה שָׁבָה לִמְקוֹמָהּ, בְּאוֹתוֹ זְמַן שֶׁגָּזַר עָלֶיהָ. וְעַכְשָׁו בַּגָּלוּת הָאַחֲרוֹנָה הַזּוֹ אֵינוֹ כָּךְ, שֶׁהֲרֵי לֹא לֹא תָשׁוּב כָּךְ כְּמוֹ בַּפְּעָמִים הָאֲחֵרוֹת. וְהַפָּסוּק הַזֶּה מוֹכִיחַ, שֶׁכָּתוּב נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל. נָפְלָה וְלֹא אוֹסִיף לַהֲקִימָהּ לֹא כָתוּב.</p>\n<p>מָשָׁל לְמֶלֶךְ שֶׁרָגַז עַל הַגְּבִירָה וְזָרַק אוֹתָהּ מֵהֵיכָלוֹ לִזְמַן יָדוּעַ. כְּשֶׁהָיָה מַגִּיעַ אוֹתוֹ זְמַן, מִיָּד הַגְּבִירָה הָיְתָה נִכְנֶסֶת וְשָׁבָה לִפְנֵי הַמֶּלֶךְ, וְכֵן פַּעַם אַחַת וּשְׁתַּיִם וְשָׁלֹשׁ פְּעָמִים. לַפַּעַם הָאַחֲרוֹנָה הִתְרַחֲקָה מֵהֵיכַל הַמֶּלֶךְ, וְהִשְׁלִיךְ אוֹתָהּ הַמֶּלֶךְ מֵהֵיכָלוֹ לִזְמַן רָחוֹק. אָמַר הַמֶּלֶךְ, הַפַּעַם הַזּוֹ אֵינָהּ כִּשְׁאָר הַפְּעָמִים שֶׁהִיא תַחֲזֹר לְפָנַי כָּךְ, אֶלָּא אֲנִי אֵלֵךְ עִם כָּל בְּנֵי הֵיכָלִי וַאֲבַקֵּשׁ אוֹתָהּ.</p>\n<p>כְּשֶׁהִגִּיעַ אֵלֶיהָ, רָאָה אוֹתָהּ שֶׁהָיְתָה שׁוֹכֶבֶת בֶּעָפָר. מִי רָאָה אֶת כְּבוֹד הַגְּבִירָה בְּאוֹתוֹ זְמַן וְאֶת בַּקָּשׁוֹת הַמֶּלֶךְ כְּנֶגְדָּהּ, עַד שֶׁהַמֶּלֶךְ אוֹחֵז אוֹתָהּ בְּיָדוֹ וּמֵקִים אוֹתָהּ, וּמֵבִיא אוֹתָהּ לְהֵיכָלוֹ, וְנִשְׁבָּע לָהּ שֶׁלֹּא יִפָּרֵד מִמֶּנָּה לִעוֹלָמִים וְלֹא יִתְרַחֵק מִמֶּנּוּ.</p>\n<p>כָּךְֹ הַקָּדוֹשׁ בָּרוּךְ הוּא - כָּל זְמַן שֶׁכְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת, כְּשֶׁהָיָה מַגִּיעַ הַזְּמַן, הִיא בָּאָה וְחוֹזֶרֶת לִפְנֵי הַמֶּלֶךְ. וְעַכְשָׁו בַּגָּלוּת הַזּוֹ לֹא כָּךְ, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא יֶאֱחֹז בְּיָדֶיהָ וְיָקִים אוֹתָהּ וְיִתְפַּיֵּס עִמָּהּ וְיָשִׁיב אוֹתָהּ לְהֵיכָלוֹ. וּבֹא תִרְאֶה שֶׁכָּךְ זֶה, שֶׁהֲרֵי כָּתוּב נָפְלָה לֹא תוֹסִיף קוּם, וְעַל זֶה כָּתוּב, (עמוס ט) בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת. הִיא לֹא תוֹסִיף קוּם כְּמוֹ בַּפַּעֲמַיִם הָאֲחֵרוֹת, אֲבָל אֲנִי אָקִים אוֹתָהּ. וְעַל זֶה כָּתוּב, בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת, אֲנִי אָקִים אֶת סֻכַּת דָּוִד. מִי זוֹ סֻכַּת דָּוִד? זוֹ בְּתוּלַת יִשְׂרָאֵל. הַנֹּפֶלֶת, כְּמוֹ שֶׁכָּתוּב נָפְלָה. וְזֶהוּ כְּבוֹדָהּ שֶׁל בְּתוּלַת יִשְׂרָאֵל וְתִשְׁבַּחְתָּהּ, וְזֶה לָמַדְנוּ בְּאוֹתָהּ שָׁעָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, וַדַּאי דִּבַּרְתָּ עַל לִבִּי וְהִתְיַשֵּׁב, וְזֶהוּ בֵּרוּר הַדָּבָר. וְזֶה הוֹלֵךְ כְּמוֹ דָבָר אֶחָד שֶׁשָּׁמַעְתִּי וְשָׁכַחְתִּי, וְעַכְשָׁו הִרְוַחְתִּי אוֹתוֹ. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יוֹסֵי, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַכְרִיז עַל כְּנֶסֶת יִשְׂרָאֵל וְיֹאמַר, (ישעיה נב) הִתְנַעֲרִי מֵעָפָר קוּמִי שְׁבִי יְרוּשָׁלם. כְּמִי שֶׁאוֹחֵז בִּידֵי חֲבֵרוֹ וְיֹאמַר: הִתְנַעֵר, קוּם! כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא יאחַז בָּהּ וְיֹאמַר: הִתְנַעֲרִי, קוּמִי!</p>\n<p>אָמַר לוֹ רַבִּי אָחָא, וְכָךְ כָּל אוֹתָם בְּנֵי הֵיכַל הַמֶּלֶךְ פּוֹתְחִים בְּלָשׁוֹן זֶה. זֶהוּ שֶׁכָּתוּב (שם ט) קוּמִי אוֹרִי כִּי בָא אוֹרֵךְ, הֲרֵי הַמֶּלֶךְ כָּאן, וַדַּאי שֶׁאָז הוּא הַכָּבוֹד שֶׁלָּהּ, וְשִׂמְחַת הַכֹּל כְּשֶׁהַמֶּלֶךְ מִתְפַּיֵּס עִמָּהּ. (כתוב (מלכים א א) ותבא בת שבע אל המלך החדרה, כמו זה) בְּכָל אוֹתָן הַפְּעָמִים הִיא בָּאָה אֶל הַמֶּלֶךְ וְעוֹמֶדֶת לְפָנָיו. זֶהוּ שֶׁכָּתוּב (מלכים א א) וַתָּבֹא לִפְנֵי הַמֶּלֶךְ, וַתַּעֲמֹד לִפְנֵי הַמֶּלֶךְ. אֲבָל בַּפַּעַם הַזּוֹ לֹא כָּךְ, אֶלָּא הַמֶּלֶךְ יֵלֵךְ אֵלֶיהָ וְיִתְפַּיֵּס עִמָּהּ וְיָשִׁיב אוֹתָהּ לְהֵיכָלוֹ. זֶהוּ שֶׁכָּתוּב הִנֵּה מַלְכֵּךְ יָבא לָךְ, וַדַּאי, וְלֹא אַתְּ אֵלָיו. יָבֹא לָךְ, לְפַיֵּס אוֹתָךְ. יָבֹא לָךְ, לְהָקִים אוֹתָךְ. יָבֹא לָךְ, לְהַשְׁלִים אוֹתָךְ בַּכֹּל. יָבֹא לָךְ, לְהַכְנִיס אוֹתָךְ לְהֵיכָלוֹ וּלְהִזְדַּוֵּג עִמָּךְ זִוּוּג עוֹלָמִים, כְּמוֹ שֶׁנֶּאֱמַר וְאֵרַשְׂתִּיךְ לִי בֶּאֱמוּנָה.</p>"],[9522011935,"<p>עֵד שֶׁהָיוּ הוֹלְכִים, פָּגַשׁ בָּהֶם רַבִּי אַבָּא. אָמְרוּ, הֲרֵי בַּעַל הַחָכְמָה בָּא, נְקַבֵּל פְּנֵי הַשְּׁכִינָה. כְּשֶׁקָּרְבוּ אֵלָיו, הִשְׁתַּמֵּט מֵהָאֻכָּף שֶׁהָיָה יוֹשֵׁב עָלָיו, וְיָרַד אֲלֵיהֶם.</p>\n<p>פָּתַח וְאָמַר, (שמות יט) וַיְהִי קוֹל הַשֹּׁפָר הוֹלֵךְ וְחָזֵק מְאֹד וְגוֹ'. וַיְהִי קוֹל הַשּׁפָר, כָּאן נֶחְלְקוּ סִפְרֵי הָרִאשׁוֹנִים, וְכֻלָּם בְּדָבָר אֶחָד נִתְקְעוּ. יֵשׁ מִי שֶׁאוֹמֵר, קוֹל הַשֹּׁפָר - שְׁנַיִם. קוֹל - אֶחָד. הַשֹּׁפָר - שְׁנַיִם. וְדִיֵּק זֶה מִשֶּׁלֹּא כָתוּב וַיְהִי הַשּׁוֹפָר הוֹלֵךְ וְחָזֵק, אֶלָּא קוֹל הַשּׁפָר, קוֹל שֶׁיּוֹצֵא מֵהַשּׁוֹפָר, שֶׁוַּדַּאי נִקְרָא שׁוֹפָר, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כז) יִתָּקַע בְּשׁוֹפָר גָּדוֹל, וְזֶהוּ שׁוֹפָר גָּדוֹל שֶׁבּוֹ יוֹצְאִים הָעֲבָדִים לְחֵרוּת עוֹלָמִים, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וְיִשִׁ מִי שֶׁשּׁוֹנֶה וּמְדַיֵּק שֶׁהַכֹּל אֶחָד, מִשּׁוּם שֶׁכָּתוּב קוֹל הַשֹּׁפָר, הַקּוֹל שֶׁנִּקְרָא שׁוֹפָר. וּמִנַּיִן לָנוּ שֶׁנִּקְרָא קוֹל? מִמַּה שֶּׁכָּתוּב (דברים ה) קוֹל גָּדוֹל וְלֹא יָסָף, וְהַקּוֹל הַגָּדוֹל הַזֶּה נִקְרָא שׁוֹפָר. וְעַל כֵּן, קוֹל הַשֹּׁפָר הוֹלֵךְ כָּתוּב. לְאָן הוֹלֵךְ? אִם תֹּאמַר לְהַר סִינַי אוֹ לְיִשְׂרָאֵל, אָז יוֹרֵד הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא הַתּוֹרָה יָצְאָה מִכָּאן. וּמֵהַמָּקוֹם הַזֶּה, שֶׁהוּא הַכְּלָל שֶׁל כָּל שְׁאָר הַקּוֹלוֹת, נִתְּנָה, וּכְשֶׁיִּסְתַּכְּלוּ בַדְּבָרִים, הַכֹּל אֶחָד.</p>\n<p>וְלָכֵן הַלּוּחוֹת הָרִאשׁוֹנִים הָיוּ רְשׁוּמִים מֵהַמָּקוֹם הַזֶּה, וְזֶהוּ סוֹד הַדָּבָר, שֶׁכָּתוּב (שמות לב) חָרוּת עַל הַלֻּחֹת. אַל תִּקְרֵי חָרוּת אֶלָּא חֵרוּת, חֵרוּת מַמָּשׁ, מָקוֹם שֶׁכָּל הַחֵרוּת תְּלוּיָה בּוֹ. וּבֹא רְאֵה, אֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁאוֹמְרִים כָּל הַחֲבֵרִים זֶה כָּךְ וְזֶה כָּךְ, שֶׁלֹּא הוֹלֵךְ הַכֹּל לְמָקוֹם אֶחָד וּמִתְכַּנֵּס לְמַעְיָן אֶחָד.</p>\n<p>הוֹלֵךָ, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם, וְכָתוּב הַכֹּל הוֹלֵךְ אֶל מָקוֹם אֶחָד. וְחָזֵק מְאֹד - כְּמוֹ שֶׁשָּׁנִינוּ, כְּלִי מַחֲזִיק אַרְבָּעִים סְאָה. וְחָזֵק מְאֹד - שֶׁאֵין לְךְ דָּבָר בַּתּוֹרָה חַלָּשׁ אוֹ שָׁבוּר, שֶׁכְּשֶׁתִּסְתַּכֵּל וְתַכִּיר אוֹתוֹ, שֶׁלֹּא תִמְצָא אוֹתוֹ חָזָק כְּפַטִּישׁ שֶׁשּׁוֹבֵר סְלָעִים. וְאִם זֶה חַלָּשׁ - זֶה מִמְּךְ, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (דברים לב) כִּי לֹא דָבָר רֵק הוּא, וְאִם רֵק הוּא - מִכֶּם הוּא. וְעַל זֶה וְחָזֵק מְאֹד.</p>"],[9522011936,"<p>כָּתוּב, (שמות יט) מֹשֶׁה יְדַבֵּר וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל. בַּמָּקוֹם הַזּה נִכְלְלוּ דְבָרִים עֶלְיוֹנִים, הֲרֵי פֵּרְשׁוּהָ וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל, בְּקוֹלוֹ שֶׁל מֹשֶׁה, בְּאוֹתוֹ קוֹל שֶׁאוֹחֵז בּוֹ מֹשֶׁה. כָּאן יֵשׁ לְהִתְבּוֹנֵן, שֶׁהֲרֵי הָפוּךְ הָיָה, שֶׁכָּתוּב (שם כ) וַיְדַבֵּר אֱלֹהִים, וְכָאן כָּתוּב מֹשֶׁה יְדַבֵּר.</p>\n<p>אֶלָּא יֵשׁ אוֹמְרִים, מִשּׁוּם שֶׁכָּתוּב וַיּאמְרוּ אֶל מֹשֶׁה דַּבֶּר אַתָּה עִמָּנוּ וְנִשְׁמָעָה וְאַל יְדַבֵּר עִמָּנוּ אֱלֹהִים. וְעַל זֶה מֹשֶׁה יְדַבֵּר, וְהָאֱלֹהִים יַעֲנֶנּוּ. מִשּׁוּם שֶׁלֹּא נִמְצָא דָבָר בַּתּוֹרָה מִפִּי מֹשֶׁה לְבַדּוֹ, וְזֶהוּ שֶׁבֵּאֲרוּהָ - קְלָלוֹת שֶׁבְּמִשְׁנֵה תוֹרָה, מֹשֶׁה מִפִּי עַצְמוֹ אָמַר אוֹתָן. מֵעַצְמוֹ לֹא שָׁנִינוּ, אֶלָּא מִפִּי עַצְמוֹ. הַלָּלוּ מִפִּי הַגְּבוּרָה, וְהַלָּלוּ מִפִּי עַצְמוֹ, מִפִּי אוֹתוֹ קוֹל שֶׁאָחַז בּוֹ שֶׁנִּקְרָא כָּךְ. וְהַדָּבָר יָפֶה.</p>\n<p>וּבְסֵפֶר הָאַגָּדָה שֶׁל בֵּית רַב אוֹמְרִים, אַף עַל גַּב שֶׁתּוֹרָה נֶאֶמְרָה כֻלָּהּ מִפִּי הַגְּבוּרָה - מִפִּי עַצְמוֹ שֶׁל מֹשֶׁה כְּמוֹ כֵן נֶאֶמְרָה. וּמִי הוּא? כְּמוֹ קְלָלוֹת שֶׁבְּמִשְׁנֵה תוֹרָה. וְאַחַר כָּךְ נִכְלְלוּ בַגְּבוּרָה. זֶהוּ שֶׁכָּתוּב מֹשֶׁה יְדַבֵּר וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל. מֹשֶׁה יְדַבֵּר - זֶה קוֹלוֹ שֶׁל מֹשֶׁה. וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל - זוֹ גְבוּרָה שֶׁמּוֹדָה לְאוֹתוֹ הַקּוֹל. זֶהוּ שֶׁכָּתוּב יַעֲנֶנּוּ בְקוֹל, בְּאוֹתוֹ קוֹל שֶׁל מֹשֶׁה. וְעַכְשָׁו מִי שֶׁפָּתַח בְּדִבְרֵי תוֹרָה, (אנחנו נחזיק תודות לו. אמרו נשב, ומי שפתח) יִפְתַּח וְיֹאמַר. יָשְׁבוּ.</p>"],[9522011937,"<p>פָּתַח רַבִּי אַבָּא וְאָמַר, כָּתוּב (ויקרא כב) וּבַת כֹּהֵן כִּי תִהְיֶה אַלְמָנָה וּגְרוּשָׁה וְזֶרַע אֵין לָהּ וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, שֶׁהֲרֵי כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, לֹא בָרָא אוֹתוֹ אֶלָּא בִּשְׁבִיל יִשְׂרָאֵל, כְּדֵי שֶׁיְּקַבְּלוּ תוֹרָה בְּהַר סִינַי וְיִטַּהֲרוּ בַכֹּל, וְיִמָּצְאוּ צַדִּיקִים לְפָנָיו.</p>\n<p>בֹּא רְאֵה, כְּשֶׁהֻשְׁלַם הָעוֹלָם הַזֶּה בְּיִשְׂרָאֵל כְּמוֹ שֶׁלְּמַעְלָה, וְאוֹתוֹ אָדָם נִנְעַץ בָּאָרֶץ, וְרוּמוֹ מַגִּיעַ עַד קְצֵה הַשָּׁמַיִם, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁלִים (להוציא) אֶת הַנְּשָׁמָה הַקְּדוֹשָׁה מִמַּעְלָה לְמַטָּה, כְּדֵי שֶׁיִּתְאַחֵז וְיִתְקַשֵּׁר זֶה בָּזֶה. זֶהוּ שֶׁכָּתוּב (בראשית ב) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וְגוֹ', לִהְיוֹת קָשׁוּר זֶה בָּזֶה, וְיִמָּצֵא שָׁלֵם כְּמוֹ שֶׁלְּמַעְלָה, וְיַשְׁלִים וִיתַקֵּן עַצְמוֹ כָּךְ.</p>\n<p>וּמִשּׁוּם כָּךְ בָּרָא אוֹתוֹ זָכָר וּנְקֵבָה, לִהְיוֹת שָׁלֵם. וּמָתַי נִקְרָא אָדָם שָׁלֵם כְּמוֹ שֶׁלְּמַעְלָה? בְּשָׁעָה שֶׁמִּזְדַּוֵּג עִם בַּת זוּגוֹ בְּאַחְדוּת וּבְשִׂמְחָה וּבְרָצוֹן, וְיוֹצִיא מִמֶּנּוּ וּמִנְּקֵבָתוֹ בֵּן וּבַת. וְאָז הוּא אָדָם שָׁלֵם כְּמוֹ שֶׁלְּמַעְלָה, וּמַשְׁלִים הוּא לְמַטָּה, כְּמוֹ שֶׁהַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, וְאָז נִקְרָא (יתקים) הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן עָלָיו.</p>\n<p>וְאָדָם שֶׁלֹּא רוֹצֶה לְהַשְׁלִים אֶת הַשֵּׁם הַקָּדוֹשׁ לְמַטָּה, טוֹב לוֹ שֶׁלֹּא נִבְרָא, שֶׁהֲרֵי אֵין לוֹ כְּלָל חֵלֶק בַּשֵּׁם הַקָּדוֹשׁ. וּכְשֶׁיּוֹצֵאת נִשְׁמָתוֹ מִמֶּנּוּ, לֹא נֶאֱחֶזֶת בּוֹ כְּלָל, שֶׁהֲרֵי הִקְטִין אֶת דְּיוֹקַן רִבּוֹנוֹ עַד שֶׁיִּתְקַשֵּׁר (שיחזר) וִיתֻקַּן בַּכֹּל.</p>\n<p>זְהִוּ שֶׁכָּתוּב, (ויקרא כב) וּבַת כֹּהֵן כִּי תִהְיֶה אַלְמָנָה וּגְרוּשָׁה וְגוֹ'. וּבַת כֹּהֵן - זוֹ הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁנִּקְרֵאת בַּת הַמֶּלֶךְ, שֶׁהֲרֵי פֵּרְשׁוּהָ שֶׁהַנְּשָׁמָה הַקְּדוֹשָׁה הִיא מִזִּוּוּג שֶׁל הַמֶּלֶךְ וְהַגְּבִירָה יוֹצֵאת. וּמִשּׁוּם כָּךְ, אֵיךְ שֶׁהַגּוּף שֶׁלְּמַטָּה הוּא מִזָּכָר וּנְקֵבָה, אַף כָּךְ הַנְּשָׁמָה לְמַעְלָה. כִּי תִהְיֶה אַלְמָנָה, מֵאוֹתוֹ הַגּוּף שֶׁהִזְדַּוְּגָה בּוֹ, וּמֵת. וּגְרוּשָׁה, שֶׁגֹּרְשָׁה מֵאוֹתוֹ הַחֵלֶק שֶׁל הַשֵּׁם הַקָּדוֹשׁ. וְכָל כָּךְ לָמָּה? מִשּׁוּם שֶׁזֶּרַע אֵין לָהּ לְהִמָּצֵא כְּמוֹ שֶׁלְּמַעְלָה וּלְהִתְקַשֵּׁר בַּשֵּׁם הַקָּדוֹשׁ. וְשָׁבָה אֶל בֵּית אָבִיהָ, מִי וְשָׁבָה? וְשָׁבָה סְתָם, לְהִתְתַּקֵּן כְּמוֹ מִקֹּדֶם. וְאָז וְשָׁבָה אֶל בֵּית אָבִיהָ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. כִּנְעוּרֶיהָ - כְּבָרִאשׁוֹנָה. מִלֶּחֶם אָבִיהָ תֹּאכֵל - לְהִתְעַנֵּג בָּעֹנֶג שֶׁל הַמֶּלֶךְ.</p>\n<p>מִכָּאן וָהָלְאָה - (שם) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. מִי הוּא הַזָּר? אוֹתוֹ שֶׁלֹּא (כבד) הֵקִים אֶת הַשֵּׁם הַקָּדוֹשׁ לְמַטָּה וְאֵין לוֹ בּוֹ חֵלֶק. לֹא יֹאכַל קֹדֶשׁ, אֵין בּוֹ חֵלֶק מֵהָעֹנֶג שֶׁלְּמַעְלָה שֶׁיֵּשׁ בּוֹ אֲכִילָה, שֶׁכָּתוּב (שיר ה) אִכְלוּ רֵעִים, אֲכִילָה שֶׁלְּמַעְלָה הִיא הָעֹנֶג שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהָעֹנֶג הַזֶּה שָׁרוּי בַּמָּקוֹם שֶׁשָּׁרוּי כַּאֲשֶׁר רֵיחַ הַקָּרְבָּן הָיָה עוֹלֶה.</p>"],[9522011938,"<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּמְצָא מָזוֹן לְמַטָּה, נִמְצָא מָזוֹן לְמַעְלָה. לְמֶלֶךְ שֶׁתִּקֵּן אֶת סְעוּדָתוֹ וְלֹא תִקֵּן לַעֲבָדָיו. כְּשֶׁתִּקֵּן לַעֲבָדָיו, הוּא אָכַל אֶת סְעוּדָתוֹ, וְהֵם אָכְלוּ אֶת סְעוּדָתָם. זֶהוּ שֶׁכָּתוּב (שם) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי - זוֹ סְעוּדַת הַמֶּלֶךְ. אִכְלוּ רֵעִים שְׁתוּ וְשִׁכְרוּ דּוֹדִים - זוֹ סְעוּדָתָם מֵרֵיחַ הַקָּרְבָּן, כְּשֶׁרֵיחַ הַקָּרְבָּן הָיָה עוֹלֶה, וּמִשּׁוּם כָּךְ נִקְרָא רֵיחַ נִיחֹחַ לַה'. רֵיחַ לַעֲבָדָיו, נִיחֹחַ לַה'. (ממקום הענג של העתיק נמצא) וְלָכֵן סְעוּדַת הַמֶּלֶךְ מִתְעַכֶּבֶת, בִּגְלַל סְעוּדָתָם שֶׁל עֲבָדָיו. וּמִשּׁוּם כָּךְ יִשְׂרָאֵל מְפַרְנְסִים אֶת אֲבִיהֶם שֶׁבַּשָּׁמַיִם שָׁנִינוּ. וּמִסְּעוּדַת הַמֶּלֶךְ מִי אוֹכֵל? אֶלָּא אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים.</p>"],[9522011939,"<p>עוֹד פָּתַח וְאָמַר, (תהלים קלג) הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁלֹּא נָתַן אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לְגָדוֹל אוֹ לְשָׁלִיחַ, אֶלָּא יִשְׂרָאֵל אֲחוּזִים בּוֹ, וְהוּא אָחוּז בָּהֶם, וּמֵחֲבִיבוּתָם קָרָא לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא עֲבָדִים, זֶהוּ שֶׁכָּתוּב (ויקרא כה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים עֲבָדַי הֵם. אַחַר כָּךְ קָרָא לָהֶם בָּנִים, זֶהוּ שֶׁכָּתוּב בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. אַחַר כָּךְ קָרָא לָהֶם אַחִים, זֶהוּ שֶׁכָּתוּב לְמַעַן אַחַי וְרֵעָי וְגוֹ'. וּמִשּׁוּם שֶׁקָּרָא לָהֶם אַחִים, רָצָה לָשִׂים אֶת מְדוֹרוֹ בָהֶם וְלֹא יָסוּר מֵהֶם, וְאָז כָּתוּב הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד.</p>"],[9522011940,"<p>וְהַמְּנוֹרָה הַקְּדוֹשָׁה כָּךְ אָמַר, הִנֵּה מַה טּוֹב וּמַה נָּעִים וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר (ויקראכ) וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחֹתוֹ. וּבְסִפְרוֹ שֶׁל רַב יֵיבָא סָבָא, וְאִישׁ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. אֲשֶׁר יִקַּח אֶת אֲחֹתוֹ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְכָל כָּךְ לָמָּה? חֶסֶד הוּא, חֶסֶד הוּא וַדַּאי, וַהֲרֵי פֵּרְשׁוּהָ. וְלָכֵן, הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד - הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל. גַּם - לְרַבּוֹת יִשְׂרָאֵל שֶׁלְּמַטָּה, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁהֲרֵי בְּשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל (באחוה באחדות) בְּאַחְדוּת עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, יִשְׂרָאֵל שֶׁלְּמַטָּה שְׁרוִּים בְּשִׂמְחָה גַּם הֵם עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִשּׁוּם כָּךְ כָּתוּב גַּם יָחַד. וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, גַּם יָחַד - לְרַבּוֹת צַדִּיק. בָּהּ, בִּכְנֶסֶת יִשְׂרָאֵל, שֶׁהֵם זִוּוּג אֶחָד, וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>וְשָׁנִינוּ בְּפָרָשַׁת שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, מַהוּ אֶחָד? זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁאֲחוּזָה בַּקָּדוֹשׁ- בָּרוּךְ-הוּא. שֶׁאָמַר רַבִּי שִׁמְעוֹן, זִוּוּג שֶׁל זָכָר וּנְקֵבָה נִקְרָא אֶחָד. בְּמָקוֹם שֶׁהַנְּקֵבָה שׁוֹרָה, אֶחָד נִקְרָא. מָה הַטַּעַם? בִּגְלַל שֶׁזָּכָר בְּלִי נְקֵבָה נִקְרָא חֲצִי גוּף, וַחֲצִי אֵינוֹ אֶחָד. וּכְשֶׁמִּתְחַבְּרִים כְּאֶחָד שְׁנֵי חֲצָאֵי גוּף, נַעֲשִׂים גּוּף אֶחָד, וְאָז נִקְרָא אֶחָד.</p>\n<p>וְעַכְשָׁו הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נִקְרָא אֶחָד. וְסוֹד הַדָּבָר - כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָלָה לְמַעְלָה לְמַעְלָה, וְהַזִּוּוּג נִפְרד, וְהַשֵּׁם הַקָּדוֹשׁ לֹא נִמְצָא שָׁלֵם וְלֹא נִקְרָא אֶחָד. וּמָתַי יִקָּרֵא אֶחָד? בְּשָׁעָה שֶׁהַגְּבִירָה תִּמָּצֵא עִם הַמֶּלֶךְ וְיִזְדַּוְּגוּ כְאֶחָד. זֶהוּ שֶׁכָּתוּב (עובדיה א) וְהָיְתָה לַה' הַמְּלוּכָה. מִי הַמְּלוּכָה? זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁהַמַּלְכוּת קְשׁוּרָה בָּהּ, אָז (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. וְעַל זֶה, הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד.</p>\n<p>כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ. מִי שֶׁמֶן הַטּוֹב? זֶה שֶׁמֶן מִשְׁחַת קֹדֶשׁ שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵהָעַתִּיק הַקָּדוֹשׁ שֶׁנִּמְצָא בְּאוֹתוֹ נָהָר עֶלְיוֹן, שֶׁמֵּינִיק אֶת הַבָּנִים לְהַדְלִיק מְנוֹרוֹת, וְאוֹתוֹ שֶׁמֶן שׁוֹפֵעַ עַל רֹאשׁ הַמֶּלֶךְ, וּמֵרֹאשׁוֹ לַכָּבוֹד שֶׁל הַזָּקָן הַקָּדוֹשׁ, וּמִשָּׁם שׁוֹפֵעַ לְכָל אוֹתָם לְבוּשֵׁי כָבוֹד שֶׁהַמֶּלֶךְ מִתְלַבֵּשׁ בָּהֶם. זֶהוּ שֶׁכָּתוּב שֶׁיּוֹרֵד עַל פִּי מִדּוֹתָיו. עַל פִּי מִדּוֹתָיו מַמָּשׁ, וְאֵלּוּ הֵם כִּתְרֵי הַמֶּלֶךְ שֶׁהַשֵּׁם הַקָּדוֹשׁ נִמְצָא בָהֶם.</p>\n<p>בֹּא רְאֵה, כָּל הַשֶּׁפַע וְכָל שִׂמְחַת הָעוֹלָמוֹת לֹא יוֹרְדִים לְבָרֵךְ אֶלָּא עַל יְדֵי הַכְּתָרִים הַקְּדוֹשִׁים הַלָּלוּ, שֶׁהֵם שְׁמוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ, וּמִשּׁוּם כָּךְ שֶׁיּוֹרֵד עַל פִּי מִדּוֹתָיו. עַל פִּי מִדּוֹתָיו וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר (במדבר ד) עַל פִּי אַהֲרֹן וּבָנָיו תִּהְיֶה. כָּךְ עַל פִּי מִדּוֹתָיו יוֹרֵד וּמַשְׁפִּיעַ לְכָל הָעוֹלָמוֹת, לְהַמְצִיא בְרָכוֹת לְכֻלָּם. וּבא רְאֵה, הַשֶּׁמֶן הַטּוֹב הַזֶּה אֵינוֹ זָמִין, עַד אוֹתוֹ זְמַן שֶׁהָעֲבוֹדָה שֶׁלְּמַטָּה הָיְתָה עוֹלָה וְנִפְגָּשִׁים זֶה בָּזֶה. זֶהוּ שֶׁכָּתוּב (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. שֶׁמֶן לְמַעְלָה וּקְטֹרֶת לְמַטָּה, אֲזַי זוֹ שִׂמְחַת הַכֹּל. רַבִּי אָחָא וְרַבִּי יְהוּדָה זָקְפוּ יָדַיִם, וְהוֹדוּ לְרַבִּי אַבָּא.</p>"],[9522011941,"<p>רַבִּי אָחָא פָּתַח, (בראשית כ) וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ בַּחֲלוֹם הַלָּיְלָה, וְכָתוּב וַיֹּאמֶר אֵלָיו הָאֱלֹהִים בַּחֲלֹם גַּם אָנֹכִי יָדַעְתִּי כִּי בְתָם לְבָבְךְ עָשִׂיתָ זֹּאת. וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ הַזֶּה, מַה שּׁוֹנֶה בְּאֻמּוֹת הָעוֹלָם וַיָּבֹא אֱלֹהִים, וּלְיִשְׂרָאֵל לֹא? (אלא זהו סוד של אלהים אחרים. ויש לך לדעת שהשם של הקדוש ברוך הוא (ישעיה נז) רם ונשא שכן עד וקדוש שמו, והוא לבדו מלך על כל מה שנמצא, בין למעלה בין למטה, וההיכל הקדוש שלו באמצע נתקן, וסביבו יש שבעים כתרים, ומהם נמשכו שבעים גדולים, והפקדו על שבעים עמי העולם להיות כל אחד ואחד שולט על עמו ועל ארצו. והקדוש ברוך הוא נתן לישראל סוד של שמו להם בלבד והוא שולט על ישראל וירושלים זהו שכתוב (דניאל ט') כי שמך נקרא על עירך ועל עמך. ואין לעם אחר חלק בו בקדוש'ברוך' הוא שכתוב (דברים כ\"ד) וראו כל עמי הארץ כי שם יי' נקרא עליך. וכתוב (מיכה ד') כי כל העמים ילכו איש בשם אלהיו וגו'. וכתוב (דברים ל\"ב) כי חלק יי' עמו וגו') אֶלָּא כָּךְ שָׁנִינוּ, כָּל אֱלֹהִים שֶׁל כָּאן, אוֹתוֹ כֹּחַ גָּדוֹל שֶׁמְּמֻנֶּה עֲלֵיהֶם הָיָה, כְּמוֹ כֵן - וַיָּבא אֱלֹהִים אֶל בִּלְעָם לַיְלָה, אוֹתוֹ כֹּחַ שֶׁמֻּפְקָד עָלָיו.</p>\n<p>וְאִם תֹּאמַר, וַיֹּאמֶר אֵלָיו הָאֱלֹהִים בַּחֲלֹם - כָּךְ זֶה וַדַּאי. גַּם אָנֹכִי יָדַעְתִּי, לָמָּה כָּאן גַּם? אֶלָּא שֶׁבָּא לְרַבּוֹת, שֶׁאַף עַל גַּב שֶׁלְּמַעְלָה מִמֶּנִּי יָדוּעַ, גַּם אָנֹכִי יָדַעְתִּי. וָאֶחְשֹׂךְ גַּם אָנֹכִי - גַּם לְרַבּוֹת - אוֹתְךְ מֵחֲטוֹ לִי. מֵחֲטוֹ חָסֵר אָלֶ\"ף כָּתוּב. מָה אָמַר? מִשּׁוּם שֶׁחֵטְא אֵינוֹ עוֹמֵד בְּכֹחַ.</p>\n<p>אֶלָּא כָּךְ לָמַדְנוּ, בַּחֲטָאֵי הָעָם שֶׁלְּמַטָּה נִפְגָּם לְמַעְלָה. בַּחֲטָאֵי הָעָם שֶׁלְּמַטָּה מָעֳבָר הַגָּדוֹל שֶׁלָּהֶם שֶׁלְּמַעְלָה מִשִּׁלְטוֹנוֹ. זֶהוּ שֶׁכָּתוּב וָאֶחְשּךְ גַּם אָנֹכִי אוֹתְךְ, שֶׁאַף עַל גַּב שֶׁלְּמַעְלָה מִמֶּנִּי תָּלוּי הַדָּבָר - גַּם אָנֹכִי, לְרַבּוֹת לְעַצְמוֹ, מֵחֲטוֹ לִי, כְּדֵי שֶׁלֹּא יִמָּצְאוּ אֶצְלִי, כְּמוֹ הַמַּחַט הַזּוֹ הַנְּעוּצָה בַּבָּשָׂר, שֶׁלֹּא תִגְרֹם לִי אַתָּה בְּחֶטְאֲךְ לְהַעֲבִיר אוֹתִי מִשִּׁלְטוֹנִי וְיָקוּצוּ בִי, שֶׁלֹּא תָקֹץ אוֹתִי בְּמַחַטְךְ, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כ) וָאָקֻץ בָּם, כְּמוֹ הַקּוֹצִים הַלָּלוּ שֶׁנְּעוּצִים בַּבָּשָׂר. מַה מַּשְׁמִיעַ? מַשְׁמִיעַ שֶׁבַּחֲטָאֵי בְּנֵי אָדָם נַעֲשִׂים פְּגָמִים לְמַעְלָה. מַה הוּא? כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נ) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם.</p>\n<p>וְעַל כֵּן נִקְרָב קָרְבָּן, אֵיזֶה קָרְבָּן? זֶה שֶׁאָמַרְנוּ שֶׁכָּתוּב, וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. שֶׁהֲרֵי הַחֵטְא גּוֹרֵם פֵּרוּד בְּחֶטְאוֹ. הַקָּרְבָּן מְקָרֵב אֶת הָעוֹלָם הָעֶלְיוֹן לָעוֹלָם הַתַּחְתּוֹן, וְהַכֹּל נַעֲשֶׂה אֶחָד. בָּאוּ רַבִּי אַבָּא וְרַבִּי יְהוּדָה וְהוֹדוּ לוֹ לְרַבִּי אָחָא.</p>"],[9522011942,"<p>פָּתַח רַבִּי יְהוּדָה וְאָמַר, (תהלים ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה וְגוֹ'. עִבְדוּ אֶת ה' בְּשִׂמְחָה, כָּךְ לָמַדְנוּ, שֶׁכָּל עֲבוֹדָה שֶׁצָּרִיךְ אָדָם לַעֲבֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, צָרִיךְ בְּשִׂמְחָה וּבִרְצוֹן הַלֵּב, כְּדֵי שֶׁתִּמָּצֵא עֲבוֹדָתוֹ בִּשְׁלֵמוּת. וְאִם תֹּמַר שֶׁעֲבוֹדַת הַקָּרְבָּן כָּךְ הִיא - אִי אֶפְשָׁר! שֶׁהֲרֵי אוֹתוֹ אָדָם שֶׁעָבַר עַל מִצְוַת רִבּוֹנוֹ וְעַל מִצְוַת הַתּוֹרָה וְשָׁב לִפְנֵי רִבּוֹנוֹ, בְּאֵיזֶה פָנִים יַעֲמֹד לְפָנָיו? הֲרֵי וַדַּאי בְּרוּחַ שְׁבוּרָה, בְּרוּחַ עֲצוּבָה, אֵיפֹה הַשִּׂמְחָה? אֵיפֹה הָרְנָנָה?</p>\n<p>אֶלָּא שָׁם שָׁנִינוּ, אוֹתוֹ אָדָם שֶׁחוֹטֵא לִפְנֵי רִבּוֹנוֹ וְעָבַר עַל מִצְווֹתָיו, וּבָא לְהַקְרִיב קָרְבָּן וּלְתַקֵּן אֶת עַצְמוֹ בְּרוּחַ שְׁבוּרָה, צָרִיךְ לְהִמָּצֵא בְּרוּחַ עֲצוּבָה. וְאִם הוּא בּוֹכֶה, זֶה יָפֶה מֵהַכֹּל. הֲרֵי שִׂמְחָה וַהֲרֵי רְנָנָה אֵין נִמְצָאִים. אֶלָּא בַּמֶּה מִתְתַּקֵּן? בְּאוֹתָם כֹּהֲנִים וּלְוִיִּם, שֶׁהֲרֵי הֵם מַשְׁלִימִים שִׂמְחָה וּרְנָנָה בִּשְׁבִילוֹ. הַשִּׂמְחָה מִתְקַיֶּמֶת בְּכֹהֵן, מִשּׁוּם שֶׁהוּא תָמִיד רָחוֹק מִן הַדִּין, וְהַכֹּהֲנִים צְרִיכִים תָּמִיד לְהִמָּצֵא בְּפָנִים מְאִירוֹת, שְׂמֵחִים יוֹתֵר מִכָּל הָעָם, שֶׁהֲרֵי הַכֶּתֶר שֶׁלּוֹ גּוֹרֵם הָרְנָנָה בַּלְוִיִּם, וְכָךְ זֶה, שֶׁהֲרֵי הַלְוִיִּם נִמְצָאִים תָּמִיד עַל הַשִּׁיר, כְּמוֹ שֶׁבֵּאֲרוּהָ.</p>\n<p>וְאֵלּוּ עוֹמְדִים עָלָיו, וּבָהֶם נִשְׁלֶמֶת הָעֲבוֹדָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא. הַכֹּהֵן עוֹמֵד עָלָיו וּמְכַוֵּן דְּבָרִים בְּשִׂמְחָה וּבְרָצוֹן, לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, וְהַלְוִיִּם בְּשִׁיר. אָז כָּתוּב, דְּעוּ כִּי ה' הוּא אֱלֹהִים. זֶהוּ קָרְבָּן לְקָרֵב רַחֲמִים לְדִין, וְהַכֹּל מִתְבַּשֵּׂם.</p>\n<p>עֵכְשָׁו שֶׁלֹּא נִמְצָא קָרְבָּן, מִי שֶׁחוֹטֵא לִפְנֵי רִבּוֹנוֹ וְשָׁב אֵלָיו, וַדַּאי בִּמְרִירוּת הַנֶּפֶשׁ, בְּעֶצֶב, בִּבְכִיָּה, בְּרוּחַ שְׁבוּרָה, אֵיךְ מֵקִים שִׂמְחָה וּרְנָנָה? הֲרֵי אֵין הֵם נִמְצָאִים אֶצְלוֹ? אֶלָּא כָּךְ פֵּרְשׁוּהָ, שֶׁתִּשְׁבְּחוֹת רִבּוֹנוֹ וְשִׂמְחַת הַתּוֹרָה וְרִנְנוֹת הַתּוֹרָה, זוֹהִי שִׂמְחָה וּרְנָנָה. וַהֲרֵי שָׁנִינוּ, וְלֹא מִתּוֹךְ עַצְבוּת וְכוּ', שֶׁלֹּא יַעֲמֹד אָדָם לִפְנֵי רִבּוֹנוֹ בְּעַצְבוּת, וַהֲרֵי לֹא יָכוֹל, אָז מַה תַּקָּנָתוֹ?</p>\n<p>אֶלָּא סוֹד הַדָּבָר, הֲרֵי שָׁנִינוּ, לְעוֹלָם יִכָּנֵס אָדָם שִׁעוּר שְׁנֵי פְתָחִים וְכוּ', וְיִתְפַּלֵּל תְּפִלָּתוֹ. זֶהוּ שֶׁכָּתוּב (משלי ח) לִשְׁמֹר מְזוּזֹת פְּתָחָי. הֶחָשַׁבְתָּ שְׁנֵי פְתָחִים? אֶלָּא אֱמֹר, שִׁעוּר שְׁנֵי פְתָחִים. כָּאן רֶמֶז לְמַה שֶּׁאָמַר דָּוִד (תהלים כד), שְׁאוּ שְׁעָרִים רָאשֵׁיכֶם. הֵם מָעוֹן וּמָכוֹן, שֶׁהֵם לִפְנַי וְלִפְנִים. רֵאשִׁית הַדְּרָגוֹת - חֶסֶד וּפַחַד, וְהֵם הַפְּתָחִים שֶׁל הָעוֹלָם. עַל כֵּן צָרִיךְ אָדָם לְהִתְכַּוֵּן בִּתְפִלָּתוֹ כְּנֶגֶד קֹדֶשׁ הַקְּדָשִׁים, שֶׁהֵם הַשֵּׁם הַקָּדוֹשׁ, וְיִתְפַּלֵּל תְּפִלָּתוֹ, וְאֵלֶּה הֵם שִׁעוּר שְׁנֵי פְתָחִים, שְׁנֵי כְתָרִים.</p>\n<p>וְיִשִׁ שֶׁשּׁוֹנֶה כָּךְ: שִׂמְחָה זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְשִׂמְחָה הֲרֵי פֵּרְשׁוּהָ, כַּכָּתוּב (ישעיה נה) כִּי בְשִׂמְחָה תֵצֵאוּ וְגוֹ'. וַעֲתִידִים יִשְׂרָאֵל לָצֵאת מֵהַגָּלוּת בַּשִּׂמְחָה הַזּוֹ, וּמִי זוֹ? כְּנֶסֶת יִשְׂרָאֵל. וְלָכֵן עִבְדוּ אֶת ה' בְּשִׂמְחָה, כְּמוֹ שֶׁכָּתוּב (ויקרא טז) בזאת יבא אהרן אל הקדש, והכל אחד.</p>\n<p>בֹּאוּ לְפָנָיו בִּרְנָנָה - זוֹ הַשְּׁלֵמוּת שֶׁלָּהּ. שֶׁל שִׂמְחָה בַּלֵּב, וּרְנָנָה בַּפֶּה. וְזוֹהִי שְׁלֵמוּת יְתֵרָה. וְהַשְּׁלֵמוּת שֶׁל הַשִּׂמְחָה הַזּוֹ הֲרֵי יְדוּעָה וְנוֹדַעַת, וְזֶהוּ הַתִּקּוּן שֶׁל הָאָדָם לִפְנֵי רִבּוֹנוֹ, וְאָז - דְּעוּ כִּי ה' הוּא הָאֱלֹהִים. וְהַכֹּל בָּא בְּדָבָר אֶחָד, שֶׁצָּרִיךְ אַחַר כָּךְ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי וְלִקְשֹׁר זֶה בָּזֶה לִהְיוֹת הַכֹּל אֶחָד, וְזוֹהִי עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמְרוּ לוֹ רַבִּי אָחָא וְרַבִּי אַבָּא, וַדַּאי כָּךְ הוּא. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. קָמוּ וְהָלְכוּ אַחֲרֵי רַבִּי אַבָּא שְׁלֹשָׁה מִילִין.</p>"],[9522011943,"<p>פָּתַח רַבִּי אַבָּא וְאָמַר, (תהלים ה) וַאֲנִי בְּרֹב חַסְדֶּךְ אָבוֹא בֵיתֶךְ. כָּךְ פֵּרְשׁוּהָ, שֶׁלֹּא צָרִיךְ אָדָם לְהִכָּנֵס לְבֵית הַכְּנֶסֶת אֶלָּא אִם נִמְלַךְ בָּרִאשׁוֹנָה בְּאַבְרָהָם וְיִצְחָק וְיַעֲקֹב, מִשּׁוּם שֶׁהֵם תִּקְּנוּ אֶת הַתְּפִלָּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב וַאֲנִי בְּרֹב חַסְדֶּךְ אָבוֹא בֵיתֶךְ. אָבוֹא בֵיתֶךְ - זֶה אַבְרָהָם. אֶשְׁתַּחֲוֶה אֶל הֵיכַל קָדְשֶׁךְ - זֶה יִצְחָק. בְּיִרְאָתֶךְ - זֶה יַעֲקֹב. (ואני ברב חסדך זה יעקב. אשתחוה אל היכל קדשך זהיצחק) וְצָרִיךְ לְהַכְלִילָם בַּתְּחִלָּה, וְיִכָּנֵס לְבֵית הַכְּנֶסֶת וְיִתְפַּלֵּל תְּפִלָּתוֹ. אָז כָּתוּב, (ישעיה מט) וַיּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>"],[9522011944,"<p>אִם עֹלָה קָרְבָּנוֹ מִן הַבָּקָר. אָמַר רַבִּי יוֹסֵי, מַה שּׁוֹנֶה מִן הַבָּקָר לְעוֹלָה וּמִן הַצּאן לְעוֹלָה וּמִן הָעוֹף לְעוֹלָה? אִם הַכֹּל אֶחָד, מִפְּנֵי מָה שׁוֹנִים זֶה מִזֶּה, שֶׁהֲרֵי מֵהַכֹּל נַעֲשֶׂה דָבָר אֶחָד? אֶלָּא מִי שֶׁהִשִּׂיגָה יָדוֹ אֶת זֶה - מַקְרִיב מִן הַבָּקָר, וְאִם לֹא יָכוֹל - אָז מִן הַצּאן, וְאִם לֹא יָכוֹל - אָז מִן הָעוֹף, שֶׁהֲרֵי כָּתוּב (ויקרא יד) וְאִם דַּל הוּא וְאֵין יָדוֹ מַשֶּׂגֶת, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אֵין מַטְרִיחַ עַל הָאָדָם יוֹתֵר בְּדָבָר שֶׁלֹּא יָכוֹל.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כְּמוֹ שֶׁהָיָה הַחֵטְא - כָּךְ הָיָה מַקְרִיב. עָשִׁיר, שֶׁלִּבּוֹ גַּס בּוֹ לִפְעָמִים, הָיָה מַקְרִיב שׁוֹר, מִשּׁוּם שֶׁלִּבּוֹ חוֹשֵׁב יוֹתֵר לַחֲטֹא לִפְנֵי רִבּוֹנוֹ. הַבֵּינוֹנִי מַקְרִיב מִן הַצֹּאן, מִשּׁוּם שֶׁרְצוֹנוֹ אֵינוֹ גַס בּוֹ כָּל כָּךְ לַחֲטֹא. הֶעָנִי שֶׁלִּבּוֹ לֹא גַס בּוֹ, רְצוֹנוֹ נָמוּךְ מֵהַכֹּל, מַקְרִיב מֵאוֹתוֹ הַקַּל מֵהַכֹּל. וְנוֹדְעוּ הַקָּרְבָּנוֹת שֶׁלָּהֶם לְכֻלָּם, כָּל אֶחָד וְאֶחָד לְבַדָּם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא דָּן דִּינוֹ שֶׁל כָּל אֶחָד וְאֶחָד בְּמִשְׁקָל יָשָׁר.</p>\n<p>רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו, אָמַר לוֹ, הֲרֵי שָׁנִינוּ שֶׁעַל שְׁלֹשָׁה חֲטָאֵי הָעוֹלָם הָרָעָב בָּא לָעוֹלָם, וְכָל הַחֲטָאִים אֵינָם נִמְצָאִים אֶלָּא רַק בָּעֲשִׁירִים, מִשּׁוּם שֶׁלִּבָּם גַּס בָּהֶם, וְלֹא נִמְצָאִים בָּעֲנִיִּים. מָה הַדִּין? שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַהֲרֹג אֶת הָעֲנִיִּים וְיַעֲמִיד אֶת הָעֲשִׁירִים?! שֶׁהֲרֵי מֵעַכְשָׁו יוֹסִיפוּ לַחֲטֹא לְפָנָיו! אָמַר לוֹ, יָפֶה שָׁאַלְתָּ, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים וְאָמְרוּ, כְּשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִפָּרַע מֵהָרְשָׁעִים וּלְאַבְּדָם מִן הָעוֹלָם, אֲזַי נוֹתֵן לָהֶם שָׁלוֹם וּמַשְׁלִים לָהֶם בַּכֹּל.</p>\n<p>אֲבָל בֹּא וּרְאֵה שֶׁכָּל בְּנֵי הָעוֹלָם לֹא נִמְצָאִים קְרוֹבִים לַמֶּלֶךְ הָעֶלְיוֹן, כַּכֵּלִים הַלָּלוּ שֶׁהוּא מִשְׁתַּמֵּשׁ בָּהֶם, וּמִי הֵם? (תהלים נה) לֵב נִשְׁבָּר וְנִדְכֶּה. (ישעיה נז) וְאֶת דַּכָּא וּשְׁפַל רוּחַ. אֵלּוּ הֵם כְּלֵי הַמֶּלֶךְ. וּכְשֶׁנִּמְצֵאת בַּצֹּרֶת בָּעוֹלָם וְהָרָעָב וְהַדִּין מִתְחַזְּקִים עַל הָעֲנִיִּים, אֲזַי בּוֹכִים וְגוֹעִים לִפְנֵי הַמֶּלֶךְ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְקָרֵב אוֹתָם יוֹתֵר מֵהַכֹּל. זֶהוּ שֶׁכָּתוּב (תהלים כב) כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת עָנִי. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא פּוֹקֵד עַל מַה בָּא הָרָעָב לָעוֹלָם. אוֹי לְאוֹתָם הָרְשָׁעִים שֶׁגָּרְמוּ לָזֶה.</p>\n<p>כְּשֶׁמִּתְעוֹרֵר הַמֶּלֶךְ לְהַשְׁגִּיחַ בָּעוֹלָם עַל קוֹלוֹת הָעֲנִיִּים, הָרַחֲמָן יַצִּילֵנוּ מֵהֶם וּמֵעֶלְבּוֹנָם, אָז כָּתוּב (שמות כב) שָׁמוֹעַ אֶשְׁמַע צַעֲקָתוֹ. שָׁמוֹעַ אֶשְׁמַע - שְׁתֵּי פְעָמִים, אַחַת לְהַשְׁגִּיחַ עַל קוֹלָם, וְאַחַת לְהִפָּרַע מֵאוֹתָם שֶׁגּוֹרְמִים לָהֶם אֶת זֶה. זֶהוּ שֶׁכָּתוּב וְשָׁמַעְתִּי כִּי חַנּוּן אָנִי וְחָרָה אַפִּי וְגוֹ'. וְלָכֵן בְּשָׁעָה שֶׁרָעָב נִמְצָא בָעוֹלָם, אוֹי לְאוֹתָם הָעֲשִׁירִים הָרְשָׁעִים, מִשּׁוּם קוֹלָם שֶׁל הָעֲנִיִּים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בֹּא וּרְאֵה שֶׁאוֹתוֹ קָרְבָּן שֶׁל הֶעָנִי קַל מֵהַכֹּל, מִשּׁוּם שֶׁלִּבּוֹ שָׁבוּר, וְאַף עַל גַּב שֶׁחוֹשֵׁב לַחֲטֹא, זֶה עוֹבֵר מִמֶּנּוּ, שֶׁהֲרֵי דַּי לוֹ בְּצַעֲרוֹ וְשֶׁל אַנְשֵׁי בֵיתוֹ. וְלָכֵן כָּל קָרְבָּן וְקָרְבָּן, כָּל אֶחָד וְאֶחָד לְבַדּוֹ, כֻּלָּם יְדוּעִים אֵצֶל הַכֹּהֵן.</p>\n<p>מַעָשֶׂה בְאוֹתוֹ עָשִׁיר שֶׁהִקְרִיב לִפְנֵי הַכֹּהֵן שְׁנֵי יוֹנִים. כְּשֶׁרָאָה אוֹתוֹ הַכֹּהֵן, אָמַר לוֹ, הַקָּרְבָּן הַזֶּה אֵינוֹ שֶׁלְּךְ. הָלַךְ לְבֵיתוֹ וְהָיָה עָצוּב. אָמְרוּ לוֹ אֶחָיו, לָמָּה אַתָּה עָצוּב? אָמַר לָהֶם, שֶׁהַכֹּהֵן לֹא הִקְרִיב אֶת קָרְבָּנִי. אָמְרוּ לוֹ, וּמַה הוּא? אָמַר לָהֶם, שְׁנֵי יוֹנִים. אָמְרוּ לוֹ, וַהֲרֵי זֶה שֶׁל עָנִי, וְלֹא שֶׁלְּךְ! שֶׁהֲרֵי כָּתוּב, וְאִם דַּל הוּא וְאֵין יָדוֹ מַשֶּׂגֶת וְגוֹ', אֶלָּא הַקְרֵב קָרְבָּנְךְ. אָמַר לָהֶם, וּמַה הוּא? אָמְרוּ לוֹ, שׁוֹר אֶחָד.</p>\n<p>אָמַר לָהֶם, וּמַה כָּל כָּךְ חֲמוּרָה מַחֲשֶׁבֶת הַחֵטְא? נָדַרְתִּי שֶׁלֹּא אַעֲלֶה עַל לִבִּי מַחֲשֶׁבֶת חֵטְא. מִשָּׁם וָהָלְאָה מֶה עָשָׂה? כָּל יוֹם הִתְעַסֵּק בִּסְחוֹרָה, וּבַלַּיְלָה הָיָה יָשֵׁן. כְּשֶׁהִתְעוֹרֵר, הָיָה קוֹרֵא לְאֶחָיו, וְלִמְּדוּ אוֹתוֹ דִּבְרֵי תוֹרָה, וְהָיָה לוֹמֵד עַד שֶׁיַּעֲלֶה הַיּוֹם, וְנִמְצָא שֶׁלָּמַד תּוֹרָה, וְהָיוּ קוֹרְאִים לוֹ יְהוּדָה הָאַחֵר. יוֹם אֶחָד פָּגַשׁ בּוֹ רַבִּי יֵיסָא סָבָא, וְהָיָה מַפְרִישׁ נְכָסָיו, חֲצִי לַעֲנִיִּים וַחֲצִי לִסְחוֹרָה עַל הַיָּם עִם אוֹתָם אֲנָשִׁים שֶׁפּוֹרְשִׁים לַיַּמִּים, וְהָיָה יוֹשֵׁב וְלוֹמֵד תּוֹרָה.</p>\n<p>פָּתַח וְאָמַר, (שמואל א טו) וַיֹּאמֶר שָׁאוּל אֶל הַקֵּינִי. מִי הוּא הַקֵּינִי? אֵלּוּ בְּנֵי יִתְרוֹ, חָמִיו שֶׁל מֹשֶׁה, שֶׁעָשׂוּ קֵן בַּמִּדְבָּר כְּמוֹ הַדְּרוֹר הַזֶּה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פב) וּדְרוֹר קֵן לָהּ, כְּדֵי לִלְמֹד תּוֹרָה. שֶׁתּוֹרָה לֹא צְרִיכָה תַפְנוּקִים וְלֹא סְחוֹרָה, אֶלָּא לַעֲמֹל בָּהּ יוֹמָם וָלַיְלָה. מִשּׁוּם כָּךְ נָסְעוּ לַמִּדְבָּר מֵהָעֹנֶג שֶׁל יְרִיחוֹ. זֶהוּ שֶׁכָּתוּב (שופטים א) וּבְנֵי קֵינִי חֹתֵן מֹשֶׁה עָלוּ מֵעִיר הַתְּמָרִים וְגוֹ'.</p>\n<p>וְאַתָּה עָשִׂיתָ חֶסֶד עִם כָּל בְּנֵי יִשְׂרָאֵל. מִשּׁוּם שֶׁנָּתַן לְמֹשֶׁה לֵהָנוֹת בְּבֵיתוֹ, וּמֹשֶׁה הָיָה כְּלָל שֶׁל כָּל יִשְׂרָאֵל. וְעוֹד, מִשּׁוּם שֶׁלִּמֵּד פָּרָשָׁה אַחַת יוֹתֵר בַּתּוֹרָה, וּבָזֶה עָשָׂה חֶסֶד עִם יִשְׂרָאֵל.</p>\n<p>לָמָּה בָּא הַדָּבָר הַזֶּה כָּאן בְּמִלְחֶמֶת עֲמָלֵק? אֶלָּא אָמַר שָׁאוּל, כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, מִכָּל שְׁאָר אֻמּוֹת הָעוֹלָם לֹא הָיָה מִי שֶׁיִּזְדַּוֵּג עִם יִשְׂרָאֵל לְקַטְרֵג לָהֶם, אֶלָּא רַק עֲמָלֵק, וְהוּא עָשָׂה רַע לְיִשְׂרָאֵל וְעָרַךְ בָּהֶם קְרָב, וְאַתָּה הִקְדַּמְתָּ לָהֶם שָׁלוֹם וְעָשִׂיתָ חֶסֶד עִם כֻּלָּם, וּמִשּׁוּם כָּךְ אֵין אַתָּה כְּדַאי לְהִתְחַבֵּר עִמָּהֶם.</p>\n<p>וְלֹא עוֹד, אֶלָּא מַה כָּתוּב בְּיִתְרוֹ? (שמות יח) וַיִּקַּח יִתְרוֹ חֹתֵן מֹשֶׁה עֹלָה וּזְבָחִים לֵאלֹהִים, שֶׁהוּא הִקְרִיב קָרְבָּן לַקָּדוֹשׁ- בָּרוּךְ-הוּא וּבָא לְהִתְגַּיֵּר. מַה זֶּה אוֹמֵר? שֶׁקָּרְבָּנוֹ חָשׁוּב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם שֶׁהוּא הִקְרִיב קָרְבָּן לַקָּדוֹשׁ-בָּרוּךְ-הוּא, כָּתוּב וַיָּבֹא אַהֲרֹן וְכֹל זִקְנֵי יִשְׂרָאֵל לֶאֱכָל לֶחֶם עִם חֹתֵן מֹשֶׁה לִפְנֵי הָאֱלֹהִים. לִפְנֵי הָאֱלֹהִים דַּוְקָא. מִכָּאן לָמַדְנוּ, שֶׁכָּל מִי שֶׁמַּקְרִיב קָרְבָּן בִּרְצוֹן הַלֵּב, הַקָּדוֹשׁ בָּרוּךְ הוּא מִזְדַּמֵּן לְעֻמָּתוֹ.</p>\n<p>בֹּא רְאֵה, קָרְבַּן הֶעָנִי חָשׁוּב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי הוּא הִקְרִיב שְׁנֵי קָרְבָּנוֹת לְפָנָיו, אֶחָד חֶלְבּוֹ וְדָמוֹ, וְאֶחָד אוֹתוֹ שֶׁהִקְרִיב. שֶׁהֲרֵי אֵין לוֹ לֶאֱכֹל, וְהוּא הֵבִיא קָרְבָּן. קָרְבַּן הֶעָנִי קַל מֵהַכֹּל - שְׁנֵי תוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה, וְאִם לֹא - מְעַט קֶמַח, וּמִתְכַּפֵּר בּוֹ, וּבְאוֹתָהּ שָׁעָה מַכְרִיזִים וְאוֹמְרִים: כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת עָנִי. כָּל כָּךְ לָמָּה? כִּי קָרְבַּן הֶעָנִי עָדִיף מֵהַכֹּל, שֶׁהֲרֵי הוּא גָרַם לִי לִהְיוֹת בְּגוֹרָלוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא גוֹרֵם לִי לִהְיוֹת בַּחֵלֶק שֶׁל הַתּוֹרָה. מִשּׁוּם כָּךְ חִלַּקְתִּי כָּל נְכָסַי (חלקתי נכסי, חצי) לַעֲנִיִּים, שֶׁהֲרֵי הֵם גָּרְמוּ לִי כָּל זֶה.</p>\n<p>כְּמוֹ שֶׁהֶעָנִי הִרְתִּיחַ חֶלְבּוֹ וְדָמוֹ, כָּךְ אוֹתוֹ הַקֶּמַח מַרְתִּיחִים בְּשֶׁמֶן מִשְׁחָה. וְכָךְ לָמַדְנוּ, שֶׁאֲפִלּוּ כָּל אָדָם מַקְרִיב אֶת הַמִּנְחָה הַזּוֹ עַל הַמַּחֲבַת וּמִנְחַת מַרְחֶשֶׁת, מִשּׁוּם שֶׁכְּמוֹ שֶׁהַחֵטְא הִרְתִּיחַ אֶת חֶלְבּוֹ וְדָמוֹ בְּאֵשׁ הַיֵּצֶר הָרָע וְכָל אֵיבָרָיו רָתְחוּ בָאֵשׁ - כָּךְ הַקָּרְבָּן הַזֶּה כְּמוֹ כֵן מַמָּשׁ, וְעִקַּר הַקָּרְבָּן כְּמוֹ הַחֵטְא, וּלְהַקְרִיב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רְצוֹן לִבּוֹ וְרוּחוֹ וְנַפְשׁוֹ, שֶׁזֶּה חָבִיב מֵהַכֹּל לְפָנָיו.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁמַּקְרִיבִים בְּכָל יוֹם וָיוֹם אֶת הַקָּרְבָּן הַזֶּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמַה הוּא? עַצְמָם וְנַפְשָׁם שֶׁמַּקְרִיבִים לְפָנָיו. וַאֲנִי רוֹצֶה לְהַקְרִיב אֶת הַקָּרְבָּן הַזֶּה (ממש), וְזֶה רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאָדָם בָּעוֹלָם הַזֶּה. וְעִם כָּל זֶה, קָרְבָּן שֶׁל הַכֹּל (ממש) עָדִיף, כְּדֵי שֶׁיִּתְבָּרְכוּ כָּל הָעוֹלָמוֹת.</p>"],[9522011945,"<p>עוֹד פָּתַח וְאָמַר, (תהלים קלה) בָּרוּךְ ה' מִצִּיּוֹן שֹׁכֵן יְרוּשָׁלם הַלְלוּיָהּ. וְכִי מִצִּיּוֹן הוּא בָּרוּךְ? וַהֲרֵי מֵהַנָּהָר הֶעָמֹק הָעֶלְיוֹן הוּא בָּרוּךְ! אֶלָּא בָּרוּךְ ה', כְּשֶׁמְּאִירָה הַלְּבָנָה מֵאוֹר הַשֶּׁמֶשׁ וּמִתְקָרְבִים זֶה לָזוֹ, וְלֹא מוּסָר הָאוֹר הַזֶּה מִזֶּה. וְלִפְעָמִים שֶׁהַלְּבָנָה נִקְרֵאת בְּשֵׁם הַמֶּלֶךְ, כְּמוֹ שֶׁהוּא נִקְרָא יְהֹוָ\"ה, כָּךְ הִיא נִקְרֵאת יְהֹוָ\"ה, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יט) וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ מֵאֵת ה' מִן הַשָּׁמָיִם. וְלֹא זֶה לְבַדּוֹ, אֶלָּא אֲפִלּוּ שָׁלִיחַ אֶחָד לִפְעָמִים (ממש) נִקְרָא בְּשֵׁם הַמֶּלֶךְ.</p>\n<p>דָּבָר אַחֵר בָּרוּךְ ה' מִצִּיּוֹן - מֵאֵיזֶה מָקוֹם נוֹדָע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא בָּרוּךְ? חָזַר וְאָמַר מִצִּיּוֹן, מִמָּקוֹם שֶׁל צִיּוֹן נוֹדָע שֶׁהוּא בָּרוּךְ. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (תהלים קלד) כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה וְגוֹ'. אָמַר לוֹ רַבִּי יֵיסָא, אַשְׁרֵי חֶלְקְךְ שֶׁזָּכִיתָ לְכָל זֶה. אַשְׁרֵי אוֹתָם שֶׁעוֹסְקִים בַּתּוֹרָה. שֶׁכָּל מִי שֶׁעוֹסֵק בַּתּוֹרָה כְּאִלּוּ אוֹחֵז בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. זֶהוּ שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>"],[9522011946,"<p>אִם זֶבַח שְׁלָמִים קָרְבָּנוֹ. רַבִּי יְהוּדָה פָּתַח, (בראשית א) וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וְגוֹ'. בּא רְאֵה, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם - בָּרָא שִׁבְעָה רְקִיעִים לְמַעְלָה, בָּרָא שֶׁבַע אֲרָצוֹת לְמַטָּה, שִׁבְעָה יַמִּים, שִׁבְעָה נְהָרוֹת, שִׁבְעָה יָמִים, שִׁבְעָה שָׁבוּעוֹת, שֶׁבַע שָׁנִים, שֶׁבַע פְּעָמִים. שִׁבְעָה אַלְפֵי שָׁנִים יִהְיֶה הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא בַּשְּׁבִיעִי שֶׁל הַכֹּל.</p>\n<p>שִׁבְעָה שְׁחָקִים (רקיעים) לְמַעְלָה, וּבְכָל אֶחָד וְאֶחָד כּוֹכָבִים וּמַזָּלוֹת וְשַׁמָּשִׁים שֶׁמְּשַׁמְּשִׁים בְּכָל רָקִיעַ וְרָקִיעַ. וּבְכֻלָּם מֵאֵלּוּ, מֶרְכָּבוֹת אֵלּוּ עַל אֵלּוּ, לְקַבֵּל עֲלֵיהֶם עֹל מַלְכוּת רִבּוֹנָם, וּבְכָל הָרְקִיעִים יֵשׁ מֶרְכָּבוֹת וְשַׁמָּשִׁים מְשֻׁנִּים זֶה מִזֶּה אֵלּוּ עַל אֵלּוּ, מֵהֶם בְּשֵׁשׁ כְּנָפַיִם, וּמֵהֶם בְּאַרְבַּע כְּנָפַיִם. מֵהֶם בְּאַרְבַּע פָּנִים, וּמֵהֶם בִּשְׁתֵּי פָנִים, וּמֵהֶם בְּאַחַת. מֵהֶם אֵשׁ לוֹהֵט, וּמֵהֶם מַיִם. מֵהֶם רוּחַ. זֶהוּ שֶׁכָּתוּב (תהלים קד) עוֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לֹהֵט.</p>\n<p>וְכָל הָרְקִיעִים אֵלּוּ עַל אֵלּוּ כְּגִלְדֵי בְצָלִים, אֵלּוּ לְמַטָּה וְאֵלּוּ לְמַעְלָה. וְכָל רָקִיעַ וְרָקִיעַ הוֹלֵךְ וְרוֹעֵשׁ מֵאֵימַת רִבּוֹנָם. עַל פִּיו נוֹסְעִים, וְעַל פִּיו עוֹמְדִים. וּמֵעַל לְכֻלָּם הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנּוֹשֵׂא הַכֹּל בְּחֵילוֹ וְתָקְפּוֹ. כְּמוֹ כֵן שֶׁבַע אֲרָצוֹת לְמַטָּה, וְכֻלָּם בְּיִשּׁוּב, פְּרָט שֶׁאֵלֶּה עֶלְיוֹנִים וְאֵלֶּה תַחְתּוֹנִים. וְאֶרֶץ יִשְׂרָאֵל עֶלְיוֹנָה מֵהַכֹּל, וִירוּשָׁלַיִם עֶלְיוֹנָה מִכָּל יִשּׁוּב.</p>\n<p>וַחֲבֵרֵינוּ יוֹשְׁבֵי הַדָּרוֹם רָאוּ בְּסִפְרֵי הַקַּדְמוֹנִים וּבְסִפְרוֹ שֶׁל אָדָם, שֶׁכָּךְ מְחֻלָּקִים כָּל הָאֲרָצוֹת הַלָּלוּ, שֶׁכֻּלָּם נִמְצָאִים לְמַטָּה כְּמוֹ אוֹתָם הָרְקִיעִים שֶׁלְּמַעְלָה, אֵלּוּ עַל אֵלּוּ וְאֵלּוּ עַל אֵלּוּ, וּבֵין כָּל אֶרֶץ וְאֶרֶץ רָקִיעַ מַפְרִיד בֵּין זֶה לָזֶה, וְלָכֵן כָּל הָאֲרָצוֹת מְפֹרָשׁוֹת בְּשֵׁמוֹת, וּבֵינֵיהֶן גַּן עֵדֶן וְגֵיהִנֹּם, וְיֵשׁ בֵּינֵיהֶן בְּרִיּוֹת מְשֻׁנּוֹת אֵלּוּ מֵאֵלּוּ, כְּמוֹ שֶׁלְּמַעְלָה, מֵהֶן בִּשְׁתֵּי פָנִים וּמֵהֶן בְּאַרְבַּע וּמֵהֶן בְּאַחַת, וּמַרְאֶה שֶׁל אֵלֶּה אֵינוֹ כְאֵלֶּה.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּל בְּנֵי הָעוֹלָם יָצְאוּ מֵאָדָם, (אינו כך, שלא) וְכִי יָרַד אָדָם הָרִאשׁוֹן לְכָל הָאֲרָצוֹת וְהוֹלִיד בָּנִים? וְכַמָּה נָשִׁים הָיוּ לוֹ? אֶלָּא אָדָם לֹא נִמְצָא אֶלָּא בָּעוֹלָם הָעֶלְיוֹן הַזֶּה מִכֻּלָּם, שֶׁנִּקְרָא תֵבֵל, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב (משלי ח) (משחקת בתבל ארצו) וַיְצַו לְתֵבֵל אַרְצוֹ. וְהַתֵּבֵל הַזּוֹ אֲחוּזָה בָּרָקִיעַ שֶׁלְּמַעְלָה וְנֶאֱחֶזֶת בַּשֵּׁם הָעֶלְיוֹן. זֶהוּ שֶׁכָּתוּב (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק. בְּצֶדֶק וַדַּאי. מִשּׁוּם כָּךְ בָּנָיו שֶׁל אָדָם נִמְצָאִים בָּאָרֶץ הָעֶלְיוֹנָה הַזּוֹ שֶׁנִּקְרֵאת תֵּבֵל. וְהֵם עֶלְיוֹנִים עַל הַכֹּל, כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>מָה הַטַּעַם? כְּמוֹ שֶׁלְּמַעְלָה לְכָל הָרְקִיעִים יֵשׁ רָקִיעַ עֶלְיוֹן מִכֻּלָּם, וּלְמַעְלָה נִמְצָא כִּסְאוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. אַף כָּאן בַּתֵּבֵל הַזּוֹ נִמְצָא הַמֶּלֶךְ שֶׁל הַכֹּל, וּמִיהוּ? אָדָם, מַה שֶּׁלֹּא נִמְצָא בְּכָל הַתַּחְתּוֹנִים.</p>\n<p>וְאוֹתָם תַּחְתּוֹנִים מֵאֵיפֹה בָּאוּ? אֶלָּא מֵהָאֵדִים (מעשן) שֶׁל הָאָרֶץ וְהַסִּיּוּעַ שֶׁל הָרָקִיעַ שֶׁלְּמַעְלָה, יוֹצְאִים בְּרִיּוֹת מְשֻׁנּוֹת אֵלּוּ מֵאֵלּוּ, מֵהֶם בִּלְבוּשִׁים, מֵהֶם בִּקְלִפּוֹת, כַּתּוֹלָעִים הַלָּלוּ שֶׁנִּמְצָאוֹת בָּאָרֶץ, מֵהֶן בִּקְלִפּוֹת אֲדֻמּוֹת, שְׁחוֹרוֹת וּלְבָנוֹת, וּמֵהֶן מִכָּל הַגְּוָנִים. כָּךְ כָּל הַבְּרִיּוֹת כְּמוֹ כֵן, וְלֹא נִמְצָאִים בְּקִיּוּם, רַק עֶשֶׂר שָׁנִים (או יותר. ס\"א מעט או פחות מעט).</p>\n<p>וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא פֵּרַשׁ יוֹתֵר, שֶׁהֲרֵי כָּל הַיִּשּׁוּב מִתְגַּלְגֵּל בְּעִגּוּל כְּמוֹ כַּדּוּר, אֵלֶּה לְמַטָּה וְאֵלּוּ לְמַעְלָה, וְכָל אוֹתָן בְּרִיּוֹת מְשֻׁנּוֹת בְּמַרְאֵיהֶן מִשִּׁנּוּי הָאֲוִיר כְּפִי כָּל מָקוֹם וּמָקוֹם, וְעוֹמְדוֹת בְּקִיּוּמָן כְּמוֹ שְׁאָר בְּנֵי אָדָם.</p>\n<p>וְלָכֵן יֵשׁ מָקוֹם בַּיִּשּׁוּב, כְּשֶׁמֵּאִיר לְאֵלֶּה חָשׁוּךְ לְאֵלֶּה, לְאֵלֶּה יוֹם וּלְאֵלֶּה לַיְלָה. וְיֵשׁ מָקוֹם שֶׁכֻּלּוֹ יוֹם, וְלֹא נִמְצָא בּוֹ לַיְלָה פְּרָט לְשָׁעָה אַחַת קְטַנָּה. וְזֶה שֶׁאָמַר בְּסִפְרֵי הַקַּדְמוֹנִים, וּבְסִפְרוֹ שֶׁל אָדָם הָרִאשׁוֹן כָּךְ הוּא. שֶׁכָּךְ כָּתוּב, (תהלים קלט) אוֹדְךְ עַל כִּי נוֹרָאוֹת נִפְלֵיתִי נִפְלָאִים מַעֲשֶׂיךְ. וְכָתוּב (שם קד) מָה רַבּוּ מַעֲשֶׂיךְ ה'. וְלָכֵן הַכֹּל יָפֶה. וְסוֹד זֶה נִמְסָר לְבַעֲלֵי הַחָכְמָה, וְלֹא לִמְחַלְּקֵי תְחוּמִים, מִשּׁוּם שֶׁהוּא סוֹד עָמֹק שֶׁל הַתּוֹרָה.</p>\n<p>כְּמוֹ כֵן יֵשׁ בַּיָּם, שֶׁיֵּשׁ בּוֹ כַּמָּה בְרִיּוֹת מְשֻׁנּוֹת זוֹ מִזּוֹ. זֶהוּ שֶׁכָּתוּב (שם) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדלוֹת שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן וְגוֹ'. וְהַכֹּל תָּלוּי זֶה בָּזֶה (ומתקשר זה בזה), וְהַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. וּבְכָל הָעוֹלָמוֹת אֵין שׁוֹלֵט בַּכֹּל, רַק אָדָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֵעָלָיו.</p>\n<p>רַבִּי נְהוֹרַאי סָבָא פָּרַשׁ לַיָּם הַגָּדוֹל, וְהִתְרַעֵשׁ הַיָּם, וְנֶאֶבְדוּ כָּל אוֹתָם שֶׁהָיוּ בַסְּפִינָה, וְהִתְרַחֵשׁ לוֹ נֵס, וְיָרַד בִּשְׁבִילִים יְדוּעִים לְלֵב הַיָּם, וְיָצָא תַחַת הַיָּם לְיִשּׁוּב אֶחָד, וְרָאָה מֵאוֹתָן הַבְּרִיּוֹת כֻּלָּן קְטַנּוֹת, וְהָיוּ מִתְפַּלְלִים תְּפִלָּה, וְלֹא יָדַע מָה אוֹמְרִים. הִתְרַחֵשׁ לוֹ נֵס וְעָלָה. אָמַר, אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים נִסְתְּרֵי הַסּוֹדוֹת הָעֶלְיוֹנִים. אוֹי לְאוֹתָם שֶׁחוֹלְקִים עַל דִּבְרֵיהֶם וְלֹא מַאֲמִינִים.</p>\n<p>מֵאוֹתוֹ יוֹם, כְּשֶׁהָיָה בָּא לְבֵית רַב וְאוֹמְרִים דְּבַר תּוֹרָה, הָיָה בּוֹכֶה. אָמְרוּ לוֹ, לָמָּה אַתָּה בּוֹכֶה? אָמַר לָהֶם, מִשּׁוּם שֶׁעָבַרְתִּי עַל אֱמוּנַת דִּבְרֵי חֲכָמִים, וּפוֹחֵד מֵהַדִּין שֶׁל אוֹתוֹ הָעוֹלָם.</p>"],[9522011947,"<p>וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם (בראשית א). רַבִּי יְהוּדָה אָמַר, אִלְמָלֵא אוֹתוֹ רָקִיעַ שֶׁמַּפְרִיד בֵּין מַיִם הָעֶלְיוֹנִים לַמַּיִם הַתַּחְתּוֹנִים, הָיְתָה מַחֲלֹקֶת בָּעוֹלָם מֵהֶם, אֲבָל הָרָקִיעַ הַזֶּה עוֹשֶׂה שָׁלוֹם בֵּינֵיהֶם, וְהָעוֹלָם אֵינוֹ מִתְקַיֵּם אֶלָּא עַל שָׁלוֹם. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא שָׁלוֹם, הוּא שָׁלוֹם וּשְׁמוֹ שָׁלוֹם, וְהַכֹּל נִקְשָׁר בְּשָׁלוֹם. רַבִּי אַבָּא אָמַר, רָאִיתִי שֶׁהַשֵּׁם הָעֶלְיוֹן הַקָּדוֹשׁ הַכֹּל הוּא שָׁלוֹם, וְהַכֹּל אֶחָד, וְהַדְּרָכִים נִפְרָדוֹת לַצַּד הַזֶּה וְלַצַּד הַזֶּה.</p>\n<p>יוֹ\"ד שֶׁל הַשֵּׁם הַקָּדוֹשׁ קְשׁוּרָה בִּשְׁלֹשָׁה קְשָׁרִים, מִשּׁוּם זֶה הַי' הַזּוֹ, קוֹץ אֶחָד לְמַעְלָה, וְקוֹץ אֶחָד לְמַטָּה, וְאֶחָד בָּאֶמְצַע. מִשּׁוּם שֶׁשְּׁלֹשָׁה קְשָׁרִים הִשְׁתַּלְשְׁלוּ (התקשרו) בָהּ, קוֹץ אֶחָד לְמַעְלָה, כֶּתֶר עֶלְיוֹן, שֶׁהוּא עֶלְיוֹן מֵעַל כָּל הָעֶלְיוֹנִים, הָרֹאשׁ שֶׁל כָּל הָרָאשִׁים, וְהוּא עוֹמֵד עַל הַכֹּל.</p>\n<p>קוֹץ אֶחָד בָּאֶמְצַע, שֶׁהוּא רֹאשׁ אַחֵר. מִשּׁוּם שֶׁהָיוּ שְׁלֹשָׁה רָאשִׁים, וְכָל אֶחָד וְאֶחָד רֹאשׁ לְבַדּוֹ. וְלָכֵן הַקּוֹץ שֶׁל הָאֶמְצַע זֶהוּ רֹאשׁ אַחֵר שֶׁיּוֹצֵא מֵהַקּוֹץ שֶׁלְּמַעְלָה, וְהוּא רֹאשׁ שֶׁל כָּל שְׁאָר הָרָאשִׁים שֶׁיִּבָּנֶה מִמֶּנּוּ הַשֵּׁם הַקָּדוֹשׁ, וְהָרֹאשׁ הַזֶּה הוּא נִסְתָּר שֶׁל הַכֹּל.</p>\n<p>רֹאשׁ אַחֵר תַּחְתּוֹן, הוּא רֹאשׁ לְהַשְׁקוֹת אֶת הַגָּן, וְהוּא מַעְיַן הַמַּיִם שֶׁכָּל הַנְּטִיעוֹת מֻשְׁקוֹת מִמֶּנּוּ. וְזֶהוּ י' בִּשְׁלֹשָׁה קְשָׁרִים, וְלָכֵן נִקְרֵאת שַׁלְשֶׁלֶת, כְּמוֹ הַשַּׁלְשֶׁלֶת הַזּוֹ שֶׁנִּקְשְׁרָה זֶה בָּזֶה, וְהַכֹּל אֶחָד.</p>\n<p>שָׁנִינוּ בְּסִפְרוֹ שֶׁל חֲנוֹךְ, בְּשָׁעָה שֶׁהֶרְאוּ לוֹ חָכְמַת הַסּוֹדוֹת הָעֶלְיוֹנִים וְרָאָה אֶת הָאִילָן שֶׁל גַּן עֵדֶן, הֶרְאוּ לוֹ חָכְמָה בְּסוֹד עֶלְיוֹן, וְרָאָה שֶׁכָּל הָעוֹלָמוֹת הָיוּ נִקְשָׁרִים זֶה בָּזֶה, שָׁאַל אוֹתָם עַל מָה קַיָּמִים? אָמְרוּ לוֹ, כֻּלָּם עוֹמְדִים עַל י', מִמֶּנָּה נִבְנוּ וְהִשְׁתַּלְשְׁלוּ (נבראו ונתקנו), שֶׁכָּתוּב (תהלים קד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ. וְרָאָה שֶׁכֻּלָּם מִזְדַּעְזְעִים מֵאֵימַת רִבּוֹנָם, וְעַל שְׁמוֹ כֻּלָּם נִקְרְאוּ.</p>\n<p>וּבְסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ אָמַר, הַהַגָּעָה הִיא בְּשַׁלְשֶׁלֶת שֶׁל שְׁלֹשָׁה שֶׁכְּלוּלִים בְּדֶבֶק וְקֶשֶׁר שֶׁל גּוּפוֹ. אֶחָד פַּחַד (שלמות) שֶׁל הַכֹּל, אֶחָד סוֹתֵם שְׁבִילִים, וְאֶחָד נָהָר עָמֹק.</p>\n<p>אַחַר כָּךְ פֵּרַט בָּאוֹתִיּוֹת, (של אלף) הַבַּיִת בְּשִׁכְלוּלוֹ יוֹ\"ד הֵ\"א, הַבִּנְיָן שֶׁל הַכֹּל. (אחד סתום השבילים, ואחד נהר עמק לכל) שְׁלֵמוּת הַשֵּׁם הַקָּדוֹשׁ י' רֹאשׁ שֶׁל הַכֹּל, אָב לַכֹּל. ו' הַבֵּן שֶׁהוֹלִיד וְיָצָא מִמֶּנּוּ, וּמִמֶּנּוּ נִמְצָא ד', בַּת. הַגְּבִירָה שֶׁכָּל הַדִּינִים (הדינים) בְּיָדֶיהָ נִמְצָאִים, טְמִירָה בְּכָל הָעוֹלָמוֹת, (עליונים יוצאים, ועליונים ותחתונים) שֶׁעֶלְיוֹנִים יוֹצְאִים, וְעֶלְיוֹנִים וְתַחְתּוֹנִים נִזּוֹנִים מִמֶּנָּה. הֲרֵי יוֹ\"ד שְׁלֵמוּת הַכֹּל, וְהַשֵּׁם הַקָּדוֹשׁ נִתְקָן בּוֹ, וְנִמְצָא נִסְתָּר בְּתוֹכוֹ.</p>\n<p>אַחַר כָּךְ יוֹ\"ד הוֹצִיאָה הַכֹּל, וְשִׁלְשְׁלָה הַכֹּל בְּקֶשֶׁר אֶחָד זֶה עִם זֶה. וַהֲרֵי בֵּאֲרָהּ הַמְּנוֹרָה הַקְּדוֹשָׁה, י' הוֹצִיאָה אוֹתוֹ הַנָּהָר, שֶׁכָּתוּב בּוֹ (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. (כמו) זוֹ ה', סוֹד הַבִּינָה, וְהִיא הָאֵם הָעֶלְיוֹנָה.</p>\n<p>וְאוֹתוֹ נָהָר מוֹצִיא שְׁנֵי בָנִים, כְּמוֹ שֶׁנִּתְבָּאֵר, וּמִמֶּנָּה נִזּוֹנִים. אַחַר כָּךְ יוֹצְאִים שְׁנֵי בָנִים, וְהַבַּת נִזּוֹנֵית מִבֵּן, זֶה ו', הֲרֵי בֶּן הַמֶּלֶךְ הַזֶּה שֶׁהַשָּׁלוֹם כֻּלּוֹ שֶׁלּוֹ, סוֹד שֶׁל תִּפְאֶרֶת. וְאַחַר כָּךְ נִמְצֵאת ה' שֶׁנִּזּוֹנֵית מִן ו', וַהֲרֵי פֵּרְשׁוּהָ. (אחר כך יוצאים שנים, בן ובת. ו\"ה זה בן המלך ששלמות הכל שלו. וזו ה' הבת נזונה מן ו', והרי פרשוה) נִמְצָא שֶׁי' עִקַּר וְשֹׁרֶשׁ וּשְׁלֵמוּת הַכֹּל. זֶהוּ מַה שֶּׁכָּתוּב (משלי כב) בְּחָכְמָה יִבָּנֶה בָּיִת.</p>"],[9522011948,"<p>שָׁנִינוּ, עֲשָׂרָה שֵׁמוֹת הִשְׁתַּכְלְלוּ וְיָצְאוּ מֵהַיּוֹ\"ד הַזּוֹ. י' שֶׁהִיא הָעֲשִׂירִית שֶׁל הָאוֹתִיּוֹת. וְאֶת כֻּלָּם הִכְנִיסָה לְאוֹתוֹ נָהָר קָדוֹשׁ כְּשֶׁהִתְעַבְּרָה. וַעֲשָׂרָה שֵׁמוֹת נִסְתָּרִים בְּאֶחָד. וְכֻלָּם נִסְתָּרִים בְּי'. י' כּוֹלֶלֶת אוֹתָם. י' מוֹצִיאָה אוֹתָם. הוּא אָב לַכֹּל. אָב לָאָבוֹת.</p>\n<p>מִמֶּנּוּ יָצְאוּ (ובו יושבים) (בו עשר תבות) ו\"ד. רֶמֶז לַעֲשָׂרָה בְּחֶשְׁבּוֹן. אוֹתִיּוֹת יוֹ\"ד כּוֹלְלוֹת לָהֶן ו\"ד (יו\"ד), שְׁלֵמוּת הַכֹּל. ו\"ד - זָכָר וּנְקֵבָה. דּוּ קוֹרְאִים לָהֶם, שְׁנַיִם. וְלָכֵן אָדָם נִבְרָא דּוּ פַּרְצוּפִים, וְאוֹתָם פַּרְצוּפִים זָכָר וּנְקֵבָה הָיוּ כְּמוֹ שֶׁלְּמַעְלָה. ו\"ד מִמַּעְלָה לְמַטָּה. ד\"ו מִמַּטָּה לְמַעְלָה, וְהַכֹּל דָּבָר אֶחָד. י\"ג מִדּוֹת הָרַחֲמִים תְּלוּיִים בּוֹ, וְעַל כֵּן יוֹ\"ד כּוֹלֵל ו\"ד כְּמוֹ שֶׁנִּתְבָּאֵר, וַהֲרֵי פֵּרְשׁוּהָ.</p>\n<p>וּבֹא רְאֵה, עֲשָׂרָה שֵׁמוֹת הֵם כְּנֶגֶד עֶשֶׂר אוֹתִיּוֹת. וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא הֵם שְׁמוֹנָה, וּשְׁתֵּי דְרָגוֹת כְּנֶגֶד שְׁנֵי רְקִיעִים. וּמִשְׁתַּנִּים הַשֵּׁמוֹת, עֲשָׂרָה, וְתִשְׁעָה, וּשְׁמוֹנָה, וְשִׁבְעָה.</p>\n<p>הָרִאשׁוֹן - י\"ה, מִשּׁוּם שֶׁי' כּוֹלֶלֶת ה', וְה' יוֹצֵאת מִי'. לָכֵן חָכְמָה נִקְרָא י\"ה.</p>\n<p>הַשֵּׁנִי - יֱהִֹוִה (יה\"ו) שֶׁנִּקְרָא אֱלֹהִים, מִשּׁוּם שֶׁאוֹתוֹ נָהָר רַחֲמִים, וּמִשּׁוּם שֶׁדִּינִים מִתְעוֹרְרִים מִמֶּנּוּ, (אלהים ויצאו) כְּתוּבוֹת אוֹתִיּוֹת הָרַחֲמִים עִם נִקּוּד שֶׁל אֱלֹהִים, וְלֹא אֱלֹהִים דִּין.</p>\n<p>הַשְּׁלִישִׁי - אֵל, וְהוּא גְּדֻלָּה, וְהוּא נִקְרָא הָאֵל הַגָּדוֹל. הָרְבִיעִי - אֱלֹהִים, שֶׁדִּינִים מִתְעוֹרְרִים בּוֹ, וְהוּא הַדִּין הַקָּשֶׁה. הַחֲמִישִׁי - יְהֹוָ\"ה, הַכְּלָל שֶׁל כָּל שְׁלֵמוּת הָאֱמוּנָה, וְזֶהוּ רַחֲמִים בִּשְׁלמוּת וְזֶהוּ תִּפְאֶרֶת. שִׁשִּׁי וּשְׁבִיעִי - צְבָאוֹת נִקְרָאִים.</p>\n<p>הַשְּׁמִינִי - אֵ\"ל חַ\"י, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קלו) כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה חַיִּים וְגוֹ'. וְזֶה צַדִּיק, שֶׁכָּל הַחַיִּים יוֹצְאִים מִשָּׁם, וְנִקְרָא יְהֹוָ\"ה, כְּמוֹ שֶׁנֶּאֱמַר (משלי כז) ה' צַדִּיק יִבְחָן. וְזוֹהִי ו' קְטַנָּה שֶׁל הַשֵּׁם הַקָּדוֹשׁ. מִשּׁוּם כָּךְ וָ\"ו שְׁנֵי וָוִים.</p>\n<p>הַתְּשִׁיעִי - אֲדנָ\"י, וְזוֹ מַלְכוּת הַקְּדוֹשָׁה שֶׁדִּינִים יוֹצְאִים מִשָּׁם לָעוֹלָם, וְזֶהוּ הַכֶּתֶר הָאַחֲרוֹן שֶׁל כָּל הַשֵּׁמוֹת. וְשֵׁם אֶהְיֶ\"ה, הַכְּלָל וְהַנִּסְתָּר שֶׁבָּרִאשׁוֹנָה. וְזֶהוּ כֶּתֶר עֶלְיוֹן, הָרֹאשׁ שֶׁל כָּל הָרָאשִׁים, שְׁמוֹ נִסְתָּר וְלֹא נִגְלֶה, וְנִתְבָּאֵר. וּבְסֵפֶר הָאַגָּדָה, עֲשָׂרָה שֵׁמוֹת כְּתוּבִים בְּגָוֶן אַחֵר, וְאָנוּ לֹא שָׁנִינוּ כָּךְ.</p>\n<p>רַבִּי אַבָּא פָּתַח, (שיר ד) עוּרִי צָפוֹן וּבֹאִי תֵימָן הָפִיחִי גַנִּי יִזְּלוּ בְשָׂמָיו יָבא דּוֹדִי לְגַנּוֹ וְיֹאכַל פְּרִי מְגָדָיו. עוּרִי צָפוֹן, אֵלּוּ עוֹלוֹת שֶׁנִּשְׁחָטוֹת בַּצָּפוֹן, מִשּׁוּם שֶׁהֵן מַחֲשָׁבוֹת בִּצְפוּנוֹת הַלֵּב וּבִמְקוֹם הַדִּין. מִשּׁוּם שֶׁמַּחֲשָׁבָה נִמְצֵאת בַּלַּיְלָה, בִּזְמַן שֶׁהַדִּין נִמְצָא. רוּחַ צָפוֹן נוֹשֶׁבֶת בַּחֲצוֹת הַלַּיְלָה כְּשֶׁמִּתְעוֹרְרִים אֲנָשִׁים, וְכִנּוֹר דָּוִד מְנַגֵּן מֵאֵלָיו, וּמַחְשְׁבוֹת בְּנֵי אָדָם מִתְעוֹרְרוֹת.</p>\n<p>וּבֹאִי תֵימָן, אֵלּוּ שְׁלָמִים שֶׁנִּשְׁחָטִים בַּדָּרוֹם, מִשּׁוּם שֶׁהֵם הַשָּׁלוֹם שֶׁל הַכֹּל, שְׁלוֹם הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. וְאֵלּוּ הֵם הַשְּׁלֵמוּת שֶׁל צִדְדֵי הָעוֹלָם, הַשְּׁלֵמוּת שֶׁל הַכֹּל מִצַּד הָאֱמוּנָה. וּשְׁלָמִים, מִשּׁוּם שֶׁהֵם הַשָּׁלוֹם שֶׁל הַכֹּל, הַבְּעָלִים אוֹכְלִים מֵהֶם וְנֶהֱנִים מֵהֶם, שֶׁהֲרֵי שָׁלוֹם הוּא לוֹ וּלְכָל הָעוֹלָם בְּדַרְגָּה אַחַת. חֲטָאוֹת וַאֲשָׁמוֹת נֶאֱכָלִים לַכֹּהֲנִים מִשּׁוּם שֶׁהֵם עֲתִידִים לְכַפֵּר עֲלֵיהֶם וּלְהַעֲבִיר אֶת חֲטָאֵיהֶם. וּמִכָּל הַקָּרְבָּנוֹת אֵין חֲבִיבִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ שְׁלָמִים, מִשּׁוּם שֶׁנִּמְצָא שָׁלוֹם בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים.</p>\n<p>וּמֵעַל כֻּלָּם קְטֹרֶת, שֶׁהִיא שְׁלֵמָה מֵהַכֹּל, וְלֹא בָאָה עַל חֵטְא וְלֹא עַל אָשָׁם וְלֹא עַל עָון, אֶלָּא עַל שִׂמְחָה, כְּמוֹ שֶׁנֶּאֱמַר (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב, וַהֲרֵי פֵּרְשׁוּהָ. וְלָכֵן קְטֹרֶת לֹא קְרֵבָה אֶלָּא בִּזְמַן שֶׁשֶּׁמֶן קָרֵב, זֶהוּ שֶׁכָּתוּב (שמות ל) וְהִקְטִיר עָלָיו אַהֲרֹן קְטֹרֶת סַמִּים בַּבֹּקֶר בַּבֹּקֶר בְּהֵטִיבוֹ אֶת הַנֵּרוֹת יַקְטִירֶנָּה. וְכָתוּב (שם) וּבְהַעֲלוֹת אַהֲרֹן אֶת הַנֵּרוֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה. מִשּׁוּם שֶׁנִּמְצָאִים שֶׁמֶן וּקְטֹרֶת כְּאֶחָד. בֹּא רְאֵה, שְׁלָמִים הוּא שָׁלוֹם בַּכֹּל, וּקְטָטָה וְקִטְרוּג לֹא מִתְעוֹרְרִים בָּעוֹלָם. אֲבָל קְטֹרֶת קוֹשֶׁרֶת אֶת קֶשֶׁר הָאֱמוּנָה.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, כָּל עֲשֶׂרֶת הַשֵּׁמוֹת כְּתוּבִים, וְאָנוּ שָׁנִינוּ, שֶׁהָרִאשׁוֹן אֶהְיֶה, זֶה הַנִּסְתָּר הָעֶלְיוֹן, כְּמִי שֶׁאוֹמֵר: אֲנִי מִי שֶׁאֲנִי! וְלֹא נוֹדָע מִי הוּא. אַחַר כָּךְ אֲשֶׁר אֶהְיֶה, אֲנִי שֶׁעָתִיד לְהִתְגַּלּוֹת בְּאוֹתָם הַכְּתָרִים (האחרים), שֶׁהֲרֵי בָּרִאשׁוֹנָה נִסְתָּר, וְאַחַר כָּךְ מַתְחִיל לְהִתְגַּלּוֹת, עַד שֶׁמַּגִּיעַ לַגִּלּוּי שֶׁל הַשֵּׁם (של שלמות) הַקָּדוֹשׁ.</p>\n<p>וְכָךָ כָּתוּב בְּמֹשֶׁה, אֶהְיֶה בָּרִאשׁוֹנָה, הַנִּסְתָּר שֶׁל הַכֹּל, אֲנִי הוּא מִי שֶׁאֲנִי. אַחַר כָּךְ אֲשֶׁר אֶהְיֶה, אֲנִי עָתִיד לְהִתְגַּלּוֹת. אַחַר כָּךְ אֶהְיֶה אַחֲרוֹן, וְזֶה כְּשֶׁהָאֵם מִתְעַבֶּרֶת וַעֲדַיִן הוּא נִסְתָּר. מָתַי מִתְגַּלֶּה? בִּזְמַן שֶׁכָּתוּב (שמות ג) לֵךְ וְאָסַפְתָּ אֶת זִקְנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵהֶם ה' אֱלֹהֵי אֲבתֵיכֶם וְגוֹ'. זוֹ שְׁלֵמוּת הַכֹּל, וְכָאן הוּא הַגִּלּוּי וְהַקֶּשֶׁר שֶׁל הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>מִשּׁוּם כָּךְ, הָרִאשׁוֹן שֶׁל הַכֹּל - אֶהְיֶה. הַשֵּׁנִי - יָהּ. מִשּׁוּם שֶׁחָכְמָה מוֹצִיאָה ה' וְנִסְתֶּרֶת בָּהּ, וְלֹא נִפְרֶדֶת מִמֶּנָּה לְעוֹלָמִים, וַהֲרֵי פֵּרְשׁוּהָ שֶׁכָּתוּב, (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן, כְּמוֹ זֶה. ה.</p>\n<p>וְכָךָ לָמַדְתִּי מֵאַבָּא, י' כְּמוֹ שֶׁנִּתְבָּאֵר. אַחַר כָּךְ יָ\"הּ, שֶׁלֹּא נִפְרָדִים לְעוֹלָמִים, י' מוֹצִיאָה ה', כְּמוֹ זֶה ה' הֲרֵי י', וְאוֹתוֹ נָהָר שֶׁיּוֹצֵא מִמֶּנּוּ.</p>\n<p>וְנִמְשָׁךְ מִמֶּנּוּ וּלְמַטָּה, שְׁנֵי בָנִים שֶׁיּוֹצְאִים מֵהֶם. מִצַּד הָאָב י' יוֹצֵא בֵן, שֶׁהֲרֵי אוֹחֵז בּוֹ בְּי', וְאוֹחֵז בְּאוֹתוֹ נָהָר. וּמִצַּד הָאֵם יוֹצֵאת בַּת, שֶׁהִיא הַנָּהָר הַתַּחְתּוֹן, וְהַבֵּן הַזֶּה נִמְשָׁךְ אַחַר כָּךְ וְיוֹצֵא מֵהֶם, וְהוּא ו', וְזֶה יוֹרֵשׁ אֶת הָאָב וְהָאֵם, וְנִקְשֶׁרֶת בּוֹ אֱמוּנַת הַכֹּל, וּמִמֶּנּוּ נִזּוֹנֵית הַבַּת, מֵאוֹתָהּ יְרֻשָּׁה שֶׁהוּא יוֹרֵשׁ.</p>\n<p>וְלָכֵן צָרִיךְ לִכְתֹּב אֶת הַשֵּׁם הַקָּדוֹשׁ - י' בָּרִאשׁוֹנָה, קוֹץ אֶחָד לְמַעְלָה, וְקוֹץ אֶחָד בָּאֶמְצַע, וְקוֹץ אֶחָד לְמַטָּה, וַהֲרֵי נִתְבָּאֵר. אַחַר כָּךְ יָהּ, שֶׁאֵין נִפְרָדִים זֶה מִזּוֹ לְעוֹלָמִים. כְּמוֹ כֵן ה, כְּדֵי שֶׁיִּמָּצְאוּ שְׁנֵיהֶם בִּשְׁלֵמוּת הַכֹּל, אָב וָאֵם בֵּן וּבַת. כְּמוֹ כֵן י\"ה (ו\"ה). הֲרֵי לְךְ כָּל שְׁלֵמוּת הָאֱמוּנָה.</p>\n<p>אַחַר כָּךְ מִתְפַּשֶּׁטֶת הָאֱמוּנָה, וְיוֹצְאִים שְׁנֵי בָנִים מִכְּלָל אֶחָד בְּדַרְכֵיהֶם. הַבֵּן יוֹצֵא מִשְּׁנֵיהֶם, וְהוּא ו' שֶׁל הַשֵּׁם הַקָּדוֹשׁ. הַבַּת יוֹצֵאת מִצַּד הָאֵם, וְהִיא ה' אַחֲרוֹנָה שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְאֵין נִשְׁלֶמֶת אֶלָּא עִם ו', מִשּׁוּם שֶׁמִּמֶּנּוּ הִיא נִזּוֹנֵית, וְלָכֵן צָרִיךְ לִכְתֹּב ו' וְאַחַר כָּךְ ה', כְּמוֹ זֶה ה', הֲרֵי ו' וְאוֹתָהּ הַהִתְפַּשְּׁטוּת שֶׁיּוֹצֵאת מִמֶּנּוּ, כְּמוֹ אוֹתוֹ נָהָר שֶׁיּוֹצֵא מִי', מִשּׁוּם שֶׁמִּמֶּנּוּ נִזּוֹנֵית. ו' הֲרֵי בֵּן שֶׁיּוֹצֵא מִמֶּנּוּ לְמַטָּה.</p>\n<p>וְהַדְּבָרִים הַלָּלוּ בֵּאֵר אוֹתָם אָבִי, וַהֲרֵי נִתְבָּאֲרוּ. וַאֲנִי כְּשֶׁמַּגִּיעַ לַדְּבָרִים הַלָּלוּ, אוֹמֵר אוֹתָם, מִשּׁוּם שֶׁצַּוָּאַת אָבִי כָּךְ. וְכָךְ צָרִיךְ אָדָם לְהִזָּהֵר בַּשֵּׁם הַקָּדוֹשׁ, שֶׁיִּכְתֹּב אֶת הַשֵּׁם הַקָּדוֹשׁ כְּמוֹ זֶה, וְזֶהוּ כָּרָאוּי. וְאִם לֹא, אֵינוֹ נִקְרָא שֵׁם קָדוֹשׁ, וְנִקְרָא פָּגוּם. וּמִי שֶׁפּוֹגֵם אֶת הַשֵּׁם הַקָּדוֹשׁ, טוֹב לוֹ שֶׁלֹּא נִבְרָא.</p>\n<p>הַשְּׁלִישִׁי - יֱהִֹוִ\"ה שֶׁנִּקְרָא אֱלֹהִים, כְּמוֹ שֶׁנֶּאֱמַר, רַחֲמִים, וְיוֹצֵא מִמֶּנּוּ דִין, וְזֶהוּ אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן. הָרְבִיעִי - אֵל גָּדוֹל. וַהֲרֵי נֶאֱמַר, וְזוֹ גְּדֻלָּה. הַחֲמִישִׁי - אֱלֹהִים, וּבְכָל מָקוֹם הוּא גְבוּרָה. הַשִּׁשִּׁי - יְהֹוָ\"ה, רַחֲמִים, שְׁלֵמוּת הַכֹּל, הָעִקָּר שֶׁל הַכֹּל. קֶשֶׁר הָאֱמוּנָה, אָחוּז לְכָל הַצְּדָדִים, וְזוֹ תִפְאֶרֶת יִשְׂרָאֵל.</p>\n<p>הַשְּׁבִיעִי וְהַשְּׁמִינִי - צְבָאוֹת. וְלָכֵן יְהֹוָ\"ה קָרוֹב בַּכֹּל. אָחוּז בְּכָל הַצְּדָדִים, לִפְעָמִים ה' אֱלֹהִים, שֶׁהֲרֵי הֵם קְרוֹבִים תִּפְאֶרֶת לִגְבוּרָה. לִפְעָמִים ה' צְבָאוֹת, שֶׁהֲרֵי הֵם קְרוֹבִים תִּפְאֶרֶת לְנֵצַח וְהוֹד, שֶׁנִּקְרָאִים צְבָאוֹת. וַהֲרֵי נִתְבָּאֵר שֶׁנּוֹדָעִים דִּבְרֵי הַנְּבִיאִים הַנֶּאֱמָנִים מִפִּיהֶם, כְּשֶׁאוֹמְרִים כֹּה אָמַר ה' אֱלֹהִים, וּכְשֶׁאוֹמְרִים כֹּה אָמַר ה' צְבָאוֹת, וְהָיוּ יוֹדְעִים מֵאֵיזֶה מָקוֹם בָּאִים הַדְּבָרִים.</p>\n<p>הַתְּשִׁיעִי - (א\"ל) שַׁדַּי. שֶׁאָמַר לָעוֹלָם דַּי, שֶׁהֲרֵי דֵּי סִפּוּק הוּא. וְהַסִּפּוּק לֹא בָא לָעוֹלָם אֶלָּא מִצַּדִּיק שֶׁהוּא יְסוֹד הָעוֹלָם, שֶׁאָמַר לָעוֹלָם דַּי. הָעָשִׂירִי - אֲדֹנָ\"י, שֶׁהֲרֵי דִּין הַמַּלְכוּת דִּין וַדַּאי. וְזֶה לַעֲרֹךְ אֶת קְרָבוֹת הַמֶּלֶךְ בָּעוֹלָם, וְזוֹ גְבוּרָה תַחְתּוֹנָה, וְזֶהוּ צֶדֶק.</p>\n<p>וְאֵלּוּ הֵם הָעֲשָׂרָה שֵׁמוֹת שֶׁבָּהֶם נִקְרָא הַקָּדוֹשׁ בָּרוּךְ הוּא, קְשׁוּרִים זֶה בָּזֶה בְּיִחוּד שָׁלֵם, וְאֵלּוּ הֵם הַכְּתָרִים הַקְּדוֹשִׁים שֶׁל הַמֶּלֶךְ, שֶׁהוּא נוֹדָע בָּהֶם, וְהֵם שְׁמוֹ, וְהוּא הֵם. וּכְשֶׁנִּקְשָׁרִים כֻּלָּם כְּאֶחָד עַל רֵיחַ הַקְּטֹרֶת, אָז נִקְרֵאת קְטֹרֶת, הַקֶּשֶׁר שֶׁנִּקְשָׁרִים כְּאֶחָד. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁיּוֹדְעִים אֶת דַּרְכֵי הַתּוֹרָה וְיוֹדְעִים לְהַכִּיר בִּכְבוֹד רִבּוֹנָם, עֲלֵיהֶם כָּתוּב (ישעיה סו) וּבָאוּ וְרָאוּ אֶת כְּבוֹדִי.</p>"],[9522011949,"<p>וְאִם זֶבַח שְׁלָמִים קָרְבָּנוֹ. רַבִּי שִׁמְעוֹן אוֹמֵר, כָּתוּב (במדבר ז) עֲשָׂרָה עֲשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ. עֲשָׂרָה עֲשָׂרָה, לְמָה זֶה בָּא? אֶלָּא עֲשָׂרָה לְמַעֲשֵׂה בְרֵאשִׁית, וַעֲשָׂרָה לְמַתַּן תּוֹרָה. עֲשָׂרָה מַאֲמָרוֹת בְּמַעֲשֵׂה בְרֵאשִׁית, וַעֲשָׂרָה מַאֲמָרוֹת בְּמַתַּן תּוֹרָה. בַּמֶּה זֶה מְדַבֵּר? מִשּׁוּם שֶׁהָעוֹלָם לֹא נִבְרָא אֶלָּא בִּשְׁבִיל הַתּוֹרָה, וְכָל זְמַן שֶׁיִּשְׂרָאֵל עוֹסְקִים בַּתּוֹרָה, הָעוֹלָם מִתְקַיֵּם. וְכָל זְמַן שֶׁיִּשְׂרָאֵל מִתְבַּטְּלִים מֵהַתּוֹרָה, מַה כָּתוּב? (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי.</p>\n<p>בֹּא רְאֵה, עֲשָׂרָה מַאֲמָרוֹת לְמַעֲשֵׂה בְרֵאשִׁית, כְּפִי שֶׁשָּׁנִינוּ בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם. עֲשָׂרָה מַאֲמָרוֹת לְמַתַּן תּוֹרָה, אֵלּוּ עֲשֶׂרֶת הַדִּבְּרוֹת. כָּתוּב (שמות ב) אָנֹכִי ה' אֱלֹהֶיךְ. וְכָתוּב בְּמַעֲשֵׂה בְרֵאשִׁית, (בראשית א) יְהִי אוֹר וַיְהִי אוֹר. אֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא הַזּוֹ נִקְרֵאת אוֹר, שֶׁכָּתוּב (תהלים כז) ה' אוֹרִי וְיִשְׁעִי מִמִּי אִירָא וְגוֹ'.</p>\n<p>כָּתוּב (שמות כ) לֹא יִהְיֶה לְךְ אֱלֹהִים אֲחֵרִים עַל פָּנָי. וְכָתוּב בְּמַעֲשֵׂה בְרֵאשִׁית, (בראשית א) יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וְגוֹ'. יְהִי רָקִיעַ - אֵלּוּ יִשְׂרָאֵל, שֶׁהֵם חֶלְקוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאוֹחֲזִים בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא שָׁמַיִם. וְהַיְנוּ הַסּוֹד, שֶׁפַּעַם אַחַת שָׁאַל רַבִּי יֵיסָא סָבָא לְרַבִּי אֶלְעַאי, אָמַר, הֲרֵי אֶת שְׁאָר הָעַמִּים נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לִגְדוֹלִים מְמֻנִּים שַׁלִּיטִים, וְאֶת יִשְׂרָאֵל בְּאֵיזֶה מָקוֹם נָתַן אוֹתָם? שָׁלַח לוֹ, וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם. וְיָפֶה שָׁלַח לוֹ.</p>\n<p>בְּתוֹךָ הַמָּיִם, בֵּין דִּבּוּרֵי הַתּוֹרָה. וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם - בֵּין הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרָא בְּאֵר מַיִם חַיִּים, וּבֵין עֲבוֹדָה זָרָה שֶׁנִּקְרֵאת (ירמיה ב) בֹּארֹת נִשְׁבָּרִים וְגוֹ', שֶׁהֵם מַיִם הַמָּרִים, מַיִם עֲכוּרִים, מְכֻנָּסִים, סְרוּחִים וּמְטֻנָּפִים, וְעַל כֵּן יִשְׂרָאֵל הַקְּדוֹשִׁים מַבְדִּילִים בֵּין מַיִם לָמָיִם.</p>\n<p>כָּתוּב (שמות כ) לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךְ לַשָּׁוְא, וְכָתוּב בְּמַעֲשֵׂה בְרֵאשִׁית, (בראשית א) יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד. בֹּא וּרְאֵה, כָּל מִי שֶׁנִּשְׁבַּע בְּשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא לַשֶּׁקֶר, כְּאִלּוּ הִפְרִיד אֶת הָאֵם מִמְּקוֹמָהּ לְמַעְלָה, וְהַכְּתָרִים הַקְּדוֹשִׁים אֵינָם מִתְיַשְּׁבִים בִּמְקוֹמָם, כְּמוֹ שֶׁנֶּאֱמַר (משלי טז) וְנִרְגָּן מַפְרִיד אַלּוּף. וְאֵין אַלּוּף אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא. וְכָתוּב יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד, אַל תָּשִׂים פֵּרוּד בִּגְלַל שְׁבוּעַת שֶׁקֶר. אֶל מָקוֹם אֶחָד, כָּרָאוּי בִּמְקוֹם אֱמֶת, וְלֹא בְמָקוֹם אַחֵר לַשֶּׁקֶר. וּמָה הַשֶּׁקֶר? הוּא שֶׁהוֹלְכִים הַמַּיִם לְמָקוֹם אַחֵר שֶׁאֵינוֹ שֶׁלָּהֶם.</p>\n<p>כָּתוּב זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ, וְכָתוּב בְּמַעֲשֵׂה בְרֵאשִׁית, תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב. מָתַי מִתְגַּדֶּלֶת הָאָרֶץ הַקְּדוֹשָׁה וּמִתְעַטֶּרֶת בְּעַטְרוֹתֶיהָ? הֱוֵי אוֹמֵר, בְּיוֹם הַשַּׁבָּת, שֶׁהֲרֵי אָז מִתְחַבֶּרֶת הַכַּלָּה (הגבירה) עִם הַמֶּלֶךְ לְהוֹצִיא דְשָׁאִים וּבְרָכוֹת לָעוֹלָם.</p>\n<p>כָּתוּב כַּבֵּד אֶת אָבִיךְ וְאֶת אִמֶּךְ, וְכָתוּב בְּמַעֲשֵׂה בְרֵאשִׁית, יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם. מַה זֶּה אוֹמֵר? אֶלָּא אֵלּוּ הַמְּאוֹרוֹת, זֶהוּ אָבִיךְ וְאִמֶּךְ. אָבִיךְ זֶה הַשֶּׁמֶשׁ. אִמֶּךְ זוֹ הַלְּבָנָה. וְאֵין שֶׁמֶשׁ אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים פד) כִּי שֶׁמֶשׁ וּמָגֵן ה' אֱלֹהִים. וְאֵין לְבָנָה אֶלָּא כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב (ישעיה ס) וִירֵחֵךְ לֹא יֵאָסֵף, וְעַל כֵּן הַכֹּל אֶחָד.</p>\n<p>כָּתוּב לֹא תִרְצַח, וְכָתוּב בְּמַעֲשֵׂה בְרֵאשִׁית, יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה, וְאַתָּה אַל תַּהֲרֹג אָדָם שֶׁנִּקְרָא כָּךְ, שֶׁכָּתוּב וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה. וְאַל תִּהְיֶה כַדָּגִים הַלָּלוּ, שֶׁגְּדוֹלִים בּוֹלְעִים אֶת הַקְּטַנִּים.</p>\n<p>כָּתוּב לֹא תִנְאָף, וְכָתוּב בְּמַעֲשֵׂה בְרֵאשִׁית, תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. מִכָּאן לָמַדְנוּ שֶׁלֹּא יְשַׁקֵּר אָדָם בְּאִשָּׁה אַחֶרֶת שֶׁאֵינָהּ בַּת זוּגוֹ, וְלָכֵן כָּתוּב תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ, שֶׁלֹּא תוֹלִיד אִשָּׁה אֶלָּא מִמִּינָהּ, וּמִיהוּ מִינָהּ? זֶה בֶּן זוּגָהּ.</p>\n<p>כָּתוּב לֹא תִגְנֹב, וְכָתוּב בְּמַעֲשֵׂה בְרֵאשִׁית, וַיֹּאמֶר אֱלֹהִים הִנֵּה נָתַתִּי לָכֶם אֶת כָּל עֵשֶׂב זֹרֵעַ זֶרַע. מַה שֶּׁנָּתַתִּי לָכֶם וְצִוִּיתִי לָכֶם, יִהְיֶה לָכֶם, וְאַל תִּגְנְבוּ מַה שֶּׁהוּא שֶׁל אַחֵר.</p>\n<p>כָּתוּב לֹא תַעֲנֶה בְרֵעֲךְ עֵד שָׁקֶר, וְכָתוּב בְּמַעֲשֵׂה בְרֵאשִׁית, וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ. מִי שֶׁהוּא בִּדְיוֹקַן הַמֶּלֶךְ, אַל תָּעִיד בּוֹ שֶׁקֶר. וּמִי שֶׁמֵּעִיד שֶׁקֶר בַּחֲבֵרוֹ, כְּאִלּוּ הֵעִיד לְמַעְלָה.</p>\n<p>כָּתוּב לֹא תַחְמֹד אֵשֶׁת רֵעֶךְ, וְכָתוּב בְּמַעֲשֵׂה בְרֵאשִׁית, לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ וְגוֹ'. הֲרֵי בַּת זוּגְךְ כְּנֶגְדְּךְ, וְלָכֵן לֹא תַחְמֹד אֵשֶׁת רֵעֶךְ.</p>\n<p>וְהַיְנוּ עֲשָׂרָה מַאֲמָרוֹת לְמַעֲשֵׂה בְרֵאשִׁית, וַעֲשָׂרָה מַאֲמָרוֹת לְמַתַּן תּוֹרָה. וְהַיְנוּ שֶׁכָּתוּב (במדבר ז) עֲשָׂרָה עֲשָׂרָה הַכַּף בְּשֶׁקֶל הַקֹּדֶשׁ. נִשְׁקְלוּ כְאֶחָד בְּמִשְׁקָל אֶחָד, וּמִשּׁוּם כָּךְ עוֹמֵד הָעוֹלָם וְנִמְצָא בוֹ שָׁלוֹם. וְעַל כֵּן, אִם זֶבַח שְׁלָמִים קָרְבָּנוֹ, לְהַעֲמִיד הָעוֹלָם בְּשָׁלוֹם. וְלֹא עוֹד, אֶלָּא שֶׁמְּכַפֵּר עַל מִצְווֹת עֲשֵׂה וְעַל מִצְווֹת לֹא תַעֲשֶׂה, כְּדֵי לְהַטִּיל שָׁלוֹם עַל הַכֹּל.</p>\n<p>כָּתוּב (איוב כה) הַמְשֵׁל וָפַחַד עִמּוֹ עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ הַחֲבֵרִים. אֲבָל הַמְשֵׁל - זֶה אַבְרָהָם, שֶׁכָּתוּב בּוֹ (בראשית כג) נְשִׂיא אֱלֹהִים אַתָּה בְּתוֹכֵנוּ, וְכָתוּב (שם יב) וַאֲבָרֶכְךְ וַאֲגַדְּלָה שְׁמֶךְ. וָפַחַד - זֶה יִצְחָק, שֶׁכָּתוּב (שם לא) וּפַחַד יִצְחָק הָיָה לִי. עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו - זֶה יַעֲקֹב, שֶׁכָּתוּב (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב, וְכָתוּב (זכריה ח) וְהָאֱמֶת וְהַשָּׁלוֹם אֱהָבוּ. שֶׁאֱמֶת וְשָׁלוֹם קְשׁוּרִים זֶה עִם זֶה, וְלָכֵן הוּא שְׁלֵמוּת הַכֹּל.</p>"],[9522011950,"<p>וּשְׁלָמִים הוּא שְׁלֵמוּת, וְהַשָּׁלוֹם שֶׁל הַכֹּל. וּמִי שֶׁמַּקְרִיב שְׁלָמִים, מַרְבֶּה שָׁלוֹם בָּעוֹלָם. יַעֲקֹב עָשָׂה שָׁלוֹם, כְּמוֹ שֶׁאָמַרְנוּ, מִשּׁוּם שֶׁאָחַז אֶת זֶה וְאֶת זֶה. וּשְׁלָמִים אֲחוּזִים בְּמִצְווֹת עֲשֵׂה וּבְמִצְווֹת לֹא תַעֲשֶׂה, בַּצַּד הַזֶּה וּבַצַּד הַזֶּה, וְעַל כֵּן נִקְרָא שְׁלָמִים. וְסוֹד הַדָּבָר - שֶׁכָּתוּב (בראשיתכה) וְיַעֲקֹב אִישׁ תָּם, אִישׁ שָׁלֵם, שָׁלֵם לְמַעְלָה וְשָׁלֵם לְמַטָּה. דָּבָר אַחֵר הַמְשֵׁל (איוב כה) - זֶה מִיכָאֵל. וָפַחַד - זֶה גַבְרִיאֵל. זֶה יְסוֹדוֹ מִמַּיִם, וְזֶה יְסוֹדוֹ מֵאֵשׁ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה שָׁלוֹם בֵּינֵיהֶם, שֶׁכָּתוּב (שם) עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו.</p>\n<p>רַבִּי אָחָא אָמַר, כָּתוּב (ויקרא ז) אִם עַל תּוֹדָה יַקְרִיבֶנּוּ וְהִקְרִיב עַל זֶבַח הַתּוֹדָה וְגוֹ'. מַה זֶּה אוֹמֵר? כְּמוֹ שֶׁנֶּאֱמַר, (שם ה) וְהִתְוַדָּה אֲשֶׁר חָטָא עָלֶיהָ. עָלֶיהָ דַּוְקָא. וְעַל זֶה חַלּוֹת מַצּוֹת וְגוֹ'. וְחַלּוֹת מַצּוֹת, הֲרֵי פֵּרְשׁוּהָ, וְעַל מַה בָּאָה? מַצֹּת וְחַלֹּת כָּתוּב חָסֵר, מִשּׁוּם שֶׁחָטָא עָלֶיהָ.</p>\n<p>שָׁנָה רַבִּי חִיָּיא, כָּתוּב עַל זֶבַח תּוֹדַת שְׁלָמָיו, זוֹ שְׁלֵמוּת הַכֹּל. שְׁלָמָיו - שְׁנַיִם. תּוֹדָה, נוֹדָע. אָמַר לוֹ רַבִּי יְהוּדָה, תּוֹדָה יָדוּעַ. שְׁלָמָיו לָמָּה זֶה שְׁנַיִם? אָמַר לוֹ, שְׁנֵי וָוִי\"ם, וָ\"ו שֶׁהַיְנוּ שְׁלָמָיו, הַשָּׁלוֹם שֶׁל הַכֹּל.</p>\n<p>אָמַר רַבִּי יִצְחָק, תּוֹדַת שְׁלָמָיו, שֶׁמַּטִּיל שָׁלוֹם בַּכֹּל, וּמִתְעוֹרְרִים רַחֲמִים בְּכָל הָעוֹלָמוֹת. תּוֹדַת שְׁלָמָיו, אָמַר רַבִּי יוֹסֵי, מַה שֶּׁאָמַר רַבִּי חִיָּיא - יָפֶה, שֶׁכְּנֶסֶת יִשְׂרָאֵל מִתְבָּרֶכֶת מֵאוֹתָם שְׁנַיִם, שֶׁהֵם הַשָּׁלוֹם שֶׁל הַכֹּל. רַבִּי יוֹסֵי אָמַר, לֶחֶם חָמֵץ הֲרֵי יָדוּעַ, וַהֲרֵי נִתְבָּאֵר, כְּמוֹ שֶׁהָיָה חֵטְא, כָּךְ הָיָה מַקְרִיב בְּאוֹתוֹ גָוֶן מַמָּשׁ.</p>\n<p>בֹּא רְאֵה, חַלֹּת מַצֹּת חָסֵר, כְּמוֹ שֶׁנֶּאֱמַר בְּלוּלֹת בַּשֶּׁמֶן וּרְקִיקֵי מַצּוֹת מְשֻׁחִים בַּשָּׁמֶן. לְמָה זֶה רוֹמֵז? אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי הֵם (בראשית ג) לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת וְגוֹ'. מִשּׁוּם שֶׁכֻּלָּם הִתְמַנּוּ עַל דַּרְכֵי בְּנֵי אָדָם, עַל אוֹתָם שֶׁעוֹבְרִים עַל מִצְווֹת הַתּוֹרָה, וְעַל כֵּן הַכֹּל סֹלֶת בְּלוּלָה בַּשֶּׁמֶן, לְהַמְשִׁיךְ שֶׁמֶן מִשְׁחָה מֵהַמָּקוֹם הָעֶלְיוֹן לְמַטָּה, וְיִתְבָּרְכוּ כֻלָּם כְּאֶחָד מֵאוֹתוֹ שֶׁמֶן מִשְׁחַת קֹדֶשׁ.</p>\n<p>וְזְהִוּ יַיִן לַנֶּסֶךְ, וַהֲרֵי בֵּאַרְנוּ רְבִיעִית הַהִין. וּמָקוֹם אֶחָד (תלוי) מָלֵא יַיִן וְשֶׁמֶן וּמַיִם לְנִסּוּךְ, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים, מַיִם לְהַשְׁקוֹת אֶת הַגָּן וְאֶת כָּל אוֹתָן הַנְּטִיעוֹת. וְעַל כֵּן, יֵשׁ מַיִם וְיֵשׁ מַיִם. יַיִן, יֵשׁ מָקוֹם שֶׁהוּא טוֹב, וְיֵשׁ מָקוֹם שֶׁהוּא לְהַעֲנִישׁ, שֶׁהוּא דִין.</p>\n<p>עֵל כֵּן, מִי שֶׁרוֹאֶה יַיִן בַּחֲלוֹמוֹ - יֵשׁ לְמִי שֶׁהוּא טוֹב, וְיֵשׁ לְמִי שֶׁהוּא דִין. אִם תַּלְמִיד חָכָם הוּא, כָּתוּב (תהלים קד) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ. וְכָתוּב, (שיר א) טוֹבִים דֹּדֶיךְ מִיָּיִן. זֶהוּ יַיִן הַמְשֻׁמָּר שֶׁמְּשַׂמֵּחַ אֶת הַכֹּל. וְאִם לֹא - (משלי לא) תְּנוּ שֵׁכָר לְאוֹבֵד וְיַיִן לְמָרֵי נָפֶשׁ. יֵשׁ יַיִן אַחֵר שֶׁהוּא דִין, וְעַל כֵּן נָאֶה לְהַקְרִיב אֶת הַדְּבָרִים הַלָּלוּ בְּקָרְבָּנוֹ, כְּדֵי שֶׁיָּעֳבַר הַדִּין וְיִתְעוֹרְרוּ רַחֲמִים. עוֹבֵר יַיִן וּבָא יַיִן, וְכֵן בַּכֹּל.</p>\n<p>וְשֶׁמֶן אֵינוֹ סָר מִקָּרְבָּנוֹת לְעוֹלָמִים, פְּרָט לְמִנְחַת קְנָאוֹת, שֶׁכָּתוּב (במדבר ה) לֹא יִצֹק עָלָיו שֶׁמֶן וְגוֹ'. שֶׁהֲרֵי כָּאן לֹא צְרִיכִים רַחֲמִים, שֶׁהֲרֵי הַכֹּל דִּין, שֶׁכָּתוּב וְצָבְתָה בִּטְנָהּ וְנָפְלָה יְרֵכָהּ. וְכָתוּב יִתֵּן ה' וְגוֹ'. וְעַל זֶה, וְזֹּאת תּוֹרַת זֶבַח הַשְּׁלָמִים אִם עַל תּוֹדָה יַקְרִיבֶנּוּ.</p>"],[9522011951,"<p>רַבִּי חִזְקִיָּה הָיָה יוֹשֵׁב לִפְנֵי רַבִּי יִצְחָק. קָמוּ בַחֲצוֹת הַלַּיְלָה לִלְמֹד תּוֹרָה. פָּתַח רַבִּי יִצְחָק וְאָמַר, (תהלים קלד) הִנֵּה בָּרְכוּ אֶת ה' כָּל עַבְדֵי ה' וְגוֹ'. הַפָּסוּק הַזֶּה הֲרֵי פֵּרְשׁוּהוּ הַחֲבֵרִים וַהֲרֵי נִתְבָּאֵר, אֲבָל הַשֶּׁבַח הַזֶּה הוּא שֶׁל כָּל בְּנֵי הָאֱמוּנָה, וּמִי הֵם בְּנֵי הָאֱמוּנָה? אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי. וְהַשֶּׁבַח שֶׁל אוֹתָם בְּנֵי הָאֱמוּנָה, אוֹתָם שֶׁעוֹמְדִים בַּחֲצוֹת הַלַּיְלָה לַעֲסֹק בַּתּוֹרָה וְנִדְבָּקִים בִּכְנֶסֶת יִשְׂרָאֵל לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדִבְרֵי תוֹרָה.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁאָדָם קָם בַּחֲצוֹת הַלַּיְלָה לַעֲסֹק בַּתּוֹרָה וְרוּחַ צָפוֹן מִתְעוֹרֶרֶת בַּחֲצוֹת הַלַּיְלָה, אוֹתָהּ אַיֶּלֶת עוֹמֶדֶת וּמְשַׁבַּחַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. וּבְשָׁעָה שֶׁהִיא עוֹמֶדֶת, כַּמָּה אֲלָפִים וְכַמָּה רְבָבוֹת עוֹמְדִים עִמָּהּ בִּמְקוֹמָם, וְכֻלָּם מַתְחִילִים לְשַׁבֵּחַ אֶת הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>אוֹתוֹ מִי שֶׁזָּכָה וְקָם בַּחֲצוֹת הַלַּיְלָה לַעֲסֹק בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַקְשִׁיב לוֹ, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (שירח) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי. וְכָל אוֹתָם אוּכְלוּסִים שֶׁל מַעְלָה וְכָל בְּנֵי הַתִּשְׁבַּחַת שֶׁמְּזַמְּרִים לְרִבּוֹנָם, כֻּלָּם שׁוֹכְכִים בִּשְׁבִיל הַתִּשְׁבַּחַת שֶׁל אוֹתָם שֶׁעָסְקוּ בַתּוֹרָה, וּמַכְרִיזִים וְאוֹמְרִים: (תהלים קלד) הִנֵּה בָּרְכוּ אֶת ה' כָּל עַבְדֵי ה'. אַתֶּם בָּרְכוּ אֶת ה', אַתֶּם שַׁבְּחוּ אֶת הַמֶּלֶךְ הַקָּדוֹשׁ, אַתֶּם עַטְּרוּ אֶת הַמֶּלֶךְ.</p>\n<p>וְאוֹתָהּ הָאַיֶּלֶת מִתְעַטֶּרֶת בְּאוֹתוֹ אָדָם, וְעוֹמֶדֶת לִפְנֵי הַמֶּלֶךְ וְאוֹמֶרֶת: רְאֵה בְּאֵיזֶה בֵן בָּאתִי לְפָנֶיךְ, בְּאֵיזֶה בֵן הִתְעוֹרַרְתִּי אֵלֶיךְ. וּמִי הֵם שֶׁהַשֶּׁבַח כֻּלּוֹ שֶׁלָּהֶם לִפְנֵי הַמֶּלֶךְ? וְחוֹזֵר וְאוֹמֵר, הָעוֹמְדִים בְּבֵית ה' בַּלֵּילוֹת, אֵלּוּ נִקְרָאִים עַבְדֵי ה', אֵלּוּ רְאוּיִים לְבָרֵךְ אֶת הַמֶּלֶךְ, וּבִרְכָתָם בְּרָכָה, זֶהוּ שֶׁכָּתוּב (שם) שְׂאוּ יְדֵיכֶם קֹדֶשׁ וּבָרְכוּ אֶת ה' וְגוֹ'. אַתֶּם רְאוּיִים שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ יִתְבָּרֵךְ עַל יְדֵיכֶם, וְהַבְּרָכָה שֶׁעַל יְדֵיכֶם בְּרָכָה הִיא.</p>"],[9522011952,"<p>שְׂאוּ יְדֵיכֶם קֹדֶשׁ. מַהוּ קֹדֶשׁ? הַמָּקוֹם הָעֶלְיוֹן שֶׁמַּעְיַן הַנַּחַל הֶעָמֹק יוֹצֵא מִמֶּנּוּ, שֶׁכָּתוּב וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת. וְעֵדֶן הוּא שֶׁנִּקְרָא קֹדֶשׁ עֶלְיוֹן, מִשּׁוּם כָּךְ שְׂאוּ יְדֵיכֶם קֹדֶשׁ. וְאָדָם שֶׁעוֹשֶׂה כֵּן וְזוֹכֶה לָזֶה, מַה מַּכְרִיזִים עָלָיו? יְבָרֶכְךְ ה' מִצִּיּוֹן, אַתָּה תְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא מִמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ עֶלְיוֹן, וְהוּא יְבָרֵךְ אוֹתְךְ מִמָּקוֹם שֶׁנִּקְרָא צִיּוֹן, שֶׁאַתָּה וְהַגְּבִירָה תִּתְבָּרְכוּ כְאֶחָד.</p>\n<p>כְּמוֹ שֶׁהַזִּוּוּג שֶׁלָּכֶם הָיָה כְאֶחָד לְשַׁבֵּחַ אֶת הַמֶּלֶךְ, כָּךְ מֵאוֹתוֹ מָקוֹם שֶׁמִּתְבָּרֶכֶת כְּנֶסֶת יִשְׂרָאֵל, מֵאוֹתוֹ מָקוֹם יַזְמִין לְךְ בְּרָכוֹת. זֶהוּ שֶׁכָּתוּב יְבָרֶכְךְ ה' מִצִּיּוֹן וּרְאֵה בְּטוּב יְרוּשָׁלם. מִי הוּא טוּב יְרוּשָׁלַיִם? אוֹתָן בְּרָכוֹת שֶׁיּוֹצְאוֹת לָהּ מֵהַמֶּלֶךְ עַל יְדֵי אוֹתָהּ דַּרְגַּת צַדִּיק הַקְּדוֹשָׁה. וְעַל כֵּן, יְבָרֶכְךְ ה' מִצִּיּון וּרְאֵה בְּטוּב יְרוּשָׁלם, וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>וּרְאֵה בָנִים לְבָנֶיךְ וְגוֹ'. וּרְאֵה בָנִים לְבָנֶיךְ - יָפֶה, מַה זֶּה שָׁלוֹם עַל יִשְׂרָאֵל? מַה צָּרִיךְ כָּאן עַל יִשְׂרָאֵל? אֶלָּא מִשּׁוּם שֶׁמַּרְבֶּה שָׁלוֹם לְמַעְלָה, שֶׁכַּאֲשֶׁר הוּא זוֹכֶה לְכָל זֶה, מַרְבֶּה שָׁלוֹם לְמַעְלָה וּלְמַטָּה. שָׁלוֹם עַל יִשְׂרָאֵל, סְתָם. וְהַשָּׁלוֹם הוּא שִׁבְחָם שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים, שֶׁבַח הוּא שֶׁל כָּל הָעוֹלָמוֹת, וְדִבְרֵי תוֹרָה מַרְבִּים שָׁלוֹם בָּעוֹלָם, שֶׁכָּתוּב (שם כט) ה' עֹז לְעַמּוֹ יִתֵּן ה' יְבָרֵךְ אֶת עַמּוֹ בַשָּׁלוֹם.</p>"],[9522011953,"<p>נֶפֶשׁ כִּי תֶחֱטָא. רַבִּי יוֹסֵי פָּתַח, (שיר ב) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים וְגוֹ'. כַּמָּה יֵשׁ לָהֶם לִבְנֵי אָדָם לְהִזָּהֵר מֵחֲטָאֵיהֶם שֶׁלֹּא לַחֲטֹא לִפְנֵי רִבּוֹנָם, שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם יוֹצֵא כָרוֹז וְקוֹרֵא: הָעִירוּ בְּנֵי הָעוֹלָם אֶת לִבְּכֶם לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ! הָעִירוּ לְהִזָּהֵר מֵחֲטָאֵיכֶם! הָעִירוּ אֶת הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁנָּתַן בְּתוֹכֲכֶם מֵהַמָּקוֹם הָעֶלְיוֹן הַקָּדוֹשׁ.</p>\n<p>שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁמּוֹצִיא הַקָּדוֹשׁ בָּרוּךְ הוּא נְשָׁמָה לְהוֹרִידָהּ לִבְנֵי אָדָם, הוּא מֵעִיד בָּהּ בְּכַמָּה יִעוּדִים, בְּכַמָּה עֳנָשִׁים, כְּדֵי לִשְׁמֹר אֶת מִצְווֹתָיו. וְלֹא עוֹד, אֶלָּא שֶׁמַּעֲבִיר אוֹתָהּ בְּאֶלֶף וּשְׁמוֹנָה עוֹלָמוֹת לְהִשְׁתַּעֲשֵׁעַ, וְלִרְאוֹת בָּהֶם אֶת כְּבוֹד אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה. (יוצאת) וְעוֹמֶדֶת לִפְנֵי הַמֶּלֶךְ בִּלְבוּשׁ נִכְבָּד, בִּדְמוּת שֶׁל הָעוֹלָם הַזֶּה, בִּלְבוּשׁ נִכְבָּד עֶלְיוֹן מִסְתַּכֶּלֶת בִּכְבוֹד הַמֶּלֶךְ בְּכָל יוֹם וּמְעַטֵּר אוֹתָהּ בְּכַמָּה עֲטָרוֹת.</p>\n<p>בְּשָׁעָה שֶׁמַּגִּיעַ זְמַנָּהּ לָרֶדֶת לָעוֹלָם, הוּא עוֹשֶׂה מְדוֹרָהּ בְּגַן עֵדֶן שֶׁל הָאָרֶץ שְׁלֹשִׁים יָמִים, לִרְאוֹת אֶת כְּבוֹד רִבּוֹנָם שֶׁל הַצַּדִּיקִים, וְעוֹלֶה לִמְקוֹמָהּ לְמַעְלָה, וְאַחַר כָּךְ יוֹרֶדֶת לָעוֹלָם, וְהַמֶּלֶךְ הַקָּדוֹשׁ מְעַטֵּר אוֹתָהּ בְּשֶׁבַע עֲטָרוֹת, עַד שֶׁבָּאָה וְנִכְנֶסֶת לְתוֹךְ גּוּף שֶׁל אָדָם. וּכְשֶׁהִיא בְּגוּף שֶׁל אָדָם וְחוֹטֵאת בָּעוֹלָם הַזֶּה וּמִתְעַסֶּקֶת בַּחֹשֶׁךְ שֶׁלָּהּ, הַתּוֹרָה תְּמֵהָה עָלֶיהָ וְאוֹמֶרֶת: וּמַה כָּל הַכָּבוֹד הַזֶּה וְכָל הַשְּׁלֵמוּת שֶׁהִשְׁלִים לַנֶּפֶשׁ הַזּוֹ הַמֶּלֶךְ הָעֶלְיוֹן וְהִיא חוֹטֵאת לְפָנָיו?! נֶפֶשׁ כִּי תֶחֱטָא, מַה הַדִּין הוּא שֶׁתֶּחֱטָא?</p>\n<p>אָמַר רַבִּי יוֹסֵי, נֶפֶשׁ כִּי תֶחֱטָא, חָזַרְנוּ לַכָּתוּב עַד שֶׁיָּפוּחַ הַיּוֹם. הָעֵצָה לַנֶּפֶשׁ הַזּוֹ לְהִזָּהֵר מֵחֲטָאֶיהָ וְתָשׁוּב לְהִטָּהֵר - עַד שֶׁיָּפוּחַ הַיּוֹם, עַד שֶׁלֹּא יָפוּחַ הַיּוֹם שֶׁל הָעוֹלָם הַזֶּה וְיָבא אוֹתוֹ הַיּוֹם הַקָּשֶׁה שֶׁיִּתְבְּעֶנָּה הַמֶּלֶךְ דִּין לָצֵאת מֵהָעוֹלָם הַזֶּה. וְנָסוּ הַצְּלָלִים - זֶהוּ סוֹד שֶׁאוֹמְרִים בֵּין הַחֲבֵרִים, שֶׁבְּשָׁעָה שֶׁמַּגִּיעַ זְמַנּוֹ שֶׁל אָדָם לָצֵאת מִן הָעוֹלָם, צֶלֶם הָאָדָם מָעֳבָר מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב עַד שֶׁיָּפוּחַ הַיּוֹם, טֶרֶם שֶׁיִּנְשֹׁף הַיּוֹם לָצֵאת מֵהָעוֹלָם הַזֶּה. וְנָסוּ הַצְּלָלִים, שֶׁיָּעֳבַר הַצֶּלֶם, יָשׁוּב לִפְנֵי רִבּוֹנוֹ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, שְׁנֵי צְלָמִים יֵשׁ לָאָדָם כְּשֶׁהוּא בְקִיּוּמוֹ, אֶחָד גָּדוֹל וְאֶחָד קָטָן, שֶׁכָּתוּב הַצְּלָלִים, שְׁנַיִם. וּכְשֶׁנִּמְצָאִים כְּאֶחָד, אֲזַי הָאָדָם בְּקִיּוּמוֹ. וְעַל זֶה כָּתוּב וְנָסוּ הַצְּלָלִים. אֲזַי צָרִיךְ אָדָם לְהִסְתַּכֵּל בְּמַעֲשָׂיו וּלְתַקְּנָם לִפְנֵי אֲדוֹנוֹ וְיוֹדֶה עֲלֵיהֶם, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא רַחוּם וְחַנּוּן, וּמְקַבֵּל אֶת אוֹתָם שֶׁשָּׁבִים לְפָנָיו.</p>\n<p>וְזְהִוּ עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים, שֶׁכֵּיוָן שֶׁאוֹתָם צְלָלִים עָבְרוּ מִמֶּנּוּ וְהוּא תָפוּס בְּקוֹלָר, זוֹ תְשׁוּבָה, אֲבָל לֹא כָּל כָּךְ מְעֻלָּה כְּמוֹ בִּזְמַן שֶׁהוּא עוֹמֵד בְּקִיּוּמוֹ. וּשְׁלֹמֹה הַמֶּלֶךְ מַכְרִיז וְאוֹמֵר, (קהלתיב) וּזְכֹר אֶת בּוֹרְאֶיךְ בִּימֵי בְּחוּרֹתֶיךְ עַד אֲשֶׁר לֹא יָבֹאוּ יְמֵי הָרָעָה וְגוֹ'.</p>\n<p>וְעַל זֶה עַד שֶׁיָּפוּחַ הַיּוֹם, שֶׁצָּרִיךְ אָדָם לְתַקֵּן מַעֲשָׂיו. שֶׁכְּשֶׁמַּגִּיעִים יָמָיו לְהִסְתַּלֵּק מֵהָעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹהֶה עָלָיו וְאוֹמֵר, וְנֶפֶשׁ כִּי תֶחֱטָא וְשָׁמְעָה קוֹל אָלָה, וַהֲרֵי הִשְׁבַּעְתִּי אוֹתָהּ בִּשְׁבוּעָה שֶׁל שְׁמִי שֶׁלֹּא לְשַׁקֵּר בִּי, וְהֵעַדְתִּי בָהּ כְּשֶׁיָּרְדָה לָעוֹלָם, וְהוּא עֵד וַדַּאי, מִכַּמָּה פְעָמִים שֶׁהֵעַדְתִּי בָהּ לִשְׁמֹר מִצְווֹתַי. לָכֵן, הוֹאִיל וְהָאָדָם הוּא עֵד, בְּשָׁעָה שֶׁיָּשׁוּב לִפְנֵי הַמֶּלֶךְ - אוֹ רָאָה אוֹ יָדָע. אוֹ רָאָה אוֹתָם חֲטָאִים שֶׁעָשָׂה וְהִתְבּוֹנֵן בָּהֶם. אוֹ יָדָע בְּבֵרוּר הַדָּבָר שֶׁעָבַר עַל מִצְוַת רִבּוֹנוֹ. אִם לוֹא יַגִּיד - אִם לֹא יוֹדֶה עֲלֵיהֶם לִפְנֵי רִבּוֹנוֹ (מה כתוב) כְּשֶׁיֵּצֵא מִן הָעוֹלָם הַזֶּה, וְנָשָׂא עֲונוֹ. וּכְשֶׁיִּשָּׂא עֲונוֹ, אֵיךְ יִפְתְּחוּ לוֹ פֶּתַח וְאֵיךְ יַעֲמֹד לִפְנֵי רִבּוֹנוֹ, וְעַל זֶה נֶפֶשׁ כִּי תֶחֱטָא כָּתוּב.</p>"],[9522011954,"<p>נֶפֶשׁ כִּי תֶחֱטָא. רַבִּי אַבָּא פָּתַח, (תהלים מד) כָּל זֹּאת בָּאַתְנוּ וְלֹא שְׁכַחֲנוּךְ וְלֹא שִׁקַּרְנוּ בִּבְרִיתֶךְ. כָּל זֹּאת בָּאַתְנוּ, הָיָה צָרִיךְ לִהְיוֹת כָּל אֵלּוּ בָּאוּ עָלֵינוּ! אֶלָּא כָּל הַדִּינִים שֶׁלְּמַעְלָה בָּאוּ עָלֵינוּ. וְלֹא שְׁכַחֲנוּךְ, וְלֹא שָׁכַחְנוּ דִּבְרֵי תוֹרָתֶךְ. מִכָּאן לָמַדְנוּ, כָּל מִי שֶׁשּׁוֹנֶה דִּבְרֵי תוֹרָה וְלֹא רוֹצֶה לַעֲסֹק בָּהּ, כְּאִלּוּ שָׁכַח אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי כָּל הַתּוֹרָה הִיא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְלֹא שִׁקַּרְנוּ בִּבְרִיתֶךְ, שֶׁכָּל מִי שֶׁמְּשַׁקֵּר בִּבְרִית הַקֹּדֶשׁ הַזּוֹ שֶׁרְשׁוּמָה בּוֹ, כְּאִלּוּ שֶׁמְּשַׁקֵּר בִּשְׁמוֹ שֶׁל הַמֶּלֶךְ, מִשּׁוּם שֶׁשְּׁמוֹ שֶׁל הַמֶּלֶךְ רָשׁוּם בָּאָדָם. וּמִקְרָא אַחֵר מוֹדֶה לַכָּתוּב הַזֶּה, שֶׁכָּתוּב (שם) אִם שָׁכַחְנוּ שֵׁם אֱלֹהֵינוּ וַנִּפְרֹשׂ כַּפֵּינוּ לְאֵל זָר. אִם שָׁכַחְנוּ שֵׁם אֱלֹהֵינוּ, כְּמוֹ שֶׁנֶּאֱמַר וְלֹא שְׁכַחְנוּךְ (וזוהי התורה שהיא שם אלהינו). וַנִּפְרֹשׂ כַּפֵּינוּ לְאֵל זָר, כְּמוֹ שֶׁנֶּאֱמַר וְלֹא שִׁקַּרְנוּ בִּבְרִיתֶךְ. וְהַכֹּל דָּבָר אֶחָד. מָה הַשֶּׁקֶר כָּאן? שֶׁפָּרַשׂ כַּפָּיו לְרָשׁוּת אַחֶרֶת וּמְשַׁקֵּר בַּבְּרִית הַזּוֹ, וְלָכֵן הַתּוֹרָה אוֹחֶזֶת בָּזֶה. שֶׁכָּל מִי שֶׁשּׁוֹמֵר אֶת הַבְּרִית הַזּוֹ כְּאִלּוּ שָׁמַר אֶת כָּל הַתּוֹרָה, וּמִי שֶׁמְּשַׁקֵּר בָּזֶה כְּאִלּוּ מְשַׁקֵּר בְּכָל הַתּוֹרָה.</p>\n<p>בֹּא רְאֵה, טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם הֲרֵי לֹא נֶאֱמַר שֶׁהוּא שָׁמַר אֶת הַתּוֹרָה. כֵּיוָן שֶׁנִּמּוֹל מַה כָּתוּב? (בראשית כו) עֵקֶב אֲשֶׁר שָׁמַע אַבְרָהָם בְּקֹלִי וַיִּשְׁמֹר מִשְׁמַרְתִּי מִצְותַי חֻקּוֹתַי וְתוֹרֹתָי. וְהַכֹּל מִשּׁוּם שֶׁנִּמּוֹל וְנִרְשַׁם בּוֹ הָרֹשֶׁם הַקָּדוֹשׁ וְשָׁמַר אוֹתוֹ כָּרָאוּי, מַעֲלֶה עָלָיו כְּאִלּוּ שָׁמַר אֶת כָּל הַתּוֹרָה. אַף בְּיִצְחָק כָּתוּב, (בראשית יז) וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק. וְעַל זֶה נִקְרֵאת הַתּוֹרָה בְּרִית.</p>\n<p>בֹּא רְאֵה, מִשּׁוּם שֶׁיּוֹסֵף שָׁמַר אֶת הַבְּרִית הַזּוֹ וְלֹא רָצָה לְשַׁקֵּר בָּהּ, זָכָה לְכָבוֹד בָּעוֹלָם הַזֶּה וּלְכָבוֹד בָּעוֹלָם הַבָּא, וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁרָה אֶת שְׁמוֹ בְּתוֹכוֹ, שֶׁכָּתוּב (תהלים פא) עֵדוּת בִּיהוֹסֵף שָׂמוֹ. וְזָכָה לְבִרְכַּת הָעוֹלָם הַזֶּה וּלְבִרְכַּת הָעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי יִצְחָק, כָּתוּב (דברים לג) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ וְגוֹ'. מִשּׁוּם שֶׁיּוֹסֵף שָׁמַר אֶת הַבְּרִית הַזּוֹ, זָכָה בְשׁוֹר, שֶׁהוּא רִאשׁוֹן לְקָרְבָּן. אָמַר לוֹ רַבִּי יְהוּדָה, אִם כָּךְ, לָמָּה הִתְבָּרֵךְ בְּדָבָר שֶׁהוּא שְׂמֹאל? בְּיָמִין הָיָה צָרִיךְ, שֶׁהֲרֵי כָּתוּב (יחזקאל א) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. אָמַר לוֹ, כְּדֵי שֶׁיָּגֵן עַל חֲטָאֵי יָרָבְעָם.</p>\n<p>אָמַר לוֹ, סוֹד לָמַדְנוּ בַּכָּתוּב הַזֶּה, שֶׁכֵּיוָן שֶׁיּוֹסֵף שָׁמַר אֶת הַבְּרִית הַזּוֹ, שֶׁהַבְּרִית הַזּוֹ אֲחוּזָה בִּשְׁתֵּי דְרָגוֹת, וְאוֹתָן שְׁתֵּי דְרָגוֹת לְמַעְלָה נִקְרְאוּ בְשֵׁמוֹת. וְלָמַדְנוּ בְּפָרָשַׁת פָּרָה אֲדֻמָּה, שֶׁהַפָּרָה הַזּוֹ הִיא דַּרְגָּה אַחַת מֵאוֹתָן שְׁתֵּי דְרָגוֹת עֶלְיוֹנוֹת, וְהַזִּוּוּג שֶׁל פָּרָה נִקְרָא שׁוֹר, וְזֶהוּ בְּכוֹר שׁוֹרוֹ הָדָר לוֹ וְקַרְנֵי רְאֵם קַרְנָיו. הָדָר לוֹ וַדַּאי. וְלֹא כְּמוֹ הַשּׁוֹר הַזֶּה שֶׁל הָעוֹלָם, אֶלָּא וְקַרְנֵי רְאֵם קַרְנָיו. קֶרֶן עֶלְיוֹנָה הִיא עַל כָּל הָאֲחֵרוֹת, וְעַל כֵּן - בָּהֶם עַמִּים יְנַגַּח יַחְדָּיו אַפְסֵי אָרֶץ.</p>\n<p>אָמַר רַבִּי אַבָּא, מַשְׁמָע שֶׁכָּל מִי שֶׁשּׁוֹמֵר אֶת אוֹת הָרֹשֶׁם הַקָּדוֹשׁ, אוֹתָן שְׁתֵּי דְרָגוֹת עֶלְיוֹנוֹת נִקְשָׁרוֹת בּוֹ, לִשְׁמֹר אוֹתוֹ בַּכֹּל וּלְעַטְּרוֹ בְּכָבוֹד עֶלְיוֹן, וְלָכֵן זָכָה בִּשְׁתֵּי מַלְכֻיּוֹת - אַחַת הוּא, וְאַחַת בְּנוֹ. שֶׁכֵּיוָן שֶׁשְּׁלֹמֹה הַמֶּלֶךְ נִדְבַּק בְּנָשִׁים נָכְרִיּוֹת, נִתְּנָה הַמַּלְכוּת לְיָרָבְעָם, וְלָכֵן הַבְּרִית חֲבִיבָה מֵהַכֹּל.</p>\n<p>מִשּׁוּם כָּךְ אָמַר רַבִּי שִׁמְעוֹן, הָאָדָם הַזֶּה שֶׁמּוֹלִיד בֵּן, נִקְשָׁר לַשְּׁכִינָה, שֶׁהִיא הַפֶּתַח שֶׁל כָּל הַפְּתָחִים (והתינוק הזה שנמול, נקשר בשכינה, שהיא פתח של כל הכתרים) הָעֶלְיוֹנִים, הַפֶּתַח שֶׁנִּקְשָׁר בַּשֵּׁם הַקָּדוֹשׁ. (שאמר רבי שמעון) וְאוֹתוֹ דָם שֶׁיּוֹצֵא מֵאוֹתוֹ תִינוֹק שָׁמוּר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבְשָׁעָה שֶׁמִּתְעוֹרְרִים דִּינִים בָּעוֹלָם, מַשְׁגִּיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ דָם וּמַצִּיל אֶת הָעוֹלָם. וּמִשּׁוּם כָּךְ כָּתוּב, (בראשית יז) וּבֶן שְׁמֹנַת יָמִים יִמּוֹל לָכֶם כָּל זָכָר. וְכָתוּב (תהלים צ) וְאִם בִּגְבוּרֹת שְׁמוֹנִים שָׁנָה. וְהַכֹּל עוֹלֶה בְּמִשְׁקָל אֶחָד.</p>\n<p>שָׁנִינוּ, בְּאוֹתוֹ הַדָּם זוֹכֶה הָעוֹלָם לְהִתְבַּשֵּׂם בְּחֶסֶד, וְכָל הָעוֹלָמוֹת עוֹמְדִים, שֶׁכָּתוּב (ירמיהלג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ וְגוֹ'. אִם לֹא בְרִיתִי מֵילָא, אֲבָל לָמָּה יוֹמָם וָלָיְלָה?</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, שָׁנִינוּ, שְׁנֵי כְתָרִים מִתְאַחֲדִים כְּאֶחָד וְהֵם הַפֶּתַח שֶׁל כָּל הַכְּתָרִים, וְשָׁנִינוּ, אֶחָד דִּין וְאֶחָד רַחֲמִים, וּמִתְבַּשְּׂמִים זֶה עִם זֶה, זָכָר וּנְקֵבָה. (ושנינו, אחד זכר ואחד נקבה, אחד דין ואחד רחמים). בְּצַד הַזָּכָר שָׁרוּי חֶסֶד, וּבְצַד הַנְּקֵבָה שָׁרוּי דִּין. (ומשום כך) אֶחָד לָבָן וְאֶחָד אָדם. וּכְדֵי לְהִתְבַּשֵּׂם זֶה עִם זֶה, (משום כך) הֵם מִתְקַשְּׁרִים זֶה בָּזֶה. וְהַבְּרִית הַזּוֹ אוֹחֶזֶת בָּהֶם בְּיוֹמָם וָלָיְלָה, בְּדִין וְחֶסֶד. בְּדִין בָּרִאשׁוֹנָה, וְאַחַר כָּךְ שׁוֹרֶה בְּחֶסֶד, וּמִתְבַּשֵּׂם בַּכֹּל. וְזוֹהִי הַבְּרִית שֶׁנִּקְרֵאת יוֹמָם וָלָיְלָה, שֶׁאוֹחֶזֶת בִּשְׁנֵיהֶם.</p>\n<p>וּמִי שֶׁזּוֹכֶה לִשְׁמֹר אֶת אוֹת הַבְּרִית הַזּוֹ כָּרָאוּי וְלֹא חוֹטֵא בָהּ כָּל יָמָיו, הוּא אוֹחֵז בְּיוֹמָם וָלָיְלָה, וְזוֹכֶה לִשְׁנֵי עוֹלָמוֹת, הָעוֹלָם הַזֶּה וְהָעוֹלָם הַבָּא. וְלָכֵן אַבְרָהָם נִקְרָא שָׁלֵם, שֶׁכָּתוּב (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. וְאֵימָתַי נִקְרָא שָׁלֵם? כְּשֶׁזָּכָה בִשְׁנֵיהֶם, בְּיוֹמָם וָלַיְלָה, שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. וּשְׁנֵיהֶם יָרַשׁ אַבְרָהָם, וְלֹא הִתְקַיֵּם בּוֹ הַחֶסֶד בְּקִיּוּם שָׁלֵם עַד שֶׁנִּמּוֹל. כֵּיוָן שֶׁנִּמּוֹל, הִתְקַיֵּם בּוֹ וְזָכָה לִשְׁנֵיהֶם, וְנִקְרָא שָׁלֵם.</p>\n<p>כְּמוֹ שֶׁשָּׁנִינוּ, שֶׁכָּתוּב (בראשית יח) וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל כְּחֹם הַיּוֹם. פֶּתַח הָאֹהֶל, זֶהוּ הַכֶּתֶר הָעֲשִׂירִי שֶׁל הַמֶּלֶךְ, שֶׁהִיא פֶּתַח לְכָל הַמִּשְׁכָּן הַקָּדוֹשׁ שֶׁל שְׁאָר הַכְּתָרִים, וְדָוִד הַמֶּלֶךְ קוֹרֵא (לזה) פֶּתַח (צדק), שֶׁכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק, וְכָתוּב זֶה הַשַּׁעַר לַה'. כְּחֹם הַיּוֹם, כְּשֶׁמֵּאִיר הָאוֹר שֶׁל הַחֶסֶד, חֵלֶק גּוֹרָלוֹ, כְּמוֹ שֶׁיָּשַׁב בָּזֶה - יָשַׁב בָּזֶה. מָתַי הִתְקַיְּמוּ בוֹ? כְּשֶׁנִּמּוֹל, וְלָכֵן נִקְרֵאת בְּרִית יוֹמָם וָלַיְלָה. שָׁנִינוּ, כָּתוּב (שמות יב) וּפָסַח ה' עַל הַפֶּתַח. מַה זֶּה וּפָסַח ה' עַל הַפֶּתַח? שֶׁשּׁוֹרֶה עַל הַפֶּתַח הַזֶּה חֶסֶד לְהִתְבַּשֵּׂם. וּמִשּׁוּם כָּךְ, וְלֹא יִתֵּן הַמַּשְׁחִית וְגוֹ'.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הֲרֵי שָׁנִינוּ, כְּשֶׁהַגֵּר נִמּוֹל וְנִכְנָס תַּחַת כַּנְפֵי הַשְּׁכִינָה, הוּא נִקְרָא גֵּר צֶדֶק וְלֹא יוֹתֵר, גֵּר צֶדֶק וַדַּאי, זוֹכֶה לְהִכָּנֵס לְאוֹתוֹ כֶּתֶר שֶׁל צֶדֶק, וְאַתָּה אוֹמֵר יוֹמָם וָלַיְלָה שֶׁזָּכוּ לִשְׁנֵיהֶם?</p>\n<p>אָמַר לוֹ רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי, אֵינוֹ דוֹמֶה מִי שֶׁבָּא מִשֹּׁרֶשׁ קָדוֹשׁ וּמִגֶּזַע אֱמֶת, לְמִי שֶׁבָּא מִגֶּזַע רַע וּמִשֹּׁרֶשׁ שֶׁל גְּעָלִים רָעִים קָשִׁים. בְּיִשְׂרָאֵל כָּתוּב בָּהֶם, (ירמיה ב) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת. בְּאֻמּוֹת עוֹבְדֵי עֲבוֹדָה זָרָה כָּתוּב, (יחזקאל כג) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם וְזִרְמַת סוּסִים זִרְמָתָם.</p>\n<p>וּמִשּׁוּם כָּךְ, יִשְׂרָאֵל קְדוֹשִׁים זֶרַע שֶׁל אֱמֶת, גֶּזַע שֶׁהִתְבַּשְּׂמוּ בְּהַר סִינַי וּפָסְקָה מֵהֶם כָּל הַזֻּהֲמָה, כֻּלָּם מִתְבַּשְּׂמִים, וְכֻלָּם נִכְנָסִים בַּבְּרִית הַקְּדוֹשָׁה שֶׁל יוֹמָם וָלָיְלָה לִהְיוֹת שְׁלֵמִים בַּכֹּל. אֲבָל בְּאֻמּוֹת עוֹבְדֵי עֲבוֹדָה זָרָה קָשֶׁה לְהַעֲבִיר מֵהֶם אֶת הַזֻּהֲמָה, וַאֲפִלּוּ עַד שְׁלֹשָׁה דוֹרוֹת. וּמִשּׁוּם כָּךְ שָׁנִינוּ, טוֹב שֶׁבְּעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת וְכוּ', וּמִשּׁוּם כָּךְ גֵּר צֶדֶק וַדַּאי.</p>\n<p>שֶׁאָמַר רַב הַמְנוּנָא סָבָא, אֻמּוֹת עוֹבְדֵי עֲבוֹדָה זָרָה, טֶרֶם שֶׁנִּמּוֹלוּ שְׁרוּיִים הֵם בִּכְתָרִים תַּחְתּוֹנִים שֶׁאֵינָם קְדוֹשִׁים, וְרוּחַ טֻמְאָה שׁוֹרָה עֲלֵיהֶם. כֵּיוָן שֶׁהִתְגַּיְּרוּ וְנִמּוֹלוּ, הֵם שׁוֹרִים בַּכֶּתֶר הַקָּדוֹשׁ (של השכינה) שֶׁשּׁוֹרֶה עַל שְׁאָר הַכְּתָרִים הַתַּחְתּוֹנִים, וְרוּחַ קְדוֹשָׁה שׁוֹרָה עֲלֵיהֶם. אֲבָל יִשְׂרָאֵל, קְדוֹשִׁים בְּנֵי קְדוֹשִׁים שֶׁל גְּזָעִים וְשָׁרָשִׁים, וְהִתְבַּשְּׂמוּ בְּהַר סִינַי, וְנִכְנְסוּ לָאֱמוּנָה הַשְּׁלֵמָה הַקְּדוֹשָׁה בְּשָׁעָה שֶׁנִּמּוֹלִים, הֵם שׁוֹרִים בַּכֹּל, שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>"],[9522011955,"<p>וְהָיָה כִּי יֶחֱטָא וְאָשֵׁם וְהֵשִׁיב אֶת הַגְּזֵלָה וְגוֹ'. רַבִּי יוֹסֵי אָמַר, (ישעיה נד) כי מי נח זאת לי אשר נשבעתי מעבר מי נח. הפסוק הזה קשה, כתוב (בראשית ז) ומי המבול היו על הארץ, וכתוב (שם ט) ולא יכרת כל בשר עוד ממי המבול. כתוב מי המבול, ולא מי נח, וכאן כָּתוּב כִּימֵי נֹחַ זֹּאת לִי. זֹּאת לִי?! הֵם לִי הָיָה צָרִיךְ לִהְיוֹת!</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, כְּשֶׁצַּדִּיקִים מִתְרַבִּים בָּעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ וּמִשְׁתַּבֵּחַ בָּהֶם. שֶׁשָּׁנִינוּ, כְּשֶׁשָּׁרוּי צַדִּיק בָּעוֹלָם וְנִמְצָא בוֹ, כִּבְיָכוֹל הוּא מַטִּיל שָׁלוֹם בָּעוֹלָם, וְכָל הָעוֹלָם מִתְבָּרֵךְ בִּגְלָלוֹ, וּמַטִּיל שָׁלוֹם בְּפָמַלְיָא שֶׁל מַעְלָה. מִנַּיִן לָנוּ? שֶׁכָּתוּב (ישעיה כז) אוֹ יַחֲזֵק בְּמָעֻזִּי יַעֲשֶׂה שָׁלוֹם לִי שָׁלוֹם יַעֲשֶׂה לִּי. שְׁנֵי שְׁלוֹמוֹת כָּאן לָמָּה? אֶלָּא יַעֲשֶׂה שָׁלוֹם לִי - שֶׁמַּשְׁרֶה זָכָר וּנְקֵבָה. שָׁלוֹם יַעֲשֶׂה לִּי - שֶׁהָאָבוֹת מִתְבָּרְכִים.</p>\n<p>מַה יֵּשׁ בֵּינֵיהֶם? אָמַר רַבִּי יוֹסֵי, כְּשֶׁהָאָבוֹת מִתְבָּרְכִים, שָׁלוֹם יַעֲשֶׂה לִּי, שֶׁמַּקְדִּים שָׁלוֹם בַּכֹּל. וּמִשּׁוּם כָּךְ שָׁלוֹם קוֹדֵם. יַעֲשֶׂה שָׁלוֹם לִי, מָה הַטַּעַם לֹא הִקְדִּים כָּאן שָׁלוֹם? אֶלָּא כְּדֵי שֶׁיָּעֳבַר הַנָּחָשׁ שֶׁשָּׁרוּי בַּנְּקֵבָה בָּרִאשׁוֹנָה, וְיָבֹא הַזָּכָר לִשְׁרוֹת בִּמְקוֹמוֹ, וּמִשּׁוּם כָּךְ הִקְדִּים יַעֲשֶׂה, וְאַחַר כָּךְ שָׁלוֹם.</p>\n<p>שָׁנִינוּ, בִּזְמַן שֶׁצַּדִּיק שָׁרוּי בָּעוֹלָם, הַדִּינִים לֹא מִתְעוֹרְרִים וְלֹא שׁוֹלְטִים בָּעוֹלָם, מִשּׁוּם שֶׁאוֹתוֹ אִישׁ צַדִּיק הוּא אוֹת בָּעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִכְבוֹדוֹ, וְהָעוֹלָם מִתְקַיֵּם בִּשְׁבִילוֹ.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, בִּזְמַן שֶׁבְּנֵי הָעוֹלָם נִמְצָאִים רְשָׁעִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אוֹתוֹ הַצַּדִּיק שֶׁנִּמְצָא בָעוֹלָם, (רוצה) הַקָּדוֹשׁ בָּרוּךְ הוּא מְדַבֵּר עִמּוֹ, כְּדֵי שֶׁיְּבַקֵּשׁ רַחֲמִים עַל הָעוֹלָם וְיִתְפַּיֵּס עִמָּם. מָה עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? מְדַבֵּר עִמּוֹ עַל אוֹתָם הָרְשָׁעִים שֶׁל הָעוֹלָם. אוֹמֵר לוֹ לְהֵיטִיב עִמּוֹ לְבַדּוֹ וּלְהַשְׁמִיד אֶת כֻּלָּם. מַהִי דַּרְכּוֹ שֶׁל אוֹתוֹ צַדִּיק? עוֹזֵב אֶת שֶׁלּוֹ וְלוֹקֵחַ אֶת שֶׁל כָּל הָעוֹלָם כְּדֵי שֶׁיִּתְפַּיֵּס הַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּם.</p>\n<p>מִנַּיִן לָנוּ? מִמֹּשֶׁה, שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, חָטְאוּ יִשְׂרָאֵל, (שמות לב) עָשׂוּ לָהֶם עֵגֶל מַסֵּכָה וַיִּשְׁתַּחֲווּ לוֹ וְגוֹ'. עוֹד אָמַר לוֹ, הֶרֶף מִמֶּנִּי וְאַשְׁמִידֵם וְגוֹ'. בְּאוֹתָהּ שָׁעָה אָמַר מֹשֶׁה, אִם בִּשְׁבִיל כְּבוֹדִי יֻשְׁמְדוּ יִשְׂרָאֵל מִן הָעוֹלָם - טוֹב לִי מָוֶת, וְלֹא יֹאמְרוּ שֶׁעָזַבְתִּי אֶת זֶה שֶׁל כָּל הָעוֹלָם בִּשְׁבִיל כְּבוֹדִי. מִיָּד - וַיְחַל מֹשֶׁה אֶת פְּנֵי ה' אֱלֹהָיו. וְהוֹשִׁיט עַצְמוֹ לְמִיתָה בְּכַמָּה מְקוֹמוֹת בִּשְׁבִיל יִשְׂרָאֵל, שֶׁכָּתוּב וְעַתָּה אִם תִּשָּׂא חַטָּאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךְ וְגוֹ'. וְשָׁנִינוּ, לֹא זָז מֹשֶׁה מִשָּׁם עַד שֶׁמָּחַל הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב, וַיִּנָּחֶם ה' עַל הָרָעָה אֲשֶׁר דִּבֶּר לַעֲשׂוֹת לְעַמּוֹ. וְכָתוּב, (במדבריד) וַיֹּאמֶר ה' סָלַחְתִּי כִּדְבָרֶךְ.</p>\n<p>וְאִלּוּ בְּנֹחַ כָּתוּב, וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְגוֹ'. אָמַר לוֹ נֹחַ, וְלִי מָה אַתָּה עוֹשֶׂה? אָמַר לוֹ, וַהֲקִמֹתִי אֶת בְּרִיתִי אִתָּךְ וְגוֹ' עֲשֵׂה לְךְ תֵּבַת עֲצֵי גֹפֶר. וְלֹא בִקֵּשׁ רַחֲמִים עַל הָעוֹלָם, וְיָרְדוּ הַמַּיִם וְהֶאֱבִידוּ אֶת בְּנֵי הָעוֹלָם. וּמִשּׁוּם כָּךְ כָּתוּב מֵי נֹחַ. מֵי נֹחַ וַדַּאי, שֶׁבּוֹ הֵם הָיוּ תְלוּיִים, שֶׁלֹּא בִקֵּשׁ רַחֲמִים עַל הָעוֹלָם.</p>\n<p>מִכָּאן אָמַר רַבִּי יוֹסֵי, מַה שֶּׁכָּתוּב (בראשית ט) וַיָּחֶל נֹחַ אִישׁ הָאֲדָמָה. וַיָּחֶל, כְּמוֹ שֶׁנֶּאֱמַר (במדבר ל) לֹא יָחֵל דְּבָרוֹ, שֶׁנַּעֲשָׂה חֹל. אִישׁ הָאֲדָמָה, שֶׁבִּגְלָלוֹ הֻשְׁמְדוּ בְּנֵי הָעוֹלָם, כִּי לֹא בִקֵּשׁ עֲלֵיהֶם רַחֲמִים. דָּבָר אַחֵר אִישׁ הָאֲדָמָה - שֶׁבִּשְׁבִילוֹ הִתְקַיְּמָה לְאַחַר שֶׁהֻשְׁמְדוּ הָרִאשׁוֹנִים, שֶׁכָּתוּב לֹא אֹסִף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם וְגוֹ'.</p>\n<p>שָׁנִינוּ, הֵם נִקְרְאוּ מֵי נֹחַ, שֶׁהוּא גָּרַם שֶׁנִּקְרְאוּ עַל שְׁמוֹ. אָמַר רַבִּי יוֹסֵי, זֹּאת לִי, מַה זֶּה אוֹמֵר? אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מֵי נֹחַ גָּרְמוּ לִי שֶׁאֲגַלֶּה זֹּאת בָּעוֹלָם, שֶׁכָּתוּב וַאֲנִי \"זֹּאת\" בְּרִיתִי אוֹתָם. \"זֹּאת\" אוֹת הַבְּרִית וְגוֹ'. אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן, כְּלוֹמַר אֵין מִי שֶׁמַּשְׁגִּיחַ אֶלָּא לִכְבוֹד שְׁמִי שֶׁרָמוּז בְּזֹּאת. וּמִי גָרַם לוֹ? מֵי נֹחַ.</p>\n<p>מִכָּאן סִימָן לְחָסִיד צַדִּיק שֶׁלֹּא מִתְגַּלָּה הַקֶּשֶׁת הַזּוֹ בְּיָמָיו, וְלֹא צָרִיךְ הָעוֹלָם בְּיָמָיו לָאוֹת הַזֹּאת. וּמִי הוּא? אוֹתוֹ שֶׁמְּבַקֵּשׁ רַחֲמִים עַל הָעוֹלָם וְרָאוּי לְהָגֵן עָלָיו, כְּמוֹ רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, שֶׁלֹּא צָרִיךְ הָעוֹלָם בְּיָמָיו אֶת הָאוֹת הַזֹּאת, שֶׁהֲרֵי הוּא הָיָה אוֹת סִימָן בָּעוֹלָם.</p>\n<p>שֶׁלֹּא הָיְתָה גְזֵרָה שֶׁנִּגְזְרָה עַל הָעוֹלָם לְמַעְלָה שֶׁלֹּא מְבַטֵּל אוֹתָהּ, וְהַיְנוּ מַה שֶׁכָּתוּב (שמואל ב כג) מוֹשֵׁל בָּאָדָם. הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁל בָּאָדָם. וּמִי מוֹשֵׁל בַּקָּדוֹשׁ-בָּרוּךְ-הוּא כִּבְיָכוֹל? צַדִּיק. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר, וְהוּא מְבַטֵּל.</p>"],[9522011956,"<p>כְּמוֹ רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי שֶׁיּוֹם אֶחָד הָיָה יוֹשֵׁב עַל הַדֶּלֶת שֶׁל שַׁעַר (מערת) לוֹד, הֵרִים עֵינָיו וְרָאָה שֶׁהַשֶּׁמֶשׁ מְאִירָה, וְהִסְתִּירָה אוֹרָהּ שָׁלֹשׁ פְּעָמִים. בֵּינְתַיִם נֶחְשַׁךְ הָאוֹר, וְנִרְאָה בַשֶּׁמֶשׁ שָׁחֹר וְיָרֹק. אָמַר לוֹ לְרַבִּי אֶלְעָזָר בְּנוֹ, בֹּא אַחֲרַי בְּנִי, וְנִרְאֶה שֶׁהֲרֵי וַדַּאי נִגְזְרָה גְזֵרָה לְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהוֹדִיעַ לִי, שֶׁוַּדַּאי שְׁלֹשִׁים יוֹם תָּלוּי אוֹתוֹ הַדָּבָר שֶׁנִּגְזַר לְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא אֵינוֹ עוֹשֶׂה עַד שֶׁמּוֹדִיעַ לַצַּדִּיקִים. זֶהוּ שֶׁכָּתוּב (עמוס ג) כִּי לֹא יַעֲשֶׂה ה' אֱלֹהִים דָּבָר כִּי אִם גָּלָה סוֹדוֹ אֶל עֲבָדָיו הַנְּבִיאִים.</p>\n<p>עַד שֶׁהָיוּ הוֹלְכִים, נִכְנְסוּ לְאוֹתוֹ כֶּרֶם. רָאוּ נָחָשׁ אֶחָד שֶׁהָיָה בָּא, וּפִיו פָּתוּחַ, (והיהלוחשבלשונו) וְלוֹהֵט בָּאָרֶץ בֶּעָפָר. נִעֵר בְּגָדָיו רַבִּי שִׁמְעוֹן וְהִכָּה יָדוֹ בְּרֹאשׁ הַנָּחָשׁ, שָׁכַךְ הַנָּחָשׁ, הִנְמִיךְ אֶת פִּיו וְרָאָה לְשׁוֹנוֹ רוֹחֶשֶׁת. אָמַר לוֹ: נָחָשׁ נָחָשׁ, לֵךְ וֶאֱמֹר לְאוֹתוֹ הַנָּחָשׁ הָעֶלְיוֹן שֶׁהֲרֵי רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי מָצוּי בָּעוֹלָם. הִכְנִיס אֶת רֹאשׁוֹ לְנֶקֶב שֶׁל עָפָר אֶחָד, וְאָמַר: גּוֹזֵר אֲנִי, כְּשֵׁם שֶׁהַתַּחְתּוֹן חָזַר לְנֶקֶב הֶעָפָר, כָּךְ הָעֶלְיוֹן יַחֲזֹר לְנֶקֶב תְּהוֹם רַבָּה.</p>\n<p>רָחַשׁ רַבִּי שִׁמְעוֹן בִּתְפִלָּה. עַד שֶׁהָיוּ מִתְפַּלְלִים, שָׁמְעוּ קוֹל אֶחָד: מְמֻנֵּי הַמָּוֶת, הִכָּנְסוּ לִמְקוֹמְכֶם. הַמַּכּוֹת שֶׁל הַמַּשְׁחִיתִים לֹא שׁוֹרוֹת בָּעוֹלָם, שֶׁהֲרֵי רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי בִּטֵּל אוֹתָן. אַשְׁרֶיךְ רַבִּי שִׁמְעוֹן, שֶׁרִבּוֹנְךְ רוֹצֶה בִכְבוֹדְךְ עַל כָּל בְּנֵי הָעוֹלָם. בְּמֹשֶׁה כָּתוּב (שמות לב) וַיְחַל מֹשֶׁה וְגוֹ', שֶׁמַּשְׁמָע שֶׁאָחַז אוֹתוֹ פַּרְגּוֹד, וְאַתָּה רַבִּי שִׁמְעוֹן גּוֹזֵר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַיֵּם. הוּא גּוֹזֵר, וְאַתָּה מְבַטֵּל.</p>\n<p>בֵּין כָּךְ רָאָה שֶׁהֵאִיר הַשֶּׁמֶשׁ וְעָבַר אוֹתוֹ הַשְּׁחוֹר. אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי שֶׁהָעוֹלָם הִתְבַּשֵּׂם. נִכְנַס לְבֵיתוֹ וְדָרַשׁ, (תהלים יא) כִּי צַדִּיק ה' צְדָקוֹת אָהֵב יָשָׁר יֶחֱזוּ פָנֵימוֹ. מָה הַטַּעַם כִּי צַדִּיק ה' צְדָקוֹת אָהֵב? מִשּׁוּם שֶׁיָּשָׁר יֶחֱזוּ פָנֵימוֹ. מַה זֶּה פָנֵימוֹ? הַפָּנִים הָעֶלְיוֹנִים שֶׁל כָּל הָעוֹלָם, שֶׁצְּרִיכִים לְבַקֵּשׁ רַחֲמִים מִמֶּנּוּ עַל כָּל מַה שֶּׁצְּרִיכִים.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר בְּנוֹ, אִם כָּךְ, הָיָה צָרִיךְ לִהְיוֹת יָשָׁר יֶחֱזֶה פָנֵימוֹ, אוֹ יְשָׁרִים יֶחֱזוּ. מַה זֶּה יָשָׁר יֶחֱזוּ? אָמַר לוֹ, סוֹד עֶלְיוֹן שֶׁאוֹתָם יְמֵי קֶדֶם שֶׁל הָעַתִּיק הַקָּדוֹשׁ, נִסְתַּר כָּל הַנִּסְתָּרִים. וִימֵי עוֹלָם שֶׁל ז\"א, שֶׁהֵם נִקְרָאִים פָּנֵימוֹ, (שהם) רוֹאִים בְּדֶרֶךְ יָשָׁר מַה שֶּׁצָּרִיךְ לִרְאוֹת.</p>\n<p>שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ בָּעוֹלָם וְרוֹאֶה שֶׁכְּשֵׁרִים מַעֲשֵׂיהֶם שֶׁל בְּנֵי הָאָדָם לְמַטָּה, מִתְגַּלֶּה הָעַתִּיק הַקָּדוֹשׁ בִּזְעֵיר אַנְפִּין, וּמִסְתַּכְּלִים כָּל אוֹתָם הַפָּנִים בְּפָנִים נִסְתָּרִים, וְכֻלָּם מִתְבָּרְכִים. מָה הַטַּעַם שֶׁמִּתְבָּרְכִים? מִשּׁוּם שֶׁמִּסְתַּכְּלִים אֵלּוּ בְאֵלּוּ בְּדֶרֶךְ יָשָׁר, שֶׁלֹּא סוֹטִים יָמִינָה וּשְׂמֹאלָה. זֶהוּ שֶׁכָּתוּב יָשָׁר יֶחֱזוּ פָנֵימוֹ. וְכֻלָּם מִתְבָּרְכִים וּמַשְׁקִים זֶה אֶת זֶה, עַד שֶׁמִּתְבָּרְכִים כָּל הָעוֹלָמוֹת. וְכָל הָעוֹלָמוֹת נִמְצָאִים כְּאֶחָד, וְאָז נִקְרָא ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>וּכְשֶׁחֲטָאֵי הָעוֹלָם מִתְרַבִּים, נִסְתָּר הָעַתִּיק הַקָּדוֹשׁ, וְאֵין מַשְׁגִּיחִים פָּנִים בְּפָנִים, וְאָז מִתְעוֹרְרִים הַדִּינִים בָּעוֹלָם, וְהַכִּסְאוֹת עוֹלִים, וְעַתִּיק הַיָּמִים סָתוּם וְלֹא מִתְגַּלֶּה. זֶהוּ שֶׁכָּתוּב (דניאל ז) הָיִיתִי רוֹאֶה עַד שֶׁהַכִּסְאוֹת הוּרְמוּ וְעַתִּיק הַיָּמִים יוֹשֵׁב. עַד שֶׁהַכִּסְאוֹת הוּרְמוּ, שֶׁאוֹתָם הַכְּתָרִים הָעֶלְיוֹנִים, שֶׁמַּשְׁקִים אֶת כָּל הָאֲחֵרִים לְהַעֲמִידָם בְּקִיּוּמָם. וּמִי הֵם? הָאָבוֹת. וְעַתִּיק הַיָּמִים יוֹשֵׁב וְלֹא מִתְגַּלֶּה. וְאָז מְהַפְּכִים הָרְשָׁעִים שֶׁל הָעוֹלָם רַחֲמִים לְדִין.</p>"],[9522011957,"<p>שָׁנִינוּ, מִצַּד הָאֵם יוֹצְאִים שׁוֹמְרֵי הַחֻקִּים, הַקְּלִפּוֹת שֶׁלָּהֶם, וּ וְאוֹחֲזִים בַּמַּקֵּל שֶׁל הַגְּבוּרָה, שׁוֹלְטִים עַל הָרַחֲמִים, כְּמוֹ שֶׁנֶּאֱמַר (במדבר טו) הַנּוֹעָדִים עַל ה', עַל ה' מַמָּשׁ. וְאָז נִמְצָאִים הָעוֹלָמוֹת חֲסֵרִים, (קשורים) שֶׁאֵינָם שְׁלֵמִים, וּמִתְעוֹרֶרֶת בְּכֻלָּם קְטָטָה.</p>\n<p>וּכְשֶׁבְּנֵי אָדָם מַכְשִׁירִים מַעֲשֵׂיהֶם לְמַטָּה, אֲזַי מִתְבַּשְּׂמִים הַדִּינִים וְעוֹבְרִים, וּמִתְעוֹרְרִים רַחֲמִים וְשׁוֹלְטִים עַל אוֹתוֹ הָרָע שֶׁמִּתְעוֹרֵר מִן הַדִּין הַקָּשֶׁה. וּכְשֶׁמִּתְעוֹרְרִים רַחֲמִים, נִמְצָאִים שִׂמְחָה וְנִחוּמִים, מִשּׁוּם שֶׁשּׁוֹלְטִים עַל אוֹתוֹ הָרָע. זֶהוּ שֶׁכָּתוּב וַיִּנָּחֶם ה' עַל הָרָעָה. וַיִּנָּחֶם, מִשּׁוּם (ששולט על הרעה) שֶׁנִּכְנָע הַדִּין הַקָּשֶׁה, וְשׁוֹלְטִים הָרַחֲמִים.</p>\n<p>שָׁנִינוּ, בְּשָׁעָה שֶׁהַדִּינִים מִתְבַּשְּׂמִים וְשׁוֹלְטִים הָרַחֲמִים, כָּל כֶּתֶר וְכֶתֶר שָׁב לְקִיּוּמוֹ, וְכֻלָּם מִתְבָּרְכִים כְּאֶחָד. וּכְשֶׁשָּׁבִים כָּל אֶחָד וְאֶחָד לִמְקוֹמוֹ וְכֻלָּם מִתְבָּרְכִים כְּאֶחָד, וְהָאֵם מִתְבַּשֶּׂמֶת בְּמַפְתְּחוֹת הַחֲקוּקִים וְשָׁבִים לְצִדָּהּ, אָז נִקְרֵאת תְּשׁוּבָה שְׁלֵמָה, וְהָעוֹלָם מִתְכַּפֵּר, שֶׁהֲרֵי הָאֵם יוֹשֶׁבֶת בְּשִׂמְחָה שְׁלֵמָה, שֶׁכָּתוּב אֵם הַבָּנִים שְׂמֵחָה, וְאָז נִקְרָא יוֹם הַכִּפּוּרִים, שֶׁכָּתוּב בּוֹ לְטַהֵר אֶתְכֶם מִכֹּל חַטֹּאתֵיכֶם. וְנִפְתָּחִים חֲמִשִּׁים שְׁעָרִים שֶׁל צְדָדִים חֲקוּקִים.</p>\n<p>שָׁנִינוּ, כָּתוּב וְהָיָה כִּי יֶחֱטָא וְאָשֵׁם, מַה זֶּה כִּי יֶחֱטָא, וּלְבַסּוֹף וְאָשֵׁם? אֶלָּא כָּךְ שָׁנִינוּ, כִּי יֶחֱטָא מֵאוֹתָם חֲטָאִים שֶׁנִּקְרְאוּ חֵטְא, שֶׁכָּתוּב מִכֹּל חַטֹּאת הָאָדָם. וְאָשֵׁם, כְּמוֹ שֶׁנֶּאֱמַר הָאָשָׁם הַמּוּשָׁב לַה'. וְאָשֵׁם, וִיתַקֵּן. כְּלוֹמַר, אִם יְתַקֵּן אֶת מַעֲשָׂיו, וְהֵשִׁיב אֶת הַגְּזֵלָה אֲשֶׁר גָּזָל. אָמַר רַבִּי יוֹסֵי, מִמַּשְׁמָע שֶׁכָּתוּב וְהֵשִׁיב, לֹא כָתוּב וְיָשִׁיב אֶלָּא וְהֵשִׁיב, וְהֵשִׁיב דַּוְקָא.</p>"],[9522011958,"<p>שָׁנִינוּ, בְּאַרְבַּע תְּקוּפוֹת הַשָּׁנָה הַקּוֹל נִפְסָק, וּמִתְעוֹרְרִים הַדִּינִים, וְהַתְּשׁוּבָה תְלוּיָה עַד שֶׁמִּתְתַּקֵּן. וּכְשֶׁהַדִּינִים מִתְעוֹרְרִים, יוֹצֵא קוֹל, וְאַרְבַּע זָוִיּוֹת (פעמים) הָעוֹלָם עוֹלִים וְיוֹרְדִים. הַכָּרוֹז קוֹרֵא, וְאֵין מִי שֶׁיַּשְׁגִּיחַ וְיִתְעוֹרֵר. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְזֻמָּן, אִם יָשׁוּבוּ - יָשׁוּב, וְאִם לֹא - (הכל ס\"א הקול) נִפְסָק, וְהַדִּינִים נַעֲשִׂים, וְאָז נִקְרָא וַיִּתְעַצֵּב, וַיִּתְעַצֵּב בַּבָּתִּים הַחִיצוֹנִים.</p>\n<p>אָמַר רַבִּי יְהוּדָה, שָׁנִינוּ, מִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ אֵין יוֹם שֶׁלֹּא נִמְצָא בּוֹ כַּעַס רַע, מָה הַטַּעַם? מִשּׁוּם שֶׁשָּׁנִינוּ, אָמַר רַבִּי יוּדָאִי אָמַר רַבִּי יֵיסָא, נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יִכָּנֵס בִּירוּשָׁלַיִם שֶׁל מַעְלָה עַד שֶׁיִּכָּנְסוּ יִשְׂרָאֵל לִירוּשָׁלַיִם שֶׁל מַטָּה. וּמִשּׁוּם כָּךְ נִמְצֵאת רִתְחָה בָּעוֹלָם.</p>"],[9522011959,"<p>אָמַר רַבִּי יוֹסֵי, כָּתוּב עֶרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה. וְכָתוּב אִמְּךְ הִיא לֹא תְגַלֶּה עֶרְוָתָהּ. וְשָׁנִינוּ, אִמְּךְ הִיא וַדַּאי. הֲרֵי אִם גִּלָּה עֶרְוָתָהּ, לָמָּה צָרִיךְ לְהָשִׁיב אוֹתָהּ? וַדַּאי לְתַקֵּן אֶת מַה שֶּׁגִּלָּה.</p>\n<p>שֶׁשָּׁנִינוּ, כְּשֶׁמִּתְגַּבֵּר יֵצֶר הָרָע בָּאָדָם, אֵינוֹ מִתְגַּבֵּר אֶלָּא בְּאוֹתָן עֲרָיוֹת, וְכָל הַחֲטָאִים אֲחוּזִים בְּאוֹתָהּ עֶרְוָה. וְכָתוּב לֹא תְגַלֵּה. כְּשֶׁמִּתְתַּקֵּן, מְתַקֵּן כְּנֶגֶד אוֹתוֹ שֶׁגִּלָּה, וְזוֹ נִקְרֵאת תְּשׁוּבָה.</p>\n<p>אָמַר רַבִּי יִצְחָק, כָּל חֲטָאֵי הָעוֹלָם אֲחוּזִים (זה) בָּזֶה, עַד שֶׁהָאֵם מִתְגַּלָּה בִגְלָלָם. וּכְשֶׁהִיא מִתְגַּלָּה, כָּל אוֹתָם הַבָּנִים מִתְגַּלִּים (בשבילה). וְכָתוּב לֹא תִקַּח הָאֵם עַל הַבָּנִים. וּכְשֶׁמִּתְתַּקֵּן הָעוֹלָם לְמַטָּה, הַכֹּל מִתְתַּקֵּן, עַד שֶׁעוֹלֶה הַתִּקּוּן לָאֵם הַקְּדוֹשָׁה וּמִתְתַּקֶּנֶת, וּמִתְכַסֵּית מִמַּה שֶּׁהִתְגַּלְּתָה. וּמִשּׁוּם כָּךְ כָּתוּב, אַשְׁרֵי נְשׂוּי פֶּשַׁע כְּסוּי חֲטָאָה, וְאָז נִקְרֵאת תְּשׁוּבָה, תְּשׁוּבָה וַדַּאי. וְאָז נִקְרָא יוֹם הַכִּפּוּרִים, כְּמוֹ שֶׁכָּתוּב מִכֹּל חַטאתֵיכֶם לִפְנֵי ה' תִּטְהָרוּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מָתַי נִקְרֵאת תְּשׁוּבָה? כְּשֶׁהָאֵם מִתְכַּסָּה וְעוֹמֶדֶת בְּשִׂמְחָה עַל הַבָּנִים, שֶׁכָּתוּב (תהלים קיג) אֵם הַבָּנִים שְׂמֵחָה. וְשָׁבָה לְקִיּוּם. וּמִי שֶׁהָיָה סָגוּר, שָׁב לִמְקוֹמוֹ. וְכֻלָּם שָׁבִים אֶחָד לְאֶחָד, וּמִתְבָּרְכִים כָּל אֶחָד וְאֶחָד, וְאָז נִקְרֵאת תְּשׁוּבָה (שלמה), תְּשׁוּבָה סְתָם, לְהַכְלִיל הַכֹּל.</p>\n<p>אָמַר רַבִּי יִצְחָק, כְּשֶׁמֻּכְשָׁר הָעוֹלָם, כֻּלּוֹ מֻכְשָׁר כְּאֶחָד. כָּתוּב כִּי גָדוֹל מֵעַל שָׁמַיִם חַסְדֶּךְ. מֵעַל שָׁמַיִם, שֶׁעוֹלֶה לְמַעְלָה מֵהַמָּקוֹם שֶׁנִּקְרָא שָׁמַיִם. וּמִי הוּא. זוֹ הָאֵם. וְהַיְנוּ שֶׁנִּקְרֵאת תְּשׁוּבָה.</p>\n<p>רַבִּי יְהוּדָה אוֹמֵר, מְדֻיָּק שֶׁכָּתוּב מֵעַל שָׁמַיִם. אִלְמָלֵא כָתוּב עַל שָׁמַיִם, מַשְׁמָע אוֹתוֹ מָקוֹם שֶׁעוֹמֵד עַל שָׁמַיִם וְלֹא יוֹתֵר. כֵּיוָן שֶׁאָמַר מֵעַל שָׁמַיִם, מַשְׁמָע אוֹתוֹ מָקוֹם שֶׁעוֹמֵד עַל הַשָּׁמַיִם לְמַעְלָה לְמַעְלָה. (ומה היא, ' אמא, וזהו שנקרא תשובה).</p>\n<p>שֶׁשָּׁנִינוּ, בְּאוֹתוֹ זְמַן שֶׁמֻּכְשָׁרִים הַמַּעֲשִׂים לְמַטָּה וְהָאֵם בְּשִׂמְחָה, מִתְגַּלֶּה הָעַתִּיק הַקָּדוֹשׁ, וְשָׁב הָאוֹר לִזְעֵיר אַנְפִּין, וְאָז הַכֹּל בְּשִׂמְחָה, הַכֹּל בִּשְׁלֵמוּת, הַכֹּל נִמְצָאִים בִּבְרָכוֹת, וְהָרַחֲמִים מְזֻמָּנִים, וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה. זֶהוּ שֶׁכָּתוּב (מיכה ז) יָשׁוּב יְרַחֲמֵנוּ יִכְבֹּשׁ עֲונֹתֵינוּ. מִי יָשׁוּב? יָשׁוּב הָעַתִּיק הַקָּדוֹשׁ לְהִתְגַּלּוֹת בִּזְעֵיר, יָשׁוּב לְהִתְגַּלּוֹת, שֶׁהָיָה נִסְתָּר בָּרִאשׁוֹנָה, וְהַכֹּל נִקְרָא תְשׁוּבָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, הַכֹּל בִּכְלָל, הַכֹּל סְתָם. וְכָתוּב (דברים יג) לְמַעַן יָשׁוּב ה' מֵחֲרוֹן אַפּוֹ וְנָתַן לְךְ רַחֲמִים. אָמַר רַבִּי יִצְחָק, הַכֹּל הוּא וַדַּאי, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים לִפְנֵי רַבִּי שִׁמְעוֹן.</p>"],[9522011960,"<p>וְהֵשִׁיב אֶת הַגְּזֵלָה. שָׁם שָׁאֲלוּ הַחֲבֵרִים, מִפְּנֵי מָה בִּגְזֵלָה כָּתוּב וְהֵשִׁיב אֶת הַגְּזֵלָה, וְלֹא יוֹתֵר? אֶלָּא הֲרֵי בֵּאַרְנוּ, שֶׁזֶּה שָׂם יִרְאָה הָעֶלְיוֹנָה כְּמוֹ הַתַּחְתּוֹנָה, וְזֶה שֶׁגּוֹנֵב שָׂם אֶת הַיִּרְאָה הַתַּחְתּוֹנָה כְּנֶגְדּוֹ, וְלֹא הַיִּרְאָה הָעֶלְיוֹנָה.</p>\n<p>מַה כָּתוּב לְמַעְלָה? נֶפֶשׁ כִּי תֶחֱטָא. כְּמוֹ שֶׁאָמַרְנוּ, שֶׁהַתּוֹרָה וְהַקָּדוֹשׁ בָּרוּךְ הוּא תְּמֵהִים עָלָיו וְאוֹמְרִים, נֶפֶשׁ כִּי תֶחֱטָא וְגוֹ'? וְכָתוּב נֶפֶשׁ כִּי תִמְעֹל מַעַל וְגוֹ', אוֹ - נֶפֶשׁ כִּי תִשָּׁבַע וְגוֹ'. אָמַר רַבִּי יִצְחָק, כָּתוּב נֶפֶשׁ, וְלֹא רוּחַ, וְלֹא נְשָׁמָה, וְכָאן גּוּף (רוח) וָנֶפֶשׁ, שֶׁנֶּאֱמַר וְהָיָה כִּי יֶחֱטָא וְאָשֵׁם וְהֵשִׁיב אֶת הַגְּזֵלָה. מִי שֶׁרוֹצֶה לְתַקֵּן אֶת מַעֲשָׂיו, כְּמוֹ שֶׁאָמַרְנוּ וְהֵשִׁיב. מִי זֶה וְהֵשִׁיב? אֶלָּא כְּמִי שֶׁיְּתַקֵּן מַעֲשִׂים, כְּדֵי שֶׁיָּשִׁיב מַעַיְנוֹת הַמַּיִם לִמְקוֹמָם לְהַשְׁקוֹת אֶת הַנְּטִיעוֹת, שֶׁהֲרֵי הוּא גָּרַם בַּחֲטָאָיו לִמְנֹעַ מֵהֶם. וְעַל זֶה - וְהֵשִׁיב אֶת הַגְּזֵלָה וְגוֹ', כְּמוֹ שֶׁנִּתְבָּאֵר.</p>"],[9522011961,"<p>רַבִּי אַבָּא הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. נִכְנָס רַבִּי אֶלְעָזָר בְּנוֹ. אָמַר רַבִּי שִׁמְעוֹן, כָתוּב (תהלים צב) צַדִּיק כַּתָּמָר יִפְרָח וְגוֹ'. צַדִּיק כַּתָּמָר, מַה זֶּה כַּתָּמָר? שֶׁהֲרֵי מִכָּל הָאִילָנוֹת שֶׁל הָעוֹלָם, אֵין מִי שֶׁמִּתְעַכֵּב לִפְרֹחַ כְּמוֹ תָמָר שֶׁעוֹלֶה לְשִׁבְעִים שָׁנִים. מָה הַטַּעַם כַּתָּמָר? אֶלָּא אַף עַל גַּב שֶׁהַכָּתוּב מֵעִיד, הַחֲבֵרִים כֻּלָּם אֵין רוֹצִים לְגַלּוֹת.</p>\n<p>אֲבָל צַדִּיק כַּתָּמָר יִפְרָח, זֶה נֶאֱמַר עַל גָּלוּת בָּבֶל, שֶׁהֲרֵי לֹא שָׁבָה שְׁכִינָה לִמְקוֹמָהּ אֶלָּא לְסוֹף שִׁבְעִים שָׁנָה. זֶהוּ שֶׁכָּתוּב (ירמיה כט) כִּי לְפִי מְלֹאת לְבָבֶל שִׁבְעִים שָׁנָה אֶפְקֹד אֶתְכֶם. וְזֶהוּ צַדִּיק כַּתָּמָר יִפְרָח, שֶׁעוֹלֶה זָכָר וּנְקֵבָה לְשִׁבְעִים שָׁנָה. צַדִּיק - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, זֶהוּ שֶׁכָּתוּב (תהלים יא) כִּי צַדִּיק ה' צְדָקות אָהֵב. וְכָתוּב (שמות ה) ה' הַצַּדִּיק. וְכָתוּב (ישעיה ג) אִמְרוּ צַדִּיק כִּי טוֹב.</p>\n<p>כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה. מַה זֶּה אֶרֶז? זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בָּחוּר כָּאֲרָזִים. (שיושב על כסא של יעקב השלם) בַּלְּבָנוֹן יִשְׂגֶּה, בַּלְּבָנוֹן וַדַּאי, וְזֶהוּ הָעֵדֶן שֶׁלְּמַעְלָה, שֶׁעָלָיו כָּתוּב (שם סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ. וְהָאֶרֶז הַזֶּה בְּאוֹתוֹ מָקוֹם עֶלְיוֹן יִשְׂגֶּה.</p>\n<p>וְזְהִ בַּגָּלוּת הָאַחֲרוֹנָה הוּא כְּמוֹ הָאֶרֶז הַזֶּה שֶׁמִּתְעַכֵּב לַעֲלוֹת. וּמִשָּׁעָה שֶׁעוֹלֶה עַד שֶׁעוֹמֵד בְּקִיּוּמוֹ הוּא יוֹם, וּתְחִלַּת הַיּוֹם הָאַחֵר עַד שֶׁעוֹשֶׂה צֵל בְּאוֹר הַיּוֹם. וְהָאֶרֶז לֹא עוֹלֶה אֶלָּא בָּעִדּוּן שֶׁל הַמַּיִם, כְּמוֹ שֶׁנֶּאֱמַר (במדבר כד) כָּאֲרָזִים עֲלֵי מָיִם. כָּךְ אֶרֶז בַּלְּבָנוֹן יִשְׂגֶּה. שֶׁמִּשָּׁם יוֹצֵא הַמַּעְיָן וְהַנָּהָר שֶׁל הַמַּיִם לְהַשְׁקוֹת. וְאֶרֶז זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שיר ה) בָּחוּר כָּאֲ רָזִים.</p>\n<p>שְׁתוּלִים בְּבֵית ה' - לִזְמַנּוֹ שֶׁל מֶלֶךְ הַמָּשִׁיחַ. בְּחַצְרוֹת אֱלֹהֵינוּ יַפְרִיחוּ - בִּתְחִיַּת הַמֵּתִים. עוֹד יְנוּבוּן בְּשֵׂיבָה - בְּאוֹתוֹ יוֹם שֶׁהָעוֹלָם יִמָּצֵא חָרֵב. דְּשֵׁנִים וְרַעֲנַנִּים יִהְיוּ - לְאַחַר שֶׁכָּתוּב (ישעיה סו) הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה. וְאָז, (תהלים קד) יִשְׂמַח ה' בְּמַעֲשָׂיו כָּתוּב. וְכָל כָּךְ לָמָּה? (תהלים צב) לְהַגִּיד כִּי יָשָׁר ה' צוּרִי וְלֹא עַוְלָתָה בּוֹ.</p>"],[9522011962,"<p>עוֹד פָּתַח וְאָמַר, (משלי טז) אִישׁ תַּהְפֻּכוֹת יְשַׁלַּח מָדוֹן וְנִרְגָּן מַפְרִיד אַלּוּף. אִישׁ תַּהְפֻּכוֹת יְשַׁלַּח מָדוֹן, כְּמוֹ שֶׁאָמַרְנוּ, הָרְשָׁעִים עוֹשִׂים פְּגָם לְמַעְלָה. וְנִרְגָּן מַפְרִיד אַלּוּף, מַפְרִיד אַלּוּפוֹ שֶׁל עוֹלָם, וְזֶה הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>דָּבָר אַחֵר אִישׁ תַּהְפֻּכוֹת יְשַׁלַּח מָדוֹן - מַה זֶּה יְשַׁלַּח? יְשַׁלַּח אֶת אוֹתָן נְטִיעוֹת. מָדוֹן - שֶׁיּוֹנְקִים מִן הַצַּד שֶׁל הַדִּין. וְנִרְגָּן מַפְרִיד אַלּוּף, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁהָרְשָׁעִים עוֹשִׂים פְּגָם לְמַעְלָה. מַפְרִיד - שֶׁהַיִּחוּד לֹא נִמְצָא, מַפְרִיד אֶת הַגְּבִירָה מֵהַמֶּלֶךְ, וְאֶת הַמֶּלֶךְ מֵהַגְּבִירָה. וּמִשּׁוּם כָּךְ לֹא נִקְרָא אֶחָד, שֶׁאֶחָד אֵינוֹ נִקְרָא אֶלָּא כְּשֶׁהֵם בְּזִוּוּג אֶחָד. אוֹי לְאוֹתָם הָרְשָׁעִים שֶׁעוֹשִׂים פֵּרוּד לְמַעְלָה. אַשְׁרֵי הַצַּדִּיקִים שֶׁמַּעֲמִידִים אֶת הַקִּיּוּם שֶׁלְּמַעְלָה, וְאַשְׁרֵי בַּעֲלֵי הַתְּשׁוּבָה שֶׁמְּשִׁיבִים הַכֹּל לִמְקוֹמָם.</p>\n<p>וְעַל זֶה שָׁנִינוּ, הַמָּקוֹם שֶׁבַּעֲלֵי תְשׁוּבָה יוֹשְׁבִים, צַדִּיקִים גְּמוּרִים לֹא יוֹשְׁבִים בּוֹ. מָה הַטַּעַם? אֶלָּא הָהֵם הִתְתַּקְּנוּ בְּמָקוֹם עֶלְיוֹן בַּמָּקוֹם שֶׁהַשְׁקָאַת הַגָּן נִמְצֵאת מִשָּׁם. וְזוֹהִי תְשׁוּבָה, וְעַל זֶה נִקְרָאִים בַּעֲלֵי תְשׁוּבָה. וְאֵלּוּ מִתְתַּקְּנִים בְּמָקוֹם אַחֵר שֶׁנִּקְרָא צַדִּיק.</p>\n<p>וְעַל זֶה אֵלֶּה יוֹשְׁבִים בְּמָקוֹם עֶלְיוֹן, וְאֵלֶּה יוֹשְׁבִים בְּמָקוֹם קָטָן. מָה הַטַּעַם? אֵלּוּ מְשִׁיבִים מַיִם לִמְקוֹמָם מֵהַמָּקוֹם הָעֶלְיוֹן שֶׁל הַנָּהָר הֶעָמֹק, עַד אוֹתוֹ מָקוֹם שֶׁנִּקְרָא צַדִּיק. וְצַדִּיקִים גְּמוּרִים מַשְׁפִּיעִים מֵאוֹתוֹ מָקוֹם שֶׁהֵם יוֹשְׁבִים לָעוֹלָם הַזֶּה. וְעַל כֵּן אֵלּוּ עֶלְיוֹנִים וְאֵלּוּ תַחְתּוֹנִים. אַשְׁרֵי חֶלְקָם שֶׁל בַּעֲלֵי הַתְּשׁוּבָה, וְאַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁבִּגְלָלָם הָעוֹמֵד עוֹמֵד.</p>\n<p>זֶהוּ שֶׁכָּתוּב, וְהָיָה כִּי יֶחֱטָא וְאָשֵׁם וְגוֹ'. מַה כָּתוּב לְמַעְלָה? אוֹ מָצָא אֲבֵדָה וְכִחֶשׁ בָּהּ וְגוֹ', שֶׁהֲרֵי בִּשְׁבִיל זֶה מִסְתַּלֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהַכֹּל. כִּבְיָכוֹל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נִמְצָא בִמְקוֹמוֹ, שֶׁהֲרֵי כְּנֶסֶת יִשְׂרָאֵל נִפְרְדָה מִמְּקוֹמָהּ. זֶהוּ שֶׁכָּתוּב אָבְדָה הָאֱמוּנָה. מַה זּוֹ הָאֱמוּנָה? זוֹ כְּנֶסֶת יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר וֶאֱמוּנָתְךְ בַּלֵּילוֹת. אָבְדָה הָאֱמוּנָה, כְּמוֹ שֶׁנֶּאֱמַר עַל מָה אָבְדָה הָאָרֶץ, וְהַכֹּל אֶחָד. וַהֲרֵי בֵּאַרְנוּ אָבְדָה, וְלֹא נֶאֱבֶדֶת, וְלֹא אֲבוּדָה. כְּמוֹ כֵן הַצַּדִּיק אָבָד. אָבוּד אוֹ נֶאֱבָד לֹא כָתוּב, אֶלָּא אָבָד. זֶהוּ שֶׁכָּתוּב אָבְדָה הָאֱמוּנָה, בִּשְׁבִיל כָּךְ - וְהֵשִׁיב אֶת הַגְּזֵלָה אוֹ אֶת הָאֲבֵדָה וְגוֹ'.</p>"],[9522011963,"<p>אָמַר הָרוֹעֶה הַנֶּאֱמָן, מְקוֹמוֹת יֵשׁ בַּגֵּיהִנֹּם רְשׁוּמִים לִמְחַלְּלֵי שַׁבָּתוֹת בְּפַרְהֶסְיָא, וְלֹא חוֹזְרִים בִּתְשׁוּבָה מֵאוֹתוֹ חִלּוּל, וּמְמֻנִּים עֲלֵיהֶם. וְאַף כָּךְ יֵשׁ מְקוֹמוֹת בַּגֵּיהִנֹּם לְאוֹתָם שֶׁמְּגַלִּים עֲרָיוֹת, וּלְאוֹתָם שֶׁמְּגַלִּים פָּנִים בַּתּוֹרָה שֶׁלֹּא כַּהֲלָכָה, וּלְאוֹתָם שֶׁשּׁוֹפְכִים דָּם נָקִי, וּלְאוֹתָם שֶׁנִּשְׁבָּעִים לַשֶּׁקֶר, וּלְאוֹתָם שֶׁשּׁוֹכְבִים עִם נִדָּה אוֹ בַּת אֵל נֵכָר אוֹ זוֹנָה אוֹ שִׁפְחָה. וְאַף כָּךְ לְמִי שֶׁעוֹבֵר עַל שס\"ה לֹא תַעֲשֶׂה. לְכָל חֵטְא יֵשׁ מָקוֹם בַּגֵּיהִנֹּם, וּמְמֻנֶּה עָלָיו.</p>\n<p>וְשָׂטָן יֵצֶר הָרָע שֶׁלּוֹ מְמֻנֶּה עַל כָּל הַחֲטָאִים וְהַמְּקוֹמוֹת וְהַמְמֻנִּים שֶׁלּוֹ. וְאִם חוֹזֵר בִּתְשׁוּבָה, מַה כָּתוּב? מָחִיתִי כָעָב פְּשָׁעֶיךְ, נִמְחוּ הָרִשּׁוּמִים שֶׁל הָרְשָׁעִים שֶׁל הַמָּקוֹם שֶׁל הַגֵּיהִנֹּם מִכָּל חֵטְא וְחֵטְא.</p>\n<p>וְיִשִׁ חֲטָאִים רְשׁוּמִים לְמַעְלָה, וְלֹא לְמַטָּה. וְיֵשׁ שֶׁרְשׁוּמִים לְמַטָּה וְלֹא לְמַעְלָה, וְיֵשׁ שֶׁרְשׁוּמִים לְמַטָּה וּלְמַעְלָה. נִמְחוּ לְמַטָּה - נִמְחוּ לְמַעְלָה, אַחַר שֶׁחָזַר בִּתְשׁוּבָה. וְעוֹד בֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, רָשָׁע - עֲווֹנוֹתָיו חֲקוּקִים לוֹ עַל עַצְמוֹתָיו. צַדִּיק - זְכֻיּוֹתָיו חֲקוּקִים לוֹ עַל עַצְמוֹתָיו. לָמָּה? כְּדֵי לִהְיוֹת רְשׁוּמִים בֵּין בַּעֲלֵי הַחֲטָאִים שֶׁלָּהֶם לְהִוָּדַע בָּהֶם, וְקוֹל יוֹצֵא עָלָיו: זֶהוּ רָשָׁע, יִשָּׂרְפוּ עַצְמוֹתָיו בַּגֵּיהִנֹּם.</p>"],[9522011964,"<p>וּבֵאַרְנוּ, נְשָׁמוֹת שֶׁל רְשָׁעִים הֵן הֵן הַמַּזִּיקִים בָּעולָם. וְהַדִּין שֶׁלָּהֶם בֵּאֲרוּ עֲלֵיהֶם בַּעֲלֵי הַמִּשְׁנָה, שֶׁנִּשְׁמָתָם נִשְׂרֶפֶת וְנַעֲשֵׂית אֵפֶר תַּחַת כַּפּוֹת רַגְלֵי הַצַּדִּיקִים. וּבַמֶּה נִשְׂרָפִים? בְּאֵשׁ הַכִּסֵּא, שֶׁנֶּאֱמַר בּוֹ (דניאל ז) כָּרְסְיֵהּ שְׁבִיבִין דִּי-נוּר גַּלְגִּלּוֹהִי נוּר דָּלִק. (ונהר דינור שופע ויוצא) מֵאַרְבַּע חַיּוֹת שֶׁל אֵשׁ שֶׁסּוֹבְבִים אֶת כִּסֵּא הַדִּין, שֶׁהוּא אֲדנָ\"י, דִּין שֶׁל הַמַּלְכוּת דִּין.</p>\n<p>וְאוֹתוֹ נָהָר נֶאֱמַר בּוֹ, (שם) נְהַר דִּינוּר שׁוֹפֵעַ וְיוֹצֵא מִלְּפָנָיו. נִשְׁמוֹת הַצַּדִּיקִים טוֹבְלוֹת וְנִטְהָרוֹת בּוֹ, וְנִשְׁמוֹת הָרְשָׁעִים נִדּוֹנִים בּוֹ, וּבוֹעֲרִים לְפָנָיו כְּמוֹ קַשׁ לִפְנֵי אֵשׁ, וְהַיְנוּ אֵשׁ אוֹכֶלֶת אֵשׁ. יְהֹוָ\"ה הוּא חַמָּה. וְנַרְתִּיקוֹ - אֲדֹנָ\"י וְהַיְנוּ הַסּוֹד שֶׁפֵּרְשׁוּהוּ, לֶעָתִיד לָבֹא מוֹצִיא הַקָּדוֹשׁ בָּרוּךְ הוּא חַמָּה מִנַּרְתִּיקָהּ; צַדִּיקִים מִתְרַפְּאִין בָּהּ, וּרְשָׁעִים נִדּוֹנִים בָּהּ.</p>\n<p>וּמֵהַחַיּוֹת שֶׁל כִּסֵּא הַדִּין הָיָה יוֹרֵד אַרְיֵה שֶׁל אֵשׁ לֶאֱכֹל אֶת הַקָּרְבָּנוֹת, אוֹתָם הַמְמֻנִּים עַל כָּל אֵיבָר שֶׁחָטָא מְחַבֵּל קָטֵגוֹר אֶחָד, כְּמוֹ שֶׁבֵּאֲרוּהָ, עָשָׂה עֲבֵרָה אַחַת - קָנָה לוֹ קָטֵגוֹר אֶחָד. וּמִיָּד שֶׁיּוֹרֶדֶת אֵשׁ שֶׁל גָּבוֹהַּ וְשׂוֹרֶפֶת אֶת אוֹתָם אֵיבָרִים וּפְדָרִים וְאֵמוּרִים שֶׁל פָּרִים וּכְבָשִׂים וְעַתּוּדִים וְעִזִּים, יְהֹוָ\"ה שֶׁיּוֹרֵד כְּאַרְיֵה שֶׁל אֵשׁ לִשְׂרֹף אוֹתָם, נִשְׂרָפִים הָאֵיבָרִים שֶׁלָּהֶם, נִשְׂרָפִים הַמַּשְׁחִיתִים שֶׁמְּמֻנִּים עֲלֵיהֶם, וּמִתְכַּפְּרִים חֲטָאֵי יִשְׂרָאֵל, שֶׁהֵם אֵיבְרֵי הַשְּׁכִינָה.</p>\n<p>בְּאוֹתוֹ זְמַן מִתְקָרְבוֹת הַחַיּוֹת הַמְמֻנּוֹת עַל הַזְּכֻיּוֹת, שֶׁהֵם מִכִּסֵּא הָרַחֲמִים, שֶׁהִיא תְשׁוּבָה, הָאֵם הָעֶלְיוֹנָה. וּבַמֶּה מִתְקָרְבִים? בְּשֵׁם יְהֹוָ\"ה שֶׁנִּכְנָס בָּהֶם. וּמִשּׁוּם זֶה הַקָּרְבָּן לַיהֹוָ\"ה. שֶׁאֵין מִי שֶׁיָּכוֹל לְקָרֵב חַיּוֹת וִיסוֹדוֹת לְהַכְנִיס שָׁלוֹם בֵּינֵיהֶם אֶלָּא שְׁמוֹ, שֶׁמְּקָרֵב בִּשְׁמוֹ מַיִם לְאֵשׁ, וְלֹא מְכַבִּים זֶה אֶת זֶה, וּמְקָרֵב רוּחַ לֶעָפָר וְלֹא מַפְרִיד אוֹתוֹ.</p>"],[9522011965,"<p>בְּאוֹתוֹ זְמַן, אֵלּוּ הַשְּׁלָמִים, חַיּוֹת וִיסוֹדוֹת, וְנִקְרָאִים קֳדָשִׁים, שֶׁאֵין טְמֵאִים בֵּינֵיהֶם. וְעוֹד, שְׁלָמִים זוֹ ה' הָאַחֲרוֹנָה, שֶׁהִיא שְׁלֵמוּתוֹ שֶׁל הָעַמּוּד הָאֶמְצָעִי בְּכָל הַהֲוָיוֹת שֶׁכְּלוּלוֹת בּוֹ, לְכָל שֵׁשֶׁת הַצְּדָדִים שֶׁלּוֹ, שֶׁהֵן שֵׁשׁ סְפִירוֹת.</p>\n<p>וְסוֹד הַדָּבָר - חָתַם רוּם וּפָנָה לְמַעְלָה, בְּיה\"ו, לַיָּמִין שֶׁל חֶסֶד. בְּהו\"י, לַשְּׂמֹאל שֶׁל גְּבוּרָה. וה\"י, בָּעַמּוּד הָאֶמְצָעִי. יו\"ה בְּנֵצַח. בְּהוֹד הי\"ו. בַּיְסוֹד וי\"ה. הָאִילָן שֶׁאוֹחֵז אֶת כֻּלָּם - תִּפְאֶרֶת. עֵץ עוֹשֶׂה פְּרִי. וּמִשּׁוּם כָּךְ הַמָּקוֹם שֶׁיִּפֹּל הָעֵץ, שָׁם יה\"ו. וְאַף כָּךְ בְּכָל הֲוָיָה, ה' אַחֲרוֹנָה שְׁלָמִים לָהּ, וּלְכָל הַהֲוָיוֹת שֶׁאֲחוּזִים בָּהּ. כְּמוֹ זֶה, יה\"ו עִם ה' - יְהֹוָה. הו\"י עִם ה' - הֲוָיָה. וה\"י עִם ה' - וְהָיָ\"ה. וְאַף כָּךְ שְׁאָר הַהֲוָיוֹת.</p>\n<p>וְהֵם ח\"י אוֹתִיּוֹת שֶׁל שֵׁשֶׁת הַצְּדָדִים שֶׁכְּלוּלִים בְּצַדִּיק חַי הָעוֹלָמִים, וְעִם ה' נַעֲשֶׂה חַיָּ\"ה. וְסוֹד הַדָּבָר הִיא ה', כְּמוֹ תֵּבַת נֹחַ שֶׁכִּנֵּס בָּהּ בְּכָל מִין וּמִין, שֶׁהֵם שְׁנַיִם שְׁנַיִם שִׁבְעָה שִׁבְעָה לְקָרְבָּן. שְׁנַיִם שְׁנַיִם - אַרְבָּעָה. שִׁבְעָה שִׁבְעָה - אַרְבָּעָה עָשָׂר. הֲרֵי י\"ח. וְתֵבָה ה', בָּהּ נִשְׁלֶמֶת חַיָּה.</p>\n<p>(פתח ואמר, באתי לגני וגו') וְהַצַּדִּיק כּוֹלֵל שֵׁשׁ דְּרָגוֹת, וּמִשּׁוּם כָּךְ תִּקְּנוּ לִפְתֹּר בּוֹ חֲלוֹם בִּשְׁלֹשָׁה שְׁלוֹמוֹת, בִּשְׁלֹשָׁה פִדְיוֹנוֹת, שֶׁהוּא ו', בְּחֶשְׁבּוֹן ו'. וְהוּא הַסֻּלָּם שֶׁל חֲלוֹם יַעֲקֹב, כּוֹלֵל שֵׁשׁ סְפִירוֹת. מֻצָּב אַרְצָה - שְׁכִינָה תַחְתּוֹנָה, וְזוֹ ה' הַתַּחְתּוֹנָה. וְרֹאשׁוֹ - זֶה י', בּוֹ הוּא צַדִּיק שְׁבִיעִי. מַגִּיעַ הַשָּׁמָיְמָה - זוֹ הָאֵם הָעֶלְיוֹנָה, וְזוֹ ה' הָעֶלְיוֹנָה, שֶׁמִּצַּד הַחֲלוֹם ה' שׁוֹלֶטֶת עַל י', שֶׁהוּא רֹאשׁ הַסֻּלָּם, ה\"י מִן אֱלֹהִים. וּמִשּׁוּם כָּךְ, וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְגוֹ', וְלֹא מַלְאֲכֵי יְהֹוָ\"ה.</p>\n<p>הָאוֹתִיּוֹת כְּסִדְרָן עוֹלוֹת בְּחֹלָם, שֶׁהוּא כֶּתֶר עַל אַרְבַּע אוֹתִיּוֹת, שֶׁהַהִתְפַּשְּׁטוּת שֶׁלָּהֶן מֵחָכְמָה עַד הַמַּלְכוּת הַקְּדוֹשָׁה. מִשּׁוּם שֶׁחָכְמָה הִיא י', בִּינָה ה', שֵׁשׁ סְפִירוֹת ו', מַלְכוּת ה' אֲחרוֹנָה. חֹלָם כֶּתֶר עַל כָּל הָאוֹתִיּוֹת. (ע\"כ רעיא מהימנא).</p>"],[9522011966,"<p>אִם הַכֹּהֵן הַמָּשִׁיחַ יֶחֱטָא לְאַשְׁמַת הָעָם. רַבִּי אַבָּא פָּתַח, (שירא) הַגִּידָה לִּי שֶׁאָהֲבָה נַפְשִׁי וְגוֹ', אִם לֹא תֵדְעִי לָךְ הַיָּפָה בַּנָּשִׁים צְאִי לָךְ וְגוֹ'. אֶת הַפְּסוּקִים הַלָּלוּ בֵּאֲרוּ הַחֲבֵרִים בְּמֹשֶׁה בְּשָׁעָה שֶׁהָיָה עוֹלֶה מִן הָעוֹלָם, שֶׁאָמַר (במדבר כז) יִפְקֹד ה' אֱלֹהֵי הָרוּחֹת לְכָל בָּשָׂר וְגוֹ', אֲשֶׁר יֵצֵא לִפְנֵיהֶם וְגוֹ'. וְשָׁנִינוּ שֶׁזֶּה נֶאֱמַר עַל הַגָּלוּת.</p>\n<p>וּבֹא רְאֵה, הַפְּסוּקִים הַלָּלוּ אָמְרָה אוֹתָם כְּנֶסֶת יִשְׂרָאֵל לַמֶּלֶךְ הַקָּדוֹשׁ. הַגִּידָה לִּי שֶׁאָהֲבָה נַפְשִׁי, כְּמוֹ שֶׁנֶּאֱמַר (שיר ג) אֵת שֶׁאָהֲבָה נַפְשִׁי רְאִיתֶם. וְלַמֶּלֶךְ הַקָּדוֹשׁ נֶאֱמַר, אַתָּה שֶׁאָהֲבָה נַפְשִׁי אֵיכָה תִרְעֶה.</p>\n<p>בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא אוֹמֵר, כָּל זְמַן שֶׁכְּנֶסֶת יִשְׂרָאֵל נִמְצֵאת עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, כִּבְיָכוֹל הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁלֵמוּת, וְרוֹעֶה בְרָצוֹן אוֹתוֹ (ואת האחרים הוא זן) אֶת עַצְמוֹ מֵאוֹתָהּ יְנִיקַת הֶחָלָב (של המלך) שֶׁל הָאֵם הָעֶלְיוֹנָה, וּמֵאוֹתָהּ יְנִיקָה שֶׁהוּא יוֹנֵק, מַשְׁקֶה אֶת כָּל שְׁאָר הָאֲחֵרִים וּמֵינִיק אוֹתָם. וְלָמַדְנוּ שֶׁאָמַר רַבִּי שִׁמְעוֹן, כָּל זְמַן שֶׁכְּנֶסֶת יִשְׂרָאֵל נִמְצֵאת עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁלֵמוּת, בְּשִׂמְחָה, שְׁרוּיוֹת בּוֹ בְּרָכוֹת וְיוֹצְאוֹת מִמֶּנּוּ לְכָל שְׁאָר הָאֲחֵרִים, וְכָל זְמַן שֶׁאֵין כְּנֶסֶת יִשְׂרָאֵל נִמְצֵאת עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, כִּבְיָכוֹל הַבְּרָכוֹת נִמְנָעוֹת מִמֶּנּוּ וּמִכָּל שְׁאָר הָאֲחֵרִים.</p>\n<p>וְסוֹד הַדָּבָר - בְּכָל מָקוֹם שֶׁאֵין נִמְצָאִים זָכָר וּנְקֵבָה, אֵין בְּרָכוֹת שׁוֹרוֹת עָלָיו, וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹעֶה וּבוֹכֶה, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה כח) שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. וּמַה הוּא אוֹמֵר? אוֹי שֶׁהֶחֱרַבְתִּי אֶת בֵּיתִי וְשָׂרַפְתִּי אֶת הֵיכָלִי וְכוּ'.</p>\n<p>וּבְשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל יָצְאָה לַגָּלוּת, אָמְרָה לְפָנָיו: הַגִּידָה לִּי שֶׁאָהֲבָה נַפְשִׁי. אַתָּה אֲהוּב נַפְשִׁי, אַתָּה שֶׁכָּל אַהֲבַת נַפְשִׁי בְּךְ, אֵיכָה תִרְעֶה? אֵיךְ תָּזוּן אֶת עַצְמְךְ מֵעֹמֶק הַנַּחַל שֶׁלֹּא פוֹסֵק, אֵיךְ תָּזוּן אֶת עַצְמְךְ מֵהָאוֹר שֶׁל הָעֵדֶן הָעֶלְיוֹן. אֵיכָה תַּרְבִּיץ בַּצָּהֳרָיִם, אֵיךְ תָּזוּן אֶת כָּל אֵלּוּ הָאֲחֵרִים שֶׁנִּשְׁקִים מִמְּךְ תָּמִיד?</p>\n<p>וַאֲנִי הָיִיתִי נִזּוֹנֵית מִמְּךְ בְּכָל יוֹם, וְנִשְׁקֵית וּמַשְׁקָה אֶת כָּל אוֹתָם הַתַּחְתּוֹנִים, וְיִשְׂרָאֵל נִזּוֹנוּ בִּי, וְעַכְשָׁו שַׁלָּמָה אֶהְיֶה כְּעֹטְיָה, אֵיךְ אֶהְיֶה מִתְעַטֶּפֶת בְּלִי בְרָכוֹת, כְּשֶׁיִּצְטָרְכוּ אוֹתָן בְּרָכוֹת וְלֹא יִמָּצְאוּ בְיָדִי. עַל עֶדְרֵי חֲבֵרֶיךְ, אֵיךְ אֶעֱמֹד עֲלֵיהֶם וְלֹא אֶהְיֶה רוֹעָה לָהֶם וְזָנָה אוֹתָם. עֶדְרֵי חֲבֵרֶיךְ - אֵלּוּ הֵם יִשְׂרָאֵל שֶׁהֵם בְּנֵי הָאָבוֹת, שֶׁהֵם הַמֶּרְכָּבָה הַקְּדוֹשָׁה לְמַעְלָה.</p>\n<p>אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: תַּעַזְבִי אַתְּ אֶת שֶׁלִּי, שֶׁהֲרֵי שֶׁלִּי הוּא דָבָר נִסְתָּר מִלְּהִוָּדַע. אֲבָל - אִם לֹא תֵדְעִי לָךְ, לְעַצְמֵךְ, הֲרֵי לָךְ עֵצָה. הַיָּפָה בַּנָּשִׁים, כְּמוֹ שֶׁנֶּאֱמַר הִנָּךְ יָפָה רַעְיָתִי. צְאִי לָךְ בְּעִקְבֵי הַצּאן - אֵלֶּה הֵם הַצַּדִּיקִים שֶׁהֵם נִדָּשִׁים בֵּין הָעֲקֵבִים, וּבִשְׁבִילָם נִתַּן לְךְ כֹּחַ לַעֲמֹד. (ועם כל זה) וּרְעִי אֶת גְּדִיֹּתַיִךְ עַל מִשְׁכְּנוֹת הָרֹעִים - אֵלּוּ הֵם תִּינוֹקוֹת שֶׁל בֵּית רַבָּן שֶׁהָעוֹלָם מִתְקַיֵּם בִּשְׁבִילָם, וְנוֹתְנִים כֹּחַ לִכְנֶסֶת יִשְׂרָאֵל בַּגָּלוּת. מִשְׁכְּנוֹת הָרֹעִים - אֵלּוּ בָּתֵּי רַבָּן, מְקוֹם בֵּית הַמִּדְרָשׁ שֶׁתָּמִיד נִמְצֵאת בָּהֶם הַתּוֹרָה.</p>\n<p>דָּבָר אַחֵר אִם לֹא תֵדְעִי לָךְ הַיָּפָה בַּנָּשִׁים וְגוֹ' - בֹּא רְאֵה, בְּשָׁעָה שֶׁצַּדִּיקִים נִמְצָאִים בָּעוֹלָם, וְאוֹתָם תִּינוֹקוֹת שֶׁל בֵּית רַבָּן נִמְצָאִים וְעוֹסְקִים בַּתוֹרָה, יְכוֹלָה כְּנֶסֶת יִשְׂרָאֵל לַעֲמֹד עִמָּם בַּגָּלוּת. וְאִם לֹא, כִּבְיָכוֹל הִיא וְהֵם אֵין יְכוֹלִים לְהִתְקַיֵּם בָּעוֹלָם. וְאִם נִמְצָאִים צַדִּיקִים, הֵם נִתְפָּסִים בָּרִאשׁוֹנָה. וְאִם לֹא, אוֹתָם הַגְּדָיִים שֶׁהָעוֹלָם מִתְקַיֵּם בִּשְׁבִילָם נִתְפָּסִים בָּרִאשׁוֹנָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְסַלֵּק אוֹתָם מִן הָעוֹלָם, אַף עַל גַּב שֶׁאֵין נִמְצָא בָהֶם חֵטְא. וְלֹא זֶה בִּלְבַד, אֶלָּא מַרְחִיק מִמֶּנּוּ אֶת כְּנֶסֶת יִשְׂרָאֵל וְגוֹלֶה לַגָּלוּת.</p>\n<p>זְהִוּ שֶׁכָּתוּב, אִם הַכֹּהֵן הַמָּשִׁיחַ יֶחֱטָא לְאַשְׁמַת הָעָם. לָמָּה יֶחֱטָא? לְאַשְׁמַת הָעָם. מִשּׁוּם חֲטָאֵי הָעוֹלָם שֶׁגָּרְמוּ אֶת זֶה, לְאַשְׁמַת הָעָם וַדַּאי, וְלֹא לְאַשְׁמָתוֹ. יֶחֱטָא - יִגְרַע טוּבוֹ וְדָן דִּין בַּכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א א) וְהָיִיתִי אֲנִי וּבְנִי שְׁלֹמֹה חַטָּאִים. דָּבָר אַחֵר אִם הַכֹּהֵן הַמָּשִׁיחַ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּפִי שֶׁאָמַרְנוּ. יֶחֱטָא - יֶחֱסַר מִכְּנֶסֶת יִשְׂרָאֵל וּמֵהָעוֹלָם, שֶׁלֹּא נוֹתֵן לָהֶם סִפּוּק הַבְּרָכוֹת. לָמָּה? זֶהוּ לְאַשְׁמַת הָעָם וַדַּאי, זֶה בִּשְׁבִיל הַחֵטְא שֶׁל הָעָם.</p>"],[9522011967,"<p>אִם הַכֹּהֵן הַמָּשִׁיחַ יֶחֱטָא. רַבִּי יִצְחָק פָּתַח, (שמות לב) זְכֹר לְאַבְרָהָם לְיִצְחָק וּלְיִשְׂרָאֵל עֲבָדֶיךְ, הַפָּסוּק הַזֶּה קָשֶׁה. כָּךְ הָיָה צָרִיךְ לִכְתֹּב: זְכֹר לְאַבְרָהָם וּלְיִצְחָק וּלְיִשְׂרָאֵל. מַה זֶּה לְיִצְחָק? אֶלָּא כָּךְ שָׁנִינוּ, בְּכָל מָקוֹם הַשְּׂמֹאל נִכְלָל בַּיָּמִין, וְהוּא בַּכְּלָל שֶׁל הַיָּמִין. שֶׁהַיָּמִין הַזֶּה מְתֻקָּן לְעוֹלָמִים לְהַכְלִיל בּוֹ אֶת הַשְּׂמֹאל, וְעַל כֵּן לֹא חֵלֵּק, כְּדֵי לְהַכְלִיל אוֹתוֹ בְּאַבְרָהָם. וּמִשּׁוּם כָּךְ לְאַבְרָהָם לְיִצְחָק (דוקא) כְּלָל אֶחָד. (אבל) וּלְיִשְׂרָאֵל, שֶׁהֲרֵי הוא אוֹחֵז בִּכְנָפָיו (בכתפיו) אֶת שְׁנֵיהֶם, וְהוּא שָׁלֵם בַּכֹּל.</p>\n<p>אֲשֶׁר נִשְׁבַּעְתָּ לָהֶם בָּךְ. שְׁבוּעָה נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָבוֹת, בָּאָבוֹת שֶׁלְּמַעְלָה, זֶהוּ שֶׁכָּתוּב אֲשֶׁר נִשְׁבַּעְתָּ לָהֶם בָּךְ, בְּאוֹתָם שֶׁלְּמַעְלָה בְּאוֹתָם שֶׁשּׁוֹרִים בְּךְ. וַתְּדַבֵּר אֲלֵהֶם אַרְבֶּה אֶת זַרְעֲכֶם וְגוֹ'. אֲשֶׁר אָמַרְתִּי, אֲשֶׁר אָמַרְתָּ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר כָּךְ לָאָבוֹת פַּעַם וּפַעֲמַיִם. אֲשֶׁר אָמַרְתִּי - שֶׁרָצִיתִי בִּרְצוֹן נַפְשִׁי, שֶׁהֲרֵי אֲמִירָה זֶהוּ רָצוֹן. זֶהוּ שֶׁכָּתוּב (מלכים א ח) אדני אמר לשכן בערפל. ועוד מה תאמר נפשך ואעשה לך.</p>\n<p>וְנָחֲלוּ לְעֹלָם, מַה זֶּה לְעֹלָם? הָעוֹלָם שֶׁלְּמַעְלָה שֶׁאֲחוּזָה בּוֹ אוֹתָהּ אֶרֶץ, וְנִזּוֹנֵית מֵאוֹתוֹ עוֹלָם. וְאִם הָאָרֶץ הַזּוֹ מִתְגָּרֶשֶׁת, מִמַּה זֶּה? לְאַשְׁמַת הָעָם הוּא נִהְיָה.</p>\n<p>רַבִּי יִצְחָק אָמַר, אִם הַכֹּהֵן הַמָּשִׁיחַ יֶחֱטָא - זֶה הַכֹּהֵן שֶׁלְּמַטָּה, שֶׁנִּתְתַּקֵּן לָעֲבוֹדָה וְנִמְצָא בּוֹ חֵטְא, זֶה וַדַּאי קוֹרֶה לְאַשְׁמַת הָעָם. אוֹי לְאוֹתָם שֶׁסּוֹמְכִים עָלָיו. כְּמוֹ כֵן שְׁלִיחַ צִבּוּר שֶׁנִּמְצָא בּוֹ חֵטְא, (משום שהעם לא נמצאו צדיקים לפני הקדוש ברוך הוא) אוֹי לְאוֹתָם שֶׁסּוֹמְכִים עָלָיו. אָמַר רַבִּי יְהוּדָה, וְכָל שֶׁכֵּן הַכֹּהֵן, שֶׁכָּל יִשְׂרָאֵל, וְהָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, כֻּלָּם מְאֻחָדִים (מחכים) וּמְצַפִּים לְהִתְבָּרֵךְ עַל יָדוֹ.</p>\n<p>שֶׁהֲרֵי שָׁנִינוּ, בְּשָׁעָה שֶׁהַכֹּהֵן מַתְחִיל לְכַוֵּן דְּבָרִים וּלְהַקְרִיב קָרְבָּן עֶלְיוֹן, הַכֹּל נִמְצָאִים בִּבְרָכָה וּבְשִׂמְחָה. הַיָּמִין מַתְחִיל לְהִתְעוֹרֵר, הַשְּׂמֹאל נִכְלָל לְיָמִין, וְהַכֹּל נִקְשָׁר וְנֶאֱחָז זֶה עִם זֶה, וְכֻלָּם מִתְבָּרְכִים כְּאֶחָד. נִמְצָא שֶׁעַל יְדֵי הַכֹּהֵן מִתְבָּרְכִים הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וַהֲרֵי פֵּרְשׁוּהָ. וּמִשּׁוּם כָּךְ צָרִיךְ לְהַקְרִיב קָרְבָּן עָלָיו, כְּדֵי שֶׁיִּתְכַּפֵּר חֶטְאוֹ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, הֲרֵי שָׁנִינוּ שֶׁעַל יְדֵי הַכֹּהֵן מִתְכַּפֵּר חֶטְאוֹ שֶׁל אָדָם כְּשֶׁמַּקְרִיב קָרְבָּן. עַכְשָׁו כְּשֶׁהוּא חוֹטֵא, מִי מַקְרִיב עָלָיו וּמִי יְכַפֵּר עָלָיו? אִם תֹּאמַר שֶׁהוּא מַקְרִיב עַל נַפְשׁוֹ - הֲרֵי הוּא הִתְקַלְקֵל, וְאֵינוֹ כְּדַאי שֶׁיִּתְבָּרְכוּ עָלָיו עֶלְיוֹנִים וְתַחְתּוֹנִים. הַתַּחְתּוֹנִים לֹא יִתְבָּרְכוּ עַל יָדוֹ, כָּל שֶׁכֵּן הָעֶלְיוֹנִים. אָמַר רַבִּי יְהוּדָה, וָלֹא? וַהֲרֵי כָּתוּב (ויקרא טז) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ. לָמָּה צָרִיךְ לְכַפֵּר עָלָיו? מִשּׁוּם שֶׁהוּא חָטָא, יְכַפֵּר עַל עַצְמוֹ, שֶׁכָּתוּב וְכִפֶּר בַּעֲדוֹ.</p>\n<p>אָמַר רַבִּי חִיָּיא, הֲרֵי יָדוּעַ בְּאֵיזֶה מָקוֹם נִקְשָׁר הַכֹּהֵן הַגָּדוֹל וּבְאֵיזֶה מָקוֹם נִקְשָׁר כֹּהֵן אַחֵר. וְאוֹתוֹ שֶׁנִּקְרָא סְגָן יָדוּעַ. מִשּׁוּם כָּךְ כֹּהֵן מַקְרִיב אֶת קָרְבָּנוֹ בָּרִאשׁוֹנָה, וּמַעֲלֶה אוֹתוֹ עַד אוֹתוֹ מָקוֹם שֶׁנִּקְשָׁר בּוֹ. וְאַחַר שֶׁהַכֹּהֵן עָלָה לְאוֹתוֹ מָקוֹם, לֹא מְעַכְּבִים אוֹתוֹ לַעֲלוֹת לִמְקוֹמוֹ וּלְכַפֵּר עַל חֶטְאוֹ. וְלָכֵן אַחֵר מַקְרִיב עָלָיו אֶת קָרְבָּנוֹ. כֵּיוָן שֶׁאַחֵר הוּא הַמַּקְרִיב, וְלֹא מִסְתַּפְּקִים כָּל כָּךְ עַל יָדוֹ, אַחַר כָּךְ הוּא מַקְרִיב, וְאוֹתָם הָעֶלְיוֹנִים, כֻּלָּם מִתְחַבְּרִים לְכַפֵּר אֶת חֶטְאוֹ, וְהַמֶּלֶךְ הַקָּדוֹשׁ מַסְכִּים עַל יָדָם. כְּמוֹ כֵן הַמִּתְפַּלֵּל וְטָעָה, יַעֲמֹד אַחֵר תַּחְתָּיו.</p>"],[9522011968,"<p>רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא הָיוּ יוֹשְׁבִים. אָמַר רַבִּי אֶלְעָזָר, רָאִיתִי אֶת אַבָּא בְּיוֹם רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים שֶׁאֵינוֹ רוֹצֶה לִשְׁמֹעַ תְּפִלָּה מִכָּל אָדָם, אֶלָּא אִם עָמַד עָלָיו שְׁלֹשָׁה יָמִים קֹדֶם לְטַהֵר אוֹתוֹ. שֶׁרַבִּי שִׁמְעוֹן הָיָה אוֹמֵר כָּךְ: בִּתְפִלַּת הָאָדָם הַזֶּה שֶׁאֲנִי מְטַהֵר, מִתְכַּפֵּר הָעוֹלָם. וְכָל שֶׁכֵּן בִּתְקִיעַת הַשּׁוֹפָר שֶׁאֵינוֹ מְקַבֵּל תְּקִיעָה שֶׁל אָדָם שֶׁאֵינוֹ חָכָם לִתְקֹעַ בְּסוֹד הַתְּקִיעָה.</p>\n<p>שֶׁשָּׁנִינוּ, רַבִּי יֵיסָא סָבָא אוֹמֵר, הַתְּקִיעוֹת הַלָּלוּ כְסִדְרָן. הָרִאשׁוֹנָה כְּלוּלָה מֵהַכֹּל. הַשְּׁנִיָּה - אַחַת כְּסֵדֶר וְאַחַת כְּסֵדֶר, גְּבוּרָה גְדוֹלָה בֵּינֵיהֶם. שְׁלִישִׁית - אַחַת כָּאן וְאַחַת כָּאן, וּגְבוּרָה בֵּינֵיהֶם. הַשֶּׁבֶר עוֹלֶה, וְהַתְּרוּעָה יוֹרֶדֶת. אַחַת קָשָׁה וְאַחַת רָפָה. וַהֲרֵי פֵּרְשׁוּהָ. וְהֵן עֶשֶׂר. וְהֵן תֵּשַׁע. כְּלָל אֶחָד שֶׁל הַכֹּל.</p>\n<p>וּבַיּוֹם הַזֶּה מִתְעַטֵּר יִצְחָק, וְהוּא הָרֹאשׁ לָאָבוֹת. בַּיּוֹם הַזֶּה כָּתוּב, (ישעיה לג) פָּחֲדוּ בְצִיּוֹן חַטָּאִים. בַּיּוֹם הַזֶּה יִצְחָק נֶעֱקַד, וְעָקַד הַכֹּל, וְשָׂרָה מְדַבֶּרֶת (מיללת), וְקוֹל שׁוֹפָר חָזָק מְאֹד. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁעוֹבֵר בֵּינֵיהֶם וְנִצַּל מֵהֶם. אָמַר רַבִּי אַבָּא, מִשּׁוּם כָּךְ קוֹרְאִים פָּרָשַׁת יִצְחָק בַּיּוֹם הַזֶּה, שֶׁבַּיּוֹם הַזֶּה נֶעֱקַד יִצְחָק לְמַטָּה וְנִקְשַׁר בְּאוֹתוֹ שֶׁלְּמַעְלָה. (באברהם) מָתַי נִקְשָׁר? בְּשָׁעָה שֶׁכָּתוּב (בראשית כב) וַיַּעֲקֹד אֶת יִצְחָק בְּנוֹ וְגוֹ'.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, בַּיּוֹם הַזֶּה מְעַטֵּר יִצְחָק אֶת אַבְרָהָם, שֶׁכָּתוּב וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. מַה זֶּה נִסָּה? כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מט) וְאֶל עַמִּים אָרִים נִסִּי. (שמות יז) וַיִּקְרָא שְׁמוֹ ה' נִסִּי. מַה בָּא לְהַשְׁמִיעֵנוּ? מִשּׁוּם שֶׁהַיָּמִין נִתְקַן וְנִשְׁלַם. זֶהוּ שֶׁכָּתוּב וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. וְהָאֱלֹהִים בְּדִיּוּק. וְזֶהוּ (בראשית לא) וּפַחַד יִצְחָק.</p>\n<p>רַבִּי אַבָּא אָמַר, כָּתוּב (תהלים עה) כִּי אֱלֹהִים שׁוֹפֵט זֶה יַשְׁפִּיל וְזֶה יָרִים. כִּי אֱלֹהִים שׁוֹפֵט, אִלְמָלֵא שֶׁעָבַר הַדִּין שֶׁל יִצְחָק בַּמָּקוֹם שֶׁיַּעֲקֹב שׁוֹרֶה (ונרפא) וְהִתְכַּסָּה (ורוחץ) (והתבשם) שָׁם, אוֹי לָעוֹלָם שֶׁיִּפָּגֵשׁ בְּדִינוֹ. וְסוֹד הַדָּבָר - (ישעיה סו) כִּי בָאֵשׁ ה' נִשְׁפָּט. וְזוֹהִי הִתְבַּשְּׂמוּת שֶׁל הָעוֹלָם.</p>\n<p>וְכֵיוָן שֶׁנִּכְנָס לִמְקוֹמוֹ שֶׁל יַעֲקֹב, וְיַעֲקֹב אוֹחֵז בּוֹ, אֲזַי הָאֵשׁ שׁוֹכֶכֶת וְהַגֶּחָלִים מִצְטַנְּנִים. לְאָדָם שֶׁהָיָה רוֹגֵז, וְחָגַר וְשָׂם עָלָיו כְּלֵי זַיִן, וְיָצָא מְרֻגָּז לַהֲרֹג אֲנָשִׁים. חָכָם אֶחָד עָמַד עַל הַפֶּתַח וְאָחַז בּוֹ. אָמַר: אִלְמָלֵא לֹא הֶחֱזִיק בִּי וְתָפַס אוֹתִי, הֲרֵי הָיָה נִמְצָא הֶרֶג שֶׁל אֲנָשִׁים. בְּעוֹד שֶׁהֶחֱזִיקוּ זֶה בָזֶה וְאָחֲזוּ זֶה בָזֶה, הִצְטַנֵּן רָגְזוֹ עַל שֶׁיָּצָא לַהֲרֹג. יָצָא לְהוֹכִיחַ - מִי סוֹבֵל אֶת הָרֹגֶז וְחֹזֶק הַדִּין שֶׁל אוֹתוֹ אָדָם? הֱוֵה אוֹמֵר, זֶה שֶׁעָמַד עַל הַפֶּתַח.</p>\n<p>כָּךָ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל: בָּנַי, אַל תִּפְחֲדוּ, הֲרֵי אֲנִי עוֹמֵד עַל הַפֶּתַח, אֲבָל הִזְדָּרְזוּ בַּיּוֹם הַזֶּה וּתְנוּ לִי כֹּחַ. בַּמֶּה? בַּשּׁוֹפָר. שֶׁאִם נִמְצָא קוֹל הַשּׁוֹפָר כָּרָאוּי וּמְכַוְּנִים בּוֹ לְמַטָּה, אוֹתוֹ הַקּוֹל עוֹלֶה, וּבוֹ מִתְעַטְּרִים הָאָבוֹת, וְעוֹמְדִים בְּמִשְׁכָּנוֹ שֶׁל יַעֲקֹב. וְלָכֵן צָרִיךְ לְהִזָּהֵר בַּשּׁוֹפָר וְלָדַעַת אֶת אוֹתוֹ הַקּוֹל וּלְכַוֵּן בּוֹ.</p>\n<p>וְאֵין לְךְ קוֹל בַּשּׁוֹפָר שֶׁלֹא עוֹלֶה רָקִיעַ אֶחָד, וְכָל אוֹתָם הָאוּכְלוּסִים שֶׁל אוֹתוֹ רָקִיעַ, נוֹתְנִים מָקוֹם לְאוֹתוֹ קוֹל. וּמָה אוֹמְרִים? (יואל ב) וַה' נָתַן קוֹלוֹ לִפְנֵי חֵילוֹ וְגוֹ'. וְעוֹמֵד אוֹתוֹ הַקּוֹל בְּאוֹתוֹ הָרָקִיעַ, עַד שֶׁבָּא קוֹל אַחֵר, וְנוֹעָדוּ (והתעוררו) יַחְדָּו, וְעוֹלִים בְּזִוּוּג לְרָקִיעַ אַחֵר. וְעַל זֶה שָׁנִינוּ, יֵשׁ קוֹל שֶׁמַּעֲלֶה קוֹל, וּמַה הוּא? אוֹתוֹ הַקּוֹל שֶׁל תְּקִיעָתָם שֶׁל יִשְׂרָאֵל שֶׁלְּמַטָּה.</p>\n<p>וְכֵיוָן שֶׁמִּתְחַבְּרִים כָּל הַקּוֹלוֹת הַלָּלוּ שֶׁלְּמַטָּה וְעוֹלִים לְאוֹתוֹ רָקִיעַ עֶלְיוֹן שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ שׁוֹרֶה בּוֹ, מִתְעַטְּרִים (נועדים) כֻּלָּם לִפְנֵי הַמֶּלֶךְ, וְאָז הַכִּסְאוֹת עוֹלִים, וְכִסֵּא אַחֵר שֶׁל יַעֲקֹב עוֹמֵד וּמִתְתַּקֵּן.</p>\n<p>וְעַל זֶה מָצָאנוּ בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא בְּאוֹתָן תְּפִלּוֹת שֶׁל רֹאשׁ הַשָּׁנָה שֶׁהָיָה אוֹמֵר, הַתְּפִלָּה וְקוֹל הַשּׁוֹפָר (שאותו קול) שֶׁמּוֹצִיא אוֹתוֹ הַצַּדִּיק, שֶׁנִּמְצָא מֵרוּחוֹ וְנַפְשׁוֹ בְּאוֹתוֹ הַשּׁוֹפָר שֶׁל אוֹתוֹ הַקּוֹל שֶׁעוֹלֶה לְמַעְלָה. וּבְאוֹתוֹ יוֹם עוֹמְדִים וְנִמְצָאִים מְקַטְרְגִים לְמַעְלָה. וּכְשֶׁעוֹלֶה אוֹתוֹ קוֹל הַשּׁוֹפָר, כֻּלָּם נִדְחִים לְפָנָיו וְלֹא יְכוֹלִים לַעֲמֹד. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁיּוֹדְעִים לְכַוֵּן אֶת הָרָצוֹן לִפְנֵי רִבּוֹנָם וְיוֹדְעִים לְתַקֵּן עוֹלָם בַּיּוֹם הַזֶּה בְּקוֹל שׁוֹפָר. וְעַל זֶה כָּתוּב, (תהלים פט) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה. יוֹדְעֵי, וְלֹא תוֹקְעֵי.</p>\n<p>בַּיּוֹם הַזֶּה צָרִיךְ הָעָם לְהִסְתַּכֵּל בְּאָדָם שָׁלֵם מִכֹּל, שֶׁיּוֹדֵעַ אֶת דַּרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁיּוֹדֵעַ בִּכְבוֹד הַמֶּלֶךְ שֶׁיְּבַקֵּשׁ עֲלֵיהֶם בַּקָּשָׁה בַּיּוֹם הַזֶּה, וּלְזָמֵן קוֹל שׁוֹפָר בְּכָל הָעוֹלָמוֹת, בְּכַוָּנַת הָלֵּב, בְּחָכְמָה, בְּרָצוֹן וּבִשְׁלֵמוּת, כְּדֵי שֶׁיִּסְתַּלֵּק הַדִּין עַל יָדוֹ מִן הָעוֹלָם. אוֹי לְאוֹתָם שֶׁהַשָּׁלִיחַ שֶׁלָּהֶם לֹא נִמְצָא כָּרָאוּי, שֶׁהֲרֵי חֲטָאֵי הָעוֹלָם (העם) בָּאִים לְהִזָּכֵר בִּגְלָלוֹ. זֶהוּ שֶׁכָּתוּב, אִם הַכֹּהֵן הַמָּשִׁיחַ יֶחֱטָא - שֶׁהוּא שְׁלִיחָם שֶׁל כָּל יִשְׂרָאֵל - לְאַשְׁמַת הָעָם הוּא, מִשּׁוּם שֶׁהַדִּין שׁוֹרֶה עֲלֵיהֶם.</p>\n<p>וּכְשֶׁהַשָּׁלִיחַ הוּא צַדִּיק כָּרָאוּי, אַשְׁרֵי הָעָם, שֶׁכָּל הַדִּינִים מִסְתַּלְּקִים מֵהֶם עַל יָדוֹ, כָּל שֶׁכֵּן הַכֹּהֵן שֶׁעָלָיו מִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים. אָמַר רַבִּי אֶלְעָזָר, וְעַל זֶה, כֹּהֵן וְלֵוִי טֶרֶם שֶׁיַּעֲלֶה לָעֲבוֹדָה, בּוֹדְקִים אַחֲרָיו, וְיוֹדְעִים דְּרָכָיו וּמַעֲשָׂיו. וְאִם לֹא, אֵינוֹ עוֹלֶה לָעֲבוֹדָה, וְכֵן בַּסַּנְהֶדְרִין כְּדֵי לָדוּן דִּין.</p>\n<p>וְאִם נִמְצָא כָּרָאוּי, נוֹתְנִים עָלָיו חֻמְרוֹת הַמִּקְדָּשׁ. וְאִם לֹא, אֵינוֹ עוֹלֶה לָעֲבוֹדָה. זֶהוּ שֶׁכָּתוּב, (דברים לג) וּלְלֵוִי אָמַר תֻּמֶּיךְ וְאוּרֶיךְ לְאִישׁ חֲסִידֶךְ. מִפְּנֵי מָה זָכָה (אהרן) לְאוּרִים וּלְתֻמִּים וְלַעֲבֹד עֲבוֹדָה? הֱוֵי אוֹמֵר, אֲשֶׁר נִסִּיתוֹ וְגוֹ'. הָאֹמֵר לְאָבִיו וּלְאִמּוֹ לֹא רְאִיתִיו וְגוֹ'. וְכֵיוָן שֶׁנִּמְצְאוּ בַדְּרָגוֹת הַלָּלוּ, אָז - יוֹרוּ מִשְׁפָּטֶיךְ לְיַעֲקֹב וְגוֹ', יָשִׂימוּ קְטוֹרָה וְגוֹ'. לְשַׁכֵּךְ אֶת הָרֹגֶז וּלְזַמֵּן שָׁלוֹם. וְכָלִיל עַל מִזְבְּחֶךְ, כְּדֵי שֶׁהַכֹּל יִתְבַּשְּׂמוּ וְיִמָּצְאוּ בְרָכוֹת בְּכָל הָעוֹלָמוֹת, אָז - בָּרֵךְ ה' חֵילוֹ וְגוֹ'.</p>\n<p>וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ וְנֶעְלַם וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח, (ישעיה לב) נָשִׁים שַׁאֲנַנּוֹת קֹמְנָה שְׁמַעְנָה קוֹלִי וְגוֹ'. כַּמָּה יֵשׁ לוֹ לָאָדָם לְהִתְבּוֹנֵן בִּכְבוֹד רִבּוֹנוֹ, כְּדֵי שֶׁיִּמָּצֵא בְרִיָּה שְׁלֵמָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, הוּא בָּרָא אוֹתוֹ שָׁלֵם, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ז) אֲשֶׁר עָשָׂה הָאֱלֹהִים אֶת הָאָדָם יָשָׁר וְגוֹ'. אֶת הָאָדָם - זָכָר וּנְקֵבָה. וּנְקֵבָה נִכְלֶלֶת בַּזָּכָר, וְאָז כָּתוּב יָשָׁר. אַחַר כָּךְ - וְהֵמָּה בִקְשׁוּ חִשְּׁבנוֹת רַבִּים.</p>"],[9522011969,"<p>בֹּא רְאֵה, מִנֶּקֶב תְּהוֹם רַבָּה נִמְצֵאת רוּחַ נְקֵבָה, רוּחַ שֶׁל כָּל הָרוּחוֹת, וּבֵאַרְנוּ שֶׁשְּׁמָהּ לִילִית, וְהִיא נִמְצְאָה לָרִאשׁוֹנָה אֵצֶל אָדָם. וּבְשָׁעָה שֶׁנִּבְרָא אָדָם וְנִשְׁלַם גּוּפוֹ, הִזְדַּמְּנוּ עַל אוֹתוֹ הַגּוּף אֶלֶף רוּחוֹת מִצַּד הַשְּׂמֹאל. זֶה רָצָה לְהִכָּנֵס בּוֹ, וְזֶה רָצָה לְהִכָּנֵס בּוֹ, וְלֹא הָיוּ יְכוֹלִים. עַד שֶׁגָּעַר בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָדָם הָיָה שׁוֹכֵב גּוּף בְּלִי רוּחַ, וּמַרְאֵהוּ הָיָה יָרֹק, וְכָל אוֹתָן רוּחוֹת סוֹבְבוֹת אוֹתוֹ.</p>\n<p>בְּאוֹתָהּ שָׁעָה יָרַד עָנָן אֶחָד וְדָחָה (וזרק) אֶת כָּל אוֹתָן הָרוּחוֹת, וּבַשָּׁעָה הַזּוֹ כָּתוּב, (בראשית א) וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. וַהֲרֵי בֵּאַרְנוּ, שֶׁנְּקֵבָה מִתְעַבֶּרֶת מִן הַזָּכָר מִן אוֹתָהּ נֶפֶשׁ שֶׁל אָדָם, וְהִיא מוֹצִיאָה אוֹתָהּ הָרוּחַ לְנַשֵּׁב אוֹתָהּ בָּאָדָם, כְּלוּלָה מִשְּׁנֵי צְדָדִים כָּרָאוּי. זֶהוּ שֶׁכָּתוּב (שם ב) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה. לְנֶפֶשׁ חַיָּה מַמָּשׁ. וּמִי שֶׁמִּסְתַּפֵּק בָּזֶה, כִּי אֵינוֹ יוֹדֵעַ אִם הַחַיָּה הַזּוֹ הִיא הַחַיָּה הַתַּחְתּוֹנָה, אוֹ הַחַיָּה שֶׁשְּׁמָהּ יִשְׂרָאֵל, אוֹ מֵהַזָּכָר אוֹ מֵהַנְּקֵבָה. אֲבָל לֹא כָתוּב לְנֶפֶשׁ הַחַיָּה, אֶלָּא לְנֶפֶשׁ חַיָּה סְתָם, שֶׁמַּשְׁמָע הַכֹּל.</p>\n<p>וּכְשֶׁעָמַד אָדָם, הָיְתָה נְקֵבָתוֹ תְקוּעָה בְצִדּוֹ, וְאוֹתָהּ הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁבּוֹ הָיְתָה מִתְפַּשֶּׁטֶת לַצַּד הַזֶּה וְלַצַּד הַזֶּה, וְהָיְתָה מַסְפִּיקָה לָזֶה וְלָזֶה, מִשּׁוּם שֶׁכָּךְ נִכְלְלָה. אַחַר כָּךְ נִסֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, וְתִקֵּן אֶת נְקֵבָתוֹ. זֶהוּ שֶׁכָּתוּב (שם) וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע וְגוֹ'. אֶת הַצֵּלָע, הֲרֵי בֵּאַרְנוּ, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא מד) וּלְצֶלַע הַמִּשְׁכָּן. וַיְבִיאֶהָ אֶל הָאָדָם, בְּתִקּוּנֶיהָ כְּמוֹ כַּלָּה לַחֻפָּה.</p>\n<p>כֵּיוָן שֶׁרָאֲתָה לִילִית כָּךְ, בָּרְחָה, וְהִיא בִּכְרַכֵּי הַיָּם, וְעַד עַכְשָׁו הִיא מְזֻמֶּנֶת לְהָרַע לִבְנֵי הָעוֹלָם. וּכְשֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲרִיב אֶת רוֹמִי הָרְשָׁעָה וְשֶׁתֶּחֱרַב לְעוֹלָמִים, הוּא יַעֲלֶה אֶת לִילִית הַזּוֹ, וְיָשִׂים אוֹתָהּ בַּחֻרְבָּן הַזֶּה, מִשּׁוּם שֶׁהִיא חֻרְבָּנוֹ שֶׁל הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה לד) אַךְ שָׁם הִרְגִּיעָה לִילִית וּמָצְאָה לָהּ מָנוֹחַ.</p>\n<p>וּבְסִפְרֵי הָרִאשׁוֹנִים אָמְרוּ, שֶׁהִיא בָּרְחָה מִן הָאָדָם מִקֹּדֶם לָכֵן, אֲבָל אָנוּ לֹא שָׁנִינוּ כָּךְ, מִשּׁוּם שֶׁהֲרֵי נְקֵבָה זוֹ נִמְצְאָה עִמּוֹ, אֲבָל טֶרֶם שֶׁקָּמָה הַנֶּפֶשׁ הַזּוֹ (שהרי נקבה זו לא נמצאהעמו, אבל טרם שתקנה הנקבה הזו) עִם אָדָם כָּרָאוּי, הָיְתָה מִזְדַּוֶּגֶת עִמּוֹ, וּכְשֶׁזּוֹ תֻּקְּנָה עִמּוֹ כָּרָאוּי, הִיא בָּרְחָה לַיָּם, וּמְזֻמֶּנֶת לְהַזִּיק לִבְנֵי הָעוֹלָם.</p>\n<p>הָרְפוּאָה לָזֶה - בְּאוֹתָהּ שָׁעָה שֶׁאָדָם מִזְדַּוֵּג עִם אִשְׁתּוֹ, יְכַוֵּן לִבּוֹ בִּקְדֻשַּׁת רִבּוֹנוֹ וְיֹאמַר כָּךְ: הָעֲטוּפָה בְסָדִין הִזְדַּמְּנָה, מֻתֶּרֶת מֻתֶּרֶת, אַל תִּכָּנְסִי וְאַל תֵּצְאִי, לֹא שֶׁלָּךְ וְלֹא בְּחֶלְקֵךְ. שׁוּבִי שׁוּבִי, הַיָּם רוֹעֵשׁ, הַגַּלִּים שֶׁלּוֹ קוֹרְאִים לָךְ, בְּחֵלֶק קָדוֹשׁ אֲנִי אָחוּז, וּבִקְדֻשַּׁת הַמֶּלֶךְ הִתְעַטַּפְתִּי.</p>\n<p>וּלְכַסּוֹת אֶת רֹאשׁוֹ וְאֶת אִשְׁתּוֹ עַד שָׁעָה אַחַת, וְכֵן בְּכָל פַּעַם, עַד שְׁלֹשָׁה יָמִים לַקְּלִיטָה, שֶׁכָּל הַרְכָּבָה שֶׁאֵין קוֹלֶטֶת לִשְׁלֹשָׁה יָמִים, שׁוּב אֵין קוֹלֶטֶת. וּבַסֵּפֶר שֶׁהִנִּיחַ אַשְׁמְדַאי לִשְׁלֹמֹה הַמֶּלֶךְ, אוֹמֵר שְׁלֹשִׁים יוֹם. וְאָמַר, שֶׁלְּאַחַר שֶׁסִּיֵּם אֶת הַמַּעֲשֶׂה, יִשְׁפֹּךְ מַיִם צְלוּלִים סְבִיב מִטָּתוֹ, וְזוֹ שְׁמִירָה שֶׁל הַכֹּל. (אחר כך)</p>"],[9522011970,"<p>מִי שֶׁמֵּינִיקָה תִינוֹק, לֹא תִזְדַּוֵּג עִם אָדָם אֶלָּא בְּשָׁעָה שֶׁהַתִּינוֹק יָשֵׁן. וְאַחַר כָּךְ אַל תָּנִיק אוֹתוֹ עַד שָׁעָה אַחַת, כְּמוֹ שְׁנֵי מִילִין, אוֹ מִיל אֶחָד, אִם לֹא יְכוֹלָה בִּשְׁבִיל צַעַר הַתִּינוֹק בִּזְמַן שֶׁהוּא בּוֹכֶה. וּבָזֶה לֹא יִפְחַד מִמֶּנָּה לְעוֹלָמִים.</p>\n<p>אַשְׁרֵי הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְלַמֵּד אוֹתָם סוֹדוֹת עֲמֻקִּים שֶׁלְּמַעְלָה וּלְמַטָּה, וְהַכֹּל בִּשְׁבִיל הַתּוֹרָה, שֶׁהֲרֵי מִי שֶׁמִּתְעַסֵּק בַּתּוֹרָה, מִתְעַטֵּר בָּעֲטָרוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁהֲרֵי הַתּוֹרָה הִיא שֵׁם קָדוֹשׁ, וּמִי שֶׁמִּתְעַסֵּק בָּהּ נִרְשָׁם וּמִתְעַטֵּר בַּשֵּׁם הַקָּדוֹשׁ, וְאָז יוֹדֵעַ דְּרָכִים נִסְתָּרוֹת וְסוֹדוֹת עֲמֻקִּים שֶׁלְּמַעְלָה וּלְמַטָּה, וְלֹא פוֹחֵד לְעוֹלָמִים.</p>"],[9522011971,"<p>בֹּא רְאֵה, בְּאוֹתוֹ יוֹם נִצְטַוּוּ עַל עֵץ אֶחָד וְעָבְרוּ עַל מִצְוַת רִבּוֹנָם, וּבִגְלַל שֶׁהָאִשָּׁה חָטְאָה בָרִאשׁוֹנָה וּבָא עָלֶיהָ אוֹתוֹ הַנָּחָשׁ, כָּתוּב (בראשית ג) וְהוּא יִמְשָׁל בָּךְ. מִכָּאן וָהָלְאָה, בְּכָל הַפְּעָמִים שֶׁאֲנָשִׁים נִמְצָאִים רְשָׁעִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הֲרֵי בֵּאַרְנוּ שֶׁאוֹתָן נָשִׁים (שלמעלה) שֶׁמִּצַּד הַדִּין הַקָּשֶׁה מְזֻמָּנוֹת לִשְׁלֹט עֲלֵיהֶם, מִצַּד הַדִּין הַקָּשֶׁה. זֶהוּ שֶׁכָּתוּב (ישעיה ג) עַמִּי נֹגְשָׂיו מְעוֹלֵל וְנָשִׁים מָשְׁלוּ בוֹ. נָשִׁים מָשְׁלוּ בוֹ וַדַּאי.</p>\n<p>וְאֵלֶּה נִקְרָאוֹת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, לֹא שֶׁהֵם חֶרֶב הַמִּתְהַפֶּכֶת, אֶלָּא לַהַט מֵאוֹתָהּ חֶרֶב, שֶׁנִּקְרָא (ויקרא כו) חֶרֶב נֹקֶמֶת נְקַם בְּרִית, (ישעיה לד) חֶרֶב לַה' מָלְאָה דָם. וְאוֹתוֹ לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, לִפְעָמִים גְּבָרִים וְלִפְעָמִים נְקֵבוֹת, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>אוֹי לָעוֹלָם כְּשֶׁאוֹתָן נָשִׁים שׁוֹלְטוֹת בָּעוֹלָם. כְּשֶׁרָאָה הַנָּבִיא שֶׁיִּשְׂרָאֵל מְעַקְּמִים אֶת דַּרְכֵיהֶם וְהֵם נִמְצָאִים בַּחֲטָאִים לִפְנֵי רִבּוֹנָם, אָז אָמַר: נָשִׁים שַׁאֲנַנּוֹת, אֵיךְ אַתֶּן שַׁאֲנַנּוֹת? אֵיךְ אַתֶּן יוֹשְׁבוֹת שֶׁלֹּא לְהִתְעוֹרֵר בָּעוֹלָם?! קֹמְנָה. וּבְמָקוֹם אַחֵר בֵּאַרְנוּ אֶת הַפָּסוּק הַזֶּה, וַהֲרֵי פֵּרְשׁוּהוּ הַחֲבֵרִים.</p>\n<p>אֲבָל לֹא נֶאֱמַר, אֶלָּא כְּמוֹ שֶׁמָּצָאנוּ בִדְבוֹרָה, שֶׁכָּתוּב (שופטים ה) הִיא שּפְטָה אֶת יִשְׂרָאֵל בָּעֵת הַהִיא. וְעַל כֵּן שָׁנִינוּ, אוֹי לְאָדָם שֶׁאִשָּׁה מְבָרֶכֶת לוֹ בְּשֻׁלְחָנוֹ. כָּךְ דְּבוֹרָה, הִיא שּפְטָה אֶת יִשְׂרָאֵל בָּעֵת הַהִיא - אוֹי לְדוֹר שֶׁלֹּא נִמְצָא בָהֶם מִי שֶׁיָּדוּן אֶת הָעָם אֶלָּא רַק נְקֵבָה אַחַת.</p>\n<p>בֹּא רְאֵה, שְׁתֵּי נָשִׁים הֵן שֶׁנִּמְצְאוּ בָעוֹלָם וְאוֹמְרוֹת תִּשְׁבַּחְתּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל הַגְּבָרִים שֶׁבָּעוֹלָם לֹא יֹאמְרוּ כָּזוֹ. וּמִי הֵן? דְּבוֹרָה וְחַנָּה. חַנָּה אָמְרָה (שמואל א ב) אֵין קָדוֹשׁ כַּה' כִּי אֵין בִּלְתֶּךְ, וְכָל שְׁאָר הַפְּסוּקִים. שֶׁהִיא פָּתְחָה אֶת פֶּתַח הָאֱמוּנָה לָעוֹלָם, כְּמוֹ: מֵקִים מֵעָפָר דָּל מֵאַשְׁפֹּת יָרִים אֶבְיוֹן, הֲרֵי הַפֶּתַח שֶׁל הָאֱמוּנָה. לְהוֹשִׁיבִי עִם נְדִיבִים, הֲרֵי הָאֱמוּנָה שֶׁלְּמַעְלָה, בַּמָּקוֹם שֶׁשְּׁרוּיִים הָאָבוֹת. מִי הַנְּדִיבִים? אֵלּוּ הָאָבוֹת, כַּכָּתוּב (תהלים מז) נְדִיבֵי עַמִּים נֶאֱסָפוּ.</p>\n<p>דָּבָר אַחֵר לְהוֹשִׁיב עִם נְדִיבִים - נִבְּאָה עַל שְׁמוּאֵל, שֶׁהוּא עָתִיד לִהְיוֹת שָׁקוּל עִם מֹשֶׁה וְאַהֲרֹן, שֶׁכָּתוּב (שם צט) מֹשֶׁה וְאַהֲרֹן בְּכֹהֲנָיו וּשְׁמוּאֵל בְּקֹרְאֵי שְׁמוֹ. וְכִסֵּא כָבוֹד יַנְחִלֵם, מִי יַנְחִלֵם? זֶה שְׁמוּאֵל, שֶׁהוֹרִישׁ כְּבוֹד הַמַּלְכוּת לִשְׁנֵי מְלָכִים. דָּבָר אַחֵר וְכִסֵּא כָבוֹד יַנְחִלֵם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוֹרִישׁ אֶת כִּסְאוֹ לַעֲבָדָיו. זֶהוּ שֶׁכָּתוּב וְכִסֵּא כָבוֹד יַנְחִלֵם.</p>\n<p>ה' יֵחַתּוּ מְרִיבָו, מְרִבָו חָסֵר, מַה זֶּה אוֹמֵר? אֶלָּא מְרִיבָו שָׁנִינוּ, מֵרִיב ו', וְזֶה הַמֶּלֶךְ הַקָּדוֹשׁ, וְסוֹד הַחָכְמָה נֶאֱמַר כָּאן, בְּשָׁעָה שֶׁהַדִּינִים מִתְעוֹרְרִים וְהַשַּׁלִּיטִים שׁוֹלְטִים עַל הָרַחֲמִים, וְהָרַחֲמִים נִכְנָעִים, וּבְשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְבָּרֵךְ מִמַּעְיַן הַנַּחַל, אֲזַי גּוֹבְרִים הָרַחֲמִים וְנִכְנָעִים הַדִּינִים. זֶהוּ שֶׁכָּתוּב, ה' יֵחַתּוּ מְרִיבָו, מֵרִיב ו'.</p>\n<p>עָלָו בַּשָּׁמַיִם יַרְעֵם. עָלָו, מַה זֶּה עָלָו? בְּשָׁעָה שֶׁהַטַּל שֶׁל הָעַתִּיק הַקָּדוֹשׁ שׁוֹרֶה עָלָיו, וּמְמַלֵּא אֶת רֹאשׁוֹ בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא שָׁמַיִם, אֲזַי יַרְעֵם, יִשְׁבֹּר אֶת כֹּחָם וְתָקְפָּם שֶׁל הַדִּינִים הַקָּשִׁים. וְיִתֶּן עֹז לְמַלְכּוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְיָרֵם קֶרֶן מְשִׁיחוֹ - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת קֶרֶן הַיּוֹבֵל, כְּמוֹ שֶׁבֵּאַרְנוּ. מְשִׁיחוֹ, כְּמוֹ שֶׁנֶּאֱמַר מְשִׁיחַ אֱלֹהֵי יַעֲקֹב, מִשּׁוּם כָּךְ קֶרֶן מְשִׁיחוֹ, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>דְּבוֹרָה שֶׁבָּאָה לְשַׁבֵּחַ אֶת שֶׁבַח הַמֶּלֶךְ הַקָּדוֹשׁ: ה' בְּצֵאתְךְ מִשֵּׂעִיר בְּצַעַדְּךְ מִשְּׂדֵה אֱדוֹם. מְלַמֵּד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִזְמִין אֶת כָּל שְׁאָר הָעַמִּים לְקַבֵּל תּוֹרָה, וְלֹא רָצוּ. וְכִי לֹא הָיָה גָלוּי לְפָנָיו שֶׁלֹּא רוֹצִים? אֶלָּא שֶׁלֹּא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה, שֶׁאִלְמָלֵא הָיָה נוֹתֵן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַתּוֹרָה, הָיוּ שׁוֹמְרִים אוֹתָהּ. וְכָל אוֹתָם פְּסוּקִים שֶׁאָמְרָה דְבוֹרָה, הַכֹּל הֵם בְּסוֹד הַחָכְמָה, עַד אוֹתָהּ שָׁעָה שֶׁשִּׁבְּחָה אֶת עַצְמָהּ, שֶׁנֶּאֱמַר עַד שַׁקַּמְתִּי דְּבוֹרָה שַׁקַּמְתִּי אֵם בְּיִשְׂרָאֵל, שֶׁהֲרֵי בֵּאֲרוּ שֶׁהִסְתַּלְּקָה מִמֶּנָּה רוּחַ הַקֹּדֶשׁ. וּמִשּׁוּם כָּךְ, עוּרִי עוּרִי דְּבוֹרָה עוּרִי עוּרִי דַּבְּרִי שִׁיר.</p>\n<p>וְכָל זֶה כְּשֶׁנִּמְצְאוּ הַגְּבָרִים בְּחֵטְא, וְאֵינָם כְּדָאִים לְהַשְׁרוֹת עֲלֵיהֶם רוּחַ הַקֹּדֶשׁ וַדַּאי. וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ וְגוֹ', כְּמוֹ שֶׁבֵּאַרְנוּ בְּהוֹרָאָה שֶׁטָּעוּ בָהּ. אֲבָל וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ, וְאִם כָּל יִשְׂרָאֵל יִשְׁגּוּ הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה כָּל עֲדַת יִשְׂרָאֵל? אֶלָּא אוֹתָם (כלם) שֶׁנִּמְצָאִים בִּירוּשָׁלַיִם, שֶׁהֲרֵי מִשָּׁם יוֹצֵאת תּוֹרָה לְכָל הָעָם, וְאִם אוֹתָם שֶׁהָיוּ שָׁם טוֹעִים, אָז כָּל יִשְׂרָאֵל טוֹעִים, וְשָׁנִינוּ, שֶׁכֵּיוָן שֶׁשָּׁם טוֹעִים, כָּל הָעָם טוֹעִים, מִשּׁוּם שֶׁכֻּלָּם נִמְשָׁכִים אַחֲרֵיהֶם. וְנֶעְלָם דָּבָר מֵעֵינֵי הַקָּהָל - עֵינֵי הַקָּהָל אֵלּוּ הַסַּנְהֶדְרִין, אֵלּוּ הֵם שֶׁמְּמֻנִּים עַל יִשְׂרָאֵל.</p>"],[9522011972,"<p>מִצְוָה זוֹ לְהָבִיא קָרְבָּן עַל סַנְהֶדְרִין גְּדוֹלָה שֶׁטָּעוּ, תַּנָּאִים וְאָמוֹרָאִים שִׁבְעִים סַנְהֶדְרִין גְּדוֹלָה הָיוּ, וּמֹשֶׁה עֲלֵיהֶם. וְשִׁבְעִים סַנְהֶדְרִין קְטַנָּה הָיוּ, וְאַהֲרֹן עֲלֵיהֶם. וּמִשּׁוּם כָּךְ אָמְרוּ בַּעֲלֵי הַמִּשְׁנָה, שֶׁמֹּשֶׁה הָיָה שׁוֹשְׁבִין הַמֶּלֶךְ וְזוֹ תִּפְאֶרֶת, מִשָּׁם סַנְהֶדְרִין גְּדוֹלָה. אַהֲרֹן שׁוֹשְׁבִין הַגְּבִירָה, וְזוֹ מַלְכוּת, הֵ\"א קְטַנָּה קוֹרְאִים לָהּ, כְּמוֹ (בראשית כט) אֶעֱבָדְךְ שֶׁבַע שָׁנִים בְּרָחֵל בִּתְּךְ הַקְּטַנָּה. וְעַל שְׁמָהּ נִקְרֵאת סַנְהֶדְרִין קְטַנָּה.</p>\n<p>וּמִשָּׁם הָיוּ יוֹדְעִים סַנְהֶדְרִין שִׁבְעִים לָשׁוֹן, שֶׁהֵן שִׁבְעִים פָּנִים לַתּוֹרָה, שֶׁיֵּשׁ שִׁבְעִים לָשׁוֹן מִצַּד שֶׁל הַמַּלְכוּת הָרְשָׁעָה וְכוּ', הַכֹּל בְּפֵרוּד. זֶהוּ שֶׁכָּתוּב מֵאֵלֶּה נִפְרְדוּ אִיֵּי הַגּוֹיִם בְּאַרְצֹתָם לִלְֹשנֹתָם. כָּל שִׁבְעִים הַלָּשׁוֹן בְּפֵרוּד זֶה מִזֶּה.</p>\n<p>אֲבָל בַּתּוֹרָה, שִׁבְעִים פָּנִים לַתּוֹרָה בְּלָשׁוֹן אַחַת. וְזֶה יְסוֹד. ו' הֲלָכָה אַחַת, חָכְמָה קְטַנָּה - מַלְכוּת, שֶׁבָּהּ שִׁבְעִים לָשׁוֹן כְּחֶשְׁבּוֹן סוֹד, מִן יְסוֹד. וִיסוֹד הוּא לְשׁוֹן הַקֹּדֶשׁ, סוֹד הַמֶּרְכָּבָה, בְּשִׁבְעִים קָתֶדְרָאוֹת, עֲלֵיהֶם נֶאֱמַר, כָּל הָעוֹנֶה אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ בְּכָל כֹּחוֹ, קוֹרְעִים לוֹ גְּזַר דִּינוֹ שֶׁל שִׁבְעִים שָׁנָה. לָשׁוֹן אֶחָד, הִיא שִׁבְעִים לָשׁוֹן עַל מִדָּה קְטַנָּה שֶׁל חָכְמָה קְטַנָּה, שֶׁהִיא י' עַל מִדָּה קְטַנָּה. עַל חָכְמָה קְטַנָּה שֶׁהִיא י', עַל מִדָּה קְטַנָּה שֶׁל חָכְמָה ב', שְׁתֵּי שְׂפָתַיִם שֶׁבָּהֶן דַּעַת וּתְבוּנָה, בָּהֶן נִשְׁלְמוּ שִׁבְעִים וּשְׁתַּיִם. (ע\"כ רעיא מהימנא).</p>"],[9522011973,"<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, נִשְׁתַּדֵּל בְּדִבְרֵי תוֹרָה, בְּדִבְרֵי עַתִּיק הַיָּמִים. פָּתַח רַבִּי חִיָּיא וְאָמַר, (תהלים לב) חַטָּאתִי אוֹדִיעֲךְ וְגוֹ', מִכָּאן לָמַדְנוּ, שֶׁכָּל אָדָם שֶׁמְּכַסֶּה אֶת חֲטָאָיו וְאֵינוֹ מְפָרֵשׁ אוֹתָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וִיבַקֵּשׁ עֲלֵיהֶם רַחֲמִים, לֹא נוֹתְנִים לוֹ לִפְתֹּחַ פֶּתַח שֶׁל תְּשׁוּבָה, מִשּׁוּם שֶׁהוּא מִתְבַּיֵּשׁ (מכסה) מִמֶּנּוּ. וְאִם הוּא מְפָרֵשׁ אוֹתָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו, וְיִתְגַּבְּרוּ הָרַחֲמִים עַל הַדִּין.</p>\n<p>וְכָל שֶׁכֵּן אִם הוּא בּוֹכֶה, שֶׁהֲרֵי כָּל הַפְּתָחִים הַסְּתוּמִים הוּא פּוֹתֵחַ, וּתְפִלָּתוֹ מִתְקַבֶּלֶת. וְעַל זֶה פְּרִישַׁת חֲטָאָיו, כָּבוֹד הוּא לַמֶּלֶךְ לְהַגְבִּיר רַחֲמִים עַל דִּין. וְעַל זֶה כָּתוּב, זֹּבֵחַ תּוֹדָה יְכַבְּדָנְנִי. מַה זֶּה יְכַבְּדָנְנִי? שְׁנֵי כִבּוּדִים הֵם, אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה. אֶחָד בָּעוֹלָם הַזֶּה וְאֶחָד בָּעוֹלָם הַבָּא.</p>\n<p>הַפָּסוּק הַזֶּה קָשֶׁה בַּכֹּל, בְּרֹב דְּבָרִים, שֶׁהֲרֵי בְּאוֹדֶה עֲלֵי פְשָׁעַי מַסְפִּיק, מַה זֶּה חַטָּאתִי אוֹדִיעֲךְ וַעֲונִי לֹא כִסִּיתִי, וְאַחַר כָּךְ אוֹדֶה עֲלֵי פְשָׁעַי לַה'? וְעוֹד, שֶׁהֲרֵי אוֹדֶה עֲלֵי פְשָׁעַי לַה', לְךְ הָיָה צָרִיךְ לִהְיוֹת!</p>\n<p>אֶלָּא דָּוִד, אֶת כָּל דְּבָרָיו הוּא אָמַר בְּרוּחַ הַקֹּדֶשׁ, וְאָמַר אֶת זֶה לְמַלְכוּת הַשָּׁמַיִם, מִשּׁוּם שֶׁהוּא שָׁלִיחַ מֵהַתַּחְתּוֹנִים אֶל הָעֶלְיוֹנִים, וּמֵעֶלְיוֹנִים אֶל הַתַּחְתּוֹנִים, וּמִי שֶׁרוֹצֶה אֶת הַמֶּלֶךְ, הוּא מוֹדִיעַ לָהּ בָּרִאשׁוֹנָה. וְעַל כֵּן חַטָּאתִי אוֹדִיעֲךְ, (למלכות השמים אמר) וַעֲוֹנִי לֹא כִסִּיתִי, מִצַּדִּיקוֹ שֶׁל עוֹלָם. אָמַרְתִּי אוֹדֶה עֲלֵי פְשָׁעַי לַה' - זֶהוּ הַמֶּלֶךְ הַקָּדוֹשׁ שֶׁכָּל הַשָּׁלוֹם שֶׁלּוֹ, וְהַשָּׁלוֹם שֶׁצָּרִיךְ אָדָם לְהַכְנִיס לְפָנָיו - בְּהוֹדָאָה. שֶׁהֲרֵי כָּךְ נִקְרָבִים שְׁלָמִים בְּהוֹדָאָה, שֶׁכָּתוּב עַל זֶבַח תּוֹדַת שְׁלָמָיו. וְאַתָּה נָשָׂאתָ עֲון חַטָּאתִי סֶלָה. זֶה לְמַעְלָה לְמַעְלָה, הַמָּקוֹם שֶׁהָעַתִּיק הַקָּדוֹשׁ שָׁרוּי. מִשּׁוּם כָּךְ הַפָּסוּק הַזֶּה אוֹחֵז בַּכֹּל.</p>\n<p>כְּמוֹ זֶה מִי שֶׁמְּבַקֵּשׁ בַּקָּשָׁתוֹ לַמֶּלֶךְ, צָרִיךְ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ בִּרְצוֹנוֹ, מִמַּטָּה לְמַעְלָה וּמִמַּעְלָה לְמַטָּה, וְלִקְשֹׁר הַכֹּל בְּקֶשֶׁר אֶחָד, וּבְאוֹתוֹ קֶשֶׁר נִמְצֵאת בַּקָּשָׁתוֹ. אָמַר רַבִּי יוֹסֵי, מִי הֶחָכָם לְבַקֵּשׁ בַּקָּשָׁתוֹ כְּמוֹ דָוִד הַמֶּלֶךְ, שֶׁהוּא הָיָה שׁוֹמֵר אֶת פֶּתַח הַמֶּלֶךְ? אָמַר לוֹ רַבִּי חִיָּיא, וַדַּאי כָּךְ הוּא, וְעַל כֵּן הַתּוֹרָה לִמְּדָה אוֹתָנוּ אֶת דַּרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ כְּדֵי שֶׁנֵּדַע לָלֶכֶת אַחֲרָיו, כְּמוֹ שֶׁנֶּאֱמַר (דברים יג) אַחֲרֵי ה' אֱלֹהֵיכֶם תֵּלֵכוּ וְגוֹ'.</p>"],[9522011974,"<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (ירמיה לא) כֹּה אָמַר ה' קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי וְגוֹ'. כֹּה אָמַר ה', הֲרֵי פֵּרְשׁוּהָ, בְּכָל מָקוֹם שֶׁנָּבִיא מַתְחִיל לְדַבֵּר, הָיוּ דְבָרִים נוֹדָעִים, וְכָאן כֹּה אָמַר ה' הַזֶּה, הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמָה אָמַר? קוֹל בְּרָמָה נִשְׁמָע.</p>\n<p>כָּךָ שָׁנִינוּ, שֶׁבְּאוֹתוֹ יוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ לְמַטָּה וְיִשְׂרָאֵל הָלְכוּ לַגָּלוּת, רֵחַיִם עַל צַוְּארֵיהֶם וִידֵיהֶם מְהֻדָּקוֹת לְאָחוֹר, וּכְנֶסֶת יִשְׂרָאֵל גֹּרְשָׁה מִבֵּית הַמֶּלֶךְ לָלֶכֶת אַחֲרֵיהֶם, בְּשָׁעָה שֶׁיָּרְדָה אָמְרָה: אֵלֵךְ בָּרִאשׁוֹנָה וְאֶבְכֶּה עַל מְדוֹרִי, וְעַל בָּנַי, וְעַל בַּעְלִי. כְּשֶׁיָּרְדָה, רָאֲתָה אֶת מְקוֹמָהּ חָרֵב, וְכַמָּה דָם שֶׁל חֲסִידִים שָׁפוּךְ בְּתוֹכוֹ, וְהַהֵיכָל הַקָּדוֹשׁ וְהַבַּיִת נִשְׂרָף בָּאֵשׁ.</p>\n<p>אָז הֵרִימָה קוֹל, וְרָעֲשׁוּ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְהַקּוֹל הִגִּיעַ לְמַעְלָה עַד לַמָּקוֹם שֶׁהַמֶּלֶךְ שָׁרוּי בּוֹ, וְרָצָה הַמֶּלֶךְ לְהַחֲזִיר אֶת הָעוֹלָם לְתֹהוּ וָבהוּ, עַד שֶׁיָּרְדוּ כַּמָּה אוּכְלוּסִים וְכַמָּה מַחֲנוֹת כְּנֶגְדָּהּ, וְלֹא קִבְּלָה תַנְחוּמִים מֵהֶם. זֶהוּ שֶׁכָּתוּב, קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַמְרוּרִים רָחֵל מְבַכָּה עַל בָּנֶיהָ מֵאֲנָה לְהִנָּחֵם עַל בָּנֶיהָ, שֶׁלֹּא קִבְּלָה מֵהֶם תַּנְחוּמִים. כִּי אֵינֶנּוּ, מִשּׁוּם שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ הָיָה עוֹלֶה לְמַעְלָה לְמַעְלָה וְלֹא נִמְצָא בְתוֹכָהּ. זֶהוּ שֶׁכָּתוּב כִּי אֵינֶנּוּ, וְלֹא כָתוּב כִּי אֵינָם.</p>\n<p>אָמַר לוֹ רַבִּי חִיָּיא, מַה זֶּה רָחֵל מְבַכָּה עַל בָּנֶיהָ? אָמַר לוֹ, לָמַדְנוּ שֶׁהִיא כְּנֶסֶת יִשְׂרָאֵל, וְזוֹ אִשְׁתּוֹ שֶׁל יַעֲקֹב וַדַּאי, שֶׁכָּתוּב וַיֶּאֱהַב יַעֲקֹב אֶת רָחֵל. וְכָתוּב (בראשית כט) וְרָחֵל עֲקָרָה. וְכָתוּב שָׁם, (תהלים קיג) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת אֵם הַבָּנִים שְׂמֵחָה.</p>\n<p>דָּבָר אַחֵר כִּי אֵינֶנּוּ, כְּמוֹ שֶׁנֶּאֱמַר, (בראשית לט) אֵינֶנּוּ גָדוֹל בַּבַּיִת וְגוֹ'. אֵינֶנּוּ - שֶׁהֲרֵי הִסְתַּלֵּק לְמַעְלָה וְהִתְרַחֵק מֵהַכֹּל. אֵינֶנּוּ - בְּזִוּוּג עִמָּהּ. אֵינֶנּוּ - שֶׁיִּמָּצֵא שְׁמוֹ הַגָּדוֹל.</p>\n<p>אָמַר רַבִּי חִיָּיא, מֵאֵיזֶה מָקום הִתְחִילָה לִגְלות? אָמַר לו, מִבֵּית הַמִּקְדָּשׁ, שֶׁשָּׁם שָׁרְתָה, וְאַחַר כָּךְ סוֹבְבָה בְּכָל אֶרֶץ יִשְׂרָאֵל. אַחַר כָּךְ כְּשֶׁיָּצְאָה מִן הָאָרֶץ, עָמְדָה עַל הַמִּדְבָּר וְיָשְׁבָה שָׁם שְׁלֹשָׁה יָמִים, הִנְהִיגָה אֶת אוּכְלוּסֶיהָ וּמַחֲנוֹתֶיהָ (וישיבותיה) וְתוֹשָׁבֶיהָ מִבֵּית הַמֶּלֶךְ, וְקָרְאָה עָלֶיהָ אֵיכָה יָשְׁבָה בָדָד וְגוֹ'. בָּכוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי.</p>\n<p>אָמַר רַבִּי יוֹסֵי, לֹא גָלוּ יִשְׂרָאֵל מֵהָאָרֶץ וְלֹא נֶחֱרַב בֵּית הַמִּקְדָּשׁ עַד שֶׁכָּל יִשְׂרָאֵל נִמְצְאוּ חַיָּבִים לִפְנֵי הַמֶּלֶךְ, וְעַד שֶׁמַּנְהִיגֵי הָעוֹלָם נִמְצְאוּ חַיָּבִים בָּרִאשׁוֹנָה. זֶהוּ שֶׁכָּתוּב (ישעיה ג) עַמִּי מְאַשְּׁרֶיךְ מַתְעִים וְדֶרֶךְ אֹרְחֹתֶיךְ בִּלֵּעוּ. שֶׁכֵּיוָן שֶׁרָאשֵׁי הָעָם הוֹלְכִים בְּרֶשַׁע, כָּל הָעָם נִמְשָׁכִים אַחֲרֵיהֶם. רַבִּי חִיָּיא אָמַר מִכָּאן, וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ - בַּמֶּה זֶה הָיָה? מִשּׁוּם שֶׁנֶּעְלַם דָּבָר מֵעֵינֵי הַקָּהָל, שֶׁעֵינֵי הָעָם הֵם רָאשֵׁיהֶם, שֶׁכָּל הָעָם נִמְשָׁכִים אַחֲ רֵיהֶם.</p>\n<p>הָלְכוּ, עַד שֶׁהָיוּ הוֹלְכִים רָאוּ מָקוֹם אֶחָד מְדֻשָּׁן בַּעֲשָׂבִים וּנְהַר מַיִם זוֹרֵם בּוֹ. יָשְׁבוּ. עַד שֶׁהָיוּ יוֹשְׁבִים, פָּרַח עוֹף אֶחָד וְרָחַשׁ לִפְנֵיהֶם. אָמַר רַבִּי חִיָּיא, נָקוּם מִכָּאן, שֶׁוַּדַּאי חוֹצְבֵי הָרִים (שודדים) נִמְצָאִים כָּאן. קָמוּ וְהָלְכוּ. עַד שֶׁהֶחֱזִירוּ רָאשֵׁיהֶם, רָאוּ אוֹתָם לִסְטִים שֶׁרָצִים אַחֲרֵיהֶם. הִתְרַחֵשׁ לָהֶם נֵס וּמָצְאוּ לִפְנֵיהֶם סֶלַע אֶחָד וּבוֹ מְעָרָה אַחַת. נִכְנְסוּ לְשָׁם וְיָשְׁבוּ כָּל אוֹתוֹ יוֹם וְכָל הַלַּיְלָה.</p>"],[9522011975,"<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, (ירמיה ל) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב וְגוֹ', כִּי הִנְנִי מוֹשִׁיעֲךְ מֵרָחוֹק. מֵרָחוֹק?! מִקָּרוֹב הָיָה צָרִיךְ לִהְיוֹת! וַהֲרֵי בֵּאֲרוּ אֶת הַפָּסוּק הַזֶּה, מֵרָחוֹק - כְּמוֹ שֶׁנֶּאֱמַר וְשָׁבוּ מֵאֶרֶץ מֶרְחָק. אֲבָל מֵרָחוֹק, כְּאוֹתוֹ שֶׁכָּתוּב (שם לא) מֵרָחוֹק ה', נִרְאָה לִי. וְכָתוּב (משלי לא) מִמֶּרְחָק תָּבִיא לַחְמָהּ. וּמִי הִיא? עֹמֶק הַנַּחַל, הַמָּקוֹם שֶׁאוֹתוֹ נָהָר יוֹצֵא וְזוֹרֵם. וְשָׁב יַעֲקֹב, כֵּיוָן שֶׁכָּתוּב אַל תִּירָא עַבְדִּי יַעֲקֹב, מַהוּ וְשָׁב יַעֲקֹב? אֶלָּא כְּמוֹ שֶׁשָּׁנִינוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא עָלָה לְמַעְלָה לְמַעְלָה, כְּמוֹ שֶׁכָּתוּב (תהלים י) לָמָה ה' תַּעֲמֹד בְּרָחוֹק, וּמֵאוֹתוֹ מָקוֹם רָחוֹק - הִנְנִי מוֹשִׁיעֲךְ.</p>\n<p>וְשָׁב יַעֲקֹב - לִמְקוֹמוֹ (לכסאו), לְהִזְדַּוֵּג עִם כְּנֶסֶת יִשְׂרָאֵל. וְשָׁקַט - זֶה יְסוֹד. וְשַׁאֲנַן - לְהַשְׁרוֹת דִּיּוּרוֹ בָהּ. וְאֵין מַחֲרִיד - מִיִּצְחָק. כְּמוֹ שֶׁנֶּאֱמַר (בראשית כז) וַיֶּחֱרַד יִצְחָק חֲרָדָה גְּדוֹלָה, וְעַל זֶה כָּתוּב (בראשית לא) וּפַחַד יִצְחָק. וּכְשֶׁמִּתְעוֹרֵר אוֹתוֹ הַפַּחַד, מִסְתַּלֵּק הַיְסוֹד לְמָקוֹם אַחֵר. זֶהוּ שֶׁכָּתוּב (ישעיה לג) פָּחֲדוּ בְצִיּוֹן חַטָּאִים. בְּצִיּוֹן דַּוְקָא. וְעַל זֶה וְאֵין מַחֲרִיד. וְעַכְשָׁו הַקָּדוֹשׁ בָּרוּךְ הוּא הִצִּיל אוֹתָנוּ מֵרָחוֹק וְהִסְתִּיר אוֹתָנוּ בַּמָּקוֹם הַזֶּה בְּהַשְׁקֵט וּבְשַׁלְוָה, וְאֵין מַחֲרִיד מֵהַכֹּל. שֶׁכְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה נֵס, בַּכֹּל הוּא עוֹשֶׂה.</p>\n<p>רַבִּי יוֹסֵי פָּתַח, (שופטים ד) וַיּאמֶר אֵלֶיהָ בָּרָק אִם תֵּלְכִי עִמִּי וְהָלָכְתִּי וְגוֹ', מַה זֶּה אוֹמֵר? אֶלָּא אָמַר בָּרָק, הוֹאִיל וְרוּחַ הַקְּדֻשָּׁה שׁוֹרָה עָלֶיהָ, בִּזְכוּתָהּ אֶנָּצֵל וְלֹא יִשְׁרֶה עָלַי נֶזֶק. וּמַה בָּרָק סָמוּךְ עַל אִשָּׁה לְהִנָּצֵל בִּגְלָלָהּ - אָנוּ, שֶׁהַתּוֹרָה עִמָּנוּ, שֶׁהִיא שְׁמוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ, עַל אַחַת כַּמָּה וְכַמָּה.</p>"],[9522011976,"<p>יָשְׁבוּ בְּתוֹךְ אוֹתָהּ הַמְּעָרָה כָּל אוֹתוֹ הַיּוֹם, וּכְשֶׁיָּרַד הַלַּיְלָה, הֵאִירָה הַלְּבָנָה בַּמְּעָרָה. עָבְרוּ שְׁנֵי סוֹחֲרִים וַחֲמוֹרֵיהֶם טְעוּנִים מִיַּיִן וּמִמַּאֲכָל לְעַצְמָם, נָחוּ עַל מִטְעָנָם, וְאוֹמְרִים זֶה לָזֶה: נָלוּן כָּאן, נִתֵּן אֹכֶל וּמִשְׁתֶּה לַחֲמוֹרִים, וְאָנוּ נִכָּנֵס לַמְּעָרָה הַזּוֹ. אָמַר לוֹ חֲבֵרוֹ: טֶרֶם שֶׁנִּכָּנֵס, תֹּאמַר לִי הַפָּסוּק הַזֶּה שֶׁאֵינוֹ מְיֻשָּׁב.</p>\n<p>אָמַר לוֹ: מַה הוּא? אָמַר לוֹ: דָּבָר אֶחָד, שֶׁכָּתוּב (תהלים נב) אוֹדְךְ לְעוֹלָם כִּי עָשִׂיתָ וְגוֹ'. מַהוּ כִּי עָשִׂיתָ וְלֹא כָתוּב מָה? וְכָתוּב כִּי טוֹב נֶגֶד חֲסִידֶיךְ, וְכִי לְאַחֵר אֵינוֹ טוֹב? לֹא הָיָה בְיָדוֹ? אָמַר: אוֹי לִסְחוֹרָתֵנוּ שֶׁעָזַבְנוּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּגְלָלָהּ. רַבִּי חִיָּיא וְרַבִּי יוֹסֵי שֶׁהָיוּ יוֹשְׁבִים בַּמְּעָרָה שָׂמְחוּ. אָמַר רַבִּי חִיָּיא לְרַבִּי יוֹסֵי, וְלֹא אָמַרְתִּי לְךְ שֶׁכְּשֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נֵס, בַּכֹּל הוּא עוֹשֶׂה? יָצְאוּ.</p>\n<p>כְּשֶׁיָּצְאוּ, הִקְדִּים רַבִּי חִיָּיא וּפָתַח, (ישעיה נז) שָׁלוֹם שָׁלוֹם לָרָחוֹק. שְׁנֵי שְׁלוֹמוֹת כָּאן, אֶחָד לָרָחוֹק וְאֶחָד לַקָּרוֹב, וְהַכֹּל אֶחָד. לָרָחוֹק - שֶׁנַּעֲשֶׂה קָרוֹב. (ועוד לרחוק) זֶהוּ בַּעֲלֵי הַתְּשׁוּבָה, שֶׁקֹּדֶם הָיָה רָחוֹק, וְעַכְשָׁו הוּא קָרוֹב. וְעוֹד רָחוֹק - כְּשֶׁאָדָם מִתְרַחֵק מֵהַתּוֹרָה, רָחוֹק הוּא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִי שֶׁקָּרוֹב לַתּוֹרָה, מְקָרֵב אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עִמּוֹ, וְעַכְשָׁו הִתְחַבְּרוּ עִמָּנוּ וְתִכָּנְסוּ לַמְּעָרָה. בָּאוּ אוֹתָם סוֹחֲרִים וְהִשְׁתַּתְּפוּ עִמָּם. שִׁחְרְרוּ אֶת הַמַּשָּׂא מֵחֲמוֹרֵיהֶם וְתִקְּנוּ לָהֶם אֹכֶל, וְיָצְאוּ כֻלָּם לְפִי הַמְּעָרָה.</p>\n<p>אָמַר אֶחָד מֵהַסּוֹחֲרִים: יֹאמְרוּ לָנוּ בַּעֲלֵי הַתּוֹרָה אֶת הַפָּסוּק הַזֶּה, אוֹדְךְ לְעוֹלָם כִּי עָשִׂיתָ וַאֲקַוֶּה וְגוֹ'. כִּי עָשִׂיתָ, מַה זֶּה כִּי עָשִׂיתָ, וְלֹא כָתוּב מָה? וְכָתוּב כִּי טוֹב נֶגֶד חֲסִידֶיךְ, וְכִי לְגַבֵּי אַחֵר אֵינוֹ כִּי טוֹב?</p>\n<p>אָמַר רַבִּי חִיָּיא, כִּי עָשִׂיתָ וַדַּאי. וּמָה עָשִׂיתָ? לְעוֹלָם. שֶׁבִּגְלַל זֶה הָעוֹלָם שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִתְקִין אוֹתוֹ, מוֹדֶה אָדָם לַקָּדוֹשׁ-בָּרוּךְ-הוּא בְּכָל יוֹם. וַאֲקַוֶּה שִׁמְךְ כִי טוֹב נֶגֶד חֲסִידֶיךְ, כָּךְ זֶה וַדַּאי, כְּנֶגֶד אוֹתָם צַדִּיקִים, שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא טוֹב, וְלֹא כְנֶגֶד הָרְשָׁעִים שֶׁמְּבַזִּים אוֹתוֹ בְּכָל יוֹם וְאֵינָם עוֹסְקִים בַּתּוֹרָה. אָמַר לוֹ, זֶה יָפֶה, אֲבָל שָׁמַעְתִּי דָבָר מֵאֲחוֹרֵי הַכֹּתֶל, וַאֲנִי פוֹחֵד לְגַלּוֹת. אָמְרוּ לוֹ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי, אֱמֹר דְּבָרְךְ, שֶׁתּוֹרָה אֵינָהּ יְרֻשָּׁה לְמָקוֹם אֶחָד.</p>\n<p>אָמַר לָהֶם, יוֹם אֶחָד הָיִיתִי הוֹלֵךְ לְלוֹד וְנִכְנַסְתִּי לְעִיר, וְסָמַכְתִּי אֶת עַצְמִי אַחַר כֹּתֶל אֶחָד, וְרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי הָיָה בְּאוֹתוֹ הַבַּיִת, וְשָׁמַעְתִּי מִפִּיו אֶת הַפָּסוּק הַזֶּה, אוֹדְךְ לְעוֹלָם כִּי עָשִׂיתָ. אוֹדְךְ, דָּוִד הַמֶּלֶךְ עָלָיו הַשָּׁלוֹם (לקדוש ברוך הוא) אֲמָרוֹ עַל אוֹתוֹ עוֹלָם אַחֲרוֹן, שֶׁהוּא עָשָׂה שֶׁדָּוִד הַמֶּלֶךְ אָחוּז בּוֹ בְּאוֹתוֹ עוֹלָם, וּבוֹ יָרַשׁ אֶת הַמַּלְכוּת. וַאֲקַוֶּה שִׁמְךְ כִי טוֹב - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא בַּיִּחוּד שֶׁל הָעוֹלָם הַזֶּה שֶׁנִּקְרָא טוֹב. מָתַי נִקְרָא טוֹב? נֶגֶד חֲסִידֶיךְ. מִי הֵם חֲסִידֶיךְ?</p>\n<p>אֶלָּא יֵשׁ חֶסֶד וְיֵשׁ חֶסֶד, וְאֵלּוּ נִקְרְאוּ חַסְדֵי דָוִד הַנֶּאֱמָנִים. וּכְשֶׁחַסְדֵי דָוִד הַלָּלוּ מִתְמַלְּאִים מֵאוֹתוֹ טוֹב שֶׁשּׁוֹפֵעַ שֶׁל הָעַתִּיק הַקָּדוֹשׁ, אֲזַי נִקְרָא הַיְסוֹד טוֹב, אֲזַי נִמְצָא לָהֶם טוֹב. שֶׁהֲרֵי כְּמוֹ שֶׁנִּמְצָא שֶׁהוּא בּוֹ, כָּךְ הוּא מְבַשֵּׂם אֶת הָעוֹלָם הָאַחֲרוֹן הַזֶּה, וְהַכֹּל נִמְצָא בִּבְרָכָה, וְעַל כֵּן דָּוִד הָיָה מְחַכֶּה לַדַּרְגָּה הַזּוֹ שֶׁמְּאִירָה לָעוֹלָם הַזֶּה שֶׁהוּא אָחוּז בָּהּ.</p>\n<p>הַדְּבָרִים הַלָּלוּ, כָּךְ שָׁמַעְתִּי אוֹתָם, אֶלָּא שֶׁלֹּא יָדַעְתִּי מַה זֶּה. בָּאוּ רַבִּי חִיָּיא וְרַבִּי יוֹסִי וְנָשְׁקוּ אוֹתוֹ בְרֹאשׁוֹ. אָמַר רַבִּי חִיָּיא, מִי מְכַסֶּה עֵינֶיךְ בְּעָפָר, רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, שֶׁאַתָּה בִּמְקוֹמְךְ וְאַתָּה מַרְעִישׁ הֶהָרִים הָעֶלְיוֹנִים, וַאֲפִלּוּ צִפֳּרֵי הַשָּׁמַיִם וְכֻלָּם שְׂמֵחִים בְּדִבּוּרֶיךְ. אוֹי לָעוֹלָם בְּאוֹתָהּ שָׁעָה כְּשֶׁתִּסְתַּלֵּק מִמֶּנּוּ.</p>\n<p>עוֹד פָּתַח וְאָמַר אוֹתוֹ הָאִישׁ, הֲרֵי שֶׁדָּבָר אַחֵר שָׁמַעְתִּי מִמֶּנּוּ בְּאוֹתָהּ שָׁעָה בַּפָּסוּק שֶׁכָּתוּב (דניאל ט) וְעַתָּה שְׁמַע אֱלֹהֵינוּ אֶל תְּפִלַּת עַבְדְּךְ וְאֶל תַּחֲנוּנָיו וְגוֹ' לְמַעַן אֲדנָי. וְאָמַר כָּךְ, אִם הַשֵּׁם הַזֶּה מְעֻלֶּה (למעלה) מֵהַכֹּל - יָפֶה הוּא. שֶׁכָּךְ אוֹמְרִים, עוֹשֶׂה לְמַעַן הַמֶּלֶךְ. אֲבָל הַשֵּׁם הַזֶּה הֲרֵי יָדוּעַ שֶׁהוּא מָקוֹם שֶׁל בֵּית דִּין, שֶׁמִּמֶּנּוּ יוֹצֵא דִין לָעוֹלָם. מִי רָאָה שֶׁאוֹמְרִים לַמֶּלֶךְ עֲשֵׂה לְמַעַן עַבְדְּךְ, אוֹ בִּשְׁבִיל דָּבָר קָטָן מִמֶּךְ?</p>\n<p>אֶלָּא כָּךְ צָרִיךְ, שֶׁהַשֵּׁם הַזֶּה מְתַקֵּן אֶת בֵּית הַמֶּלֶךְ וּבֵית הַמִּקְדָּשׁ לְמַטָּה, וְזֶה אָחוּז בָּזֶה, מִשּׁוּם שֶׁנִּקְשָׁר זֶה בָּזֶה. וּכְשֶׁהַמִּקְדָּשׁ לְמַטָּה עוֹמֵד בִּמְקוֹמוֹ, הַשֵּׁם הַזֶּה לְמַעְלָה עוֹמֵד בִּמְקוֹמוֹ, וְזֶהוּ כְּמִי שֶׁאוֹמֵר לַמֶּלֶךְ: בְּנֵה אֶת הַבַּיִת הַזֶה וְאֶת הַהֵיכָל הַזֶּה כְּדֵי שֶׁהַגְּבִירָה לֹא תִמָּצֵא יוֹשֶׁבֶת מִחוּץ לְהֵיכָלָהּ. אַף כָּאן - וְהָאֵר פָּנֶיךְ עַל מִקְדָּשְׁךְ הַשָּׁמֵם לְמַעַן אֲדנָי. מָה הַטַּעַם לְמַעַן אֲדנָי? שֶׁלֹּא יִמָּצֵא מִחוּץ לִמְדוֹרוֹ.</p>"],[9522011977,"<p>תָּמְהוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי, וְשָׂמְחוּ בְאוֹתוֹ לַיְלָה. אַחַר שֶׁאָכְלוּ, פָּתַח חֲבֵרוֹ הַסּוֹחֵר וְאָמַר, אֹמַר לִפְנֵיהֶם דָּבָר אֶחָד שֶׁהִתְעַסַּקְתִּי בוֹ הַיּוֹם הַזֶּה, הַפָּסוּק הַזֶּה שֶׁכָּתוּב (תהלים סג) מִזְמוֹר לְדָוִד בִּהְיוֹתוֹ בְּמִדְבַּר יְהוּדָה. דָּוִד אָמַר שִׁירָה כְּשֶׁהָיָה בּוֹרֵחַ מֵחָמִיו, לָמָּה אָמַר אֱלֹהִים אֵלִי אַתָּה אֲשַׁחֲרֶךָּ צָמְאָה לְךְ נַפְשִׁי וְגוֹ'? אֱלֹהִים אֵלִי אַתָּה, שֶׁהֲרֵי בִּגְבוּרָה אֲחוּזָה תָּמִיד. אֲשַׁחֲרֶךָּ, וְכִי אֵיךְ יָכֹל דָּוִד לְשַׁחֵר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאֶרֶץ רְחוֹקָה, וְגֹרַשׁ מֵהָאָרֶץ שֶׁבָּהּ שְׁרוּיָה הַשְּׁכִינָה?</p>\n<p>אֶלָּא, אַף עַל גַּב שֶׁגֹּרַשׁ מִשָּׁם, לֹא עָזַב אֶת שֶׁלּוֹ לְשַׁחֵר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. וַאֲנִי שָׁמַעְתִּי, אֲשַׁחֲרֶךָּ - כְּמִי שֶׁאוֹמֵר, אֵלֵךְ לְהֵרָאוֹת לְפָנֶיךְ, רַק שֶׁלֹּא יָכֹלְתִּי. כָּךְ אֲשַׁחֲרֶךָּ, רַק שֶׁאֲנִי מִחוּץ לַמָּקוֹם שֶׁשָּׁם שׁוֹרָה שְׁכִינָה. צָמְאָה לְךְ נַפְשִׁי, שֶׁהֲרֵי נַפְשִׁי וְגוּפִי מִשְׁתּוֹקְקִים אֵלֶיךְ לְהֵרָאוֹת לְפָנֶיךְ, וְלֹא יָכֹלְתִּי, כִּי אֲנִי בְּאֶרֶץ צִיָּה וְעָיֵף בְּלִי מָיִם, שֶׁהֲרֵי אֶרֶץ צִיָּה וְעָיֵף נִקְרָא מִחוּץ לַמָּקוֹם שֶׁשּׁוֹרָה שְׁכִינָה, מִשּׁוּם שֶׁמַּיִם חַיִּים אֵין מְצוּיִים כָּאן. וּמִי הֵם הַמַּיִם הַחַיִּים? זוֹ שְׁכִינָה, שֶׁכָּתוּב בָּהּ (בראשית כז) בְּאֵר מַיִם חַיִּים, וְעַל זֶה אֶרֶץ צִיָּה וְעָיֵף בְּלִי מַיִם כָּתוּב.</p>"],[9522011978,"<p>אָמְרוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי, וַדַּאי שֶׁהַדֶּרֶךְ תְּקִינָה לְפָנֵינוּ. נִכְנְסוּ לַמְּעָרָה וְיָשְׁנוּ. בַּחֲצוֹת הַלַּיְלָה שָׁמְעוּ אֶת קוֹל חַיּוֹת הַמִּדְבָּר שֶׁנּוֹהֲמוֹת. הִתְעוֹרְרוּ. אָמַר רַבִּי חִיָּיא, הֲרֵי עֵת הִיא לְסַיֵּעַ לִכְנֶסֶת יִשְׂרָאֵל שֶׁמְּשַׁבַּחַת אֶת הַמֶּלֶךְ. אָמְרוּ, כָּל אֶחָד וְאֶחָד יֹאמַר דָּבָר מִמַּה שֶּׁשָּׁמַע וְיָדַע בַּתּוֹרָה. יָשְׁבוּ כֻלָּם.</p>\n<p>פָּתַח רַבִּי חִיָּיא וְאָמַר, (תהלים כב) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר מִזְמוֹר לְדָוִד. מִי זוֹ אַיֶּלֶת הַשַּׁחַר? זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת (משלי ה) אַיֶּלֶת אֲהָבִים וְיַעֲלַת חֵן. וְכִי אַיֶּלֶת הַשַּׁחַר, וְלֹא בְּכָל הַיּוֹם? אֶלָּא אַיֶּלֶת, מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא שַׁחַר, כְּמוֹ שֶׁנֶּאֱמַר (הושע ו) כְּשַׁחַר נָכוֹן מֹצָאוֹ. וְדָוִד הַמֶּלֶךְ אָמַר אֶת זֶה עַל כְּנֶסֶת יִשְׂרָאֵל, שֶׁהֲרֵי לֹא אָמְרָה כְּנֶסֶת יִשְׂרָאֵל אֶת זֶה (שנקרא אילת אהבים ויעלת חן, והיא באה מאותו מקום שנקרא שחר, כמו שנאמר (הושע ו) כשחר נכון מצאו, ודוד המלך אמר את זה על כנסת ישראל), מַשְׁמָע שֶׁכָּתוּב עַל אַיֶּלֶת הַשַּׁחַר.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁיּוֹרֵד הַלַּיְלָה, פְּתָחִים הַסְּתוּמִים שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים נִמְצָאִים (שוככים), וְכָל אוֹתָם רְחוֹקִים מִתְעוֹרְרִים וְהוֹלְכִים וְשָׁטִים בְּכָל הָעוֹלָם, וּמְחַזְּרִים עַל גּוּפוֹת בְּנֵי אָדָם וְסוֹבְבִים לִמְקוֹמוֹתֵיהֶם וּלְמִטּוֹתֵיהֶם, וְרוֹאִים אֶת דְּיוֹקַן הַמֶּלֶךְ הַקָּדוֹשׁ וּפוֹחֲדִים, שֶׁהֲרֵי הִתְחַזְּקוּ בְמִטּוֹתֵיהֶם בְּדִבְרֵי הַשֵּׁם הַקָּדוֹשׁ. וּבְנֵי אָדָם, נִשְׁמוֹתֵיהֶם עוֹלוֹת כָּל אַחַת וְאַחַת כָּרָאוּי לָהּ, וַהֲרֵי פֵּרְשׁוּהָ. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁנִּשְׁמוֹתֵיהֶם עוֹלוֹת לְמַעְלָה וְלֹא מִתְעַכְּבוֹת בְּמָקוֹם אַחֵר שֶׁלֹּא צָרִיךְ.</p>\n<p>כְּשֶׁנֶּחֱלָק הַלַּיְלָה, הַכָּרוֹז עוֹמֵד וּמַכְרִיז, וְנִפְתָּחִים הַפְּתָחִים. אָז רוּחַ אַחַת שֶׁל צָפוֹן מִתְעוֹרֶרֶת וּמַקִּישָׁה בְּכִנּוֹר דָּוִד, וּמְנַגֵּן מֵאֵלָיו, וּמְשַׁבַּחַת אֶת הַמֶּלֶךְ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּתְעוֹרֵר בְּאוֹתוֹ זְמַן וְעוֹסֵק בַּתּוֹרָה, וְכָל מִי שֶׁעוֹמֵד בְּאוֹתוֹ זְמַן וְעוֹסֵק בַּתּוֹרָה, נִקְרָא חֲבֵרוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל, וְלֹא עוֹד, אֶלָּא שֶׁאֵלּוּ נִקְרָאִים אַחִים וְרֵעִים שֶׁלּוֹ, שֶׁכָּתוּב (תהלים קפב) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָּא שָׁלוֹם בָּךְ. וְנִקְרָאִים חֲבֵרִים שֶׁל הַמַּלְאָכִים הָעֶלְיוֹנִים וְהַמַּחֲנוֹת הָעֶלְיוֹנִים, שֶׁכָּתוּב (שיר ח) חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ.</p>\n<p>כְּשֶׁבָּא הַיּוֹם, הַכָּרוֹז עוֹמֵד וּמַכְרִיז, וּפְתָחִים שֶׁל צַד דָּרוֹם נִפְתָּחִים, וּמִתְעוֹרְרִים כּוֹכָבִים וּמַזָּלוֹת, וּפִתְחֵי הָרַחֲמִים נִפְתָּחִים, וְהַמֶּלֶךְ יוֹשֵׁב וּמְקַבֵּל תִּשְׁבָּחוֹת. אֲזַי כְּנֶסֶת יִשְׂרָאֵל נוֹטֶלֶת אֶת אוֹתָם דְּבָרִים וְעוֹלָה, וְכָל אוֹתָם חֲבֵרִים אֲחוּזִים בִּכְנָפֶיהָ, וְדִבְרֵיהֶם בָּאִים וְשׁוֹרִים בְּחֵיק הַמֶּלֶךְ. אָז מְצַוֶּה הַמֶּלֶךְ לִכְתֹּב אֶת כָּל אוֹתָם הַדְּבָרִים.</p>\n<p>וּבַסֵּפֶר כְּתוּבִים כָּל אותָם בְּנֵי הֵיכָלו, וְחוּט שֶׁל חֶסֶד נִמְשָׁךְ עֲלֵיהֶם, שֶׁמֵּאוֹתוֹ חוּט מִתְעַטֵּר אָדָם בַּעֲטֶרֶת הַמֶּלֶךְ, וּמִמֶּנּוּ פוֹחֲדִים עֶלְיוֹנִים וְתַחְתּוֹנִים. הוּא נִכְנָס לְכָל שַׁעֲרֵי הַמֶּלֶךְ, וְאֵין מִי שֶׁיִּמְחֶה בְיָדוֹ. וַאֲפִלּוּ בִּזְמַן שֶׁבַּעֲלֵי הַדִּין עוֹמְדִים לָדוּן אֶת הָעוֹלָם, אֵין דָּנִים עָלָיו דִּין, מִשּׁוּם שֶׁהֲרֵי נִרְשָׁם בָּרֹשֶׁם שֶׁל הַמֶּלֶךְ, שֶׁנּוֹדָע שֶׁהוּא מֵהֵיכַל הַמֶּלֶךְ, וְלָכֵן לֹא דָנִים עָלָיו דִּין. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, וְכָל שֶׁכֵּן בִּזְמַן שֶׁהַמֶּלֶךְ תָּאֵב לְדִבְרֵי תוֹרָה.</p>\n<p>בֹּא וּרְאֵה סוֹד הַדָּבָר, אֵין עוֹמֶדֶת כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַמֶּלֶךְ אֶלָּא בַּתּוֹרָה, וְכָל זְמַן שֶׁיִּשְׂרָאֵל בָּאָרֶץ הִתְעַסְּקוּ בַתּוֹרָה, כְּנֶסֶת יִשְׂרָאֵל הָיְתָה שְׁרוּיָה עִמָּהֶם. כְּשֶׁהִתְבַּטְּלוּ מִדִּבְרֵי תוֹרָה, לֹא יָכְלָה לַעֲמֹד עִמָּהֶם שָׁעָה אַחַת. מִשּׁוּם כָּךְ, בְּשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל מִתְעוֹרֶרֶת לַמֶּלֶךְ בַּתּוֹרָה, מִתְחַזֵּק כֹּחָהּ, וְהַמֶּלֶךְ הַקָּדוֹשׁ שָׂמֵחַ לְקַבֵּל אוֹתָהּ.</p>\n<p>וְכָל זְמַן שֶׁכְּנֶסֶת יִשְׂרָאֵל בָּאָה לִפְנֵי הַמֶּלֶךְ וְאֵין הַתּוֹרָה נִמְצֵאת עִמָּהּ, כִּבְיָכוֹל תָּשַׁשׁ כֹּחָהּ. אוֹי לְאוֹתָם שֶׁמַּחֲלִישִׁים אֶת הַכֹּחַ שֶׁלְּמַעְלָה. מִשּׁוּם כָּךְ אַשְׁרֵי אוֹתָם שֶׁעוֹסְקִים בַּתּוֹרָה, וְכָל שֶׁכֵּן בְּאוֹתָהּ שָׁעָה שֶׁצָּרִיךְ לְהִשְׁתַּתֵּף עִם כְּנֶסֶת יִשְׂרָאֵל. אֲזַי הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא עָלָיו, (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>"],[9522011979,"<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר, (שם כא) מַשָּׂא דּוּמָה אֵלַי קֹרֵא מִשֵּׂעִיר שֹׁמֵר מַה מִּלַּיְלָה שֹׁמֵר מַה מִּלֵּיל. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּ הַחֲבֵרִים בְּכַמָּה מְקוֹמוֹת. אֲבָל מַשָּׂא דּוּמָה, כָּל הַפְּעָמִים שֶׁיִּשְׂרָאֵל נִמְצְאוּ בַגָּלוּת, נוֹדָע הַזְּמַן וְהַקֵּץ שֶׁלָּהֶם, וּזְמַן וָקֵץ שֶׁל אוֹתָהּ גָּלוּת. וְגָלוּת אֱדוֹם הוּא מַשָּׂא דּוּמָה, שֶׁלֹּא הִתְגַּלָּה וְלֹא נוֹדַע כְּאוֹתָן הָאֲחֵרוֹת.</p>\n<p>הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר, אֵלַי קֹרֵא מִשֵּׂעִיר. קוֹל שָׁמַעְתִּי בְּגָלוּת שֵׂעִיר, אוֹתָם שֶׁדְּחוּקִים בֵּינֵיהֶם, אוֹתָם שֶׁשּׁוֹכְבִים בֶּעָפָר. וּמַה הֵם אוֹמְרִים? שֹׁמֵר מַה מִּלַּיְלָה שֹׁמֵר מַה מִּלֵּיל. הֵם תּוֹבְעִים אוֹתִי עַל הַגְּבִירָה, מֶה עָשִׂיתִי מֵהַגְּבִירָה שֶׁלִּי.</p>\n<p>אֲזַי הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְנִיס אֶת הַפָּמַלְיָא שֶׁלּוֹ וְאוֹמֵר: רְאוּ בָנַי אֲהוּבַי, שֶׁהֵם דְּחוּקִים בַּגָּלוּת וְעוֹזְבִים אֶת הַצַּעַר שֶׁלָּהֶם וּמְבַקְשִׁים מִמֶּנִּי עַל הַגְּבִירָה, וְאוֹמְרִים: שֹׁמֵר - אַתָּה שֶׁנִּקְרָא שׁוֹמֵר, אֵיפֹה הַשְּׁמִירָה שֶׁלְּךְ? אֵיפֹה הַשְּׁמִירָה שֶׁל בֵּיתְךְ? מַה מִּלַּיְלָה - מֶה עָשִׂיתָ מִלַּיְלָה, כָּךְ שָׁמַרְתָּ אוֹתָהּ?! מַה מִּלֵּיל? שֶׁהֲרֵי לִפְעָמִים נִקְרֵאת לַיְלָה וְלִפְעָמִים נִקְרֵאת לֵיל. זֶהוּ שֶׁכָּתוּב (שמות יב) לֵיל שִׁמֻּרִים הוּא, וְכָתוּב הוּא הַלַּיְלָה הַזֶּה.</p>\n<p>אֲזַי הַקָּדוֹשׁ בָּרוּךְ הוּא מֵשִׁיב לָהֶם: הֲרֵי שְׁמִירָתִי נִמְצֵאת, שֶׁהֲרֵי אֲנִי עָתִיד לְקַבֵּל אוֹתָהּ וּלְהִמָּצֵא עִמָּהּ. זֶהוּ שֶׁכָּתוּב אָמַר שֹׁמֵר, אוֹתוֹ שֶׁשּׁוֹמֵר אֶת הַבַּיִת, אָתָא בקֶר וְגַם לָיְלָה, שֶׁהֲרֵי בַּהַתְחָלָה הִסְתַּלֵּק לְמַעְלָה לְמַעְלָה, וְהֶעֱלָה אֶת אוֹתוֹ (מקום) בֹּקֶר שֶׁמְּזֻמָּן אֶצְלוֹ תָּמִיד. עַכְשָׁו אָתָא בקֶר, וַהֲרֵי הוּא מְזֻמָּן לְהִתְחַבֵּר עִם הַלַּיְלָה. וְגַם לָיְלָה, הֲרֵי הִיא זְמִינָה, אֲבָל בִּגְלַלְכֶם מִתְעַכְּבִים. וְאִם אַתֶּם רוֹצִים אֶת זֶה, עַל מָה אַתֶּם מִתְעַכְּבִים? שֻׁבוּ. שׁוּבוּ בִתְשׁוּבָה. אָז אֵתָיוּ, בּאוּ אֵלַי, וְנִהְיֶה כֻלָּנוּ בְּמָדוֹר אֶחָד, וְכֻלָּנוּ נָשׁוּב לִמְקוֹמֵנוּ. זֶהוּ שֶׁכָּתוּב, (דברים ל) וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ, וְהֵשִׁיב לֹא נֶאֱמַר, אֶלָּא וְשָׁב. פַּעֲמַיִם וְשָׁב וְשָׁב כָּתוּב כָּאן. אֶלָּא אֶחָד לִכְנֶסֶת יִשְׂרָאֵל, וְאֶחָד לַקָּדוֹשׁ-בָּרוּךְ-הוּא. זֶהוּ שֶׁכָּתוּב וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ, וְשָׁב וְקִבֶּצְךְ מִכָּל הָעַמִּים.</p>"],[9522011980,"<p>פָּתַח אוֹתוֹ סוֹחֵר וְאָמַר, (איוב לח) בְּרָן יָחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. בּא רְאֵה, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן, כָּל דִּבְרֵי הָעוֹלָם הַתַּחְתּוֹן (העליון), וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים מִתְעוֹרְרִים כְּנֶגְדּוֹ, וְכָל הָאִילָנוֹת שֶׁבְּגַן עֵדֶן פּוֹתְחִים בְּשֶׁבַח כְּנֶגְדּוֹ. זֶהוּ שֶׁכָּתוּב (דברי הימים א טז) אָז יְרַנְּנוּ עֲצֵי הַיָּעַר מִלִּפְנֵי ה' כִּי בָא. וַאֲפִלּוּ עוֹפוֹת הָאָרֶץ, כֻּלָּם רוֹחֲשִׁים שֶׁבַח לְפָנָיו. אֲזַי יוֹצֵאת שַׁלְהֶבֶת וּמַכָּה בְּכַנְפֵי הַתַּרְנְגוֹל, וְהוּא קוֹרֵא וּמְשַׁבֵּחַ אֶת הַמֶּלֶךְ הַקָּדוֹשׁ, וְקוֹרֵא לִבְנֵי אָדָם שֶׁיִּשְׁתַּדְּלוּ בַתּוֹרָה וּבְשִׁבְחוֹ שֶׁל אֲדוֹנָם וּבַעֲבוֹדָתוֹ. אַשְׁרֵי חֶלְקָם שֶׁל מִי שֶׁעוֹמְדִים מִמִּטּוֹתֵיהֶם לְהִשְׁתַּדֵּל בַּתּוֹרָה.</p>\n<p>כְּשֶׁבָּא הַבֹּקֶר, פִּתְחֵי הַדָּרוֹם נִפְתָּחִים, וְשַׁעֲרֵי רְפוּאָה יוֹצְאִים לָעוֹלָם, וְרוּחַ הַמִּזְרָח מִתְעוֹרֶרֶת, וְנִמְצָאִים רַחֲמִים, וְכָל אוֹתָם כּוֹכָבִים וּמַזָּלוֹת שֶׁמְּמֻנִּים תַּחַת שִׁלְטוֹנוֹ שֶׁל הַבֹּקֶר הַזֶּה, כֻּלָּם פּוֹתְחִים בְּשֶׁבַח וּמְשַׁבְּחִים לַמֶּלֶךְ הָעֶלְיוֹן. זֶהוּ שֶׁכָּתוּב בְּרָן יָחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מָה עוֹשִׂים כָּאן בְּנֵי אֱלֹהִים, שֶׁהֵם מְזַמְּנִים תְּרוּעָה בַּבֹּקֶר הַזֶּה? וַהֲרֵי כָּל הַדִּינִים הָעָבְרוּ בִּזְמַן שֶׁחֶסֶד מִתְעוֹרֵר בָּעוֹלָם? אֶלָּא וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים, הֲרֵי נִשְׁבָּר תֹּקֶף הַדִּינִים הַקָּשִׁים, נִשְׁבָּר כֹּחָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כד) רֹעָה הִתְרֹעֲעָה הָאָרֶץ.</p>\n<p>וְכָל כָּךְ, מִשּׁוּם שֶׁהַבֹּקֶר הַזֶּה הִתְעוֹרֵר בָּעוֹלָם, וְאַבְרָהָם מִתְעוֹרֵר וּבָא לִנְטֹעַ אֵשֶׁל בִּבְאֵר שָׁבַע. אֶת הַדָּבָר הַזֶּה כָּךְ שָׁמַעְתִּי, בִּבְאֵר שָׁבַע וַדַּאי, וְכָתוּב וַיִּקְרָא שָׁם בְּשֵׁם ה' אֵל עוֹלָם.</p>"],[9522011981,"<p>פָּתַח חֲבֵרוֹ הַסּוֹחֵר וְאָמַר, הַבֹּקֶר אוֹר וְהָאֲנָשִׁים שֻׁלְּחוּ וְגוֹ'. מַה זֶּה הַבֹּקֶר אוֹר? כָּךְ לָמַדְנוּ, מַה זֶּה בֹּקֶר? אֶלָּא בִּזְמַן שֶׁבָּא הַבֹּקֶר וְהַדִּינִים עוֹבְרִים וְחֶסֶד רוֹצֶה לְהִתְעוֹרֵר, כָּל אוֹתָם שֶׁבָּאִים מֵהַצַּד הַזֶּה, מְבַקְּרִים (פוקדים) אֶת מְקוֹמוֹתֵיהֶם לְזַמֵּן בְּרָכוֹת לָעוֹלָם. וְזֶהוּ הַבֹּקֶר אוֹר, שֶׁהֲרֵי הָרַחֲמִים מִתְיַשְּׁבִים לָעוֹלָם, וְהַחֶסֶד בָּא אַחֲרָיו, אֲזַי הוּא בּקֶר אוֹר. וְכָתוּב, וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב.</p>\n<p>בֹּא רְאֵה, הַכֹּל הוּא בִּדְרָגוֹת יְדוּעוֹת. הַלַּיְלָה - הֲרֵי יָדוּעַ. בֹּקֶר אוֹר - הֲרֵי יָדוּעַ, וְהוּא דַּרְגָּה עֶלְיוֹנָה שֶׁנִּמְצֵאת בּוֹ תָּמִיד. מָתַי? כְּשֶׁמְּאִירָה הַשֶּׁמֶשׁ. הַשֶּׁמֶשׁ יָדוּעַ, וְהִיא דַּרְגָּה עֶלְיוֹנַה שֶׁמְּבַשֶּׂמֶת אֶת הַכֹּל וּמְאִירָה לַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פד) כִּי שֶׁמֶשׁ וּמָגֵן ה' אֱלֹהִים. וְהַבּקֶר אוֹר הַזֶּה מֵאִיר מֵהַשֶּׁמֶשׁ, וְזֶהוּ מֵאִיר לַלַּיְלָה, וְלָכֵן הַכֹּל תָּלוּי זֶה בָּזֶה. וְהַבֹּקֶר אוֹר הַזֶּה, כְּשֶׁהוּא מִתְעוֹרֵר, כָּל בְּנֵי הָעוֹלָם מִתְאַחֲדִים בְּאַחְדוּת וּבְשִׂמְחָה, וְהֵם נִמְצָאִים בָּעוֹלָם. וְכָעֵת הֲרֵי מֵאִיר הַיּוֹם, עֵת רָצוֹן הִיא לָלֶכֶת בַּדֶּרֶךְ.</p>\n<p>בֵּרְכוּ אוֹתָם רַבִּי חִיָּיא וְרַבִּי יוֹסֵי, וְנָשְׁקוּ לָהֶם בְּרָאשֵׁיהֶם וְשָׁלְחוּ אוֹתָם. אָמַר רַבִּי חִיָּיא לְרַבִּי יוֹסֵי, בָּרוּךְ הָרַחֲמָן שֶׁתִּקֵּן דַּרְכֵּנוּ לְפָנֵינוּ, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אוֹתָם אֵלֵינוּ. אַשְׁרֵי אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְלֹא מַרְפִּים מִמֶּנָּה שָׁעָה אַחַת. יָצְאוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי וְהָלְכוּ לְדַרְכָּם. אָמַר רַבִּי יוֹסֵי, וַדַּאי אַהֲבַת לִבִּי קְשׁוּרָה בַּסּוֹחֲרִים הַלָּלוּ. אָמַר רַבִּי חִיָּיא, לֹא תָמַהְתִּי עַל זֶה, שֶׁהֲרֵי בִּימֵי רַבִּי שִׁמְעוֹן אֲפִלּוּ צִפֳּרֵי הַשָּׁמַיִם מְרַחֲשׁוֹת חָכְמָה, שֶׁהֲרֵי דְּבָרָיו נוֹדָעִים לְמַעְלָה וּלְמַטָּה.</p>"]]});
